/// The x86-64 C calling convention the compiler selected for a function.
///
/// The verifier receives it from the compiler (target spec for AOT, host for
/// JIT); it is not recorded in `X86ISelFunction`. It is bound into the
/// verifier-input digest, so a report captured under one convention cannot be
/// reused under another.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum X86SourceBoundAbi {
    /// System V AMD64 (Linux, macOS and other Unix-like hosts).
    SystemV,
    /// Microsoft x64. Outside the lane: always [`X86BodyUnsupported::Abi`].
    WindowsX64,
}

/// Name of the whole-body theorem. One replayed theorem credits every value
/// row of the bound body, including copies and dead-but-harmless rows; the
/// name says so because the certificate text carries it.
pub const X86_BODY_OBLIGATION_NAME: &str = "Source-bound x86-64 whole-body theorem (System V, pre-RA ISel): the replayed body theorem credits every covered value row";

/// Reason of every covered row when no independently checked proof of the
/// body theorem exists (replay refused, unavailable, inconclusive or an
/// uncertified UNSAT). Such rows are never credited.
pub const X86_BODY_NEEDS_REPLAY: &str = "source-bound x86 body needs independently replayed proof";

/// Rows a bound body may contain.
const BODY_OPCODES: &str = "MovRR, MovRR32, MovRI, Movzx, MovzxW, MovsxB, MovsxW, Movsx, \
     AddRR, SubRR, ImulRR, AndRR, OrRR, XorRR, AddRI, SubRI, AndRI, OrRI, XorRI, \
     ShlRI, ShrRI, SarRI (and the tied two-operand ShlRI, ShrRI, OrRR and AndRI), ShlRR, ShrRR \
     and SarRR by CL (and their tied one-operand forms), AdcRR, SbbRR, Not, Neg, Popcnt, \
     one-operand Mul, one-operand Div and Idiv, Cqo, Cdq, TrapDivZeroExact, the zeroing XorRR \
     of one register, MovssRR, MovsdRR, MovdFromXmm, MovqFromXmm, MovdToXmm, MovqToXmm, \
     MovssRM, MovsdRM, MovssMR, MovsdMR, MovssRipRel and MovsdRipRel of a constant-pool \
     entry, Pxor, Andps, Andpd, Lea (register or \
     stack-slot base), LeaSib (register base and index, or a private stack address base and a \
     constant index), MovRM8, MovRM16, MovzxRM8, MovzxRM16, \
     MovRM32, MovRM, MovMR8, MovMR16, MovMR32, MovMR ([register or stack-slot base + disp]; a \
     byte or word one through a physical 8- or 16-bit alias too; an incoming stack parameter \
     through [rbp + disp], an outgoing stack argument through [rsp + disp]; the scalar ones \
     with an atomic origin too), MovRMSib, MovRM32Sib, MovRM8Sib, MovzxRM8Sib, MovsdRMSib, \
     MovssRMSib, MovMRSib, MovMR32Sib and MovMR8Sib (the width and extension of the row without \
     the index, at the address LeaSib computes: [virtual-register or stack-slot base + \
     virtual-register index*1, 2, 4 or 8 + disp], their value register virtual), MovRMSib of a \
     jump table at [table + index*8] (its dispatch block only), AddMR and XorMR \
     ([virtual-register base + disp]) and AddMRSib and XorMRSib ([virtual-register base + \
     index*scale + disp]) of incoming memory, LeaRip and MovRipRel of a symbol, CmpRR, CmpRI, \
     TestRR, TestRI, BtRI of a register and an in-range bit index (CF only; a reader of any other \
     flag refuses), Setcc, Cmovcc, Cmovcc32, direct Call and register CallR (System V register and \
     stack arguments and RAX/RDX results; SubRI and AddRI of RSP around one), Jcc, Jmp, Ret, \
     Ud2 and operand-free Nop";

/// Call-row flags that are metadata only: neither changes what the call
/// does. `EXACT_MODULE_CALL` must agree with the source call's binding.
const CALL_METADATA_FLAGS: InstFlags =
    InstFlags::PURE_CALL_HOISTABLE.union(InstFlags::EXACT_MODULE_CALL);

// Verify-owned register identities: x86-64 GPR64 roots in ModR/M numbering.
// `trust_cg_ir::x86_64_regs` spells the same encodings (RAX=0 .. R15=15, and
// the 32-bit aliases EAX=16 .. R15D=31); the unit tests pin that agreement,
// but no codegen ABI table is imported here.
const RAX: u16 = 0;
const RCX: u16 = 1;
const RDX: u16 = 2;
const RBX: u16 = 3;
const RSP: u16 = 4;
const RBP: u16 = 5;
const RSI: u16 = 6;
const RDI: u16 = 7;
const R8: u16 = 8;
const R9: u16 = 9;
const R10: u16 = 10;
const R11: u16 = 11;
const R12: u16 = 12;
const R13: u16 = 13;
const R14: u16 = 14;
const R15: u16 = 15;

/// Offset of the 32-bit alias encodings (EAX = 16).
const GPR32_ALIAS_BASE: u16 = 16;

/// Offsets of the 16-bit (AX = 32) and low-byte (AL = 48; SPL, BPL, SIL and
/// DIL rather than the legacy high-byte registers) alias encodings. A write
/// through either merges into its register, so they are admitted only as the
/// source operand of an extension, which reads exactly those low bits.
const GPR16_ALIAS_BASE: u16 = 32;
const GPR8_ALIAS_BASE: u16 = 48;

/// System V caller-saved GPR roots: a call may leave every one of them
/// changed, except the result bits it defines.
const SYSV_CALLER_SAVED_ROOTS: [u16; 9] = [RAX, RCX, RDX, RSI, RDI, R8, R9, R10, R11];

/// System V AMD64 integer argument registers, in parameter order.
const SYSV_ARGUMENT_ROOTS: [u16; 6] = [RDI, RSI, RDX, RCX, R8, R9];

/// System V AMD64 integer return registers, in result order (psABI §3.2.3:
/// the first INTEGER result in RAX, the second in RDX; a Rust `ScalarPair`
/// returns its two scalars there). A third result leaves the C return file.
const SYSV_RETURN_ROOTS: [u16; 2] = [RAX, RDX];

/// Roots the caller observes after the return besides RAX: the System V
/// callee-saved registers and the stack pointer. A body may read them but
/// never write them.
const SYSV_PRESERVED_ROOTS: [u16; 7] = [RBX, RBP, R12, R13, R14, R15, RSP];

const ROOT_NAMES: [&str; 16] = [
    "rax", "rcx", "rdx", "rbx", "rsp", "rbp", "rsi", "rdi", "r8", "r9", "r10", "r11", "r12", "r13",
    "r14", "r15",
];

/// A LIR scalar carrier the body theorem admits. Thin pointers are `I64`.
/// Slice 11: `I128` is a System V INTEGER register pair (two 64-bit halves,
/// low first), and `F32`/`F64` are bit patterns in the low 32 or 64 bits of
/// an SSE register: only moved, stored, loaded and reinterpreted, never
/// computed with (no floating-point operation is admitted).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Carrier {
    B1,
    I8,
    I16,
    I32,
    I64,
    I128,
    F32,
    F64,
}

impl Carrier {
    fn of(ty: &Type) -> Option<Self> {
        Some(match ty {
            Type::B1 => Self::B1,
            Type::I8 => Self::I8,
            Type::I16 => Self::I16,
            Type::I32 => Self::I32,
            Type::I64 => Self::I64,
            Type::I128 => Self::I128,
            Type::F32 => Self::F32,
            Type::F64 => Self::F64,
            _ => return None,
        })
    }

    fn lir(self) -> Type {
        match self {
            Self::B1 => Type::B1,
            Self::I8 => Type::I8,
            Self::I16 => Type::I16,
            Self::I32 => Type::I32,
            Self::I64 => Type::I64,
            Self::I128 => Type::I128,
            Self::F32 => Type::F32,
            Self::F64 => Type::F64,
        }
    }

    fn bits(self) -> u32 {
        match self {
            Self::B1 => 1,
            Self::I8 => 8,
            Self::I16 => 16,
            Self::I32 | Self::F32 => 32,
            Self::I64 | Self::F64 => 64,
            Self::I128 => 128,
        }
    }

    /// Slice 11: a floating-point bit pattern, which travels in an SSE
    /// register (psABI §3.2.3: class SSE).
    fn is_float(self) -> bool {
        matches!(self, Self::F32 | Self::F64)
    }

    /// An integer carrier of at most 64 bits: one general-purpose register,
    /// the domain of every integer operation before slice 11 (and of every
    /// operation slice 11 does not extend to `I128`).
    fn is_word(self) -> bool {
        !self.is_float() && self != Self::I128
    }

    /// The `bits`-wide mask of a word carrier. An `I128` or a float carrier
    /// has no `u64` mask; no caller asks for one ([`Self::all_ones`] states
    /// a 128-bit one).
    fn mask(self) -> u64 {
        debug_assert!(self.bits() <= 64, "{self:?} has no u64 mask");
        crate::smt::mask(u64::MAX, self.bits())
    }

    /// The all-ones value of this carrier's width (slice 11: also of 128 bits).
    fn all_ones(self) -> E {
        match self {
            Self::I128 => E::bv_const(u64::MAX, 64).concat(E::bv_const(u64::MAX, 64)),
            other => E::bv_const(other.mask(), other.bits()),
        }
    }

    /// Bytes a value of this type occupies in memory: a `bool` is one byte.
    fn bytes(self) -> u32 {
        self.bits().div_ceil(8)
    }

    /// Bits an access of this type reads or writes: its memory bytes. A
    /// `bool` access is one whole byte.
    fn memory_bits(self) -> u32 {
        self.bytes() * 8
    }

    /// `value` (at this carrier's width) as the bytes it occupies in memory:
    /// a stored `bool` is the byte 0 or 1.
    fn memory_value(self, value: E) -> E {
        fit(value, self.bits(), self.memory_bits())
    }

    /// The value a LIR `Load` of this type defines from the
    /// [`Self::memory_bits`] it reads, which is trust-ir's `Load`: a `bool`
    /// is `byte != 0` (the reference interpreter decodes a stored bool byte
    /// as `bytes[0] != 0`, and the adapter lowers `Load Bool` to LIR `Load
    /// B1` unchanged); an integer is its bytes.
    fn loaded_value(self, memory: E) -> E {
        match self {
            Self::B1 => E::ite(
                memory.eq_expr(E::bv_const(0, 8)),
                E::bv_const(0, 1),
                E::bv_const(1, 1),
            ),
            _ => memory,
        }
    }

    /// Low bits of a register the ABI defines for a value of this type (see
    /// the module documentation): the bits a caller reads of a result, a
    /// callee reads of an argument, and a callee's result defines. A `bool`
    /// is the backend's clean 32-bit boolean, 0 or 1 in the low 32 bits.
    fn return_bits(self) -> u32 {
        match self {
            Self::B1 => 32,
            other => other.bits(),
        }
    }

    /// `value` (at this carrier's width) at its [`Self::return_bits`].
    fn abi_value(self, value: E) -> E {
        fit(value, self.bits(), self.return_bits())
    }

    /// Low bits of a result register (RAX, RDX) the call row declares for a
    /// result of this type: the register width the caller extracts, a
    /// `bool` as its byte (AL, DL). How many of those bits hold the value is
    /// [`Self::call_result_bits`].
    fn call_result_register_bits(self) -> u32 {
        match self {
            Self::B1 => 8,
            other => other.bits(),
        }
    }

    /// Low bits of RAX or RDX that another function's result of this type
    /// defines when the call returns `results` results, which is all a
    /// caller may rely on: the type's own bits, except for a `bool`.
    ///
    /// - The only result of a call: AL, 0 or 1 (psABI §3.2.3; rustc declares
    ///   it `zeroext i1`, and an LLVM callee returns it with `setcc %al` or
    ///   `andb $1, %al` and leaves EAX bits 8..31 as they were).
    /// - A lane of a two-result call: bit 0 alone. rustc declares a
    ///   `ScalarPair` return as the LLVM struct `{ T, i1 }` or `{ i1, T }`,
    ///   which carries no `zeroext`, so LLVM any-extends the lane: `(x,
    ///   transmute::<u8, bool>(x as u8 & 1))` returns with `movl %eax, %edx`
    ///   and leaves bits 1..7 of DL as bits 1..7 of `x`.
    ///
    /// Measured with trustc stage-1 (d7f143f3b, LLVM 22.1.2) on
    /// x86_64-apple-darwin at -O3. The backend's clean 32-bit bool is a
    /// promise about its OWN results.
    fn call_result_bits(self, results: usize) -> u32 {
        match self {
            Self::B1 if results > 1 => 1,
            Self::B1 => 8,
            other => other.bits(),
        }
    }
}

/// The caller convention a machine walk assumes for `B1` argument registers
/// (see the module documentation). Other parameters are read identically.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum BoolArguments {
    /// psABI §3.2.3: bit 0 is the value, bits 1..7 are zero, bits 8..63 are
    /// unconstrained. A psABI caller reads AL of a `B1` result.
    PsAbi,
    /// The backend's own clean 32-bit bool, which LLVM's `zeroext i1` also
    /// provides: bits 1..31 are zero, bits 32..63 are unconstrained. Such a
    /// caller reads EAX of a `B1` result.
    Clean32,
}

impl BoolArguments {
    fn view_name(self, i: usize) -> String {
        match self {
            Self::PsAbi => format!("a{i}"),
            Self::Clean32 => format!("z{i}"),
        }
    }

    fn machine_name(self, k: usize) -> String {
        match self {
            Self::PsAbi => format!("m{k}"),
            Self::Clean32 => format!("n{k}"),
        }
    }

    /// Free input naming the `k`-th undefined machine value this walk reads:
    /// the bits a narrow load keeps from an undefined destination, or a
    /// private stack byte the body never wrote.
    fn undefined_name(self, k: usize) -> String {
        match self {
            Self::PsAbi => format!("u{k}"),
            Self::Clean32 => format!("w{k}"),
        }
    }

    /// Slice 21 (OD-198): free input naming the result of the `k`-th
    /// rounding SSE row this walk pairs with no source event (an FP leaf, as
    /// [`float_event_name`]): the walk states nothing of what it computes.
    fn float_leaf_name(self, k: usize) -> String {
        match self {
            Self::PsAbi => format!("fu{k}"),
            Self::Clean32 => format!("fw{k}"),
        }
    }

    /// The register a caller of this convention passes for a `B1` argument
    /// whose entry value is `entry`.
    fn view(self, entry: E) -> E {
        let (upper, cleared) = match self {
            Self::PsAbi => (8, 7),
            Self::Clean32 => (32, 31),
        };
        entry
            .clone()
            .extract(63, upper)
            .concat(entry.extract(0, 0).zero_ext(cleared))
    }
}

/// Immutable binding of one exact (LIR, pre-RA x86 stream, ABI) triple to its
/// whole-body theorem. No public constructor: only [`source_bound_x86_body`]
/// builds one, after admission, the machine walk, the exact affine refusal
/// check and the structural non-vacuity check.
pub struct SourceBoundX86Body<'a> {
    source: &'a Function,
    machine: &'a X86ISelFunction,
    abi: X86SourceBoundAbi,
    bound_rows: Vec<usize>,
    source_definitions: Vec<(String, Block, usize)>,
    machine_definitions: Vec<(String, usize)>,
    call_sites: Vec<(Block, usize, usize)>,
    access_sites: Vec<(Block, usize, usize)>,
    obligation: std::sync::Arc<ProofObligation>,
    /// Slice 16: the theorem's parts, for a function stated in parts (empty
    /// for any other), with the number of the statement's claims each region
    /// accounts for ([`check_x86_body_parts`]).
    parts: std::sync::Arc<X86BodyParts>,
    /// Slice 21 (ruling OD-200): whether the theorem abstracts a rounding
    /// operation (a source rounding event or an SSE rounding row): a
    /// satisfying model of its negation is then no counterexample.
    fp_abstract: bool,
    /// Slice 23 (OD-205): the theorem without the arithmetic pairing (the
    /// theorem of slices 1 to 22), when the pairing spelled a row: a model of
    /// the paired theorem's negation may violate only an operand claim, so
    /// this theorem decides a refutation ([`Self::has_unpaired`]). `None`
    /// exactly when no row was paired (the theorem is then its own arbiter):
    /// a paired theorem is built only beside it ([`owner_theorems`]).
    unpaired: Option<std::sync::Arc<X86UnpairedTheorem>>,
    /// Slice 23: whether the theorem pairs a row.
    paired: bool,
    /// Slice 23 (OD-205): the paired theorem's pairing record (`None` when
    /// it pairs nothing): every consumer re-derives the pairing and the
    /// statement from it before it credits or publishes the paired theorem
    /// ([`Self::check_pairing`]); a paired theorem without one never does.
    pairing: Option<std::sync::Arc<X86BodyPairing>>,
    /// OD-210, OD-217: the runtime routines whose contract the theorem
    /// trusts, one per `I128` division opcode (OD-202) and C memory routine
    /// (slice 13) it states as a call.
    routines: std::collections::BTreeSet<&'static str>,
    /// Slice 24a (OD-226): for a theorem stated over the merged-chain
    /// quotient, the chains it contracts (`None`: stated over the original
    /// pair).
    merged: Option<MergedChains>,
    /// Slice 24c (OD-228): for a theorem stated over segments, how many, of
    /// how many members, and their kinds (`None`: over none).
    segments: Option<segment::SegmentsStated>,
    /// OD-233: how many cut-input bytes and value items the statement in
    /// parts defines ([`Self::defined_cut_inputs`]).
    defined_inputs: split::DefinedInputs,
}

/// Slice 24a (OD-226): the chains a theorem over the merged-chain quotient
/// contracts: how many, how many LIR blocks they absorb, and their
/// description in the ORIGINAL ids (`Block(h)=[Block(h), Block(c1), ..]; ..`,
/// [`quotient::Quotient::describe`]), which every refusal of the route but
/// the empty observable names ([`over_chains`]).
#[derive(Debug, Clone)]
struct MergedChains {
    chains: usize,
    absorbed: usize,
    described: String,
}

/// Slice 24a (OD-226): `refusal` of the route over the merged-chain quotient
/// whose chains `described` names, as the owner reports it: every
/// `Unsupported` but the empty observable (OD-115) names the chains
/// ([`X86BodyUnsupported::OverQuotient`], once); a mismatch names machine
/// rows, blocks and counts, which the quotient machine shares with the
/// original, and is returned as it is.
fn over_chains(described: &str, refusal: X86BodyRefusal) -> X86BodyRefusal {
    match refusal {
        X86BodyRefusal::Unsupported(reason)
            if !matches!(
                reason,
                X86BodyUnsupported::NoObservable | X86BodyUnsupported::OverQuotient { .. }
            ) =>
        {
            X86BodyRefusal::Unsupported(X86BodyUnsupported::OverQuotient {
                chains: described.to_owned(),
                reason: Box::new(reason),
            })
        }
        other => other,
    }
}

/// Slice 23 (OD-205): the theorem of an owner without the arithmetic pairing
/// (its statement and, for one stated in parts, its parts), built with the
/// owner's own walks: the exact spelling of slices 1 to 22, which alone
/// decides whether a paired theorem's refutation is one.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct X86UnpairedTheorem {
    obligation: std::sync::Arc<ProofObligation>,
    parts: std::sync::Arc<X86BodyParts>,
}

/// Slice 23 (OD-205): which of an owner's theorems a replay route runs: the
/// owner's (`Paired`, the canonical spelling) or the one without the
/// arithmetic pairing (`Unpaired`, [`X86UnpairedTheorem`]).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum X86Theorem {
    Paired,
    Unpaired,
}

/// The parts of an x86-64 body theorem stated in parts (slice 16): the
/// replayed obligations, in order, and the number of the statement's claims
/// each region accounts for. The parts are exactly the statement's split
/// ([`check_x86_body_parts`]).
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct X86BodyParts {
    region_claims: Vec<usize>,
    parts: Vec<ProofObligation>,
}

impl X86BodyParts {
    /// The number of the statement's claims each region accounts for.
    pub fn region_claims(&self) -> &[usize] {
        &self.region_claims
    }

    /// The replayed obligations, in order.
    pub fn parts(&self) -> &[ProofObligation] {
        &self.parts
    }

    /// Whether the parts are exactly the split of `statement`
    /// ([`check_x86_body_parts`]).
    pub fn check(&self, statement: &ProofObligation) -> Result<(), String> {
        check_x86_body_parts(statement, &self.region_claims, &self.parts)
    }

    /// Tests only: the same inventory with one part removed (the export and
    /// credit checks must refuse it).
    #[cfg(test)]
    pub(crate) fn without_part(&self, k: usize) -> Self {
        let mut fewer = self.clone();
        fewer.parts.remove(k);
        fewer
    }
}

/// One replayable part of a body theorem stated in parts (slice 16). No
/// public constructor: only [`SourceBoundX86Body::replay_parts`] hands one
/// out, so a part is always a part of an owner-built theorem.
pub struct X86BodyPart<'e> {
    obligation: &'e ProofObligation,
}

impl X86BodyPart<'_> {
    pub fn obligation(&self) -> &ProofObligation {
        self.obligation
    }
}

/// Slice 19 (OD-197): one claim of an owner-built theorem or part, replayed
/// on its own ([`split::claim_parts`]). No public constructor: only
/// [`SourceBoundX86Body::replay_claims`] hands one out, cut mechanically from
/// the owner's own replayed obligation.
pub struct X86BodyClaim {
    obligation: ProofObligation,
}

impl X86BodyClaim {
    pub fn obligation(&self) -> &ProofObligation {
        &self.obligation
    }

    /// Slice 23 (OD-206): the replay capability of this claim's
    /// generalization over its arithmetic leaves ([`split::generalize`]);
    /// `Err` when it has none.
    pub fn generalized(&self) -> Result<X86BodyGeneralized, String> {
        Ok(X86BodyGeneralized {
            obligation: split::generalize(&self.obligation)?,
        })
    }
}

/// Slice 23 (ruling OD-206): the generalization of an owner-built theorem,
/// part or claim over its arithmetic leaves ([`split::generalize`]), replayed
/// once after the exact obligation's replay was neither Valid nor refuted. No
/// public constructor: only [`SourceBoundX86Body::replay_generalized`] and
/// [`X86BodyClaim::generalized`] hand one out, cut mechanically from the
/// owner's own obligation. Its Valid replay credits the obligation
/// (instantiation); any other outcome is no verdict (a satisfying model
/// gives a leaf a value its operation may never compute: OD-200's rule).
pub struct X86BodyGeneralized {
    obligation: ProofObligation,
}

impl X86BodyGeneralized {
    pub fn obligation(&self) -> &ProofObligation {
        &self.obligation
    }
}

/// Slice 23 (ruling OD-206): how the generalizations credited one replayed
/// obligation of an x86-64 body theorem: its generalization, when that
/// credited it whole; else (an obligation credited claim by claim) each
/// claim's generalization, when that credited the claim. Each is exactly
/// [`split::generalize`] of what it generalizes ([`X86BodyClaims::check`]).
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct X86UnitGeneralized {
    whole: Option<ProofObligation>,
    claims: Vec<Option<ProofObligation>>,
}

impl X86UnitGeneralized {
    /// Credited whole by its generalization `generalized`.
    pub(crate) fn whole(generalized: ProofObligation) -> Self {
        Self {
            whole: Some(generalized),
            claims: Vec::new(),
        }
    }

    /// Credited claim by claim, each claim by itself or (`Some`) by its
    /// generalization.
    pub(crate) fn claims(claims: Vec<Option<ProofObligation>>) -> Self {
        Self {
            whole: None,
            claims,
        }
    }

    /// Whether a generalization credited anything here.
    pub fn any(&self) -> bool {
        self.whole.is_some() || self.claims.iter().any(Option::is_some)
    }

    /// The generalization that credited the obligation whole.
    pub fn whole_generalization(&self) -> Option<&ProofObligation> {
        self.whole.as_ref()
    }

    /// The generalization that credited claim `k`.
    pub fn claim_generalization(&self, k: usize) -> Option<&ProofObligation> {
        self.claims.get(k).and_then(Option::as_ref)
    }
}

/// Slice 19 (OD-197): which replayed obligations of an x86-64 body theorem
/// (its parts in order, or the theorem itself when not stated in parts) its
/// credit replayed claim by claim, with those claims: exactly
/// [`split::claim_parts`] of the obligation ([`Self::check`]). A consumer
/// publishes an obligation's claims in its place.
///
/// Slice 23 (OD-206): it also records the generalizations that credited an
/// obligation or a claim ([`X86UnitGeneralized`]); a consumer publishes each
/// in the place of what it generalizes, once it checks as its generalization.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct X86BodyClaims {
    units: Vec<Option<Vec<ProofObligation>>>,
    /// Slice 23 (OD-206): one entry per replayed obligation, or none when no
    /// generalization credited anything.
    generalized: Vec<X86UnitGeneralized>,
}

impl X86BodyClaims {
    /// One entry per replayed obligation, in order: its claims when it was
    /// credited claim by claim.
    pub(crate) fn new(units: Vec<Option<Vec<ProofObligation>>>) -> Self {
        Self {
            units,
            generalized: Vec::new(),
        }
    }

    /// Slice 23 (OD-206): this record with `generalized`, one entry per
    /// replayed obligation.
    pub(crate) fn with_generalized(self, generalized: Vec<X86UnitGeneralized>) -> Self {
        Self {
            generalized: if generalized.iter().any(X86UnitGeneralized::any) {
                generalized
            } else {
                Vec::new()
            },
            ..self
        }
    }

    /// Whether any replayed obligation was credited claim by claim, or (slice
    /// 23) by a generalization.
    pub fn any(&self) -> bool {
        self.units.iter().any(Option::is_some)
            || self.generalized.iter().any(X86UnitGeneralized::any)
    }

    /// Slice 23 (OD-206): how generalizations credited replayed obligation
    /// `unit` (`None` when none did).
    pub fn generalized_of(&self, unit: usize) -> Option<&X86UnitGeneralized> {
        self.generalized.get(unit).filter(|unit| unit.any())
    }

    /// The obligations a consumer publishes for replayed obligation `unit`
    /// (`obligation`), in order, once [`Self::check`] holds: its
    /// generalization, when that credited it whole; its claims (each claim's
    /// generalization in its place where that credited the claim), when it
    /// was credited claim by claim; else the obligation itself.
    pub fn published<'u>(
        &'u self,
        unit: usize,
        obligation: &'u ProofObligation,
    ) -> Vec<&'u ProofObligation> {
        let general = self.generalized.get(unit);
        if let Some(whole) = general.and_then(|general| general.whole.as_ref()) {
            return vec![whole];
        }
        match self.claims_of(unit) {
            Some(claims) => claims
                .iter()
                .enumerate()
                .map(|(k, claim)| {
                    general
                        .and_then(|general| general.claim_generalization(k))
                        .unwrap_or(claim)
                })
                .collect(),
            None => vec![obligation],
        }
    }

    /// The claims of replayed obligation `unit`, when it was credited claim
    /// by claim.
    pub fn claims_of(&self, unit: usize) -> Option<&[ProofObligation]> {
        self.units.get(unit).and_then(|claims| claims.as_deref())
    }

    /// Whether these are, obligation by obligation, exactly the claim split
    /// of `units` (the theorem's replayed obligations, in order).
    pub fn check(&self, units: &[&ProofObligation]) -> Result<(), String> {
        if self.units.len() != units.len() {
            return Err(format!(
                "a claim record of {} obligations for a theorem of {}",
                self.units.len(),
                units.len()
            ));
        }
        for (k, (claims, unit)) in self.units.iter().zip(units).enumerate() {
            if let Some(claims) = claims
                && split::claim_parts(unit)? != *claims
            {
                return Err(format!(
                    "the claims of obligation {} of {} are not its claim split",
                    k + 1,
                    units.len()
                ));
            }
        }
        self.check_generalized(units)
    }

    /// Slice 23 (OD-206): whether every recorded generalization is exactly
    /// [`split::generalize`] of what it generalizes (the obligation, or its
    /// claim), re-derived here, with one entry per replayed obligation; an
    /// obligation credited whole by its generalization was not split, and a
    /// claim generalization belongs to a claim of the split.
    pub fn check_generalized(&self, units: &[&ProofObligation]) -> Result<(), String> {
        if self.generalized.is_empty() {
            return Ok(());
        }
        if self.generalized.len() != units.len() {
            return Err(format!(
                "a generalization record of {} obligations for a theorem of {}",
                self.generalized.len(),
                units.len()
            ));
        }
        for (k, ((general, unit), claims)) in self
            .generalized
            .iter()
            .zip(units)
            .zip(&self.units)
            .enumerate()
        {
            let at = format!("obligation {} of {}", k + 1, units.len());
            if let Some(whole) = &general.whole {
                if claims.is_some() || !general.claims.is_empty() {
                    return Err(format!(
                        "{at} is recorded both generalized whole and claim by claim"
                    ));
                }
                if split::generalize(unit)? != *whole {
                    return Err(format!(
                        "{at}'s recorded generalization is not its generalization"
                    ));
                }
            }
            if general.claims.is_empty() {
                continue;
            }
            let Some(claims) = claims else {
                return Err(format!(
                    "{at} records claim generalizations but was not credited claim by claim"
                ));
            };
            if general.claims.len() != claims.len() {
                return Err(format!(
                    "{at} records {} claim generalizations for {} claims",
                    general.claims.len(),
                    claims.len()
                ));
            }
            for (i, (generalized, claim)) in general.claims.iter().zip(claims).enumerate() {
                if let Some(generalized) = generalized
                    && split::generalize(claim)? != *generalized
                {
                    return Err(format!(
                        "{at}: claim {}'s recorded generalization is not its generalization",
                        i + 1
                    ));
                }
            }
        }
        Ok(())
    }
}

/// Slice 23 (ruling OD-205): one paired row of a pairing record
/// ([`X86BodyPairing`]): its operator key, the source's operands `(a, b)`,
/// the row's own operands `(c, d)` in the walk's order (`crossed`: claimed as
/// `(d, c)`, a commutative key's crossing), and each name the row defines,
/// with the part of the key's term it holds and its WALK definition (read
/// from the walk's own table, never from the pairing step).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct X86PairedRow {
    key: ArithKey,
    source: (E, E),
    machine: (E, E),
    crossed: bool,
    results: Vec<(String, ArithPart, E)>,
}

/// Slice 23 (ruling OD-205): the pairing record of a paired x86-64 body
/// theorem: each paired row ([`X86PairedRow`]), and the theorem as built
/// before its spelling (its definitions in order, the paired names' new ones
/// among them, and its two sides, the operand claims among their conjuncts)
/// with the spelling's choices ([`SpellingChoice`]). Every consumer re-derives
/// the pairing from it before it credits or publishes the paired theorem
/// ([`Self::check`]), so the pairing step of the builder is not trusted:
/// - check (3): each paired name's walk definition is its part of the row's
///   own `K(c, d)`;
/// - its definition in the theorem is the same part of the same key's
///   `K(a, b)`, and `a`, `b`, `c` and `d` read only names defined before it;
/// - each operand claim (`a = c` and `b = d` at the bits `K` reads,
///   [`ArithKey::read_operand`]) that is no identity is an unconditional
///   conjunct of the theorem's claims against `true`;
/// - the statement is the spelling of the recorded theorem
///   ([`spell_statement`]), which binds the record to the published bytes.
///
/// Given these, Theorem A (design §2.2) holds whatever the stamp chose: on
/// every input the claims make the paired name's value `K(a, b)` equal to
/// `K(c, d)`, its walk definition's, so the theorem with every paired name
/// defined by its walk definition and no operand claim is valid whenever the
/// statement is. What is trusted is what slices 1 to 22 trust: the walk's
/// definitions (the record's among them) and claims, and the spelling.
pub struct X86BodyPairing {
    rows: Vec<X86PairedRow>,
    definitions: Vec<(String, E)>,
    source_side: E,
    machine_side: E,
    choice: SpellingChoice,
    /// What [`Self::derive`] re-derives, once per record (an export shares
    /// one record between every row it credits). Never cloned: a copy
    /// derives again.
    derived: std::sync::OnceLock<Result<X86PairedStatement, String>>,
}

/// Slice 23 (OD-205): the statement a pairing record re-derives: the
/// premises, in the order the query states them, and the two sides.
#[derive(Debug, Clone, PartialEq, Eq)]
struct X86PairedStatement {
    preconditions: Vec<E>,
    source_side: E,
    machine_side: E,
}

impl Clone for X86BodyPairing {
    fn clone(&self) -> Self {
        Self {
            rows: self.rows.clone(),
            definitions: self.definitions.clone(),
            source_side: self.source_side.clone(),
            machine_side: self.machine_side.clone(),
            choice: self.choice,
            derived: std::sync::OnceLock::new(),
        }
    }
}

impl PartialEq for X86BodyPairing {
    fn eq(&self, other: &Self) -> bool {
        self.rows == other.rows
            && self.definitions == other.definitions
            && self.source_side == other.source_side
            && self.machine_side == other.machine_side
            && self.choice == other.choice
    }
}

impl Eq for X86BodyPairing {}

impl std::fmt::Debug for X86BodyPairing {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("X86BodyPairing")
            .field("rows", &self.rows)
            .field("definitions", &self.definitions.len())
            .field("choice", &self.choice)
            .finish_non_exhaustive()
    }
}

impl X86BodyPairing {
    fn new(
        rows: Vec<X86PairedRow>,
        definitions: Vec<(String, E)>,
        source_side: E,
        machine_side: E,
        choice: SpellingChoice,
    ) -> Self {
        Self {
            rows,
            definitions,
            source_side,
            machine_side,
            choice,
            derived: std::sync::OnceLock::new(),
        }
    }

    /// How many rows the record pairs.
    pub fn paired_rows(&self) -> usize {
        self.rows.len()
    }

    /// Whether `statement` (a paired theorem's) re-derives from this record:
    /// the record's pairing re-checked and the statement exactly its
    /// theorem's spelling ([`X86BodyPairing`]). `Err` names what fails.
    pub fn check(&self, statement: &ProofObligation) -> Result<(), String> {
        let derived = self
            .derived
            .get_or_init(|| self.derive())
            .as_ref()
            .map_err(Clone::clone)?;
        if statement.trust_ir_expr != derived.source_side
            || statement.aarch64_expr != derived.machine_side
            || statement.preconditions != derived.preconditions
        {
            return Err(
                "the paired statement is not the spelling of its pairing record's theorem".into(),
            );
        }
        Ok(())
    }

    /// The pairing re-checked, and the statement the record's theorem
    /// spells ([`Self::check`]).
    fn derive(&self) -> Result<X86PairedStatement, String> {
        if self.rows.is_empty() {
            return Err("a pairing record that pairs no row".into());
        }
        // The theorem is definitional in order: each name defined once,
        // reading free inputs and earlier names only (Theorem A's induction).
        let mut position: HashMap<&str, usize> = HashMap::with_capacity(self.definitions.len());
        for (at, (name, _)) in self.definitions.iter().enumerate() {
            if position.insert(name.as_str(), at).is_some() {
                return Err(format!("the recorded theorem defines `{name}` twice"));
            }
        }
        let before = |expr: &E, at: usize| {
            expr.free_vars().iter().all(|name| {
                position
                    .get(name.as_str())
                    .is_none_or(|&defined| defined < at)
            })
        };
        if let Some((name, _)) = self
            .definitions
            .iter()
            .enumerate()
            .find_map(|(at, (name, expr))| (!before(expr, at)).then_some((name, expr)))
        {
            return Err(format!(
                "the recorded definition of `{name}` reads a name defined at or after it"
            ));
        }
        // The theorem's unconditional claims: the conjuncts of its claims
        // against `true`.
        let mut conjuncts: HashSet<&E> = HashSet::new();
        if self.source_side == E::bool_const(true) {
            let mut pending = vec![&self.machine_side];
            while let Some(term) = pending.pop() {
                match term {
                    E::And { lhs, rhs } => {
                        pending.push(lhs.as_ref());
                        pending.push(rhs.as_ref());
                    }
                    other => {
                        conjuncts.insert(other);
                    }
                }
            }
        }
        let mut paired: HashSet<&str> = HashSet::new();
        for (k, row) in self.rows.iter().enumerate() {
            let what = format!("paired row {} of {}", k + 1, self.rows.len());
            let key = row.key;
            let ((a, b), (c, d)) = (&row.source, &row.machine);
            if !key.admits(a, b) || !key.admits(c, d) {
                return Err(format!("{what}: an operand outside its key {key:?}"));
            }
            if row.crossed && !key.commutative() {
                return Err(format!(
                    "{what}: crossed operands of a key {key:?} that does not commute"
                ));
            }
            if row.results.is_empty() {
                return Err(format!("{what}: no name"));
            }
            let own = key.apply(c.clone(), d.clone());
            let source = key.apply(a.clone(), b.clone());
            for (name, part, walked) in &row.results {
                if !paired.insert(name.as_str()) {
                    return Err(format!("{what}: `{name}` is paired twice"));
                }
                let Some(&at) = position.get(name.as_str()) else {
                    return Err(format!("{what}: `{name}` is not defined"));
                };
                // Check (3): the name's walk definition is its part of the
                // row's own `K(c, d)`.
                if *walked != part.of(own.clone(), key.bits) {
                    return Err(format!(
                        "{what}: `{name}`'s walk definition is not its part of the row's own \
                         K(c, d) (check (3))"
                    ));
                }
                // Its definition in the theorem: the same part of `K(a, b)`.
                if self.definitions[at].1 != part.of(source.clone(), key.bits) {
                    return Err(format!(
                        "{what}: `{name}` is not defined as its part of the source's K(a, b)"
                    ));
                }
                if ![a, b, c, d].into_iter().all(|operand| before(operand, at)) {
                    return Err(format!(
                        "{what}: an operand reads a name defined at or after `{name}`"
                    ));
                }
            }
            let (c, d) = if row.crossed { (d, c) } else { (c, d) };
            for (operand, (source, machine)) in [(a, c), (b, d)].into_iter().enumerate() {
                let source = key.read_operand(operand, source.clone());
                let machine = key.read_operand(operand, machine.clone());
                if source != machine && !conjuncts.contains(&source.eq_expr(machine)) {
                    return Err(format!(
                        "{what}: operand {} is not claimed equal unconditionally",
                        operand + 1
                    ));
                }
            }
        }
        let spelled = spell_statement(
            self.definitions.clone(),
            self.source_side.clone(),
            self.machine_side.clone(),
            &self.choice,
        )
        .ok_or_else(|| "the recorded theorem has no spelling under its choices".to_owned())?;
        Ok(X86PairedStatement {
            preconditions: spelled
                .definitions
                .into_iter()
                .rev()
                .map(|(name, expr)| {
                    let width = expr.bv_width();
                    E::var(name, width).eq_expr(expr)
                })
                .collect(),
            source_side: spelled.source_side,
            machine_side: spelled.machine_side,
        })
    }

    /// Tests only: this record with `edit` applied to its parts (a forged
    /// record every consumer must refuse).
    #[cfg(test)]
    pub(crate) fn forged(
        &self,
        edit: impl FnOnce(&mut Vec<X86PairedRow>, &mut Vec<(String, E)>, &mut E),
    ) -> Self {
        let mut forged = self.clone();
        edit(
            &mut forged.rows,
            &mut forged.definitions,
            &mut forged.machine_side,
        );
        forged
    }
}

/// Slice 23 (OD-205): what an export of an x86-64 body theorem carries of
/// OD-205's pairing.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub enum X86ExportPairing {
    /// The exported theorem pairs no row (and every export of another kind).
    #[default]
    NotPaired,
    /// The exported theorem is a paired one, with its pairing record (`None`:
    /// absent, which every consumer refuses).
    Paired(Option<std::sync::Arc<X86BodyPairing>>),
}

impl X86ExportPairing {
    /// Whether `statement`, the exported theorem's, may be published: one
    /// that pairs nothing always; a paired one only with its record, once the
    /// record re-derives it ([`X86BodyPairing::check`]).
    pub fn check(&self, statement: &ProofObligation) -> Result<(), String> {
        match self {
            Self::NotPaired => Ok(()),
            Self::Paired(None) => Err("a paired theorem without its pairing record".into()),
            Self::Paired(Some(pairing)) => pairing.check(statement),
        }
    }
}

impl<'a> SourceBoundX86Body<'a> {
    pub fn source(&self) -> &'a Function {
        self.source
    }

    pub fn machine(&self) -> &'a X86ISelFunction {
        self.machine
    }

    pub fn abi(&self) -> X86SourceBoundAbi {
        self.abi
    }

    /// The whole-body theorem. Construction is not discharge. For a function
    /// stated in parts (slice 16) it is the statement, the conjunction of every
    /// part's claims over all their definitions, which is never replayed:
    /// AY proves [`Self::parts`].
    pub fn obligation(&self) -> &ProofObligation {
        &self.obligation
    }

    /// The theorem, shared (exports hold it once for every row they credit).
    pub(crate) fn shared_obligation(&self) -> std::sync::Arc<ProofObligation> {
        std::sync::Arc::clone(&self.obligation)
    }

    /// Slice 21 (ruling OD-200): whether the theorem abstracts a rounding
    /// operation: the source has a rounding event or the machine a rounding
    /// row. Its pairings claim operand patterns equal and its results are FP
    /// leaves, so a satisfying model of its negation (a pairing's operands
    /// differing, or a leaf no IEEE 754 unit computes) is no counterexample.
    pub fn is_fp_abstract(&self) -> bool {
        self.fp_abstract
    }

    /// OD-210, OD-217: the runtime routines whose contract the theorem
    /// trusts: the routine of each `I128` division (OD-202,
    /// [`i128_division_routine`]) and C memory routine (slice 13,
    /// [`memory_routine`]) it states as a call, ascending by name.
    pub fn trusted_routines(&self) -> impl Iterator<Item = &'static str> + '_ {
        self.routines.iter().copied()
    }

    /// Slice 24a (OD-226): for a theorem stated over the merged-chain
    /// quotient, the number of LIR chains it contracts and of blocks they
    /// absorb; `None` for a theorem over the original pair. The bound source
    /// and machine are the original's either way.
    pub fn merged_chains(&self) -> Option<(usize, usize)> {
        self.merged
            .as_ref()
            .map(|merged| (merged.chains, merged.absorbed))
    }

    /// Slice 24c (OD-228): for a theorem stated over segments, the number of
    /// segments, of their members other than their heads, and their kinds
    /// (`[diamond,silent,chain]`, [`segment::SegmentKind`]); `None` for a
    /// theorem over none. The bound source and machine are the original's.
    pub fn segments(&self) -> Option<(usize, usize, String)> {
        self.segments
            .as_ref()
            .map(|segments| (segments.segments, segments.members, segments.kinds()))
    }

    /// OD-233: how many cut-input bytes and value items a theorem stated in
    /// parts defines as the one term over the run's fixed inputs every edge
    /// into their cut brings (each claimed on every such edge); `(0, 0)` for
    /// any other theorem.
    pub fn defined_cut_inputs(&self) -> (usize, usize) {
        self.defined_inputs.counts
    }

    /// Tests only (OD-233): the statement's stated edges into cut points and
    /// the definition claims made on them.
    #[cfg(test)]
    fn definition_record(&self) -> &split::DefinitionRecord {
        &self.defined_inputs.record
    }

    /// Slice 16: whether the theorem is stated in parts.
    pub fn is_stated_in_parts(&self) -> bool {
        !self.parts.parts.is_empty()
    }

    /// Slice 16: the replayed parts of a theorem stated in parts, in order
    /// (empty for any other). The theorem holds exactly when every part does.
    pub fn parts(&self) -> &[ProofObligation] {
        &self.parts.parts
    }

    /// Slice 16: the part inventory, shared.
    pub(crate) fn shared_parts(&self) -> std::sync::Arc<X86BodyParts> {
        std::sync::Arc::clone(&self.parts)
    }

    /// Slice 16: the replay capabilities of [`Self::parts`], in order.
    pub fn replay_parts(&self) -> impl Iterator<Item = X86BodyPart<'_>> {
        self.parts
            .parts
            .iter()
            .map(|obligation| X86BodyPart { obligation })
    }

    /// Slice 19 (OD-197): the obligations replayed for the theorem, in
    /// order: its parts, or the theorem itself when not stated in parts.
    pub fn replayed_units(&self) -> Vec<&ProofObligation> {
        if self.is_stated_in_parts() {
            self.parts.parts.iter().collect()
        } else {
            vec![&self.obligation]
        }
    }

    /// Slice 19 (OD-197): the replay capabilities of the claims of replayed
    /// obligation `unit` ([`Self::replayed_units`]), each cut mechanically
    /// by [`split::claim_parts`]; `Err` when the obligation has no claim
    /// split (fewer than two distinct claims, a one-path theorem, or a claim
    /// that fails the part check).
    pub fn replay_claims(&self, unit: usize) -> Result<Vec<X86BodyClaim>, String> {
        let units = self.replayed_units();
        let obligation = units
            .get(unit)
            .ok_or_else(|| format!("no replayed obligation {}", unit + 1))?;
        Ok(split::claim_parts(obligation)?
            .into_iter()
            .map(|obligation| X86BodyClaim { obligation })
            .collect())
    }

    /// Slice 23 (OD-206): the replay capability of the generalization of
    /// replayed obligation `unit` ([`Self::replayed_units`]) over its
    /// arithmetic leaves ([`split::generalize`]); `Err` when it has none.
    pub fn replay_generalized(&self, unit: usize) -> Result<X86BodyGeneralized, String> {
        let units = self.replayed_units();
        let obligation = units
            .get(unit)
            .ok_or_else(|| format!("no replayed obligation {}", unit + 1))?;
        Ok(X86BodyGeneralized {
            obligation: split::generalize(obligation)?,
        })
    }

    /// Slice 23 (OD-205): whether the theorem pairs a row, so that its
    /// refutation is decided by the theorem without the pairing.
    pub fn is_paired(&self) -> bool {
        self.paired
    }

    /// Slice 23 (OD-205): whether the theorem without the pairing was built
    /// (only for a paired theorem).
    pub fn has_unpaired(&self) -> bool {
        self.unpaired.is_some()
    }

    /// Slice 23 (OD-205): the paired theorem's pairing record (`None` when
    /// the theorem pairs nothing, or a defect left it without one).
    pub fn pairing(&self) -> Option<&X86BodyPairing> {
        self.pairing.as_deref()
    }

    /// Slice 23 (OD-205): whether the owner's theorem may credit as far as
    /// its pairing goes: one that pairs nothing always; a paired one only
    /// with its pairing record, once the record re-derives it
    /// ([`X86BodyPairing::check`]). The verifier runs this before it
    /// replays the paired theorem, and every export carries what it needs.
    pub fn check_pairing(&self) -> Result<(), String> {
        self.export_pairing(X86Theorem::Paired)
            .check(&self.obligation)
    }

    /// Slice 23 (OD-205): what an export of `theorem` carries of the
    /// pairing ([`X86ExportPairing`]).
    pub(crate) fn export_pairing(&self, theorem: X86Theorem) -> X86ExportPairing {
        if theorem == X86Theorem::Paired && self.paired {
            X86ExportPairing::Paired(self.pairing.clone())
        } else {
            X86ExportPairing::NotPaired
        }
    }

    /// Tests only: this owner with its pairing record replaced (a forged
    /// record, or none).
    #[cfg(test)]
    pub(crate) fn with_pairing_record(self, pairing: Option<X86BodyPairing>) -> Self {
        Self {
            pairing: pairing.map(std::sync::Arc::new),
            ..self
        }
    }

    /// Slice 23: the statement of `theorem` (`None`: no such theorem).
    pub fn statement_of(&self, theorem: X86Theorem) -> Option<std::sync::Arc<ProofObligation>> {
        match theorem {
            X86Theorem::Paired => Some(self.shared_obligation()),
            X86Theorem::Unpaired => self
                .unpaired
                .as_ref()
                .map(|unpaired| std::sync::Arc::clone(&unpaired.obligation)),
        }
    }

    /// Slice 23: the part inventory of `theorem` (`None`: not stated in
    /// parts, or no such theorem).
    pub(crate) fn parts_of(&self, theorem: X86Theorem) -> Option<std::sync::Arc<X86BodyParts>> {
        let parts = match theorem {
            X86Theorem::Paired => self.shared_parts(),
            X86Theorem::Unpaired => std::sync::Arc::clone(&self.unpaired.as_ref()?.parts),
        };
        (!parts.parts.is_empty()).then_some(parts)
    }

    /// Slice 23: the obligations replayed for `theorem`, in order (its parts,
    /// or its statement); empty for no such theorem.
    pub fn replayed_units_of(&self, theorem: X86Theorem) -> Vec<&ProofObligation> {
        match theorem {
            X86Theorem::Paired => self.replayed_units(),
            X86Theorem::Unpaired => match &self.unpaired {
                None => Vec::new(),
                Some(unpaired) if unpaired.parts.parts.is_empty() => vec![&unpaired.obligation],
                Some(unpaired) => unpaired.parts.parts.iter().collect(),
            },
        }
    }

    /// Slice 23: whether `theorem`'s parts are exactly its statement's split
    /// ([`check_x86_body_parts`]); always for a theorem not in parts.
    pub fn check_parts_of(&self, theorem: X86Theorem) -> Result<(), String> {
        match (theorem, &self.unpaired) {
            (X86Theorem::Paired, _) => self.check_parts(),
            (X86Theorem::Unpaired, None) => Err("no theorem without the pairing".into()),
            (X86Theorem::Unpaired, Some(unpaired)) if unpaired.parts.parts.is_empty() => Ok(()),
            (X86Theorem::Unpaired, Some(unpaired)) => unpaired.parts.check(&unpaired.obligation),
        }
    }

    /// Slice 23: the replay capability of replayed obligation `unit` of
    /// `theorem` ([`Self::replayed_units_of`]).
    pub fn replay_unit_of(&self, theorem: X86Theorem, unit: usize) -> Option<X86BodyPart<'_>> {
        self.replayed_units_of(theorem)
            .get(unit)
            .map(|obligation| X86BodyPart { obligation })
    }

    /// Slice 23: [`Self::replay_claims`] of `theorem`'s obligation `unit`.
    pub fn replay_claims_of(
        &self,
        theorem: X86Theorem,
        unit: usize,
    ) -> Result<Vec<X86BodyClaim>, String> {
        let units = self.replayed_units_of(theorem);
        let obligation = units
            .get(unit)
            .ok_or_else(|| format!("no replayed obligation {}", unit + 1))?;
        Ok(split::claim_parts(obligation)?
            .into_iter()
            .map(|obligation| X86BodyClaim { obligation })
            .collect())
    }

    /// Slice 23: [`Self::replay_generalized`] of `theorem`'s obligation
    /// `unit`.
    pub fn replay_generalized_of(
        &self,
        theorem: X86Theorem,
        unit: usize,
    ) -> Result<X86BodyGeneralized, String> {
        let units = self.replayed_units_of(theorem);
        let obligation = units
            .get(unit)
            .ok_or_else(|| format!("no replayed obligation {}", unit + 1))?;
        Ok(X86BodyGeneralized {
            obligation: split::generalize(obligation)?,
        })
    }

    /// Slice 16: whether the parts are exactly the statement's split
    /// ([`check_x86_body_parts`]); always for a theorem not in parts.
    pub fn check_parts(&self) -> Result<(), String> {
        if self.parts.parts.is_empty() {
            return Ok(());
        }
        self.parts.check(&self.obligation)
    }

    /// Walk ordinals (the verifier's `inst_index`: `block_order` blocks, then
    /// their instructions) of every row the theorem covers: every row a
    /// paired machine path runs except `Jmp`, `Ret`, `Ud2`, `Call` and inert
    /// `Nop` (value rows, loads and stores, compares and tests, and, slice 6,
    /// the `jcc`s whose directions the theorem states), live or dead.
    /// Ascending.
    pub fn bound_rows(&self) -> &[usize] {
        &self.bound_rows
    }

    /// Whether the walk ordinal `row` is covered by the theorem.
    pub fn covers(&self, row: usize) -> bool {
        self.bound_rows.binary_search(&row).is_ok()
    }

    /// Audit map: each source definition name and the LIR `(block, index)`
    /// it was built from.
    pub fn source_definitions(&self) -> &[(String, Block, usize)] {
        &self.source_definitions
    }

    /// Audit map: each machine definition name and the walk ordinal of the
    /// row whose write it names.
    pub fn machine_definitions(&self) -> &[(String, usize)] {
        &self.machine_definitions
    }

    /// Audit map of the paired direct calls, in execution order: the source
    /// call's LIR `(block, index)` and the walk ordinal of the machine `Call`
    /// row the walk paired with it (same position, same callee symbol and
    /// binding). The `k`-th pair's result is the free input `r{k}`.
    pub fn call_sites(&self) -> &[(Block, usize, usize)] {
        &self.call_sites
    }

    /// Audit map of the paired incoming-memory accesses (slice 4), in
    /// execution order: the source `Load`/`Store`'s LIR `(block, index)` and
    /// the walk ordinal of the machine load/store row paired with it (same
    /// position in the access trace, same kind and width). A paired load
    /// reads the free input `l{j}`; private stack accesses are not listed.
    pub fn access_sites(&self) -> &[(Block, usize, usize)] {
        &self.access_sites
    }
}

/// Why [`source_bound_x86_body`] built no theorem.
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
pub enum X86BodyRefusal {
    /// Outside the checked domain: no claim; ordinary coverage rules apply.
    #[error("unsupported source-bound x86-64 body: {0}")]
    Unsupported(X86BodyUnsupported),
    /// An admitted source whose recognized machine body is wrong. Enforcing
    /// callers reject the function by name.
    #[error("source-bound x86-64 body mismatch: {0}")]
    Mismatch(X86BodyMismatch),
}

impl X86BodyRefusal {
    /// The typed mismatch, when this refusal identifies an erroneous target.
    pub fn mismatch(&self) -> Option<&X86BodyMismatch> {
        match self {
            Self::Mismatch(mismatch) => Some(mismatch),
            Self::Unsupported(_) => None,
        }
    }
}

/// A (source, machine, ABI) triple outside the lane. None of these grants or
/// withholds any other authority.
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
pub enum X86BodyUnsupported {
    #[error("no calling convention was supplied")]
    NoAbi,
    #[error("calling convention {0:?} is outside the lane (System V only)")]
    Abi(X86SourceBoundAbi),
    /// The LIR control flow is outside the domain (slices 6, 9 and 12): an
    /// irreducible cycle or a loop the lane does not admit, an unmodelled
    /// terminator, an unreachable block, or more blocks or instructions than
    /// the lane bounds. The detail names which.
    #[error("LIR source control flow is outside the acyclic domain: {0}")]
    SourceShape(String),
    #[error("LIR source is outside the body domain: {0}")]
    SourceDomain(String),
    #[error("machine function is outside the body domain: {0}")]
    MachineFunction(String),
    #[error("machine row {row} is outside the body domain ({BODY_OPCODES}): {detail}")]
    MachineRow { row: usize, detail: String },
    /// The machine's incoming-memory accesses and calls do not follow the
    /// source's in number, order, kind or width. The access-trace theorem
    /// pairs them positionally, so it makes no claim about such a body (a
    /// reordering can be correct, for instance two loads swapped).
    #[error(
        "the machine's incoming-memory access trace differs from its LIR source's ({detail}); \
         the access-trace theorem pairs accesses positionally and makes no claim"
    )]
    AccessTrace { detail: String },
    /// The admitted body has nothing a caller or callee observes: no result
    /// and no call argument. A theorem over an empty observable would be
    /// vacuous, so none is built.
    #[error(
        "the body has no value observable (no result and no call argument), so no \
         non-vacuous theorem exists"
    )]
    NoObservable,
    /// A builder invariant failed (a premise that is not a fresh definition,
    /// a use before definition, a degenerate side). Never credit.
    #[error("the body theorem failed its definitional construction check: {0}")]
    Construction(String),
    /// Slice 24a (OD-226): a refusal of the theorem over the merged-chain
    /// quotient ([`quotient`]): `reason` is stated over the quotient, whose
    /// contracted `chains` (in the ORIGINAL LIR ids) the suffix names. The
    /// reason's own text comes first, so a parser of today's refusal texts
    /// still matches it.
    #[error("{reason} (over the merged-chain quotient: chains {chains})")]
    OverQuotient {
        chains: String,
        reason: Box<X86BodyUnsupported>,
    },
    /// Slice 24c (OD-228): a refusal of the theorem stated over segments
    /// ([`segment`]): `reason` is stated over them, and the suffix names each
    /// one's members (in the stated pair's LIR ids). The reason's own text
    /// comes first, as for [`Self::OverQuotient`].
    #[error("{reason} (over segments: {segments})")]
    OverSegments {
        segments: String,
        reason: Box<X86BodyUnsupported>,
    },
    /// OD-210, OD-216, OD-217: the theorem would trust the contract of a runtime
    /// routine (OD-202: an `I128` division's routine; slice 13: a C memory
    /// routine) that nothing outside the link unit under proof binds, so no
    /// theorem is built.
    #[error(
        "the body calls the runtime routine `{routine}`, whose contract the theorem would \
         trust, but {definition} (rulings OD-210, OD-216, OD-217)"
    )]
    TrustedRoutine {
        routine: String,
        definition: X86RoutineDefinition,
    },
}

/// OD-210, OD-216, OD-217: why a trusted runtime routine's call is refused
/// ([`X86BodyUnsupported::TrustedRoutine`]).
#[derive(Debug, Clone, Copy, PartialEq, Eq, thiserror::Error)]
pub enum X86RoutineDefinition {
    /// The function under proof is the routine: its own division or copy
    /// would call itself, and the contract would be assumed of the body under
    /// proof.
    #[error("the function under proof is that routine")]
    TheFunction,
    /// The module under proof defines the routine, so its call binds to that
    /// unchecked definition.
    #[error("the module under proof defines it")]
    TheModule,
    /// OD-216: another compile unit of the module's link unit defines the
    /// routine, as the frontend states (for the rustc bridge, another codegen
    /// unit of the crate, or another function module of the same one), so
    /// the call binds to that unchecked definition.
    #[error("another compile unit of its link unit (crate) defines it")]
    TheLinkUnit,
    /// The caller named no module, so whether the module defines the routine
    /// is unknown.
    #[error("no module was named, so its definition is unknown")]
    Unnamed,
}

/// A recognized body that disagrees with its admitted source or with its own
/// control skeleton. No correct lowering produces one.
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
pub enum X86BodyMismatch {
    #[error("machine signature differs from the LIR source signature")]
    Signature,
    #[error("machine block layout is inconsistent: {0}")]
    Layout(String),
    #[error("block {block:?} (row {row:?}) {detail}")]
    Control {
        block: Block,
        row: Option<usize>,
        detail: String,
    },
    #[error("block {block:?} is not on the chain from the entry block")]
    UnreachableBlock { block: Block },
    #[error("row {row} reads {operand}, which holds no defined value")]
    UndefinedRead { row: usize, operand: String },
    #[error("row {row} writes {register}, which the caller observes unchanged")]
    PreservedWrite { row: usize, register: &'static str },
    #[error("the return observes {register}, which holds no defined value")]
    UndefinedReturn { register: &'static str },
    #[error(
        "the machine returns a different value in result lane {lane} than its LIR source (exact \
         affine evaluation)"
    )]
    ReturnValue { lane: usize },
    /// A symbol-address row (`LeaRip`/`MovRipRel`) names a symbol, or a form
    /// of reference, that its LIR source never takes the address of.
    #[error(
        "row {row} takes the address of {symbol}, which its LIR source does not reference in \
         that form"
    )]
    Symbol { row: usize, symbol: String },
    #[error("the machine makes {machine} direct call(s) where its LIR source makes {lir}")]
    CallCount { lir: usize, machine: usize },
    #[error(
        "call row {row} targets {found}, where the source's call in that position targets {expected}"
    )]
    CallTarget {
        row: usize,
        expected: String,
        found: String,
    },
    #[error("call row {row} {detail}")]
    CallMetadata { row: usize, detail: String },
    #[error(
        "call {call} passes a different argument {argument} than its LIR source (exact affine \
         evaluation)"
    )]
    CallArgument { call: usize, argument: usize },
    /// Slice 7: a call row passes a private stack address (slot and offset)
    /// other than the one its paired source call passes in that argument, or
    /// a private address where the source passes none.
    #[error(
        "call row {row} passes {found} as argument {argument} where its LIR source passes {expected}"
    )]
    CallStackAddress {
        row: usize,
        argument: usize,
        expected: String,
        found: String,
    },
    #[error(
        "incoming-memory access {access} addresses a different location than its LIR source \
         (exact affine evaluation)"
    )]
    MemoryAddress { access: usize },
    #[error(
        "incoming-memory store {access} writes a different value than its LIR source (exact \
         affine evaluation)"
    )]
    MemoryValue { access: usize },
    #[error(
        "row {row} accesses bytes {first}..{end} of private stack slot {slot}, which has {size}"
    )]
    StackSlotBounds {
        row: usize,
        slot: u32,
        first: i64,
        end: i64,
        size: u32,
    },
}

fn unsupported(reason: X86BodyUnsupported) -> X86BodyRefusal {
    X86BodyRefusal::Unsupported(reason)
}

fn mismatch(reason: X86BodyMismatch) -> X86BodyRefusal {
    X86BodyRefusal::Mismatch(reason)
}

/// The source side of the owner's admission under `abi`: [`admitted_body`]
/// admits `source`, or a source past the single-query LIR bounds is admitted
/// as one body at the bounds of a function stated in parts. It is exact for a
/// pair one query states, but it is no over-approximation of the owner: a
/// source stated in parts is admitted region by region from its cut
/// interfaces (several edges into a loop header meet at its interface, which
/// the whole-body admission refuses), and a source within the LIR bounds is
/// stated in parts when its machine is past them. Whether the owner may
/// build a theorem for a pair is [`pair_admits_x86_body_owner`].
pub fn source_admits_x86_body_owner(source: &Function, abi: Option<X86SourceBoundAbi>) -> bool {
    admitted_abi(abi).is_ok()
        && (admitted_body(source).is_ok() || split::source_admits_split(source))
}

/// Whether [`source_bound_x86_body_in_module`] may build a theorem for
/// `source` and `machine` under `abi`, decided before any machine walk and
/// whatever module is named: for a pair one query states
/// ([`split::fits_one_query`]), exactly whether [`admitted_body`] admits the
/// source; for a pair stated in parts (slice 16), the checks the split makes
/// before it plans its cut points ([`split::pair_may_split`]). `false` means
/// the owner refuses the pair; `true` claims nothing. The AOT certificate
/// lane routes a pair on it (OD-210, amended: a routing predicate that is no
/// over-approximation sent `core`'s `exp_u128` and `parse_decimal_seq`, both
/// stated in parts, down the walk that once named no module).
pub fn pair_admits_x86_body_owner(
    source: &Function,
    machine: &X86ISelFunction,
    abi: Option<X86SourceBoundAbi>,
) -> bool {
    admitted_abi(abi).is_ok()
        && if split::fits_one_query(source, machine) {
            admitted_body(source).is_ok()
        } else {
            split::pair_may_split(source, machine)
        }
}

/// [`source_bound_x86_body_in_module`] for a caller that names no module:
/// a theorem that would trust a runtime routine's contract (an `I128`
/// division, OD-202; a C memory routine, slice 13 and OD-217) is refused
/// (OD-210, [`X86RoutineDefinition::Unnamed`]); every other one is the same.
pub fn source_bound_x86_body<'a>(
    source: &'a Function,
    machine: &'a X86ISelFunction,
    abi: Option<X86SourceBoundAbi>,
) -> Result<SourceBoundX86Body<'a>, X86BodyRefusal> {
    source_bound_x86_body_in_module(source, machine, abi, None)
}

/// Build the whole-body theorem for an admitted source and a recognized
/// machine body of a function of the module whose definitions are `module`
/// (`None`: unnamed). OD-210, OD-216: a theorem that trusts the contract of a
/// runtime routine the function itself is, the module or its link unit
/// defines, or (no module named) anything may define, is refused
/// ([`check_trusted_routines`]); slice 24a (OD-226): over the merged-chain
/// quotient, that refusal names the chains too ([`over_chains`]); slice 24c
/// (OD-228): over segments, the segments first ([`segment::over_segments`]).
pub fn source_bound_x86_body_in_module<'a>(
    source: &'a Function,
    machine: &'a X86ISelFunction,
    abi: Option<X86SourceBoundAbi>,
    module: Option<&X86ModuleDefinitions>,
) -> Result<SourceBoundX86Body<'a>, X86BodyRefusal> {
    let owner = build_x86_body(source, machine, abi)?;
    check_trusted_routines(&owner, module).map_err(|refusal| {
        let refusal = match &owner.segments {
            Some(segments) => segment::over_segments(&segments.described, refusal),
            None => refusal,
        };
        match &owner.merged {
            Some(merged) => over_chains(&merged.described, refusal),
            None => refusal,
        }
    })?;
    Ok(owner)
}

/// Build the whole-body theorem for an admitted source and a recognized
/// machine body. See the module documentation. Slice 16: a pair past the
/// single-query bounds ([`split::fits_one_query`]) is stated in parts. The
/// module's definitions are checked by the caller
/// ([`source_bound_x86_body_in_module`]).
fn build_x86_body<'a>(
    source: &'a Function,
    machine: &'a X86ISelFunction,
    abi: Option<X86SourceBoundAbi>,
) -> Result<SourceBoundX86Body<'a>, X86BodyRefusal> {
    if !split::fits_one_query(source, machine) {
        return split::source_bound_split(source, machine, abi, &split::SplitPolicy::PRODUCTION);
    }
    with_stated_pair(source, machine, abi, None, |body, cfg, quotient, abi| {
        finish_owner(body, cfg, quotient, source, machine, abi)
    })
}

/// Slice 24a (OD-226): whether the walk of an admitted body reads no block
/// correspondence: a one-path source whose machine has no conditional jump is
/// its machine chain ([`walk_machine_for_callers`], whose routing reads this
/// one test). Such a pair keeps its theorem, and its refusals, byte for byte:
/// no quotient is stated for it.
fn states_machine_chain(body: &SourceBody, cfg: &MachineCfg<'_>) -> bool {
    body.loops.is_none() && body.dag.is_none() && body.paths.len() == 1 && !cfg.has_jcc
}

/// The single-query statement of `source` and `machine` (slices 1 to 23),
/// handed to `state`: the admitted body (`dag` as [`admitted_body_as`]), its
/// machine skeleton, the pair it is stated over and the ABI. Slice 24a
/// (OD-226): when the original pair has no block correspondence and its walk
/// needs one ([`states_machine_chain`]), the pair stated is the merged-chain
/// quotient the stamps choose ([`quotient::Quotient::of`]), admitted with the
/// original's encoding ([`admitted_quotient`]); with no chain to contract,
/// the original pair, its refusal naming why ([`quotient::Quotient::annotate`]).
/// Slice 24c (OD-228): either pair, still without one, is stated over the
/// segments its stamps choose ([`segment::restate`]), and every refusal of
/// `state` but the empty observable names them ([`segment::Segments::over`]).
/// Every other pair is the original, unchanged. The owner and every test-only
/// builder state their theorems through this one function.
fn with_stated_pair<T>(
    source: &Function,
    machine: &X86ISelFunction,
    abi: Option<X86SourceBoundAbi>,
    dag: Option<bool>,
    state: impl FnOnce(
        &SourceBody,
        &MachineCfg<'_>,
        &quotient::Quotient<'_>,
        X86SourceBoundAbi,
    ) -> Result<T, X86BodyRefusal>,
) -> Result<T, X86BodyRefusal> {
    let body = admitted_body_as(source, dag)?;
    let abi = admitted_abi(abi)?;
    let mut cfg = machine_skeleton(source, machine, &body.machine_slots, &body.dead)?;
    if cfg.correspondence.is_err()
        && (!states_machine_chain(&body, &cfg) || mutated("route-gate-off"))
    {
        // Admitted already: the source's control flow is in the domain.
        let source_flow = source_cfg(source)?;
        let quotient = quotient::Quotient::of(source, machine, &source_flow)?;
        if !quotient.is_identity() {
            return owner_over_quotient(&quotient, &body, abi, state);
        }
        // Slice 24c (OD-228): the correspondence over the segments the
        // stamps choose, or the refusal naming why there is none.
        segment::restate(&mut cfg, source, &source_flow, Some(&quotient))?;
        let segments = stated_segments(&cfg);
        return state(&body, &cfg, &quotient, abi).map_err(|refusal| segments.over(refusal));
    }
    state(
        &body,
        &cfg,
        &quotient::Quotient::identity(source, machine),
        abi,
    )
}

/// Slice 24a (OD-226): `state` over a non-identity quotient: the quotient's
/// admission with the original body's encoding ([`admitted_quotient`]), its
/// machine skeleton (slice 24c: over the quotient's segments, when it has no
/// block correspondence of its own), then `state`. Every refusal but the
/// empty observable names the segments, then the chains
/// ([`quotient::Quotient::over`]).
fn owner_over_quotient<T>(
    quotient: &quotient::Quotient<'_>,
    body: &SourceBody,
    abi: X86SourceBoundAbi,
    state: impl FnOnce(
        &SourceBody,
        &MachineCfg<'_>,
        &quotient::Quotient<'_>,
        X86SourceBoundAbi,
    ) -> Result<T, X86BodyRefusal>,
) -> Result<T, X86BodyRefusal> {
    let stated = || {
        let quotient_body = admitted_quotient(quotient.source(), body)?;
        let mut cfg = machine_skeleton(
            quotient.source(),
            quotient.machine(),
            &quotient_body.machine_slots,
            &quotient_body.dead,
        )?;
        // Slice 24c (OD-228): segments over the quotient pair.
        if cfg.correspondence.is_err() {
            let quotient_flow = source_cfg(quotient.source())?;
            segment::restate(&mut cfg, quotient.source(), &quotient_flow, Some(quotient))?;
        }
        let segments = stated_segments(&cfg);
        state(&quotient_body, &cfg, quotient, abi).map_err(|refusal| segments.over(refusal))
    };
    stated().map_err(|refusal| quotient.over(refusal))
}

/// Slice 24c (OD-228): the segments a skeleton's correspondence is stated
/// over (none without a correspondence).
fn stated_segments(cfg: &MachineCfg<'_>) -> segment::Segments {
    cfg.correspondence
        .as_ref()
        .map(|correspondence| correspondence.segments.clone())
        .unwrap_or_default()
}

/// Slice 24a (OD-226): the admission of a merged-chain quotient `source`
/// with the encoding the ORIGINAL source's admission `original` chose
/// (OD-191): its DAG or its paths (`Some(dag)`, [`admitted_body_as`]), and its
/// long-chain trim. The quotient has fewer blocks and shorter paths (its
/// contracted `Jump`s no longer count), so its own shape could choose another
/// spelling; the original's is kept. Loops come first in the admission, and
/// the quotient has the original's loops.
fn admitted_quotient(
    source: &Function,
    original: &SourceBody,
) -> Result<SourceBody, X86BodyRefusal> {
    if mutated("encoding-from-quotient") {
        return admitted_body(source);
    }
    let frame = admitted_frame(source)?;
    let cfg = source_cfg(source)?;
    let mut body = admitted_body_over(source, Some(original.dag.is_some()), frame, cfg)?;
    body.long_chain = original.long_chain;
    Ok(body)
}

/// The owner of a single-query pair from its statement (slices 1 to 23): the
/// walk of `quotient`'s source and machine (the original pair, or slice 24a's
/// merged-chain quotient) under `body` and `cfg`, the exact affine refusal,
/// the theorem (and its unpaired arbiter, OD-205) and the audit maps, which
/// are in the ORIGINAL source's coordinates ([`quotient::Quotient::original`]).
/// The result binds the original `source` and `machine`.
fn finish_owner<'a>(
    body: &SourceBody,
    cfg: &MachineCfg<'_>,
    quotient: &quotient::Quotient<'_>,
    source: &'a Function,
    machine: &'a X86ISelFunction,
    abi: X86SourceBoundAbi,
) -> Result<SourceBoundX86Body<'a>, X86BodyRefusal> {
    let stated = quotient.source();
    let original = |block: Block, index: usize| {
        if mutated("audit-in-quotient-coords") {
            (block, index)
        } else {
            quotient.original(block, index)
        }
    };
    let walks = walk_machine_for_callers(stated, body, cfg, PathEncoding::CANONICAL)?;
    // The exact affine evaluation compares a value's two sides over ALL
    // inputs, so it names a mismatch only for a one-path body. On a path of
    // several, the value is observed only where the path condition holds (a
    // machine that returns 7 where the source returns `x + 7` on the `x == 0`
    // path is correct): there the theorem, which states the condition, judges.
    // Slice 14: nor on a one-path body that may stop short (a guard or an
    // undefined division), whose values are observed only where it has not.
    if let [program] = body.paths.as_slice()
        && program.stops.is_empty()
    {
        affine_refusal(program, &walks.paths[0].psabi)?;
    }
    // Slice 23 (OD-205): the theorem, and when it pairs a row, the theorem
    // without the pairing, the arbiter of its refutation.
    let (theorem, unpaired) = owner_theorems(body, &walks, |theorem| {
        theorem
            .check()
            .map_err(|reason| unsupported(X86BodyUnsupported::Construction(reason)))
    })?;
    let paired = theorem.paired;
    let unpaired = unpaired.map(|unpaired| {
        std::sync::Arc::new(X86UnpairedTheorem {
            obligation: std::sync::Arc::new(unpaired.obligation),
            parts: std::sync::Arc::new(X86BodyParts::default()),
        })
    });
    let Theorem {
        obligation,
        source_definitions,
        pairing,
        defined_inputs,
        ..
    } = theorem;
    let source_definitions = source_definitions
        .into_iter()
        .map(|(name, block, index)| {
            let (block, index) = original(block, index);
            (name, block, index)
        })
        .collect();
    // Audit maps: each paired call and incoming access once, in path order
    // (slice 9: in the DAG's block order).
    let mut call_sites: Vec<(Block, usize, usize)> = Vec::new();
    let mut access_sites: Vec<(Block, usize, usize)> = Vec::new();
    let units: Vec<(&SourceProgram, &Walks)> =
        match (&body.dag, &walks.dag, &body.loops, &walks.loops) {
            (Some(dag), Some(dag_walks), _, _) => dag
                .order
                .iter()
                .map(|block| (&dag.blocks[block], &dag_walks.blocks[block]))
                .collect(),
            // Slice 12: every region's blocks, region by region.
            (None, _, Some(loops), Some(loop_walks)) => loops
                .regions
                .iter()
                .zip(&loop_walks.regions)
                .flat_map(|(region, region_walks)| {
                    region
                        .dag
                        .order
                        .iter()
                        .map(|block| (&region.dag.blocks[block], &region_walks.blocks[block]))
                })
                .collect(),
            _ => body.paths.iter().zip(&walks.paths).collect(),
        };
    for (program, walk) in units.iter().copied() {
        for (source_call, machine_call) in program.calls.iter().zip(&walk.psabi.calls) {
            let (block, index) = original(source_call.block, source_call.index);
            let site = (block, index, machine_call.row);
            if !call_sites.contains(&site) {
                call_sites.push(site);
            }
        }
        for (source_access, machine_access) in program.accesses.iter().zip(&walk.psabi.accesses) {
            let (block, index) = original(source_access.block, source_access.index);
            let site = (block, index, machine_access.row);
            if !access_sites.contains(&site) {
                access_sites.push(site);
            }
        }
    }
    let mut bound_rows: Vec<usize> = units
        .iter()
        .flat_map(|(_, walk)| walk.psabi.bound_rows.iter().copied())
        .collect();
    bound_rows.sort_unstable();
    bound_rows.dedup();
    let machine_definitions = std::iter::once(&walks.psabi)
        .chain(walks.clean.as_ref())
        .flat_map(|names| {
            names
                .definitions
                .iter()
                // A join's definition (slice 9) names no row's write.
                .filter(|(_, _, row)| *row != JOIN_ROW)
                .map(|(name, _, row)| (name.clone(), *row))
        })
        .collect();
    Ok(SourceBoundX86Body {
        source,
        machine,
        abi,
        bound_rows,
        source_definitions,
        machine_definitions,
        call_sites,
        access_sites,
        obligation: std::sync::Arc::new(obligation),
        parts: std::sync::Arc::new(X86BodyParts::default()),
        fp_abstract: rounds(body, &walks),
        unpaired,
        paired,
        pairing: pairing.filter(|_| paired).map(std::sync::Arc::new),
        routines: body.sites.routines.clone(),
        merged: quotient.merged(),
        segments: stated_segments(cfg).stated(),
        defined_inputs,
    })
}

/// Tests only: the owner over a source stated in parts under `policy`
/// whatever its size (fixtures cut at chosen points). It checks no module's
/// definitions (OD-210 is [`source_bound_x86_body_in_module`]'s).
#[cfg(test)]
pub(crate) fn source_bound_x86_body_in_parts<'a>(
    source: &'a Function,
    machine: &'a X86ISelFunction,
    abi: Option<X86SourceBoundAbi>,
    policy: &split::SplitPolicy,
) -> Result<SourceBoundX86Body<'a>, X86BodyRefusal> {
    split::source_bound_split(source, machine, abi, policy)
}

/// The exact, solver-independent refusal of one path: a definite difference
/// between its source and machine return value, call argument, or incoming
/// access address or stored value (under the exact affine evaluation of both
/// streams) is a named mismatch. Agreement grants nothing.
fn affine_refusal(program: &SourceProgram, walked: &Walked) -> Result<(), X86BodyRefusal> {
    // Exact, solver-independent refusal: only a definite difference refuses,
    // and agreement grants nothing.
    for (lane, (machine_value, source_value)) in walked
        .return_affine
        .iter()
        .zip(&program.return_affine)
        .enumerate()
    {
        if let (Some(machine_value), Some(source_value)) = (machine_value, source_value)
            && machine_value != source_value
        {
            return Err(mismatch(X86BodyMismatch::ReturnValue { lane }));
        }
    }
    for (call, (source_call, machine_call)) in program.calls.iter().zip(&walked.calls).enumerate() {
        for (argument, (source_value, machine_value)) in source_call
            .arg_affine
            .iter()
            .zip(&machine_call.arg_affine)
            .enumerate()
        {
            if let (Some(source_value), Some(machine_value)) = (source_value, machine_value)
                && source_value != machine_value
            {
                return Err(mismatch(X86BodyMismatch::CallArgument { call, argument }));
            }
        }
    }
    // A paired access at a definitely different address, or a paired store
    // of a definitely different value, is a wrong lowering, unless the
    // machine's accesses may be a reordering of the source's: a permutation
    // that pairs every source access with a machine access of the same kind
    // and width whose address and stored value the exact evaluation does not
    // show to differ (and, when it knows every address, the n-th access to
    // one address with the n-th: accesses to one location never trade
    // places). A reordering can be correct when the addresses are disjoint,
    // so it makes no claim instead.
    let differ = |source: Option<Affine>, machine: Option<Affine>| matches!((source, machine), (Some(source), Some(machine)) if source != machine);
    let source_addresses: Vec<Option<Affine>> = program
        .accesses
        .iter()
        .map(|access| access.address_affine)
        .collect();
    let machine_addresses: Vec<Option<Affine>> = walked
        .accesses
        .iter()
        .map(|access| access.address_affine)
        .collect();
    let every_address_known = source_addresses
        .iter()
        .chain(&machine_addresses)
        .all(Option::is_some);
    // How many earlier accesses of the same trace share this access's address.
    let rank = |addresses: &[Option<Affine>], n: usize| {
        addresses[..n]
            .iter()
            .filter(|address| **address == addresses[n])
            .count()
    };
    let may_reorder = || {
        access_permutation_exists(program.accesses.len(), |source, machine| {
            let (source_access, machine_access) =
                (&program.accesses[source], &walked.accesses[machine]);
            // The machine access in position `machine` has the kind and width
            // of the source access the walk paired it with.
            let paired = &program.accesses[machine];
            matches!(source_access.kind, AccessKind::Load(_))
                == matches!(paired.kind, AccessKind::Load(_))
                && source_access.carrier.bytes() == paired.carrier.bytes()
                && !differ(source_access.address_affine, machine_access.address_affine)
                && !differ(source_access.value_affine, machine_access.value_affine)
                && (!every_address_known
                    || rank(&source_addresses, source) == rank(&machine_addresses, machine))
        })
    };
    for (access, (source_access, machine_access)) in
        program.accesses.iter().zip(&walked.accesses).enumerate()
    {
        let address = differ(source_access.address_affine, machine_access.address_affine);
        let value = differ(source_access.value_affine, machine_access.value_affine);
        if !address && !value {
            continue;
        }
        if may_reorder() {
            return Err(unsupported(X86BodyUnsupported::AccessTrace {
                detail: format!(
                    "access {access} may be a reordering of the source's incoming accesses"
                ),
            }));
        }
        return Err(mismatch(if address {
            X86BodyMismatch::MemoryAddress { access }
        } else {
            X86BodyMismatch::MemoryValue { access }
        }));
    }
    Ok(())
}

/// The theorem the owner would build for this triple WITHOUT its exact affine
/// refusal. Tests use it to show that the replayed query itself refutes a
/// wrong lowering; it is not an owner and cannot be replayed live.
#[cfg(test)]
pub(crate) fn theorem_without_affine_refusal(
    source: &Function,
    machine: &X86ISelFunction,
    abi: Option<X86SourceBoundAbi>,
) -> Result<ProofObligation, X86BodyRefusal> {
    with_stated_pair(source, machine, abi, None, |body, cfg, quotient, _| {
        let walks =
            walk_machine_for_callers(quotient.source(), body, cfg, PathEncoding::CANONICAL)?;
        let theorem = build_theorem(body, &walks, PathEncoding::CANONICAL)?;
        theorem
            .check()
            .map_err(|reason| unsupported(X86BodyUnsupported::Construction(reason)))?;
        Ok(theorem.obligation)
    })
}

