/// The several-path theorem the owner would build for this triple under
/// another spelling (qualification evidence for the canonical one; never an
/// owner, never replayed for credit).
#[cfg(test)]
pub(crate) fn theorem_with_path_encoding(
    source: &Function,
    machine: &X86ISelFunction,
    abi: Option<X86SourceBoundAbi>,
    encoding: PathEncoding,
) -> Result<ProofObligation, X86BodyRefusal> {
    with_stated_pair(
        source,
        machine,
        abi,
        encoding.dag,
        |body, cfg, quotient, _| {
            let walks = walk_machine_for_callers(quotient.source(), body, cfg, encoding)?;
            Ok(build_theorem(body, &walks, encoding)?.obligation)
        },
    )
}

/// The single-query theorem [`build_theorem`] states for this pair under
/// `encoding` (without the bound finder when `unbounded`), its free inputs
/// and its spelling, without the affine refusal and the structural check
/// (tests only: the sweep of slice 18's spelling against the plain one).
/// `None` for a pair past the single-query bounds (stated in parts).
#[cfg(test)]
#[allow(clippy::type_complexity)]
pub(crate) fn single_theorem_with_encoding(
    source: &Function,
    machine: &X86ISelFunction,
    abi: Option<X86SourceBoundAbi>,
    encoding: PathEncoding,
    unbounded: bool,
) -> Option<Result<(ProofObligation, Vec<(String, u32)>, Spelling), X86BodyRefusal>> {
    if !split::fits_one_query(source, machine) {
        return None;
    }
    WITHOUT_INDEXED_BOUNDS.with(|flag| flag.set(unbounded));
    let built = with_stated_pair(
        source,
        machine,
        abi,
        encoding.dag,
        |body, cfg, quotient, _| {
            let walks = walk_machine_for_callers(quotient.source(), body, cfg, encoding)?;
            let theorem = build_theorem(body, &walks, encoding)?;
            Ok((theorem.obligation, theorem.free, theorem.spelling))
        },
    );
    WITHOUT_INDEXED_BOUNDS.with(|flag| flag.set(false));
    Some(built)
}

/// The theorem under `encoding` (as [`theorem_with_path_encoding`]), with the
/// structural check, and a key for each of its free inputs that names what
/// the input stands for independently of the numbering an encoding gives
/// it (a call site's or load site's LIR location, a symbol, a frame byte's
/// address, a row): two encodings of one triple bind equal keys to one
/// value. Tests only (the slice-9 equivalence of the DAG and path claims).
#[cfg(test)]
pub(crate) fn theorem_with_input_keys(
    source: &Function,
    machine: &X86ISelFunction,
    abi: Option<X86SourceBoundAbi>,
    encoding: PathEncoding,
) -> Result<(ProofObligation, HashMap<String, String>), X86BodyRefusal> {
    with_stated_pair(
        source,
        machine,
        abi,
        encoding.dag,
        |body, cfg, quotient, _| input_keys(quotient.source(), body, cfg, encoding),
    )
}

/// [`theorem_with_input_keys`] of one stated pair.
#[cfg(test)]
fn input_keys(
    source: &Function,
    body: &SourceBody,
    cfg: &MachineCfg<'_>,
    encoding: PathEncoding,
) -> Result<(ProofObligation, HashMap<String, String>), X86BodyRefusal> {
    let walks = walk_machine_for_callers(source, body, cfg, encoding)?;
    let theorem = build_theorem(body, &walks, encoding)?;
    theorem
        .check()
        .map_err(|reason| unsupported(X86BodyUnsupported::Construction(reason)))?;
    let Theorem {
        obligation, free, ..
    } = theorem;
    let mut keys: HashMap<String, String> = HashMap::new();
    let site_key = |k: usize| {
        let (block, index, _) = &body.sites.calls[k];
        format!("{}:{index}", block.0)
    };
    let number = |name: &str, prefix: &str| -> Option<usize> {
        let digits = name.strip_prefix(prefix)?;
        (!digits.is_empty() && digits.bytes().all(|b| b.is_ascii_digit()))
            .then(|| digits.parse().ok())
            .flatten()
    };
    for (name, _) in &free {
        let key = if let Some((site, slot, offset)) = parse_call_byte_name(name) {
            format!("callbyte@{}:{slot}:{offset}", site_key(site))
        } else if let Some((site, slot, offset)) = parse_access_byte_name(name) {
            let (block, index, part) = body.sites.access_stores[site];
            format!("accessbyte@{}:{index}:{part}:{slot}:{offset}", block.0)
        } else if let Some(k) = number(name, "f") {
            let address = walks.frame_bytes[k];
            format!("frame@{}:{}", address.slot, address.offset)
        } else if let Some(k) = number(name, "fe") {
            let (block, index, _) = body.sites.floats[k];
            format!("float@{}:{index}", block.0)
        } else if let Some(names) = [Some(&walks.psabi), walks.clean.as_ref()]
            .into_iter()
            .flatten()
            .find(|names| names.float_leaves.iter().any(|(known, _)| known == name))
        {
            let row = names
                .float_leaf_at
                .iter()
                .find_map(|(row, expr)| {
                    matches!(expr, E::Var { name: known, .. } if known == name).then_some(*row)
                })
                .expect("an FP leaf has a row");
            format!("floatleaf@{:?}:{row}", names.convention)
        } else if let Some(j) = number(name, "sym") {
            let symbol = &body.sites.symbols[j];
            format!("sym@{}:{}", symbol.name, symbol.got)
        } else if let Some(j) = number(name, "l") {
            let (block, index, _, _) = &body.sites.loads[j];
            format!("load@{}:{index}", block.0)
        } else if let Some((lane, k)) = ["r", "q", "g", "h"]
            .iter()
            .find_map(|prefix| Some((*prefix, number(name, prefix)?)))
        {
            format!("call{lane}@{}", site_key(k))
        } else if let Some(names) = [Some(&walks.psabi), walks.clean.as_ref()]
            .into_iter()
            .flatten()
            .find(|names| names.undefined.iter().any(|(known, _)| known == name))
        {
            let row = names
                .undefined_at
                .iter()
                .find_map(|(UndefinedSite::Row(row), expr)| {
                    matches!(expr, E::Var { name: known, .. } if known == name).then_some(*row)
                })
                .expect("an undefined value has a site");
            format!("undefined@{:?}:{row}", names.convention)
        } else {
            name.clone()
        };
        keys.insert(name.clone(), key);
    }
    Ok((obligation, keys))
}

/// How a several-path theorem is spelled (slice 6): whether a definition
/// that is only another name (a copy) is substituted rather than stated, and
/// whether only the definitions the claims depend on are stated. Both are
/// satisfiability-preserving presentations of one theorem; which one AY and
/// Clean certify differs. Production uses [`PathEncoding::CANONICAL`]; a
/// one-path theorem (slices 1 to 5) states every definition, copies
/// included, whatever the encoding.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) struct PathEncoding {
    pub(crate) elide_aliases: bool,
    pub(crate) cone_of_influence: bool,
    /// The merged spelling ([`merged_spelling`]); evidence only.
    pub(crate) merge_at_observation: bool,
    /// Which encoding states a several-path source: `None` the shape's
    /// ([`SourceCfg::per_path`]); `Some(true)` its DAG (slice 9) and
    /// `Some(false)` its paths (slice 6), whatever its shape (evidence
    /// only).
    pub(crate) dag: Option<bool>,
    /// The DAG's guards (slice 9) spelled through Boolean connectives, `(ite
    /// (and (= g_B #b1) T_e) #b1 #b0)` and `(ite (or (= G_e1 #b1) ...) #b1
    /// #b0)`, rather than `bvand`/`bvor` of 1-bit terms; evidence only.
    pub(crate) bool_guards: bool,
    /// A one-path body past the slice-6 path bound (slice 9) stated like a
    /// several-path one: no name for a copy, only the definitions its items
    /// depend on, and no item both sides spell alike.
    pub(crate) trim_long_chains: bool,
    /// Slice 9 (a DAG, or a trimmed long chain): every definition the
    /// theorem uses at most once is substituted into its one use
    /// ([`inline_single_use`]).
    pub(crate) inline_single_use: bool,
    /// Slices 17 and 18: which single-query theorems are value-numbered and
    /// inlined as one slice-16 part ([`split::unify_definitions`]).
    pub(crate) value_number: ValueNumbering,
    /// Slice 17: a value-numbered theorem first has every definition that
    /// only moves bits substituted ([`split::substitute_bit_moves`]); without
    /// it, the theorem takes slice 16's part spelling (the second step of
    /// slice 18's cascade).
    pub(crate) bit_moves: bool,
    /// Slice 18 (OD-188): a value-numbered theorem's right-hand sides and
    /// claims are first folded ([`split::folded_spelling`]: constant folding
    /// and the `bvsub`-zero identity); without it, slice 17's spelling (the
    /// cascade's next step).
    pub(crate) fold: bool,
    /// Slice 19 (OD-195): the identity groups of the full canonical
    /// spelling ([`normal::spelled`]) applied after slice 18's cascade to
    /// every value-numbered theorem and every one-path theorem
    /// ([`normal::Groups::NONE`]: slice 18's spelling).
    pub(crate) normal: normal::Groups,
    /// Slice 23 (OD-205): whether an arithmetic row is spelled through the
    /// source operation it lowers ([`pair_arithmetic`], [`ArithPairs`]);
    /// [`ArithPairs::Off`] is the theorem of slices 1 to 22 (the arbiter of a
    /// paired theorem's refutation, [`SourceBoundX86Body::has_unpaired`]).
    pub(crate) pair_arithmetic: ArithPairs,
}

/// Slice 23 (OD-205): what [`build_theorem`] does with the arithmetic rows
/// [`pair_arithmetic`] pairs.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum ArithPairs {
    /// No row is paired: the theorem of slices 1 to 22.
    Off,
    /// Each paired row is spelled through the source operation it lowers,
    /// and its operands are claimed equal: the theorem (congruence).
    Claimed,
    /// Each paired row is spelled through the source operation it lowers,
    /// and NO operand claim is stated. This is no theorem (it assumes what
    /// the claims state): it is built only to compare its bytes with the
    /// theorem without the pairing ([`owner_theorems`]) and then dropped;
    /// it is never replayed, exported or checked.
    DefinitionsOnly,
}

/// Which single-query theorems [`build_theorem`] value-numbers (slices 17
/// and 18).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum ValueNumbering {
    /// None: the plain spelling (evidence only).
    Off,
    /// A theorem that states an in-bounds claim, left with two claims at
    /// least; a theorem whose spelling would empty or fail the structural
    /// check keeps the plain one (slice 17's rule, OD-183). Since slice 18
    /// the legacy custody of the goldens it moved ([`with_legacy_spelling`];
    /// tests only).
    #[cfg_attr(not(test), allow(dead_code))]
    InBounds,
    /// Every theorem whose source side is `true`, through slice 18's cascade
    /// (OD-187): slice 17's spelling; if its claims would all drop or it
    /// fails the structural check, slice 16's part spelling; and only if
    /// that also empties or fails, the plain spelling. One claim left
    /// suffices, as for a part ([`check_definitional_part`]).
    Every,
}

/// How [`build_theorem`] spelled a single-query theorem.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum Spelling {
    /// Not value-numbered.
    Plain,
    /// Slice 16's part spelling: value numbering, inlining and identity
    /// dropping.
    Numbered,
    /// Slice 17's spelling: the bit moves substituted, then slice 16's.
    BitMoves,
    /// Slice 17's spelling with every right-hand side and claim folded
    /// (OD-188).
    Folded,
    /// Slice 19 (OD-195): the full canonical spelling ([`normal::spelled`])
    /// of a value-numbered theorem or of a one-path theorem.
    Normal,
}

impl PathEncoding {
    pub(crate) const CANONICAL: Self = Self {
        elide_aliases: true,
        cone_of_influence: true,
        merge_at_observation: false,
        dag: None,
        bool_guards: false,
        trim_long_chains: true,
        inline_single_use: true,
        value_number: ValueNumbering::Every,
        bit_moves: true,
        fold: true,
        normal: normal::Groups::CANONICAL,
        pair_arithmetic: ArithPairs::Claimed,
    };

    /// Slice 23 (OD-205): the canonical encoding without arithmetic pairing,
    /// the theorem of slices 1 to 22.
    pub(crate) const UNPAIRED: Self = Self {
        pair_arithmetic: ArithPairs::Off,
        ..Self::CANONICAL
    };

    /// Slice 23 (OD-205): the canonical encoding with the paired rows'
    /// definitions and no operand claim ([`ArithPairs::DefinitionsOnly`]):
    /// no theorem, only the bytes [`owner_theorems`] compares.
    const PAIRED_DEFINITIONS_ONLY: Self = Self {
        pair_arithmetic: ArithPairs::DefinitionsOnly,
        ..Self::CANONICAL
    };

    /// The spelling [`build_theorem`] tries when this one's claims would all
    /// drop or it fails the structural check: slice 17's after the folded one
    /// (OD-188), slice 16's part spelling after slice 17's (slice 18's
    /// cascade), else the plain spelling.
    fn next_spelling(self) -> Self {
        match self.value_number {
            ValueNumbering::Every if self.fold => Self {
                fold: false,
                ..self
            },
            ValueNumbering::Every if self.bit_moves => Self {
                bit_moves: false,
                ..self
            },
            _ => Self {
                value_number: ValueNumbering::Off,
                ..self
            },
        }
    }
}

#[cfg(test)]
thread_local! {
    /// Tests only ([`with_legacy_spelling`]): every theorem spelled as before
    /// slice 18, only a theorem with an in-bounds claim value-numbered.
    static LEGACY_SPELLING: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
}

/// `f` with every theorem built in the spelling before slice 18 (slice 17's
/// [`ValueNumbering::InBounds`]): the historical custody of the golden files
/// the canonical spelling moved (tests only; never an owner's spelling).
#[cfg(test)]
pub(crate) fn with_legacy_spelling<T>(f: impl FnOnce() -> T) -> T {
    LEGACY_SPELLING.with(|flag| flag.set(true));
    let result = f();
    LEGACY_SPELLING.with(|flag| flag.set(false));
    result
}

#[cfg(test)]
thread_local! {
    /// Tests only ([`with_normal_groups`]): the slice-19 groups every
    /// theorem and part is spelled with, in place of the canonical ones.
    static NORMAL_GROUPS: std::cell::Cell<Option<normal::Groups>> =
        const { std::cell::Cell::new(None) };
}

/// `f` with every theorem and part spelled with the slice-19 identity
/// groups `groups` (OD-195; [`normal::Groups::NONE`] is slice 18's
/// spelling, the historical custody of the goldens slice 19 moved). Tests
/// only; never an owner's spelling.
#[cfg(test)]
pub(crate) fn with_normal_groups<T>(groups: normal::Groups, f: impl FnOnce() -> T) -> T {
    NORMAL_GROUPS.with(|cell| cell.set(Some(groups)));
    let result = f();
    NORMAL_GROUPS.with(|cell| cell.set(None));
    result
}

/// The slice-19 identity groups of a theorem spelled with `groups` (the
/// encoding's): the canonical groups, or (tests only) [`with_normal_groups`]'s.
fn normal_groups(groups: normal::Groups) -> normal::Groups {
    // A step the cascade turned off (`NONE`) stays off.
    #[cfg(test)]
    if groups != normal::Groups::NONE
        && let Some(groups) = NORMAL_GROUPS.with(std::cell::Cell::get)
    {
        return groups;
    }
    groups
}

/// One source path for [`merged_spelling`]: its condition C_P, the machine's
/// `jcc` literals M_P, and its observed items (source side, machine side).
type PathObservation = (E, E, Vec<(E, E)>);

/// The merged spelling of a several-path theorem (qualification evidence
/// only): the path each side takes, as a number chosen by nested `ite`s over
/// the paths' conditions, and each observed item merged the same way, all
/// equal. It exists only when every path observes items of the same widths.
fn merged_spelling(paths: Vec<PathObservation>) -> Result<(E, E), X86BodyRefusal> {
    let widths = |items: &[(E, E)]| {
        items
            .iter()
            .map(|(source, _)| source.bv_width())
            .collect::<Vec<_>>()
    };
    let shape = widths(&paths[0].2);
    if paths.iter().any(|(_, _, items)| widths(items) != shape) {
        return Err(unsupported(X86BodyUnsupported::Construction(
            "the paths observe items of different widths".into(),
        )));
    }
    // `(ite c_1 v_1 (ite c_2 v_2 ... v_n))`: the last path's value is the
    // fallback, as the conditions partition the inputs.
    let nest = |pairs: Vec<(E, E)>| {
        let mut pairs = pairs.into_iter().rev();
        let (_, mut chosen) = pairs.next().expect("several paths");
        for (condition, value) in pairs {
            chosen = E::ite(condition, value, chosen);
        }
        chosen
    };
    let tag = |k: usize| E::bv_const(k as u64, 16);
    let source_tag = nest(
        paths
            .iter()
            .enumerate()
            .map(|(k, (condition, _, _))| (condition.clone(), tag(k)))
            .collect(),
    );
    let machine_tag = nest(
        paths
            .iter()
            .enumerate()
            .map(|(k, (_, condition, _))| (condition.clone(), tag(k)))
            .collect(),
    );
    let mut equations = vec![source_tag.eq_expr(machine_tag)];
    for j in 0..shape.len() {
        let source = nest(
            paths
                .iter()
                .map(|(condition, _, items)| (condition.clone(), items[j].0.clone()))
                .collect(),
        );
        let machine = nest(
            paths
                .iter()
                .map(|(_, condition, items)| (condition.clone(), items[j].1.clone()))
                .collect(),
        );
        equations.push(source.eq_expr(machine));
    }
    let goal = equations
        .into_iter()
        .rev()
        .reduce(|tail, equation| equation.and_expr(tail))
        .expect("the path equation");
    Ok((E::bool_const(true), goal))
}

/// Whether some permutation pairs each of `n` source accesses with a distinct
/// one of `n` machine accesses such that `compatible(source, machine)` holds
/// for every pair (a perfect bipartite matching, by augmenting paths).
fn access_permutation_exists(n: usize, compatible: impl Fn(usize, usize) -> bool) -> bool {
    fn augment(
        source: usize,
        edges: &[Vec<usize>],
        seen: &mut [bool],
        owner: &mut [Option<usize>],
    ) -> bool {
        for &machine in &edges[source] {
            if seen[machine] {
                continue;
            }
            seen[machine] = true;
            if owner[machine].is_none_or(|other| augment(other, edges, seen, owner)) {
                owner[machine] = Some(source);
                return true;
            }
        }
        false
    }
    let edges: Vec<Vec<usize>> = (0..n)
        .map(|source| {
            (0..n)
                .filter(|&machine| compatible(source, machine))
                .collect()
        })
        .collect();
    let mut owner = vec![None; n];
    (0..n).all(|source| augment(source, &edges, &mut vec![false; n], &mut owner))
}

fn admitted_abi(abi: Option<X86SourceBoundAbi>) -> Result<X86SourceBoundAbi, X86BodyRefusal> {
    match abi {
        None => Err(unsupported(X86BodyUnsupported::NoAbi)),
        Some(X86SourceBoundAbi::SystemV) => Ok(X86SourceBoundAbi::SystemV),
        Some(other) => Err(unsupported(X86BodyUnsupported::Abi(other))),
    }
}

// ---------------------------------------------------------------------------
// Source translator (LIR only)
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum BinaryOp {
    Add,
    Sub,
    Mul,
    And,
    Or,
    Xor,
}

impl BinaryOp {
    fn apply(self, lhs: E, rhs: E) -> E {
        match self {
            Self::Add => lhs.bvadd(rhs),
            Self::Sub => lhs.bvsub(rhs),
            Self::Mul => lhs.bvmul(rhs),
            Self::And => lhs.bvand(rhs),
            Self::Or => lhs.bvor(rhs),
            Self::Xor => lhs.bvxor(rhs),
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ShiftOp {
    Shl,
    Lshr,
    Ashr,
}

impl ShiftOp {
    fn apply(self, value: E, amount: E) -> E {
        match self {
            Self::Shl => value.bvshl(amount),
            Self::Lshr => value.bvlshr(amount),
            Self::Ashr => value.bvashr(amount),
        }
    }

    /// `value` shifted by the constant `amount` (below its width), the one
    /// canonical spelling of a shift by a constant on both sides (the
    /// source's [`SourceOp::Shift`], `shl`/`shr`/`sar r, imm`, and a shift by
    /// CL whose count the walk knows). A left or logical right shift is
    /// `bvshl`/`bvlshr` by the constant; an arithmetic right shift is the
    /// sign extension of the bits it keeps, `((_ sign_extend k) ((_ extract
    /// w-1 k) x))`, the same value (slice 10's barrel shifter spells each of
    /// its arithmetic stages so too). Chosen by host qualification (slice
    /// 11): AY proves `bvashr` by a constant trust-free but Clean's Carcara
    /// rejects the `bitblast_ashr` step it prints, while this spelling
    /// certifies (`reports/perf/2026-10-03-darwin-x86-64-census-slice11/`).
    fn by_constant(self, value: E, amount: u32) -> E {
        let bits = value.bv_width();
        match self {
            Self::Ashr if amount > 0 && amount < bits => {
                value.extract(bits - 1, amount).sign_ext(amount)
            }
            _ => self.apply(value, E::bv_const(u64::from(amount), bits)),
        }
    }
}

/// LIR `Fneg` and `Fabs` of a float bit pattern (slice 15). trust-ir's
/// meaning (`interpret::eval_float_unop`, pin `137e2b55`) is Rust's `-x` and
/// `x.abs()` of `f32::from_bits`/`f64::from_bits`, then `to_bits`: IEEE 754
/// §5.5.1's `negate` and `abs`, which copy the operand with its sign bit
/// flipped or cleared and every other bit (a NaN's payload and quiet bit
/// included) unchanged; trust-ir states its `F16` arm as exactly those bit
/// operations (`bits ^ 0x8000`, `bits & 0x7FFF`). No rounding, no exception,
/// so the meaning is exact over bit patterns and stays inside OD-73's model
/// (`the_float_sign_and_constant_meanings_are_trust_irs` checks it against the
/// pinned interpreter on every class of pattern, signalling NaNs included).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum FloatSignOp {
    Neg,
    Abs,
}

impl FloatSignOp {
    /// `value`, a `bits`-wide float bit pattern (32 or 64), with its sign bit
    /// (bit `bits - 1`) flipped (`Neg`) or cleared (`Abs`).
    fn apply(self, value: E, bits: u32) -> E {
        let sign = 1u64 << (bits - 1);
        match self {
            Self::Neg => value.bvxor(E::bv_const(sign, bits)),
            Self::Abs => value.bvand(E::bv_const(crate::smt::mask(u64::MAX, bits) & !sign, bits)),
        }
    }
}

/// The bit pattern of LIR `Fconst { ty, imm }` (slice 15), trust-ir's
/// `float_bits_from_f64` (`interpret.rs`, pin `137e2b55`): the adapter copies
/// trust-ir's `Constant::Float(f64)` into `imm` unchanged, and its value at
/// `F64` is `imm.to_bits()` and at `F32` `(imm as f32).to_bits()`, the
/// round-to-nearest-even narrowing (exact for every `f32` value, which is
/// what a frontend stores there). `None` for an `F32` NaN: `as` narrows a NaN
/// to a NaN whose payload Rust leaves unspecified, so its bits are not
/// pinned by the definition (outside, by name); and for any other carrier.
fn float_constant_bits(carrier: Carrier, imm: f64) -> Option<u64> {
    match carrier {
        Carrier::F64 => Some(imm.to_bits()),
        Carrier::F32 if !imm.is_nan() => Some(u64::from((imm as f32).to_bits())),
        _ => None,
    }
}

/// Slice 21 (ruling OD-198): the IEEE 754 operation a ROUNDING event of the
/// body theorem computes. Each source operation of one of these kinds and
/// each SSE row that computes one is an event: a paired source operation and
/// row share one result leaf ([`FloatKey`], [`SourceFloat`]), and neither
/// side ever states what the operation computes.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum FloatEventOp {
    Add,
    Sub,
    Mul,
    Div,
    /// A 64-bit integer to the key's format (trust-ir `SIToFP`/`UIToFP` of an
    /// `I64`; `cvtsi2sd`/`cvtsi2ss r64`, which read the word signed).
    FromInt64,
    /// The key's format to a 64-bit signed integer at the key's rounding,
    /// where the result fits (trust-ir `FPToSI`'s in-range value; `cvttsd2si`
    /// toward zero, `cvtsd2si` at the MXCSR rounding).
    ToInt64,
}

/// Slice 21: the rounding direction of a rounding event (IEEE 754 §4.3).
/// Every trust-ir rounding operation the lane admits rounds to nearest, ties
/// to even, except the float-to-integer conversion, which truncates; an SSE
/// arithmetic or `cvtsi2sd` row rounds at MXCSR.RC, which the lane takes to
/// be the default (trusted, OD-198), and `cvttsd2si` truncates.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Rounding {
    NearestEven,
    TowardZero,
}

/// Slice 21 (OD-198): the OPERATOR KEY of a rounding event, which a source
/// operation and a machine row must share to pair: the operation, the
/// floating-point format (of the operands, or of the result of a conversion
/// from an integer) and the rounding direction.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct FloatKey {
    op: FloatEventOp,
    format: Carrier,
    rounding: Rounding,
}

impl FloatKey {
    fn arithmetic(op: FloatEventOp, format: Carrier) -> Self {
        Self {
            op,
            format,
            rounding: Rounding::NearestEven,
        }
    }

    /// Bits of the event's result: the format's, or 64 for a conversion to
    /// an integer.
    fn result_bits(self) -> u32 {
        match self.op {
            FloatEventOp::ToInt64 => 64,
            _ => self.format.bits(),
        }
    }

    /// Bits of each operand: the format's, or 64 for a conversion from an
    /// integer.
    fn operand_bits(self) -> u32 {
        match self.op {
            FloatEventOp::FromInt64 => 64,
            _ => self.format.bits(),
        }
    }

    /// Whether a machine row of key `machine` computes this source key's
    /// operation (the pairing's key check). Exact equality: operation,
    /// format and rounding.
    fn pairs_with(self, machine: FloatKey) -> bool {
        self == machine
    }
}

/// Slice 21: the exact bit masks of an `F32` (binary32) or `F64` (binary64)
/// pattern, the predicates of the FP-to-BV lowering
/// ([`crate::fp_bv_lowering::Masks`]): `nan`, the order `key` (`+0` and `-0`
/// both 0) and `ordered`.
fn float_masks(format: Carrier) -> crate::fp_bv_lowering::Masks {
    let (eb, sb) = match format {
        Carrier::F32 => (8, 24),
        Carrier::F64 => (11, 53),
        other => unreachable!("{other:?} is no float format"),
    };
    crate::fp_bv_lowering::Masks::of(eb, sb).expect("binary32 and binary64 are formats")
}

/// Slice 21: the IEEE 754 relations of two `format` patterns, exactly over
/// their bits ([`float_masks`]): whether they are unordered (either is NaN),
/// equal (ordered, `+0 == -0`) and less (ordered).
struct FloatRelation {
    unordered: E,
    equal: E,
    less: E,
    greater: E,
}

impl FloatRelation {
    fn of(format: Carrier, lhs: &E, rhs: &E) -> Self {
        let masks = float_masks(format);
        let ordered = masks.ordered(lhs, rhs);
        let (left, right) = (masks.key(lhs), masks.key(rhs));
        Self {
            unordered: ordered.clone().not_expr(),
            equal: ordered
                .clone()
                .and_expr(left.clone().eq_expr(right.clone())),
            less: ordered.clone().and_expr(left.clone().bvslt(right.clone())),
            greater: ordered.and_expr(right.bvslt(left)),
        }
    }

    /// LIR `Fcmp { cond }` (trust-ir `FCmp`, `ub-numerics-policy.md` §2:
    /// "ordered predicates (`O*`) are false if either operand is NaN;
    /// unordered predicates (`U*`) are true if either operand is NaN";
    /// `interpret::eval_fcmp_*`), and the two LIR adds `Ordered` and
    /// `Unordered`. A Boolean.
    fn holds(self, cond: FloatCC) -> E {
        let Self {
            unordered,
            equal,
            less,
            greater,
        } = self;
        let ordered = unordered.clone().not_expr();
        match cond {
            FloatCC::Equal => equal,
            FloatCC::NotEqual => ordered.and_expr(equal.not_expr()),
            FloatCC::LessThan => less,
            FloatCC::LessThanOrEqual => less.or_expr(equal),
            FloatCC::GreaterThan => greater,
            FloatCC::GreaterThanOrEqual => greater.or_expr(equal),
            FloatCC::Ordered => ordered,
            FloatCC::Unordered => unordered,
            FloatCC::UnorderedEqual => unordered.or_expr(equal),
            FloatCC::UnorderedNotEqual => unordered.or_expr(equal.not_expr()),
            FloatCC::UnorderedLessThan => unordered.or_expr(less),
            FloatCC::UnorderedLessThanOrEqual => unordered.or_expr(less.or_expr(equal)),
            FloatCC::UnorderedGreaterThan => unordered.or_expr(greater),
            FloatCC::UnorderedGreaterThanOrEqual => unordered.or_expr(greater.or_expr(equal)),
        }
    }

    /// The flags `ucomisd`/`ucomiss lhs, rhs` writes (Intel SDM Vol. 2B
    /// UCOMISD: unordered ZF,PF,CF = 1,1,1; greater 0,0,0; less 0,0,1; equal
    /// 1,0,0; OF, SF and AF cleared): exact.
    fn ucomis_flags(self) -> AluFlags {
        let Self {
            unordered,
            equal,
            less,
            ..
        } = self;
        AluFlags {
            zf: Some(unordered.clone().or_expr(equal)),
            pf: Some(unordered.clone()),
            cf: Some(unordered.or_expr(less)),
            sf: Some(E::bool_const(false)),
            of: Some(E::bool_const(false)),
        }
    }
}

/// Slice 21: bits of `2^63` and `-2^63` as binary64, the bounds of a
/// conversion to a 64-bit signed integer (exact powers of two).
const F64_TWO_POW_63: u64 = 0x43E0_0000_0000_0000;
const F64_MINUS_TWO_POW_63: u64 = 0xC3E0_0000_0000_0000;

/// Slice 21: whether a binary64 pattern's truncation toward zero (or its
/// rounding to an integer: binary64 values of magnitude `2^52` and above are
/// integers, so either reading has these bounds) fits a 64-bit signed
/// integer: not NaN, below `2^63`, at least `-2^63` (Intel SDM CVTTSD2SI: the
/// integer indefinite outside; trust-ir `FPToSI`: undefined outside). Exact.
fn f64_fits_i64(value: &E) -> E {
    let masks = float_masks(Carrier::F64);
    let key = masks.key(value);
    let high = masks.key(&E::bv_const(F64_TWO_POW_63, 64));
    let low = masks.key(&E::bv_const(F64_MINUS_TWO_POW_63, 64));
    masks
        .nan(value)
        .not_expr()
        .and_expr(key.clone().bvslt(high))
        .and_expr(low.bvsle(key))
}

/// Slice 21 (ruling OD-199): LIR `FcvtToInt { dst_ty: I64 }` of an `F64` is
/// the SATURATING conversion (trust-ir `FPToSISat`, Rust's `as`): NaN is 0, a
/// value at least `2^63` is `i64::MAX`, one below `-2^63` is `i64::MIN`, and
/// any other value its truncation toward zero, `leaf` (the conversion's
/// rounding event). The adapter lowers both trust-ir `FPToSI` (undefined
/// outside the range) and `FPToSISat` to this one opcode, so its meaning is
/// the stronger one: exact for `FPToSISat`, a refinement of `FPToSI`.
fn saturating_f64_to_i64(value: &E, leaf: E) -> E {
    let masks = float_masks(Carrier::F64);
    let ordered = masks.nan(value).not_expr();
    let key = masks.key(value);
    let high = masks.key(&E::bv_const(F64_TWO_POW_63, 64));
    let low = masks.key(&E::bv_const(F64_MINUS_TWO_POW_63, 64));
    E::ite(
        masks.nan(value),
        E::bv_const(0, 64),
        E::ite(
            ordered.clone().and_expr(high.bvsle(key.clone())),
            E::bv_const(i64::MAX as u64, 64),
            E::ite(
                ordered.and_expr(key.bvslt(low)),
                E::bv_const(i64::MIN as u64, 64),
                leaf,
            ),
        ),
    )
}

/// Slice 21 (ruling OD-198): the operator key of an SSE rounding row, the
/// Intel SDM transcription the lane trusts: `addsd`/`subsd`/`mulsd`/`divsd`
/// (`ss`) are the IEEE 754 binary64 (binary32) operation rounding at
/// MXCSR.RC, round to nearest even under the default MXCSR (`0x1F80`, trusted);
/// `cvtsi2sd`/`cvtsi2ss r64` round the signed 64-bit word to the format at
/// MXCSR.RC; `cvttsd2si r64` truncates toward zero and `cvtsd2si r64` rounds
/// at MXCSR.RC, each to a 64-bit signed integer where the value fits.
/// `None` for any other row.
fn machine_float_key(opcode: X86Opcode) -> Option<FloatKey> {
    let (op, format, rounding) = match opcode {
        X86Opcode::Addsd => (FloatEventOp::Add, Carrier::F64, Rounding::NearestEven),
        X86Opcode::Subsd => (FloatEventOp::Sub, Carrier::F64, Rounding::NearestEven),
        X86Opcode::Mulsd => (FloatEventOp::Mul, Carrier::F64, Rounding::NearestEven),
        X86Opcode::Divsd => (FloatEventOp::Div, Carrier::F64, Rounding::NearestEven),
        X86Opcode::Addss => (FloatEventOp::Add, Carrier::F32, Rounding::NearestEven),
        X86Opcode::Subss => (FloatEventOp::Sub, Carrier::F32, Rounding::NearestEven),
        X86Opcode::Mulss => (FloatEventOp::Mul, Carrier::F32, Rounding::NearestEven),
        X86Opcode::Divss => (FloatEventOp::Div, Carrier::F32, Rounding::NearestEven),
        X86Opcode::Cvtsi2sd => (FloatEventOp::FromInt64, Carrier::F64, Rounding::NearestEven),
        X86Opcode::Cvtsi2ss => (FloatEventOp::FromInt64, Carrier::F32, Rounding::NearestEven),
        X86Opcode::Cvttsd2si => (FloatEventOp::ToInt64, Carrier::F64, Rounding::TowardZero),
        X86Opcode::Cvtsd2si => (FloatEventOp::ToInt64, Carrier::F64, Rounding::NearestEven),
        _ => return None,
    };
    Some(FloatKey {
        op,
        format,
        rounding,
    })
}

/// Slice 21 (OD-200): whether a walked body abstracts a rounding operation:
/// a source rounding event, or a machine rounding row of either walk (paired
/// or not).
fn rounds(body: &SourceBody, walks: &BodyWalks) -> bool {
    !body.sites.floats.is_empty()
        || std::iter::once(&walks.psabi)
            .chain(walks.clean.as_ref())
            .any(|names| !names.float_leaves.is_empty())
}

/// Slice 21: the free input naming the result of the `k`-th rounding-event
/// site of the source ([`SourceSites::floats`]), which a paired machine row
/// shares. An FP leaf: a theorem with one is an abstraction of IEEE 754
/// arithmetic, whose satisfying model is no counterexample (OD-200,
/// [`SourceBoundX86Body::is_fp_abstract`]).
fn float_event_name(k: usize) -> String {
    format!("fe{k}")
}

/// Slice 21: whether `name` is an FP leaf ([`float_event_name`],
/// [`BoolArguments::float_leaf_name`]), a free input the test samplers
/// assign.
#[cfg(test)]
fn is_float_leaf_name(name: &str) -> bool {
    ["fe", "fu", "fw"].iter().any(|prefix| {
        name.strip_prefix(prefix)
            .is_some_and(|digits| !digits.is_empty() && digits.bytes().all(|b| b.is_ascii_digit()))
    })
}

/// LIR checked arithmetic (slice 10): `CheckedUadd`, `CheckedUsub`,
/// `CheckedUmul`, `CheckedSadd`, `CheckedSsub` and `CheckedSmul`, each with the
/// results `[value, overflow]` (trust-ir `Overflow { AddOverflow | SubOverflow |
/// MulOverflow }`, which the adapter maps to them).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum CheckedOp {
    Uadd,
    Usub,
    Umul,
    Sadd,
    Ssub,
    Smul,
}

impl CheckedOp {
    fn of(opcode: &L) -> Option<Self> {
        Some(match opcode {
            L::CheckedUadd => Self::Uadd,
            L::CheckedUsub => Self::Usub,
            L::CheckedUmul => Self::Umul,
            L::CheckedSadd => Self::Sadd,
            L::CheckedSsub => Self::Ssub,
            L::CheckedSmul => Self::Smul,
            _ => return None,
        })
    }

    /// The value result: trust-ir's wrapping `Add`/`Sub`/`Mul` at the
    /// operand width (`eval_int_overflow` computes it with `eval_int_binop`).
    fn binary(self) -> BinaryOp {
        match self {
            Self::Uadd | Self::Sadd => BinaryOp::Add,
            Self::Usub | Self::Ssub => BinaryOp::Sub,
            Self::Umul | Self::Smul => BinaryOp::Mul,
        }
    }

    fn signed(self) -> bool {
        matches!(self, Self::Sadd | Self::Ssub | Self::Smul)
    }

    /// The overflow result, as an SMT Boolean over two `bits`-wide operands:
    /// trust-ir's `unsigned_overflow`/`signed_overflow`, "the mathematical
    /// result lies outside `[0, 2^bits)` (unsigned) or `[-2^(bits-1),
    /// 2^(bits-1))` (signed)". The mathematical result is computed exactly at
    /// a width it cannot overflow (`bits + 1` for a sum or difference, `2 *
    /// bits` for a product) from the operands extended by their signedness,
    /// and it is representable exactly when extending its low `bits` bits the
    /// same way gives it back.
    fn overflows(self, lhs: E, rhs: E, bits: u32) -> E {
        let extra = match self.binary() {
            BinaryOp::Mul => bits,
            _ => 1,
        };
        let extend = |value: E| {
            if self.signed() {
                value.sign_ext(extra)
            } else {
                value.zero_ext(extra)
            }
        };
        let exact = self.binary().apply(extend(lhs), extend(rhs));
        extend(exact.clone().extract(bits - 1, 0))
            .eq_expr(exact)
            .not_expr()
    }
}

#[derive(Debug, Clone)]
enum SourceOp {
    /// The constant's bits at the result width.
    Const(u64),
    /// Slice 11: a 128-bit constant, `(hi << 64) | lo`: LIR `Iconst128`, or
    /// an `I128` `Iconst`, whose high half is its `i64` immediate's sign
    /// extension.
    Wide {
        lo: u64,
        hi: u64,
    },
    /// Slice 11: the bytes the two halves of an `I128` incoming load read
    /// (low, then high load site): `(concat l{hi} l{lo})`.
    WideLoad(usize, usize),
    Copy(Value),
    Binary(BinaryOp, Value, Value),
    /// The overflow result of LIR checked arithmetic (slice 10): the `bool` 1
    /// exactly when [`CheckedOp::overflows`] holds of the two operands. (Its
    /// value result is the [`SourceOp::Binary`] of the same operands.)
    Overflow {
        op: CheckedOp,
        lhs: Value,
        rhs: Value,
    },
    /// LIR `Bnot` (slice 10): the bitwise complement at the carrier width
    /// (trust-ir `UnOp::Not`, `!raw` masked to the width).
    Not(Value),
    /// LIR `Ineg` (slice 10): the wrapping negation at the carrier width
    /// (trust-ir `UnOp::Neg`, `0 - raw` masked to the width).
    Neg(Value),
    /// LIR `CtPop` (slice 10): the number of set bits of the operand, at its
    /// carrier width (trust-ir `UnOp::CtPop`, `count_ones`).
    Popcount(Value),
    /// LIR `Fneg`/`Fabs` of an `F32`/`F64` bit pattern (slice 15): the sign
    /// bit flipped or cleared, every other bit kept ([`FloatSignOp`]).
    FloatSign(FloatSignOp, Value),
    /// Slice 21 (OD-198): the result of the rounding event at site `k`
    /// ([`SourceSites::floats`]): the free input [`float_event_name`].
    FloatEvent(usize),
    /// Slice 21 (OD-199): LIR `FcvtToInt { dst_ty: I64 }` of an `F64`, the
    /// saturating conversion ([`saturating_f64_to_i64`]) whose in-range value
    /// is the truncation event at site `site`.
    FloatToInt {
        value: Value,
        site: usize,
    },
    /// Slice 21: LIR `Fcmp { cond }` of two patterns of one format, exactly
    /// ([`FloatRelation::holds`]): the `bool` 1 exactly when it holds.
    FloatCompare {
        cond: FloatCC,
        format: Carrier,
        lhs: Value,
        rhs: Value,
    },
    /// Shift by an in-range constant amount (`0 <= amount < width`).
    Shift(ShiftOp, Value, u32),
    /// Shift by a variable amount of the value's carrier (slice 10): the
    /// shift by the amount modulo the width ([`shift_modulo_width`]). For an
    /// amount below the width
    /// that is trust-ir's shift; at the width or above trust-ir has undefined
    /// behavior (`interpret::shift_amount`), which any value refines, and the
    /// theorem states the amount reduced modulo the width there (what the
    /// selector's `shl`/`shr`/`sar r, cl` computes, after its explicit mask
    /// of a narrow count). So a machine that computes anything else for an
    /// in-range amount is refuted, and the theorem never relies on the
    /// machine at an out-of-range one beyond that stated refinement.
    VariableShift(ShiftOp, Value, Value),
    Extend {
        signed: bool,
        value: Value,
    },
    Trunc(Value),
    /// Result lane `lane` of the direct call at the `k`-th call site of the
    /// body ([`SourceSites::calls`]): the free input `r{k}` (lane 0, RAX) or
    /// `q{k}` (lane 1, RDX).
    CallResult(usize, usize),
    /// The address of the `j`-th symbol the body references
    /// ([`SourceSites::symbols`]): the free input `sym{j}`.
    Symbol(usize),
    /// LIR `Icmp`: the `bool` 1 exactly when `cond` holds of the two
    /// operands at their carrier width.
    Compare {
        cond: IntCC,
        lhs: Value,
        rhs: Value,
    },
    /// LIR `Select { cond: NotEqual }` (slice 6): `then` when `test != 0` at
    /// its carrier width, else `other`.
    Select {
        test: Value,
        then: Value,
        other: Value,
    },
    /// The value the load at the `j`-th incoming-load site of the body
    /// ([`SourceSites::loads`]) reads: the free input `l{j}`, shared with the
    /// paired machine load.
    MemoryLoad(usize),
    /// Bytes read back from a private stack slot, low byte first, that no
    /// single earlier store wrote whole. A byte no store on the path wrote
    /// (slice 6) is the slot's initial byte, `None` here; a byte a call
    /// defined (slice 7) is that call's free input. A `bool` read (slice 7:
    /// of one call-defined byte) is `byte != 0`.
    StackBytes(Vec<(FrameAddr, Option<SlotByte>)>),
    /// Slice 17: a load through an indexed private address: the
    /// [`indexed::select`] over its candidate offsets of what a load at each
    /// constant offset reads ([`CandidateRead`]), on the offset term of
    /// `address`.
    IndexedLoad {
        address: IndexedAddr,
        arms: Vec<(i64, CandidateRead)>,
    },
    /// A pointer plus a constant field offset (a `StructGep` over a
    /// non-private address), wrapping.
    Offset(Value, u64),
    /// OD-185: LIR `ArrayGep` over a non-private address, the element
    /// address `base + index * stride` at 64 bits, wrapping
    /// ([`array_element_address`]).
    ArrayElement {
        base: Value,
        index: Value,
        stride: u64,
    },
    /// Slice 14: LIR `Udiv`, `Urem`, `Sdiv` or `Srem` ([`division`]):
    /// trust-ir's quotient or remainder where it is defined (truncating, the
    /// remainder with the dividend's sign); where it is undefined the run
    /// stops ([`StopKind::Undefined`]) and the value is never observed.
    Divide {
        signed: bool,
        remainder: bool,
        lhs: Value,
        rhs: Value,
        /// The divisor's bits when it is a constant of the chain.
        constant: Option<u64>,
    },
}

/// A private stack address: one of the function's stack slots and a byte
/// offset into it. It is only ever the address of a load or store, (slice 7)
/// a direct call's argument, which makes the slot ESCAPE to that call and
/// every later one, or (slice 13) the value an 8-byte store writes as data
/// ([`frame_address_term`]); any other use (a value, a return) is outside
/// the domain.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct FrameAddr {
    slot: u32,
    offset: i64,
}

impl FrameAddr {
    fn offset_by(self, delta: i64) -> Option<Self> {
        Some(Self {
            slot: self.slot,
            offset: self.offset.checked_add(delta)?,
        })
    }

    fn describe(self) -> String {
        format!("private stack slot {} + {}", self.slot, self.offset)
    }
}

/// A private stack address the source tracks (slice 17): at a constant
/// offset, or indexed.
#[derive(Debug, Clone, Copy)]
enum Private {
    Frame(FrameAddr),
    Indexed(IndexedAddr),
}

/// One byte of a source private stack slot: byte `byte` (low byte 0) of the
/// stored `value` at its memory width ([`Carrier::memory_value`]).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct SourceByte {
    value: Value,
    carrier: Carrier,
    byte: u32,
}

/// What one byte of a source private stack slot holds, once something wrote
/// it (a byte nothing wrote is the slot's initial byte, `f{k}`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SlotByte {
    /// A byte of a store (slices 4 to 6).
    Stored(SourceByte),
    /// The byte the direct call at call site `site` left there (slice 7):
    /// the slot's address had escaped to that call or an earlier one, so the
    /// call may have written any byte of it. The free input
    /// [`call_byte_name`] of the site and the byte's address.
    Call(usize),
    /// The byte the `site`-th store through an address that may derive from
    /// an escaped slot left there (slice 15): the store may have written any
    /// byte of an escaped slot. The free input [`access_byte_name`] of the
    /// site and the byte's address.
    AccessStore(usize),
    /// Byte `byte` (low byte 0) of argument register `root` at entry (slice
    /// 8): a byte of an aggregate parameter's eightbyte, which the caller
    /// passes in that register.
    Entry { root: u16, byte: u32 },
    /// Byte `byte` of result lane `lane` of the call at site `site` (slice
    /// 8): a byte of an aggregate call result's eightbyte, the free input
    /// `r{site}`/`q{site}` of `width` bits.
    Result {
        site: usize,
        lane: usize,
        byte: u32,
        width: u32,
    },
    /// A byte the paths into a DAG join leave differently (slice 9): the
    /// `id`-th [`SlotMerge`] of [`DagBody::merges`], the byte each incoming
    /// edge brings, chosen by the edges' guards. `bool_read`: every incoming
    /// byte is one a `bool` read may read (a `bool` store's, or one
    /// [`SlotByte::read_as_bool`] admits); `tainted`: some incoming byte may
    /// hold an address derived from an escaped slot (slice 7).
    Merged {
        id: usize,
        bool_read: bool,
        tainted: bool,
    },
    /// A byte a loop may change (slice 12): at the start of the region of
    /// loop header `header`, the byte is the free input
    /// [`header_byte_name`] of the header and its address, shared with the
    /// machine's byte at the same frame address (the cut-point relation
    /// states the two equal at every edge into the header). `bool_read` and
    /// `tainted` as for [`SlotByte::Merged`], over every edge into the
    /// header.
    Header {
        header: Block,
        bool_read: bool,
        tainted: bool,
    },
    /// Byte `byte` (low byte 0) of the private stack address `address`, which
    /// an 8-byte store wrote there as data (slice 13): the byte of its term
    /// [`frame_address_term`]. Read back whole as an `I64` it is that address
    /// again; any other read of it is outside the domain.
    Address { address: FrameAddr, byte: u32 },
    /// A byte an indexed store may have written (slice 17): the `id`-th
    /// [`IndexedByte`] of [`SourceSites::indexed_bytes`], the store's
    /// [`indexed::update`] of the byte before it, defined where the store
    /// runs (`ix{id}`). `bool_read` and `tainted` as for
    /// [`SlotByte::Merged`], over the stored value's bytes and the old byte.
    Indexed {
        id: usize,
        bool_read: bool,
        tainted: bool,
    },
    /// A byte DEAD at a cut point (slice 17, ruling OD-184; slice 16's cut
    /// points too): no path from the cut reads it before a store overwrites
    /// it ([`split::live_bytes`]). It is left out of the cut's relation and
    /// assumptions on both sides and is UNREADABLE in the cut's region: any
    /// read of it refuses (a liveness error only refuses).
    Dead,
}

impl SlotByte {
    fn stored(self) -> Option<SourceByte> {
        match self {
            Self::Stored(byte) => Some(byte),
            Self::Call(_)
            | Self::AccessStore(_)
            | Self::Entry { .. }
            | Self::Result { .. }
            | Self::Merged { .. }
            | Self::Header { .. }
            | Self::Address { .. }
            | Self::Indexed { .. }
            | Self::Dead => None,
        }
    }

    /// The private stack address this byte is a byte of (slice 13).
    fn address(self) -> Option<FrameAddr> {
        match self {
            Self::Address { address, .. } => Some(address),
            _ => None,
        }
    }

    /// Whether a `bool` read of this one byte is trust-ir's `Load Bool`,
    /// `byte != 0`, of a byte the lane does not know: one a call defined
    /// (slice 7), or an aggregate parameter's or call result's (slice 8), or
    /// (slice 9) a join of bytes each of which a `bool` read may read, or
    /// (slice 12) such a byte at a loop header, or
    /// (slice 13) a byte of a store of another type than `bool` (a `bool`
    /// copied byte by byte as `u8`: its value is the stored byte, and the read
    /// is `byte != 0` whatever the byte holds), or (slice 15) one a store
    /// through a derived address may have written.
    fn read_as_bool(self) -> bool {
        matches!(
            self,
            Self::Call(_)
                | Self::AccessStore(_)
                | Self::Entry { .. }
                | Self::Result { .. }
                | Self::Merged {
                    bool_read: true,
                    ..
                }
                | Self::Header {
                    bool_read: true,
                    ..
                }
                | Self::Indexed {
                    bool_read: true,
                    ..
                }
        ) || matches!(self, Self::Stored(byte) if byte.carrier != Carrier::B1)
    }

    /// Whether this byte may hold part of an address derived from an
    /// escaped slot (slice 7's retention rule), given the state that holds
    /// it.
    fn tainted_in(self, tainted: &HashSet<Value>, tainted_sites: &HashSet<usize>) -> bool {
        match self {
            Self::Call(_) | Self::AccessStore(_) => true,
            Self::Stored(byte) => tainted.contains(&byte.value),
            Self::Result { site, .. } => tainted_sites.contains(&site),
            Self::Merged { tainted, .. }
            | Self::Header { tainted, .. }
            | Self::Indexed { tainted, .. } => tainted,
            // Slice 13: a stored private address, read back only whole.
            // Slice 17: a dead byte is never read.
            Self::Entry { .. } | Self::Address { .. } | Self::Dead => false,
        }
    }
}

/// Slice 20 (ruling OD-194): whether a `bool` read may read a byte past a
/// DAG join, a loop header, a slice-16 cut point or an indexed store, where
/// the byte is a [`SlotByte::Merged`], [`SlotByte::Header`], cut item or
/// [`SlotByte::Indexed`] byte of the bytes some paths bring: a store's byte of
/// any carrier, as a direct read takes it (a `bool` store's byte is 0 or 1;
/// any other is read as trust-ir's `Load Bool`, `byte != 0`, slice 13), or one
/// [`SlotByte::read_as_bool`] admits. A byte no store wrote (the slot's
/// initial byte) is not. Through slice 19 only a `bool` store's byte was,
/// there, though a direct read admitted every store's.
fn bool_readable(byte: Option<SlotByte>) -> bool {
    match byte {
        Some(SlotByte::Stored(_)) => true,
        Some(byte) => byte.read_as_bool(),
        None => false,
    }
}

/// What an indexed load reads at one candidate offset (slice 17): exactly
/// what a load at that constant offset reads, one earlier store read back
/// whole at its type, or the bytes there (a `bool` read of one byte: `byte !=
/// 0`).
#[derive(Debug, Clone)]
enum CandidateRead {
    Whole(Value),
    Bytes(SlotBytes),
}

/// What an incoming-memory access does.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum AccessKind {
    /// The load at the `j`-th incoming-load site: its value is the free
    /// input `l{j}`.
    Load(usize),
    /// A store of `value`.
    Store(Value),
}

/// One access of the admitted source to incoming (non-private) memory, in
/// execution order. Slice 11: an `I128` access is two 8-byte accesses, the
/// low half at the address and the high half at the address plus 8 (a
/// non-atomic, non-volatile 16-byte access reads or writes exactly those
/// bytes, little-endian, and nothing runs between the halves).
struct SourceAccess {
    kind: AccessKind,
    /// Slice 13: the private stack address a store writes as data (its
    /// `Store` value is that address, no SMT term of its own): the stored
    /// value is [`frame_address_term`], and the slot escapes at the store.
    stored_address: Option<FrameAddr>,
    /// Slice 13: an `AtomicLoad`/`AtomicStore` (OD-83), stated as its
    /// plain-memory counterpart and paired only with a machine access that
    /// carries the selector's atomic origin.
    atomic: bool,
    /// Slice 21 (OD-201): an atomic access the selector lowers to one pseudo
    /// row with another access ([`AtomicPseudo`]), paired only with that row.
    pseudo: Option<AtomicPseudo>,
    /// Slice 15: an access through an address that may derive from an
    /// escaped slot (slice 7's retention rule): the contents, at the access,
    /// of every slot escaped so far, ascending by slot, which the access may
    /// read or write (observed like a call's, [`slot_chunks`]). `None` for an
    /// access through any other address, which cannot reach a slot.
    slot_reads: Option<Vec<(u32, Vec<Option<SlotByte>>)>>,
    /// Slice 15: such an access that is a store, by its site in
    /// [`SourceSites::access_stores`]: it leaves every byte of every escaped
    /// slot as the free input [`access_byte_name`] of that site.
    store_site: Option<usize>,
    address: Value,
    /// Bytes added to `address` (slice 11: 8 for an `I128`'s high half).
    offset: u64,
    /// The half of an `I128` store's value this access writes (slice 11).
    part: Option<u32>,
    carrier: Carrier,
    /// Exact affine value of the address over `I64` parameters, when known.
    address_affine: Option<Affine>,
    /// Exact affine value of an `I64` stored value, when known.
    value_affine: Option<Affine>,
    block: Block,
    index: usize,
}

/// Slice 21 (ruling OD-201): the selector's one pseudo row an atomic source
/// access is paired with, instead of one `mov` of its width (OD-83), and
/// which half of the pair the access is.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum AtomicPseudo {
    /// Half `half` (0 low, 1 high) of an `I128` `AtomicLoad`: the
    /// `AtomicLoadCmpxchg16b` row reads both.
    Cmpxchg16b(u32),
    /// The old-value load (`load`) or the new-value store of an `AtomicRmw {
    /// op: Xchg }` of an `I32`/`I64`: the `AtomicRmwCasLoop [dst, src, [base],
    /// 5]` row makes both.
    Exchange { load: bool },
}

/// One event of the source's world trace: a direct call or an
/// incoming-memory access, by index into `calls` / `accesses`, or (slice 21)
/// a rounding floating-point operation, by index into `floats`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SourceEvent {
    Call(usize),
    Access(usize),
    Float(usize),
}

/// Slice 21 (ruling OD-198): one rounding floating-point operation of the
/// admitted source, an EVENT like a call: the machine row of the same
/// operator key that the walk pairs with it ([`FloatKey::pairs_with`]) reads
/// operands the theorem claims equal to these (observed items, as a call's
/// arguments), and both read its result as the one free input
/// [`float_event_name`] of its site.
#[derive(Debug, Clone)]
struct SourceFloat {
    /// Index of its site in [`SourceSites::floats`].
    site: usize,
    key: FloatKey,
    /// The operands, in order (two for arithmetic, one for a conversion).
    args: Vec<Value>,
    /// LIR `FcvtFromUint`: the operand is read unsigned, so a pairing with
    /// a conversion that reads it signed (`cvtsi2sd r64`) also claims its
    /// bit 63 clear, where both readings are one integer.
    unsigned: bool,
    block: Block,
    index: usize,
}

struct SourceDefinition {
    result: Value,
    ty: Carrier,
    op: SourceOp,
    block: Block,
    index: usize,
}

/// Bytes of a private stack slot at one moment, low byte first, each with
/// its address and what it holds (`None`: nothing on the path wrote it, the
/// slot's initial byte).
type SlotBytes = Vec<(FrameAddr, Option<SlotByte>)>;
type EscapedSlotReads = Vec<(u32, Vec<Option<SlotByte>>)>;

/// One argument of a direct call, in System V order.
#[derive(Debug, Clone)]
enum CallArg {
    /// A scalar in one argument register, read at its return bits.
    Scalar(Value, Carrier),
    /// A private stack address (slice 7) in one argument register: no SMT
    /// term; the walk checks that the machine passes exactly this slot and
    /// offset, and the slot escapes.
    Frame(FrameAddr),
    /// An aggregate passed by value (slice 8): the bytes at its address when
    /// the call runs, one System V INTEGER eightbyte per argument register,
    /// each observed at its own bytes. The slot does not escape.
    Aggregate(Vec<SlotBytes>),
    /// Slice 17: an indexed private address in one argument register,
    /// observed as `slot{s} + o` on both sides ([`frame_address_term`] of the
    /// slot plus the offset term); the walk checks the machine passes an
    /// address of the same slot, and the slot escapes.
    Indexed(IndexedAddr),
}

impl CallArg {
    /// The argument registers this argument takes (slice 11: an `I128` takes
    /// two, low half first).
    fn registers(&self) -> usize {
        match self {
            Self::Scalar(_, Carrier::I128) => 2,
            Self::Scalar(..) | Self::Frame(..) | Self::Indexed(..) => 1,
            Self::Aggregate(lanes) => lanes.len(),
        }
    }

    /// Whether the argument travels in an SSE register (slice 11).
    fn sse(&self) -> bool {
        matches!(self, Self::Scalar(_, carrier) if carrier.is_float())
    }

    /// The private address each of its registers holds (slice 13): a
    /// private-address argument's, or an aggregate eightbyte's that is
    /// exactly a stored private address ([`whole_address`]); `None` for a
    /// register that holds bits.
    fn register_frames(&self) -> Vec<Option<FrameAddr>> {
        match self {
            Self::Frame(address) => vec![Some(*address)],
            Self::Scalar(..) | Self::Indexed(..) => vec![None; self.registers()],
            Self::Aggregate(lanes) => lanes
                .iter()
                .map(|lane| {
                    let part: Vec<Option<SlotByte>> = lane.iter().map(|(_, byte)| *byte).collect();
                    whole_address(&part)
                })
                .collect(),
        }
    }

    /// The bits each of its registers holds, which the callee reads: a
    /// scalar's return bits (an `I128`'s halves 64 each), a private
    /// address's 64, an aggregate eightbyte's bytes.
    fn register_bits(&self) -> Vec<u32> {
        match self {
            Self::Scalar(_, Carrier::I128) => vec![64, 64],
            Self::Scalar(_, ty) => vec![ty.return_bits()],
            Self::Frame(..) | Self::Indexed(..) => vec![64],
            Self::Aggregate(lanes) => lanes.iter().map(|lane| 8 * lane.len() as u32).collect(),
        }
    }
}

/// The System V argument register of every register a call's (or a
/// function's) arguments take, in order: the INTEGER registers RDI, RSI,
/// RDX, RCX, R8, R9 and (slice 11) the SSE registers XMM0-XMM7, each class
/// numbered in argument order (psABI §3.2.3); `None` when a class runs out
/// (the argument would go on the stack, outside the lane). Each argument
/// is `(registers, sse)`; an `I128` takes two consecutive INTEGER registers
/// or, when only one is left, none (System V passes it on the stack whole).
fn argument_roots(args: impl IntoIterator<Item = (usize, bool)>) -> Option<Vec<Vec<u16>>> {
    let (mut integer, mut sse) = (0usize, 0usize);
    args.into_iter()
        .map(|(registers, is_sse)| {
            let (next, table): (&mut usize, &[u16]) = if is_sse {
                (&mut sse, &SYSV_SSE_ARGUMENT_ROOTS)
            } else {
                (&mut integer, &SYSV_ARGUMENT_ROOTS)
            };
            let roots = table.get(*next..*next + registers)?.to_vec();
            *next += registers;
            Some(roots)
        })
        .collect()
}

/// Call arguments partitioned between registers and outgoing stack offsets.
type CallArgumentPartition = (Vec<CallArg>, Vec<(CallArg, i32)>);

/// Split a call's arguments (slice 13) into those its argument registers take
/// ([`argument_roots`]) and those System V passes in the outgoing argument
/// area: an `I8`/`I16`/`I32`/`I64` scalar or a private address past the six
/// INTEGER registers takes the next eightbyte, at offset `8k` from RSP at the
/// call for the `k`-th (psABI §3.2.3, as for a parameter), and (slice 15) an
/// `I128` without two INTEGER registers left takes the next two eightbytes,
/// the first at a multiple of 16 (its alignment), low half first. `None` when
/// any other argument would need the stack (an aggregate, a float past XMM7
/// or a `bool`).
fn stack_arguments(args: Vec<CallArg>) -> Option<CallArgumentPartition> {
    let (mut integer, mut sse, mut offset) = (0usize, 0usize, 0i32);
    let (mut registers, mut stack) = (Vec::new(), Vec::new());
    for arg in args {
        let (next, table): (&mut usize, &[u16]) = if arg.sse() {
            (&mut sse, &SYSV_SSE_ARGUMENT_ROOTS)
        } else {
            (&mut integer, &SYSV_ARGUMENT_ROOTS)
        };
        if *next + arg.registers() <= table.len() {
            *next += arg.registers();
            registers.push(arg);
            continue;
        }
        match arg {
            CallArg::Scalar(_, Carrier::I8 | Carrier::I16 | Carrier::I32 | Carrier::I64)
            | CallArg::Frame(..) => {
                stack.push((arg, offset));
                offset += 8;
            }
            CallArg::Scalar(_, Carrier::I128) => {
                offset = (offset + 15) & !15;
                stack.push((arg, offset));
                offset += 16;
            }
            _ => return None,
        }
    }
    Some((registers, stack))
}

/// The exact affine value of `I64` parameter `index`, when the affine normal
/// form has a term for it: [`Affine`] names the first eight parameters
/// (its ninth term is the constant). A later parameter has none, so the
/// solver-independent affine evaluation, which only ever refuses, derives no
/// refusal from it (slice 13: with parameters on the stack, and since slice
/// 11 with eight SSE parameters before an integer one, an index past seven
/// occurs; it used to alias the constant term at 8 and index out of bounds
/// past it).
fn parameter_affine(index: usize) -> Option<Affine> {
    (index < 8).then(|| Affine::parameter(index))
}

/// Where each parameter of a function arrives (slice 13): its System V
/// argument registers ([`argument_roots`]'s assignment), or, for an
/// `I8`/`I16`/`I32`/`I64` scalar past the six INTEGER registers, the next
/// eightbyte of the incoming argument area, at frame-pointer displacement
/// `16 + 8k` for the `k`-th (psABI §3.2.3: arguments the registers do not take
/// are pushed right to left, so they lie in parameter order above the return
/// address, each in its own eightbyte), and (slice 15) an `I128` without two
/// INTEGER registers left, which takes the next two eightbytes, the first at a
/// displacement that is a multiple of 16 (the area starts 16-byte aligned, and
/// an `__int128` is), low half first ([`Param::stack_eightbytes`]). `None`
/// when any other parameter would need the stack: an aggregate without
/// registers left for all of it, a float past XMM7 or a `bool` (outside the
/// lane).
fn parameter_locations(abis: &[ParamAbi]) -> Option<Vec<(Vec<u16>, Option<i32>)>> {
    let (mut integer, mut sse, mut stack) = (0usize, 0usize, 16i32);
    abis.iter()
        .map(|abi| {
            let (registers, is_sse) = match abi {
                ParamAbi::Scalar(Carrier::I128) => (2, false),
                ParamAbi::Scalar(carrier) => (1, carrier.is_float()),
                ParamAbi::Aggregate { aggregate, .. } => (aggregate.lanes.len(), false),
            };
            let (next, table): (&mut usize, &[u16]) = if is_sse {
                (&mut sse, &SYSV_SSE_ARGUMENT_ROOTS)
            } else {
                (&mut integer, &SYSV_ARGUMENT_ROOTS)
            };
            if let Some(roots) = table.get(*next..*next + registers) {
                *next += registers;
                return Some((roots.to_vec(), None));
            }
            match abi {
                ParamAbi::Scalar(Carrier::I8 | Carrier::I16 | Carrier::I32 | Carrier::I64) => {
                    let disp = stack;
                    stack += 8;
                    Some((Vec::new(), Some(disp)))
                }
                ParamAbi::Scalar(Carrier::I128) => {
                    let disp = (stack + 15) & !15;
                    stack = disp + 16;
                    Some((Vec::new(), Some(disp)))
                }
                _ => None,
            }
        })
        .collect()
}

/// One result register of a direct call (RAX, then RDX; slice 11: XMM0, then
/// XMM1, for an SSE lane): the bits of its value (`r{site}`/`q{site}` is
/// that wide), the low bits the callee defines (the rest are
/// `g{site}`/`h{site}`), the bits the call row declares, and the register.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct ResultLane {
    value_bits: u32,
    defined_bits: u32,
    register_bits: u32,
    root: u16,
}

impl ResultLane {
    /// Lane `lane` of a call's `results` scalar results, in `root`.
    fn scalar(carrier: Carrier, results: usize, root: u16) -> Self {
        Self {
            value_bits: carrier.bits(),
            defined_bits: carrier.call_result_bits(results),
            register_bits: carrier.call_result_register_bits(),
            root,
        }
    }

    /// One 64-bit half of an `I128` call result (slice 11): the callee
    /// defines all of RAX (the low half) and of RDX (the high half).
    fn half(root: u16) -> Self {
        Self {
            value_bits: 64,
            defined_bits: 64,
            register_bits: 64,
            root,
        }
    }

    /// An eightbyte of an aggregate call result (slice 8): the callee defines
    /// exactly its bytes.
    fn eightbyte(lane: Eightbyte, root: u16) -> Self {
        Self {
            value_bits: lane.bits(),
            defined_bits: lane.bits(),
            register_bits: lane.register_bits(),
            root,
        }
    }
}

/// One result lane a caller reads at the return (RAX, then RDX; slice 11:
/// XMM0, then XMM1, for an SSE lane).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ReturnLane {
    /// A scalar result (slices 1 to 5; slice 11: a float bit pattern in an
    /// SSE register).
    Scalar(Carrier),
    /// An eightbyte of a returned aggregate (slice 8): its low `bytes` bytes.
    Eightbyte(Eightbyte),
    /// Half `half` (0 low, 1 high) of a returned `I128` (slice 11): 64 bits
    /// of RAX (the low half) or RDX (the high half).
    Half(u32),
}

impl ReturnLane {
    /// Low bits of the result register every caller the backend meets reads
    /// (module documentation): a `bool` as the backend's clean 32-bit bool.
    fn return_bits(self) -> u32 {
        match self {
            Self::Scalar(carrier) => carrier.return_bits(),
            Self::Eightbyte(lane) => lane.bits(),
            Self::Half(_) => 64,
        }
    }

    /// The bits a psABI caller reads: a `bool` as its byte.
    fn psabi_bits(self) -> u32 {
        match self {
            Self::Scalar(Carrier::B1) => 8,
            other => other.return_bits(),
        }
    }

    /// Whether the lane travels in an SSE register (slice 11).
    fn sse(self) -> bool {
        matches!(self, Self::Scalar(carrier) if carrier.is_float())
    }
}

/// System V AMD64 SSE argument registers (slice 11), in parameter order:
/// XMM0-XMM7, numbered by the selector's physical encodings (XMM0 = 64).
const SYSV_SSE_ARGUMENT_ROOTS: [u16; 8] = [64, 65, 66, 67, 68, 69, 70, 71];

/// System V AMD64 SSE return registers (slice 11): XMM0, then XMM1.
const SYSV_SSE_RETURN_ROOTS: [u16; 2] = [64, 65];

/// Every SSE register: all are caller-saved under System V (psABI §3.2.1),
/// so a call may change each of them.
const XMM_ROOTS: std::ops::Range<u16> = 64..80;

/// The register of each lane of a result (slice 11): the INTEGER lanes take
/// RAX, then RDX, and the SSE lanes XMM0, then XMM1, each class in lane order
/// (psABI §3.2.3), or `None` when a class needs a third register.
fn result_roots(lanes: impl IntoIterator<Item = bool>) -> Option<Vec<u16>> {
    let (mut integer, mut sse) = (SYSV_RETURN_ROOTS.iter(), SYSV_SSE_RETURN_ROOTS.iter());
    lanes
        .into_iter()
        .map(|is_sse| {
            if is_sse {
                sse.next().copied()
            } else {
                integer.next().copied()
            }
        })
        .collect()
}

/// What a returning path returns in one result lane.
#[derive(Debug, Clone)]
enum Returned {
    /// A scalar value (a narrow lane may be carried by an `I32` value).
    Value(Value, Carrier),
    /// The bytes of one eightbyte of the returned aggregate at the return
    /// (slice 8).
    Bytes(SlotBytes),
    /// Half `half` (0 low, 1 high) of a returned `I128` value (slice 11).
    Half(Value, u32),
}

/// One direct call of the admitted source, in execution order.
struct SourceCall {
    /// Index of the call's site in [`SourceSites::calls`]: its result lanes
    /// are the free inputs `r{site}`/`q{site}`.
    site: usize,
    /// The callee symbol, exactly as the LIR names it (empty for an indirect
    /// call).
    name: String,
    /// Whether the call is bound to the exact module function
    /// (`DirectCallBinding::ExactModuleFunction`) rather than by symbol.
    exact_module: bool,
    /// Slice 10: the function pointer of an indirect call (LIR
    /// `CallIndirect`'s `args[0]`, an `I64`), observed like an argument;
    /// `None` for a direct call.
    callee: Option<Value>,
    /// Arguments in System V order.
    args: Vec<CallArg>,
    /// The System V register of every register the arguments take, in
    /// order ([`argument_roots`]; slice 11: SSE registers for floats).
    arg_roots: Vec<u16>,
    /// Slice 13: the arguments past the argument registers, each with the
    /// offset of its eightbyte in the outgoing argument area (from RSP at the
    /// call, `8k` for the `k`-th): an `I8`/`I16`/`I32`/`I64` scalar or a
    /// private address ([`stack_arguments`]).
    stack_args: Vec<(CallArg, i32)>,
    /// The contents, at the call, of every slot whose address escaped to
    /// this call or an earlier one on the path (slice 7), ascending by slot:
    /// the bytes the callee can read, observed like its arguments.
    slot_reads: Vec<(u32, Vec<Option<SlotByte>>)>,
    /// Exact affine value of each argument REGISTER that holds an `I64`
    /// scalar, over `I64` parameters (`None` for every other register).
    arg_affine: Vec<Option<Affine>>,
    /// The result lanes (none, one, or a RAX:RDX pair).
    results: Vec<ResultLane>,
    block: Block,
    index: usize,
}

/// A symbol whose address the source takes: `GlobalRef` (a direct,
/// PC-relative address) or `ExternRef` (the address the GOT slot holds).
#[derive(Debug, Clone, PartialEq, Eq)]
struct SymbolRef {
    name: String,
    got: bool,
}

impl SymbolRef {
    fn describe(&self) -> String {
        format!(
            "`{}` ({})",
            self.name,
            if self.got {
                "through the GOT"
            } else {
                "direct"
            }
        )
    }
}

/// How an admitted path ends.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SourceEnd {
    /// `Return` of the declared result (or of nothing, for a void function).
    Return,
    /// `Trap`: the path reaches a trap (after a diverging call, or bare).
    /// Reaching it is the path's observable end (slice 6).
    Trap,
    /// A DAG block's fragment (slice 9) that ends in a `Jump`, `Brif` or
    /// `Switch`: control continues at a successor.
    Continue,
}

/// What the edge an admitted path takes at a conditional terminator tests
/// (slice 6), of the terminator's value at its carrier width.
#[derive(Debug, Clone, PartialEq, Eq)]
enum BranchTest {
    /// A `Brif`'s `then` edge (`value != 0`, `true`) or `else` edge
    /// (`value == 0`, `false`).
    Nonzero(bool),
    /// A `Switch` case edge: the value equals this bit pattern.
    Case(u64),
    /// A `Switch` default edge: the value equals none of these patterns.
    Default(Vec<u64>),
    /// Slice 14: the one edge of a `Switch` to a block several of its cases
    /// (and perhaps its default) reach: the value equals one of `cases`, or
    /// (`default`: the switch's every case pattern) equals none of the
    /// switch's patterns.
    Cases {
        cases: Vec<u64>,
        default: Option<Vec<u64>>,
    },
}

/// One conditional branch an admitted path takes (slice 6): the LIR `Brif` or
/// `Switch` at `(block, index)` on `value`, and the edge the path takes.
#[derive(Debug, Clone, PartialEq, Eq)]
struct SourceBranch {
    value: Value,
    carrier: Carrier,
    test: BranchTest,
    block: Block,
    index: usize,
}

/// The literals of `branch`'s test of `value`, the tested value's term: `value
/// != 0` on a `Brif`'s `then` edge, `value == 0` on its `else` edge, `value ==
/// k` on a `Switch` case, and `value != k` for every case on its default.
/// Slice 14: a shared `Switch` target's edge is one literal, the disjunction
/// of its cases' equalities and (when the default reaches it too) the
/// default's conjunction.
fn branch_literals(branch: &SourceBranch, value: E) -> Vec<E> {
    let equals = |pattern: u64| {
        value
            .clone()
            .eq_expr(E::bv_const(pattern, branch.carrier.bits()))
    };
    match &branch.test {
        BranchTest::Nonzero(true) => vec![equals(0).not_expr()],
        BranchTest::Nonzero(false) => vec![equals(0)],
        BranchTest::Case(pattern) => vec![equals(*pattern)],
        BranchTest::Default(patterns) => patterns
            .iter()
            .map(|pattern| equals(*pattern).not_expr())
            .collect(),
        BranchTest::Cases { cases, default } => {
            let default = default.as_ref().map(|patterns| {
                patterns
                    .iter()
                    .map(|pattern| equals(*pattern).not_expr())
                    .rev()
                    .reduce(|tail, literal| literal.and_expr(tail))
                    .expect("a switch has a case")
            });
            vec![
                cases
                    .iter()
                    .map(|pattern| equals(*pattern))
                    .chain(default)
                    .rev()
                    .reduce(|tail, literal| literal.or_expr(tail))
                    .expect("a shared target is reached by a case"),
            ]
        }
    }
}

/// How the caller passes one parameter (slice 8 adds aggregates).
#[derive(Debug, Clone, PartialEq, Eq)]
enum ParamAbi {
    /// A scalar in one argument register.
    Scalar(Carrier),
    /// An aggregate by value: one argument register per eightbyte. The body
    /// sees it as the address of private slot `slot`, whose bytes are the
    /// registers' eightbytes at entry.
    Aggregate { aggregate: Aggregate, slot: u32 },
}

impl ParamAbi {
    /// The parameter's LIR type.
    fn lir(&self) -> Type {
        match self {
            Self::Scalar(carrier) => carrier.lir(),
            Self::Aggregate { aggregate, .. } => aggregate.ty.clone(),
        }
    }

    fn scalar(&self) -> Option<Carrier> {
        match self {
            Self::Scalar(carrier) => Some(*carrier),
            Self::Aggregate { .. } => None,
        }
    }
}

/// One parameter: how it is passed, and the System V argument registers it
/// takes, in order (none for a parameter on the stack).
#[derive(Debug, Clone, PartialEq, Eq)]
struct Param {
    abi: ParamAbi,
    roots: Vec<u16>,
    /// Slice 13: an `I8`/`I16`/`I32`/`I64` parameter past the six INTEGER
    /// argument registers, which the caller passes in its own eightbyte of
    /// the incoming argument area (psABI §3.2.3): the displacement of that
    /// eightbyte from the frame pointer, `16 + 8k` for the `k`-th
    /// ([`stack_parameter_name`]). Slice 15: an `I128` there, the
    /// displacement of its first (low) eightbyte.
    stack: Option<i32>,
}

impl Param {
    /// The frame-pointer displacements of the incoming stack eightbytes the
    /// parameter occupies, in order (slice 13: one; slice 15: an `I128`'s
    /// two, low half first); none for a parameter in registers.
    fn stack_eightbytes(&self) -> Vec<i32> {
        match (self.stack, &self.abi) {
            (None, _) => Vec::new(),
            (Some(disp), ParamAbi::Scalar(Carrier::I128)) => vec![disp, disp + 8],
            (Some(disp), _) => vec![disp],
        }
    }
}

/// The free input naming the incoming stack eightbyte at frame-pointer
/// displacement `disp` (slice 13): `e_stack{disp}`, the 64 bits the caller
/// left there; a parameter on the stack is its low bits, like a register's.
fn stack_parameter_name(disp: i32) -> String {
    format!("e_stack{disp}")
}

/// One entry-to-end path of the admitted source, walked as a chain.
struct SourceProgram {
    params: Vec<Param>,
    definitions: Vec<SourceDefinition>,
    calls: Vec<SourceCall>,
    /// Incoming-memory accesses, in execution order.
    accesses: Vec<SourceAccess>,
    /// Slice 21: the rounding floating-point operations, in execution order.
    floats: Vec<SourceFloat>,
    /// Calls and incoming-memory accesses (slice 21: and rounding
    /// floating-point operations) interleaved in execution order: the world
    /// trace the machine must follow.
    events: Vec<SourceEvent>,
    /// The function's private stack slot sizes, in bytes.
    slot_sizes: Vec<u32>,
    /// What each result lane returns, in lane order; empty for a void body
    /// and for a path that ends in a trap.
    returned: Vec<Returned>,
    /// The declared result lanes (at most [`SYSV_RETURN_ROOTS`]); empty for
    /// a void body and for a path that ends in a trap.
    return_tys: Vec<ReturnLane>,
    /// The register of each result lane ([`result_roots`]; slice 11: RAX,
    /// RDX, XMM0 or XMM1).
    return_roots: Vec<u16>,
    end: SourceEnd,
    /// Exact affine value of each `I64` result lane over `I64` parameters,
    /// when the chain computing it is affine; `None` makes no refusal.
    return_affine: Vec<Option<Affine>>,
    /// The LIR blocks the path runs through, from the entry block, in order
    /// (slice 6).
    blocks: Vec<Block>,
    /// The conditional branches the path takes, in order (slice 6).
    branches: Vec<SourceBranch>,
    /// The carrier of every value the path defines (a private stack address
    /// as `I64`).
    types: HashMap<Value, Carrier>,
    /// Slice 8: the aggregate type of every private stack address the LIR
    /// types as a by-value aggregate (an aggregate parameter, an aggregate
    /// call result, or a copy of one or of a slot address hinted as one).
    aggregates: HashMap<Value, Type>,
    /// Slice 14: the points, in execution order, at which the run may stop
    /// short of its end ([`SourceStop`]): a divide-by-zero guard that traps,
    /// or a division whose operands make it undefined. Empty on every body
    /// without a division.
    stops: Vec<SourceStop>,
    /// Slice 17: every indexed access and indexed call argument, in
    /// execution order, each claimed in bounds.
    indexed: Vec<IndexedSite>,
    /// Slice 17: the bytes indexed stores write, `(position, id)`: byte
    /// `ix{id}` is defined before the `position`-th of `definitions`.
    byte_definitions: Vec<(usize, usize)>,
}

/// Slice 14: a point at which the source run may stop short of its end.
#[derive(Debug, Clone)]
struct SourceStop {
    /// How many of the program's [`SourceProgram::events`] precede it: it
    /// can cut off the events from this index on, and the end.
    events: usize,
    kind: StopKind,
    /// Its LIR location.
    block: Block,
    index: usize,
}

/// Why the source run stops at a [`SourceStop`] (slice 14), from the pinned
/// trust-ir and the LIR (ruling in `docs/decision-record.md`, slice 14).
#[derive(Debug, Clone)]
enum StopKind {
    /// LIR `GuardDivZero { obligation: None }` of `divisor`: a defined trap
    /// exactly when the divisor is zero at its carrier width (the adapter
    /// emits it before a trust-ir division annotated `DivNonZero`; the
    /// selector lowers it to the `TrapDivZeroExact` carrier, which the x86
    /// pipeline expands to `test d, d; je -> ud2`). An OBSERVABLE outcome:
    /// the machine must trap there exactly when the source does.
    Guard { divisor: Value },
    /// LIR `Udiv`/`Urem`/`Sdiv`/`Srem` of `lhs` by `rhs`: trust-ir's
    /// `eval_int_binop` makes it undefined behaviour when the divisor is zero
    /// and, signed, when `lhs` is the carrier's minimum and `rhs` is -1. A
    /// DOMAIN premise of everything after it on the run: the theorem claims
    /// nothing of a run past an executed undefined division.
    Undefined {
        signed: bool,
        lhs: Value,
        rhs: Value,
    },
}

impl SourceProgram {
    /// The LIR type the path gives `value`: its aggregate type, else its
    /// carrier.
    fn lir_type(&self, value: &Value) -> Option<Type> {
        self.aggregates
            .get(value)
            .cloned()
            .or_else(|| self.types.get(value).map(|carrier| carrier.lir()))
    }
}

/// The sites every path of one body shares (slice 6). A call's result lanes
/// and an incoming load's bytes are one free input per SITE (a site runs at
/// most once on a path of an acyclic body), and a symbol's address one per
/// symbol and form, numbered in first-reference order over the paths. On a
/// one-path body the numbering is the chain's own (slices 1 to 5).
#[derive(Default, Clone)]
struct SourceSites {
    /// Each call site's LIR `(block, index)` and result lanes.
    calls: Vec<(Block, usize, Vec<ResultLane>)>,
    /// Each incoming-load site's LIR `(block, index)`, part (slice 11: 1 for
    /// the high half of an `I128` load, else 0) and carrier.
    loads: Vec<(Block, usize, u32, Carrier)>,
    /// The symbols whose address the body takes; the `j`-th is `sym{j}`.
    symbols: Vec<SymbolRef>,
    /// The private stack bytes a path reads without a store on it having
    /// written them (slice 6): each is the slot's initial byte, `f{k}`.
    frame_bytes: Vec<FrameAddr>,
    /// Slice 15: each store through an address that may derive from an
    /// escaped slot, by LIR `(block, index)` and part (the half of an `I128`
    /// store); the `k`-th leaves the escaped slots' bytes `t{k}s{x}o{y}`.
    access_stores: Vec<(Block, usize, u32)>,
    /// Slice 17: every byte an indexed store writes; the `id`-th is
    /// [`SlotByte::Indexed`] `id`, the defined name `ix{id}`.
    indexed_bytes: Vec<IndexedByte>,
    /// Slice 21: each rounding-event site's LIR `(block, index)` and result
    /// width; the `k`-th result is the free input [`float_event_name`].
    floats: Vec<(Block, usize, u32)>,
    /// OD-210, OD-217: the runtime routine of every `I128` division (OD-202,
    /// [`i128_division_routine`]) and C memory routine (slice 13,
    /// [`memory_routine`]) the body states as a call, whose contract the
    /// theorem trusts; [`check_trusted_routines`] refuses one the module under
    /// proof or its link unit defines.
    routines: std::collections::BTreeSet<&'static str>,
}

impl SourceSites {
    fn float(&mut self, block: Block, index: usize, bits: u32) -> usize {
        match self
            .floats
            .iter()
            .position(|(b, i, _)| (*b, *i) == (block, index))
        {
            Some(site) => site,
            None => {
                self.floats.push((block, index, bits));
                self.floats.len() - 1
            }
        }
    }

    fn call(&mut self, block: Block, index: usize, results: &[ResultLane]) -> usize {
        match self
            .calls
            .iter()
            .position(|(b, i, _)| (*b, *i) == (block, index))
        {
            Some(site) => site,
            None => {
                self.calls.push((block, index, results.to_vec()));
                self.calls.len() - 1
            }
        }
    }

    fn load(&mut self, block: Block, index: usize, part: u32, carrier: Carrier) -> usize {
        match self
            .loads
            .iter()
            .position(|(b, i, p, _)| (*b, *i, *p) == (block, index, part))
        {
            Some(site) => site,
            None => {
                self.loads.push((block, index, part, carrier));
                self.loads.len() - 1
            }
        }
    }

    fn frame_byte(&mut self, address: FrameAddr) -> usize {
        match self.frame_bytes.iter().position(|known| *known == address) {
            Some(k) => k,
            None => {
                self.frame_bytes.push(address);
                self.frame_bytes.len() - 1
            }
        }
    }

    fn access_store(&mut self, block: Block, index: usize, part: u32) -> usize {
        let site = (block, index, part);
        match self.access_stores.iter().position(|known| *known == site) {
            Some(k) => k,
            None => {
                self.access_stores.push(site);
                self.access_stores.len() - 1
            }
        }
    }

    fn symbol(&mut self, symbol: SymbolRef) -> usize {
        match self.symbols.iter().position(|known| *known == symbol) {
            Some(j) => j,
            None => {
                self.symbols.push(symbol);
                self.symbols.len() - 1
            }
        }
    }
}

/// The admitted source: every entry-to-end path of its acyclic LIR CFG,
/// each admitted as a chain, and the sites they share.
struct SourceBody {
    /// Every entry-to-end path, admitted as a chain (slices 1 to 6); empty
    /// when the body is stated over its DAG.
    paths: Vec<SourceProgram>,
    /// The body's DAG (slice 9), when [`SourceCfg::per_path`] does not hold
    /// for an acyclic source.
    dag: Option<DagBody>,
    /// The body's regions (slice 12), for a source with loops.
    loops: Option<LoopBody>,
    /// A one-path body past the slice-6 path bound (slice 9): its chain
    /// theorem may be trimmed ([`PathEncoding::trim_long_chains`]).
    long_chain: bool,
    sites: SourceSites,
    /// The slot table the selector's machine must have (slice 8): the
    /// source's slots, then the private copy of each aggregate parameter in
    /// parameter order, then the slot of each aggregate call result in the
    /// selector's layout order.
    machine_slots: Vec<trust_cg_lower::function::StackSlotInfo>,
    /// [`SourceCfg::dead`]: the LIR blocks no entry-to-end path reaches. The
    /// machine-side owners need it to tell the machine blocks that lower dead
    /// code (accounted for, and provably unreachable in the machine) from a
    /// machine block that drops live code off the chain (a mismatch).
    dead: std::collections::BTreeSet<Block>,
}

fn source_name(k: usize) -> String {
    format!("s{k}")
}

/// Free input naming result lane `lane` of the `k`-th direct call: `r{k}`
/// for RAX, `q{k}` for RDX.
fn call_result_name(k: usize, lane: usize) -> String {
    match lane {
        0 => format!("r{k}"),
        _ => format!("q{k}"),
    }
}

/// Free input naming the bits of a result register the `k`-th call leaves
/// undefined above result lane `lane`: `g{k}` in RAX, `h{k}` in RDX.
fn call_garbage_name(k: usize, lane: usize) -> String {
    match lane {
        0 => format!("g{k}"),
        _ => format!("h{k}"),
    }
}

/// Free input naming the address of the `j`-th symbol the source references.
fn symbol_name(j: usize) -> String {
    format!("sym{j}")
}

/// Free input naming the value the `j`-th paired incoming-memory load reads.
fn memory_load_name(j: usize) -> String {
    format!("l{j}")
}

/// Free input naming the initial value of the `k`-th private stack byte the
/// body reads before writing it (slice 6): shared by the source and every
/// machine walk, as one frame byte is one value.
fn frame_byte_name(k: usize) -> String {
    format!("f{k}")
}

/// Free input naming the byte that the call at call site `site` leaves at
/// private stack address `address` of a slot whose address escaped (slice
/// 7): `d{site}s{slot}o{offset}`, one 8-bit input per site and byte, shared
/// by the source and every machine walk (both name it by the call's site and
/// the byte's address alone, so neither side's reads number it).
fn call_byte_name(site: usize, address: FrameAddr) -> String {
    format!("d{site}s{}o{}", address.slot, address.offset)
}

/// The `(site, slot, offset)` a [`call_byte_name`] names, for declaring the
/// call-defined bytes a theorem reads in one canonical order.
fn parse_call_byte_name(name: &str) -> Option<(usize, u32, i64)> {
    parse_site_byte_name(name, 'd')
}

/// Free input naming the byte that the `site`-th store through an address
/// that may derive from an escaped slot leaves at private stack address
/// `address` of an escaped slot (slice 15): `t{site}s{slot}o{offset}`, one
/// 8-bit input per store site and byte, shared by the source and every
/// machine walk, like a call-defined byte ([`call_byte_name`]).
fn access_byte_name(site: usize, address: FrameAddr) -> String {
    format!("t{site}s{}o{}", address.slot, address.offset)
}

/// The `(site, slot, offset)` an [`access_byte_name`] names.
fn parse_access_byte_name(name: &str) -> Option<(usize, u32, i64)> {
    parse_site_byte_name(name, 't')
}

/// The `(site, slot, offset)` of a `{prefix}{site}s{slot}o{offset}` name.
fn parse_site_byte_name(name: &str, prefix: char) -> Option<(usize, u32, i64)> {
    let rest = name.strip_prefix(prefix)?;
    let (site, rest) = rest.split_once('s')?;
    let (slot, offset) = rest.split_once('o')?;
    let digits = |text: &str| !text.is_empty() && text.bytes().all(|b| b.is_ascii_digit());
    (digits(site) && digits(slot) && digits(offset))
        .then(|| Some((site.parse().ok()?, slot.parse().ok()?, offset.parse().ok()?)))
        .flatten()
}

/// Definition naming the `id`-th private byte a DAG join merges (slice 9;
/// [`SlotMerge`]): the byte the incoming edge whose guard holds brings.
fn merged_byte_name(id: usize) -> String {
    format!("y{id}")
}

/// Free input naming the value of the `i`-th parameter of loop header
/// `header` at the start of the header's region (slice 12): the source's
/// value of the parameter, and the low bits of the machine register paired
/// with it ([`HeaderParam`]).
fn header_value_name(header: Block, i: usize) -> String {
    format!("x{}v{i}", header.0)
}

/// Slice 20 (ruling OD-193): the free inputs naming the low (`x{H}v{i}l`) and
/// the high (`x{H}v{i}h`) 64-bit half of an `I128` parameter or item `i` of
/// cut point `header` (every name the theorem declares stays at most 64 bits
/// wide, slice 11).
fn header_half_name(header: Block, i: usize, high: bool) -> String {
    format!("x{}v{i}{}", header.0, if high { 'h' } else { 'l' })
}

/// The source's value of parameter or item `i` of cut point `header`, of
/// `carrier`, at the start of its region: its free input
/// ([`header_value_name`]), or (slice 20) an `I128`'s two halves, high then
/// low ([`header_half_name`]).
fn header_start_value(header: Block, i: usize, carrier: Carrier) -> E {
    if carrier == Carrier::I128 {
        E::var(header_half_name(header, i, true), 64)
            .concat(E::var(header_half_name(header, i, false), 64))
    } else {
        E::var(header_value_name(header, i), carrier.bits())
    }
}

/// Free input naming the bits of the machine register paired with the
/// `i`-th parameter of loop header `header` that the cut-point relation
/// leaves free (slice 12): the bits above the ones it states, `x{H}t{i}`
/// under the psABI walk and `x{H}c{i}` under the clean-bool walk (whose
/// stated bits differ for a `bool`).
fn header_upper_name(header: Block, i: usize, convention: BoolArguments) -> String {
    match convention {
        BoolArguments::PsAbi => format!("x{}t{i}", header.0),
        BoolArguments::Clean32 => format!("x{}c{i}", header.0),
    }
}

/// Free input naming the private stack byte at `address` at the start of
/// the region of loop header `header` (slice 12), shared by the source and
/// the machine ([`SlotByte::Header`]).
fn header_byte_name(header: Block, address: FrameAddr) -> String {
    format!("x{}b{}o{}", header.0, address.slot, address.offset)
}

fn parameter_name(i: usize) -> String {
    format!("p{i}")
}

/// The term of scalar parameter `i` of `bits` bits in every theorem: the name
/// `p{i}` its binding defines from its register or incoming stack eightbyte,
/// or (slice 11, slice 15) an `I128`'s two halves, high then low, with no
/// name ([`build_theorem`] states the bindings).
fn parameter_term(i: usize, param: &Param, bits: u32) -> E {
    match (param.roots.as_slice(), param.stack_eightbytes().as_slice()) {
        ([low_root, high_root], _) => {
            E::var(entry_name(*high_root), 64).concat(E::var(entry_name(*low_root), 64))
        }
        ([], [low_disp, high_disp]) => E::var(stack_parameter_name(*high_disp), 64)
            .concat(E::var(stack_parameter_name(*low_disp), 64)),
        _ => E::var(parameter_name(i), bits),
    }
}

/// The private stack slots the lane admits: each fixed and of 1 to
/// [`MAX_SLOT_BYTES`] bytes, and (slice 20, ruling OD-194) of at most
/// [`MAX_SLOT_TOTAL_BYTES`] bytes in all, however many there are. The walks
/// model every byte, so the cost is per byte, not per slot; through slice 19
/// the lane admitted at most 64 slots, whose largest total, 64 slots of 4096
/// bytes, is the total bound, so every frame admitted before is admitted.
const MAX_SLOT_BYTES: u32 = 4096;
const MAX_SLOT_TOTAL_BYTES: u64 = 64 * MAX_SLOT_BYTES as u64;

fn entry_name(root: u16) -> String {
    format!("e_{}", root_name(root))
}

/// The function-level facts every path of an admitted source shares.
struct SourceFrame {
    sret: bool,
    /// Every private slot's size: the source's slots, then (slice 8) each
    /// aggregate parameter's copy and each aggregate call result's slot.
    slot_sizes: Vec<u32>,
    params: Vec<Param>,
    return_tys: Vec<ReturnLane>,
    /// The register of each result lane (slice 11: RAX, RDX, XMM0, XMM1).
    return_roots: Vec<u16>,
    /// The aggregate the function returns by value (slice 8), if any.
    returned_aggregate: Option<Aggregate>,
    /// Slice 8: the private slot of each call whose one result is an
    /// aggregate, by the call's LIR `(block, index)`, with its
    /// classification.
    result_slots: HashMap<(Block, usize), (u32, Aggregate)>,
    /// The slot table the machine must have ([`SourceBody::machine_slots`]).
    machine_slots: Vec<trust_cg_lower::function::StackSlotInfo>,
}

/// Why an aggregate type is outside the register lane, as a refusal detail
/// for `what` (`"parameter"`, `"result"` or `"call result"`).
fn aggregate_refusal(what: &str, ty: &Type) -> String {
    match ty {
        // Slice 11 admits `I128`, `F32` and `F64` scalars; the 16-bit float
        // and the vectors stay outside (no selector lane, no bit model).
        Type::F16 | Type::V64 | Type::V128 => format!(
            "has an f16 or vector {what} (a 16-bit float or a vector register, outside the lane)"
        ),
        other => match classify_aggregate(other) {
            Ok(_) => unreachable!("only a refused type is described"),
            Err(reason) => format!(
                "has an aggregate {what} outside the System V INTEGER register class: {reason}"
            ),
        },
    }
}

/// The function-level half of source admission: the frame conditions, the
/// sret buffer, the stack slots, the signature and the pointee metadata.
fn admitted_frame(source: &Function) -> Result<SourceFrame, X86BodyRefusal> {
    let domain = |reason: String| unsupported(X86BodyUnsupported::SourceDomain(reason));
    // Name WHICH frame condition fired, one per refusal, so a census histogram
    // attributes every exclusion to exactly one cause. Stack slots and a
    // leading sret buffer are inside the domain (slice 4, below), and so are
    // direct calls to a callee whose argument 0 is its return buffer (slice
    // 7, checked per call); these three remaining conditions are not.
    let frame_conditions: [(bool, &str); 3] = [
        (!source.eh_info.is_empty(), "EH metadata"),
        (
            source.stack_protector != StackProtectorMode::None,
            "a stack protector",
        ),
        (
            !source.sret_arg_indirect_callees.is_empty(),
            "an sret-arg indirect callee",
        ),
    ];
    if let Some((_, named)) = frame_conditions.iter().find(|(fired, _)| *fired) {
        return Err(domain(format!(
            "requires no EH, stack protector or sret callee metadata: has {named}"
        )));
    }
    // An sret function (slice 4): a LEADING hidden buffer parameter and no
    // return value. Its result is the stores it makes through the buffer,
    // which are incoming stores, and System V requires it to return the
    // buffer's address in RAX, which is its observed return value.
    let sret = match source.abi_sret_param {
        None => false,
        Some(AbiSretParam { param_index: 0 })
            if source.signature.returns.is_empty()
                && source.signature.params.first() == Some(&Type::I64) =>
        {
            true
        }
        Some(_) => {
            return Err(domain(
                "requires an sret buffer to be a leading I64 parameter of a function with no \
                 return value"
                    .into(),
            ));
        }
    };
    // Private stack slots (slice 4): each is a distinct region of the frame,
    // disjoint from every other slot and from all incoming memory. Slice 20
    // (OD-194): bounded by their bytes in all, below, not by their count.
    if source.stack_slots.iter().any(|slot| {
        slot.allocation != StackSlotAllocationKind::Fixed
            || !(1..=MAX_SLOT_BYTES).contains(&slot.size)
    }) {
        return Err(domain(format!(
            "requires fixed-size stack slots of 1 to {MAX_SLOT_BYTES} bytes, of at most \
             {MAX_SLOT_TOTAL_BYTES} bytes in all"
        )));
    }
    let mut slot_sizes: Vec<u32> = source.stack_slots.iter().map(|slot| slot.size).collect();
    let mut machine_slots = source.stack_slots.clone();
    let signature = &source.signature;
    // Each parameter is a scalar in one argument register or (slice 8) an
    // aggregate whose System V INTEGER eightbytes take one register each,
    // assigned in order (psABI §3.2.3). The body sees an aggregate parameter
    // as the address of a private copy, which the selector allocates after
    // the source's slots, in parameter order. Slice 11: an `I128` takes the
    // next two INTEGER registers (low half first) and a float the next SSE
    // register, XMM0-XMM7, numbered separately ([`argument_roots`]).
    let mut abis = Vec::with_capacity(signature.params.len());
    for ty in &signature.params {
        let abi = match Carrier::of(ty) {
            Some(carrier) => ParamAbi::Scalar(carrier),
            None => {
                let aggregate = classify_aggregate(ty)
                    .map_err(|_| domain(aggregate_refusal("parameter", ty)))?;
                let slot = slot_sizes.len() as u32;
                slot_sizes.push(aggregate.size);
                machine_slots.push(trust_cg_lower::function::StackSlotInfo::new(
                    aggregate.size,
                    aggregate.align,
                ));
                ParamAbi::Aggregate { aggregate, slot }
            }
        };
        abis.push(abi);
    }
    let Some(locations) = parameter_locations(&abis) else {
        // System V passes an argument that no longer fits in its class's
        // argument registers on the stack; slice 13 admits there only an
        // integer scalar of at most 64 bits in its own eightbyte, and slice 15
        // an `I128` in two.
        return Err(domain(
            "passes its parameters in more than six argument registers (or eight SSE \
             registers), and one System V then passes on the stack is not an I8, I16, I32, \
             I64 or I128"
                .into(),
        ));
    };
    let params: Vec<Param> = abis
        .into_iter()
        .zip(locations)
        .map(|(abi, (roots, stack))| Param { abi, roots, stack })
        .collect();
    // Void (and `-> !`) bodies are admitted only with a direct call whose
    // arguments give the theorem an observable (checked after the walk of
    // the chain below). Two results (slice 5) are the System V RAX:RDX
    // return pair, a Rust `ScalarPair` return; a third leaves the C return
    // file for TrustCG's internal multi-result convention. One aggregate
    // result (slice 8) returns its eightbytes in RAX, then RDX.
    let mut returned_aggregate = None;
    let return_tys: Vec<ReturnLane> = match signature.returns.as_slice() {
        // The sret buffer's address, returned in RAX.
        [] if sret => vec![ReturnLane::Scalar(Carrier::I64)],
        returns if returns.len() > SYSV_RETURN_ROOTS.len() => {
            return Err(domain(
                "requires at most two results (the System V RAX:RDX return pair)".into(),
            ));
        }
        [only] if Carrier::of(only).is_none() => {
            let aggregate =
                classify_aggregate(only).map_err(|_| domain(aggregate_refusal("result", only)))?;
            let lanes = aggregate
                .lanes
                .iter()
                .map(|lane| ReturnLane::Eightbyte(*lane))
                .collect();
            returned_aggregate = Some(aggregate);
            lanes
        }
        // Slice 11: an `I128` result is the RAX:RDX pair, low half in RAX.
        [Type::I128] => vec![ReturnLane::Half(0), ReturnLane::Half(1)],
        returns => returns
            .iter()
            .map(|ty| match Carrier::of(ty) {
                Some(Carrier::I128) => Err(domain(
                    "has an i128 result beside another result (more than the RAX:RDX pair)".into(),
                )),
                Some(carrier) => Ok(ReturnLane::Scalar(carrier)),
                None if matches!(ty, Type::Struct(_) | Type::Array(..) | Type::Enum { .. }) => Err(
                    domain("has an aggregate result beside another result".into()),
                ),
                None => Err(domain(aggregate_refusal("result", ty))),
            })
            .collect::<Result<Vec<_>, _>>()?,
    };
    // Each lane's register: INTEGER lanes in RAX, then RDX, and (slice 11)
    // float lanes in XMM0, then XMM1. At most two results, so neither class
    // runs out.
    let return_roots =
        result_roots(return_tys.iter().map(|lane| lane.sse())).expect("at most two result lanes");
    // Slice 8: each direct call whose one result is an aggregate returns it
    // into a private slot the selector allocates at the call, in its layout
    // order, after the parameters' copies.
    let mut result_slots = HashMap::new();
    for block in source.layout_order() {
        let Some(body) = source.blocks.get(&block) else {
            continue;
        };
        for (index, inst) in body.instructions.iter().enumerate() {
            if !matches!(inst.opcode, L::Call { .. }) || inst.results.len() != 1 {
                continue;
            }
            let Some(ty) = source.value_types.get(&inst.results[0]) else {
                continue;
            };
            if !matches!(ty, Type::Struct(_) | Type::Array(..) | Type::Enum { .. }) {
                continue;
            }
            let aggregate =
                classify_aggregate(ty).map_err(|_| domain(aggregate_refusal("call result", ty)))?;
            let slot = slot_sizes.len() as u32;
            slot_sizes.push(aggregate.size);
            machine_slots.push(trust_cg_lower::function::StackSlotInfo::new(
                aggregate.size,
                aggregate.align,
            ));
            result_slots.insert((block, index), (slot, aggregate));
        }
    }
    // Slice 20 (OD-194): the slots' bytes in all, the aggregate parameters'
    // copies and call results' slots included.
    let total: u64 = slot_sizes.iter().map(|size| u64::from(*size)).sum();
    if total > MAX_SLOT_TOTAL_BYTES {
        return Err(domain(format!(
            "requires fixed-size stack slots of 1 to {MAX_SLOT_BYTES} bytes, of at most \
             {MAX_SLOT_TOTAL_BYTES} bytes in all (has {} slots of {total} bytes)",
            slot_sizes.len()
        )));
    }
    // Aggregate pointee metadata describes memory behind a pointer parameter;
    // the theorem models incoming memory by address alone, so the parameter
    // is still its 64 bits. It must name distinct pointer-carrier parameters.
    let mut pointee_params = HashSet::new();
    for pointee in &source.param_pointee_types {
        let index = pointee.param_index as usize;
        if params.get(index).map(|param| &param.abi) != Some(&ParamAbi::Scalar(Carrier::I64))
            || !pointee_params.insert(index)
        {
            return Err(domain(format!(
                "pointee metadata names parameter {index}, which is not a distinct pointer carrier"
            )));
        }
    }
    Ok(SourceFrame {
        sret,
        slot_sizes,
        params,
        return_tys,
        return_roots,
        returned_aggregate,
        result_slots,
        machine_slots,
    })
}

/// The bounds of the per-path encoding (slice 6): a several-path source of
/// at most this many LIR blocks, entry-to-end paths, and instructions on one
/// path keeps the slice-6 theorem, one claim per path. A larger acyclic
/// source (slice 9) is stated over its DAG ([`admitted_dag`]), whose size is
/// linear in its blocks, so no path count bounds it.
const MAX_SOURCE_BLOCKS: usize = 16;
const MAX_PATHS: usize = 16;
const MAX_PATH_INSTRUCTIONS: usize = 256;

/// The bounds of every admitted source (slice 9): at most this many LIR
/// blocks and LIR instructions in all. They bound the theorem's size, which
/// is linear in both; past them AY's strict certification on the
/// qualification host certifies too few theorems to pay for their solves
/// (LIMITATIONS.md records the measured rate by size).
const MAX_BODY_BLOCKS: usize = 128;
const MAX_BODY_INSTRUCTIONS: usize = 1024;

/// The bounds of the machine stream the walks read (slice 9; 16 blocks and
/// 256 rows through slice 8): at most this many laid-out blocks and rows. On
/// the qualification host no theorem of more rows certified offline (0 of
/// the 13 Darwin `core` bodies of 512 to 1014 rows slice 9 would bind, 7 of
/// the 12 of 384 to 511), so a larger body makes no claim rather than cost a
/// solve that cannot credit it.
const MAX_MACHINE_BLOCKS: usize = MAX_BODY_BLOCKS;
const MAX_MACHINE_ROWS: usize = 512;

/// One entry-to-end path of the source: its blocks in order, each with the
/// index of the successor edge the path takes at its conditional terminator
/// (a `Brif`: 0 for `then`, 1 for `else`; a `Switch`: its case, then the
/// default last), `None` after a `Jump`, `Return` or `Trap`.
type PathSpec = Vec<(Block, Option<usize>)>;

/// The validated control flow of the source (slices 6, 9 and 12), from the
/// LIR alone.
struct SourceCfg {
    /// Each block's successors in edge order: `then` before `else`, `Switch`
    /// cases in order before the default.
    successors: HashMap<Block, Vec<Block>>,
    /// Every block in the reverse postorder of a depth first walk from the
    /// entry block, edges in successor order: the entry block first, and
    /// every block after all its predecessors along forward edges (an
    /// acyclic source's topological order; slice 12: every back edge ends at
    /// a loop header that comes before its latch).
    order: Vec<Block>,
    /// Each block's predecessors, in `order`.
    predecessors: HashMap<Block, Vec<Block>>,
    /// The number of entry-to-end paths (saturating; slice 12: back edges
    /// not followed).
    paths: usize,
    /// The most instructions on one entry-to-end path (back edges not
    /// followed).
    longest_path: usize,
    /// Slice 12: the natural loops of a source with back edges, outermost
    /// first (a header comes before the headers of the loops it contains);
    /// empty for an acyclic source.
    loops: Vec<NaturalLoop>,
    /// Slice 14: some `Switch` reaches one block by several of its cases (or
    /// a case and its default), one edge of a disjunctive test
    /// ([`switch_targets`]). The DAG encoding states it (its machine side may
    /// reach the block by several routes, [`block_routes`]); the slice-6
    /// per-path encoding does not.
    shared_targets: bool,
    /// Slice 20 (ruling OD-191): some `Switch` the selector may lower as a
    /// binary search ([`searched_switch`]): its default is reached by several
    /// routes through the search (every leaf's `jmp`), which the DAG encoding
    /// states ([`block_routes`]) and the slice-6 per-path encoding does not.
    searched_switch: bool,
    /// Slice 14: some block divides or guards a division, so a run may stop
    /// short of its end ([`SourceStop`]; slice 22: an `I128` division is a
    /// call and does not). A several-path source with stops
    /// is stated over its DAG, whose claims carry the run's stop condition
    /// block by block; the slice-6 per-path encoding does not.
    stops: bool,
    /// The blocks of `source.blocks` the walk from the entry block does not
    /// reach, so no entry-to-end path contains them: dead code a pass left
    /// behind. They are EXCLUDED from `order`, `predecessors`, `paths`,
    /// `longest_path` and `loops`, never removed from the LIR: `block_order`
    /// lays them out deliberately and the LIR's canonical verifier identity
    /// counts them, so removing them would move certificate keys.
    /// [`block_correspondence`] and [`walk_machine_for_callers`] account for
    /// the machine blocks that lower them. Empty for almost every source.
    dead: std::collections::BTreeSet<Block>,
}

/// A natural loop of the source (slice 12): a header that dominates every
/// latch of it (the source of a back edge into it), and its blocks: the
/// header and every block that reaches a latch without passing the header.
/// Between two visits of its header, a run executes only these blocks.
#[derive(Debug, Clone)]
struct NaturalLoop {
    header: Block,
    blocks: std::collections::BTreeSet<Block>,
    latches: Vec<Block>,
}

impl SourceCfg {
    /// Whether the slice-6 encoding states this source: one path (the slice
    /// 1-5 chain, whatever its length), or several within the slice-6
    /// bounds. Any other admitted acyclic source is stated over its DAG
    /// (slice 9; slice 14: a several-path source with a shared `Switch`
    /// target or a division too), and a source with a loop over its regions
    /// (slice 12). The choice depends on the source's shape alone, never on
    /// the machine. Slice 24a (OD-226): a merged-chain quotient is stated with
    /// its ORIGINAL source's choice, never its own ([`admitted_quotient`]).
    fn per_path(&self) -> bool {
        self.loops.is_empty()
            && (self.paths == 1
                || (!self.shared_targets
                    && !self.searched_switch
                    && !self.stops
                    && self.order.len() <= MAX_SOURCE_BLOCKS
                    && self.paths <= MAX_PATHS
                    && self.longest_path <= MAX_PATH_INSTRUCTIONS))
    }

    /// The cut points of a source with loops (slice 12): the entry block,
    /// then every loop header, in `order`.
    fn cut_points(&self) -> Vec<Block> {
        let headers: HashSet<Block> = self.loops.iter().map(|lp| lp.header).collect();
        std::iter::once(self.order[0])
            .chain(
                self.order
                    .iter()
                    .copied()
                    .filter(|block| headers.contains(block)),
            )
            .collect()
    }
}

/// The source's LIR CFG, from the LIR alone: acyclic (slice 6), or (slice
/// 12) reducible with natural loops ([`natural_loops`]).
///
/// Every block ends in exactly one terminator, `Jump`, `Brif` (on one value,
/// to two different blocks), `Switch` (on one value, with at least one case,
/// every edge to a different block), `Return` or `Trap`, and branches only
/// to blocks that have a body -- checked for EVERY block, reachable or not.
/// An irreducible cycle or a loop headed by the entry block, any other
/// terminator (an invoke, an indirect branch) or a bound exceeded
/// ([`MAX_BODY_BLOCKS`], [`MAX_BODY_INSTRUCTIONS`]) is
/// [`X86BodyUnsupported::SourceShape`], naming which: no claim.
///
/// A block the walk from the entry block does not reach is [`SourceCfg::dead`]
/// and is in no other field: it lies on no entry-to-end path, so the path-by-
/// path theorem neither constrains it nor needs it. The bounds above still
/// count it, conservatively.
fn source_cfg(source: &Function) -> Result<SourceCfg, X86BodyRefusal> {
    source_cfg_bounded(source, MAX_BODY_BLOCKS, MAX_BODY_INSTRUCTIONS)
}

/// [`source_cfg`] within `max_blocks` blocks and `max_instructions`
/// instructions (slice 16: a function stated in parts has its own bounds).
fn source_cfg_bounded(
    source: &Function,
    max_blocks: usize,
    max_instructions: usize,
) -> Result<SourceCfg, X86BodyRefusal> {
    let shape = |detail: String| unsupported(X86BodyUnsupported::SourceShape(detail));
    if source.blocks.is_empty() || source.blocks.len() > max_blocks {
        return Err(shape(format!(
            "{} blocks (the lane admits 1 to {max_blocks})",
            source.blocks.len()
        )));
    }
    if !source.block_order.is_empty()
        && (source.block_order.len() != source.blocks.len()
            || source.block_order.iter().collect::<HashSet<_>>().len() != source.blocks.len()
            || source
                .block_order
                .iter()
                .any(|id| !source.blocks.contains_key(id)))
    {
        return Err(shape(
            "the block order does not name every block exactly once".into(),
        ));
    }
    if !source.blocks.contains_key(&source.entry_block) {
        return Err(shape("the entry block has no body".into()));
    }
    // Each block's successors, from its one terminator.
    let mut successors: HashMap<Block, Vec<Block>> = HashMap::new();
    let mut shared_targets = false;
    let mut searched = false;
    for (id, block) in &source.blocks {
        let Some((last, body)) = block.instructions.split_last() else {
            return Err(shape(format!("block {id:?} is empty")));
        };
        let is_terminator = |opcode: &L| {
            matches!(
                opcode,
                L::Jump { .. } | L::Brif { .. } | L::Return | L::Trap | L::Switch { .. }
            )
        };
        if body.iter().any(|inst| is_terminator(&inst.opcode)) {
            return Err(shape(format!(
                "block {id:?} transfers control before its last instruction"
            )));
        }
        let targets = match &last.opcode {
            L::Jump { dest } if last.args.is_empty() && last.results.is_empty() => vec![*dest],
            L::Brif {
                cond,
                then_dest,
                else_dest,
            } if last.args == [*cond] && last.results.is_empty() => {
                if then_dest == else_dest {
                    return Err(shape(format!(
                        "block {id:?} branches to {then_dest:?} on both edges"
                    )));
                }
                vec![*then_dest, *else_dest]
            }
            L::Return | L::Trap => Vec::new(),
            L::Switch { cases, default } if last.args.len() == 1 && last.results.is_empty() => {
                if cases.is_empty() {
                    return Err(shape(format!("block {id:?} ends in a Switch with no case")));
                }
                // Slice 14: one edge per DISTINCT target, in first-occurrence
                // order (cases, then the default). Several cases (and the
                // default) that reach one block are one edge whose test is
                // the disjunction of theirs ([`switch_targets`]): the adapter
                // gives a case with block arguments a copy block of its own,
                // so the cases that share a target pass it no argument and
                // bring it the same state, and the edge loses nothing.
                let targets = switch_targets(cases, *default);
                if targets.len() != cases.len() + 1 {
                    shared_targets = true;
                }
                searched |= searched_switch(cases);
                targets
            }
            other => {
                let name = format!("{other:?}");
                return Err(shape(format!(
                    "block {id:?} ends in {}, which is not a Jump, Brif, Return or Trap",
                    name.split([' ', '{', '(']).next().unwrap_or_default()
                )));
            }
        };
        if let Some(missing) = targets
            .iter()
            .find(|target| !source.blocks.contains_key(target))
        {
            return Err(shape(format!(
                "block {id:?} branches to {missing:?}, which has no body"
            )));
        }
        successors.insert(*id, targets);
    }
    // Reachable, with its retreating edges: a depth-first colouring from the
    // entry block; a successor still on the stack closes a cycle (slice 12:
    // admitted only as a natural loop, below). The postorder of the same
    // walk, reversed, orders every block after its forward predecessors.
    #[derive(Clone, Copy, PartialEq)]
    enum Colour {
        Open,
        Done,
    }
    let mut colour: HashMap<Block, Colour> = HashMap::new();
    let mut postorder: Vec<Block> = Vec::with_capacity(source.blocks.len());
    let mut retreating: Vec<(Block, Block)> = Vec::new();
    let mut stack: Vec<(Block, usize)> = vec![(source.entry_block, 0)];
    colour.insert(source.entry_block, Colour::Open);
    while let Some((block, next)) = stack.pop() {
        let targets = &successors[&block];
        let Some(target) = targets.get(next).copied() else {
            colour.insert(block, Colour::Done);
            postorder.push(block);
            continue;
        };
        stack.push((block, next + 1));
        match colour.get(&target) {
            Some(Colour::Open) => retreating.push((block, target)),
            Some(Colour::Done) => {}
            None => {
                colour.insert(target, Colour::Open);
                stack.push((target, 0));
            }
        }
    }
    // A block the walk did not colour lies on NO entry-to-end path, so the
    // body theorem -- which is stated path by path -- says nothing about it
    // and needs nothing from it. Refusing the whole function over one was a
    // gate, not a structural need: every field below already derives from
    // the walk's `postorder`, which is reachable by construction. The gate
    // cost real credit (a dead loop-setup block a pass left behind refused
    // bodies whose live code is fully supported), and it sent an earlier
    // investigation to the per-instruction fallback's symptom -- a `Lea`
    // with only sampled evidence -- rather than here.
    let dead: std::collections::BTreeSet<Block> = source
        .blocks
        .keys()
        .filter(|block| !colour.contains_key(*block))
        .copied()
        .collect();
    let order: Vec<Block> = postorder.iter().rev().copied().collect();
    let mut predecessors: HashMap<Block, Vec<Block>> =
        order.iter().map(|block| (*block, Vec::new())).collect();
    for block in &order {
        for target in &successors[block] {
            predecessors
                .get_mut(target)
                .expect("every successor is a block")
                .push(*block);
        }
    }
    // Path counts and the longest path, successors first (the postorder);
    // slice 12: a back edge is not followed.
    let back: HashSet<(Block, Block)> = retreating.iter().copied().collect();
    let mut counts: HashMap<Block, (usize, usize)> = HashMap::new();
    for block in &postorder {
        let length = source.blocks[block].instructions.len();
        let (paths, longest) = match successors[block].as_slice() {
            [] => (1, length),
            targets => targets
                .iter()
                .filter(|target| !back.contains(&(*block, **target)))
                .fold((0usize, length), |(paths, longest), target| {
                    let (target_paths, target_longest) = counts[target];
                    (
                        paths.saturating_add(target_paths),
                        longest.max(length + target_longest),
                    )
                }),
        };
        counts.insert(*block, (paths, longest));
    }
    let (paths, longest_path) = counts[&source.entry_block];
    let instructions: usize = source
        .blocks
        .values()
        .map(|block| block.instructions.len())
        .sum();
    if instructions > max_instructions {
        return Err(shape(format!(
            "{instructions} instructions (the lane admits at most {max_instructions})"
        )));
    }
    let loops = natural_loops(&order, &predecessors, &retreating).map_err(shape)?;
    Ok(SourceCfg {
        successors,
        order,
        predecessors,
        paths,
        longest_path,
        loops,
        shared_targets,
        searched_switch: searched,
        stops: {
            // Slice 22 (OD-202): an `I128` division is a call, which never
            // stops the run; its guard does.
            let calls = split::i128_divisions(source);
            source.blocks.iter().any(|(block, body)| {
                body.instructions
                    .iter()
                    .enumerate()
                    .any(|(index, inst)| match inst.opcode {
                        L::Udiv | L::Sdiv | L::Urem | L::Srem => !calls.contains(&(*block, index)),
                        L::GuardDivZero { .. } => true,
                        _ => false,
                    })
            })
        },
        dead,
    })
}

/// Slice 20 (ruling OD-191): whether the x86-64 selector may lower a `Switch`
/// of these cases as a balanced binary search (`emit_switch_bst`, whose
/// precondition this is): five or more cases, pairwise distinct, each in `[0,
/// i32::MAX]`. (The selector prefers a jump table for a dense set; the
/// encoding depends on the source alone, so such a switch is stated over the
/// DAG either way.)
fn searched_switch(cases: &[(i64, Block)]) -> bool {
    let values: HashSet<i64> = cases.iter().map(|(value, _)| *value).collect();
    cases.len() >= 5
        && values.len() == cases.len()
        && cases
            .iter()
            .all(|(value, _)| (0..=i64::from(i32::MAX)).contains(value))
}

/// The distinct blocks a `Switch` reaches, in first-occurrence order over its
/// cases, then its default (slice 14): one source edge each. Before slice 14
/// a `Switch` with two edges to one block was refused, so on every other
/// source this is the cases' targets then the default, as before.
fn switch_targets(cases: &[(i64, Block)], default: Block) -> Vec<Block> {
    let mut targets: Vec<Block> = Vec::with_capacity(cases.len() + 1);
    for target in cases
        .iter()
        .map(|(_, target)| *target)
        .chain(std::iter::once(default))
    {
        if !targets.contains(&target) {
            targets.push(target);
        }
    }
    targets
}

/// The natural loops of a source whose depth-first walk found the
/// `retreating` edges (slice 12), outermost first, from the reverse
/// postorder `order` and every block's predecessors. Each retreating edge
/// must be a back edge, its target dominating its source (the CFG is
/// reducible, so every cycle passes the header of a natural loop), and the
/// entry block must head none; otherwise the refusal names the edge.
fn natural_loops(
    order: &[Block],
    predecessors: &HashMap<Block, Vec<Block>>,
    retreating: &[(Block, Block)],
) -> Result<Vec<NaturalLoop>, String> {
    if retreating.is_empty() {
        return Ok(Vec::new());
    }
    // Immediate dominators over the reverse postorder (Cooper, Harvey and
    // Kennedy's iteration); the entry block is its own.
    let index: HashMap<Block, usize> = order.iter().enumerate().map(|(i, b)| (*b, i)).collect();
    let entry = order[0];
    let mut idom: HashMap<Block, Block> = HashMap::from([(entry, entry)]);
    let mut changed = true;
    while changed {
        changed = false;
        for block in order.iter().skip(1) {
            let mut new: Option<Block> = None;
            for predecessor in &predecessors[block] {
                if !idom.contains_key(predecessor) {
                    continue;
                }
                new = Some(match new {
                    None => *predecessor,
                    Some(mut a) => {
                        let mut b = *predecessor;
                        while a != b {
                            while index[&a] > index[&b] {
                                a = idom[&a];
                            }
                            while index[&b] > index[&a] {
                                b = idom[&b];
                            }
                        }
                        a
                    }
                });
            }
            let new = new.expect("every reachable block but the entry has a predecessor");
            if idom.get(block) != Some(&new) {
                idom.insert(*block, new);
                changed = true;
            }
        }
    }
    let dominates = |a: Block, mut b: Block| loop {
        if a == b {
            return true;
        }
        let up = idom[&b];
        if up == b {
            return false;
        }
        b = up;
    };
    let mut loops: Vec<NaturalLoop> = Vec::new();
    for (latch, header) in retreating {
        if !dominates(*header, *latch) {
            return Err(format!(
                "an irreducible loop (block {latch:?} branches back to block {header:?}, which \
                 does not dominate it)"
            ));
        }
        if *header == entry {
            return Err(format!(
                "a loop whose header is the entry block (block {latch:?} branches back to it)"
            ));
        }
        let position = match loops.iter().position(|lp| lp.header == *header) {
            Some(position) => position,
            None => {
                loops.push(NaturalLoop {
                    header: *header,
                    blocks: std::collections::BTreeSet::from([*header]),
                    latches: Vec::new(),
                });
                loops.len() - 1
            }
        };
        let lp = &mut loops[position];
        lp.latches.push(*latch);
        let mut work = vec![*latch];
        while let Some(block) = work.pop() {
            if lp.blocks.insert(block) {
                work.extend(predecessors[&block].iter().copied());
            }
        }
    }
    loops.sort_by_key(|lp| index[&lp.header]);
    Ok(loops)
}

/// The control flow of one region of a source with loops (slice 12): the
/// blocks a run reaches from a cut point (the entry block or a loop header)
/// before it reaches a cut point again. Every cycle passes a loop header
/// (the CFG is reducible), so a region is a DAG, and the source's reverse
/// postorder restricted to it is a topological order of it. An edge into a
/// cut point is a CUT EDGE: the region's run ends there, and the cut
/// point's region runs next.
struct RegionCfg {
    /// The cut point the region starts at.
    start: Block,
    /// The region's blocks in the source's order, `start` first.
    order: Vec<Block>,
    /// Each block's successors in edge order, cut edges included.
    successors: HashMap<Block, Vec<Block>>,
    /// Each block's predecessors inside the region (no cut edge), in
    /// `order`; the start block has none.
    predecessors: HashMap<Block, Vec<Block>>,
}

/// The regions of a source with loops (slice 12), one per cut point, in
/// [`SourceCfg::cut_points`] order (the entry block's first).
fn source_regions(cfg: &SourceCfg) -> Vec<RegionCfg> {
    let cut_points = cfg.cut_points();
    let cuts: HashSet<Block> = cut_points.iter().copied().collect();
    cut_points
        .into_iter()
        .map(|start| {
            let mut members: HashSet<Block> = HashSet::from([start]);
            let mut work = vec![start];
            while let Some(block) = work.pop() {
                for target in &cfg.successors[&block] {
                    if !cuts.contains(target) && members.insert(*target) {
                        work.push(*target);
                    }
                }
            }
            let order: Vec<Block> = cfg
                .order
                .iter()
                .copied()
                .filter(|block| members.contains(block))
                .collect();
            let mut predecessors: HashMap<Block, Vec<Block>> =
                order.iter().map(|block| (*block, Vec::new())).collect();
            for block in &order {
                for target in &cfg.successors[block] {
                    if !cuts.contains(target) {
                        predecessors
                            .get_mut(target)
                            .expect("a region successor is in the region")
                            .push(*block);
                    }
                }
            }
            let successors = order
                .iter()
                .map(|block| (*block, cfg.successors[block].clone()))
                .collect();
            RegionCfg {
                start,
                order,
                successors,
                predecessors,
            }
        })
        .collect()
}

/// Every entry-to-end path of an acyclic source the slice-6 encoding states
/// ([`SourceCfg::per_path`]), as [`enumerate_paths`] enumerates them; any
/// other source is a [`X86BodyUnsupported::Construction`] refusal here
/// (tests only).
#[cfg(test)]
fn source_paths(source: &Function) -> Result<Vec<PathSpec>, X86BodyRefusal> {
    let cfg = source_cfg(source)?;
    if !cfg.per_path() {
        return Err(unsupported(X86BodyUnsupported::Construction(format!(
            "{} entry-to-end paths are stated over the DAG, not path by path",
            cfg.paths
        ))));
    }
    Ok(enumerate_paths(source, &cfg))
}

/// Every entry-to-end path of a source the slice-6 encoding states,
/// enumerated depth first, a terminator's edges in successor order (`then`
/// before `else`, `Switch` cases in order before the default).
fn enumerate_paths(source: &Function, cfg: &SourceCfg) -> Vec<PathSpec> {
    let mut paths = Vec::with_capacity(cfg.paths);
    let mut prefix: PathSpec = Vec::new();
    fn extend(
        block: Block,
        source: &Function,
        successors: &HashMap<Block, Vec<Block>>,
        prefix: &mut PathSpec,
        paths: &mut Vec<PathSpec>,
    ) {
        let conditional = matches!(
            source.blocks[&block]
                .instructions
                .last()
                .map(|inst| &inst.opcode),
            Some(L::Brif { .. } | L::Switch { .. })
        );
        match successors[&block].as_slice() {
            [] => {
                prefix.push((block, None));
                paths.push(prefix.clone());
                prefix.pop();
            }
            targets => {
                for (edge, next) in targets.iter().enumerate() {
                    prefix.push((block, conditional.then_some(edge)));
                    extend(*next, source, successors, prefix, paths);
                    prefix.pop();
                }
            }
        }
    }
    extend(
        source.entry_block,
        source,
        &cfg.successors,
        &mut prefix,
        &mut paths,
    );
    paths
}

/// Admit the source: its frame, its acyclic CFG, and every path of it as a
/// chain (slices 1 to 6), or (slice 9) every block of its DAG
/// ([`admitted_dag`]) when [`SourceCfg::per_path`] does not hold. The
/// function-level checks that span paths (sidecar type hints, the
/// observable) run on the whole body.
fn admitted_body(source: &Function) -> Result<SourceBody, X86BodyRefusal> {
    admitted_body_as(source, None)
}

/// [`admitted_body`] under the shape's encoding (`dag: None`), or (tests
/// only, qualification evidence) a several-path source stated over its DAG
/// (`Some(true)`) or path by path (`Some(false)`) whatever its shape. (Slice
/// 24a's [`admitted_quotient`] states a quotient over its original's choice
/// through the same override of [`admitted_body_over`], in production.)
fn admitted_body_as(source: &Function, dag: Option<bool>) -> Result<SourceBody, X86BodyRefusal> {
    let frame = admitted_frame(source)?;
    let cfg = source_cfg(source)?;
    admitted_body_over(source, dag, frame, cfg)
}

/// [`admitted_body_as`] within `max_blocks` blocks and `max_instructions`
/// instructions (slice 16: whether a source past the single-query bounds is
/// admitted as one body when its size is ignored).
fn admitted_body_bounded(
    source: &Function,
    dag: Option<bool>,
    max_blocks: usize,
    max_instructions: usize,
) -> Result<SourceBody, X86BodyRefusal> {
    let frame = admitted_frame(source)?;
    let cfg = source_cfg_bounded(source, max_blocks, max_instructions)?;
    admitted_body_over(source, dag, frame, cfg)
}

/// [`admitted_body_as`] from the source's admitted frame and control flow.
fn admitted_body_over(
    source: &Function,
    dag: Option<bool>,
    frame: SourceFrame,
    cfg: SourceCfg,
) -> Result<SourceBody, X86BodyRefusal> {
    check_entry_parameters(source, &frame)?;
    let mut sites = SourceSites::default();
    let per_path = match dag {
        None => cfg.per_path(),
        Some(dag) => cfg.paths == 1 || !dag,
    };
    let (paths, dag, loops) = if !cfg.loops.is_empty() {
        // Slice 12: a source with loops, over its regions.
        (
            Vec::new(),
            None,
            Some(admitted_loops(source, &frame, &cfg, &mut sites)?),
        )
    } else if per_path {
        let paths = enumerate_paths(source, &cfg)
            .iter()
            .map(|spec| admit_path(source, &frame, spec, &mut sites))
            .collect::<Result<Vec<_>, _>>()?;
        (paths, None, None)
    } else {
        (
            Vec::new(),
            Some(admitted_dag(source, &frame, &cfg, &mut sites)?),
            None,
        )
    };
    finish_admission(source, frame, &cfg, paths, dag, loops, sites)
}

/// The entry block's parameters must be the function's, `Value(0..n)` at
/// their declared types.
fn check_entry_parameters(source: &Function, frame: &SourceFrame) -> Result<(), X86BodyRefusal> {
    let domain = |reason: String| unsupported(X86BodyUnsupported::SourceDomain(reason));
    let block = source
        .blocks
        .get(&source.entry_block)
        .ok_or_else(|| domain("missing entry block".into()))?;
    if !block.params.is_empty()
        && (block.params.len() != frame.params.len()
            || block
                .params
                .iter()
                .enumerate()
                .any(|(i, (value, ty))| value.0 as usize != i || *ty != frame.params[i].abi.lir()))
    {
        return Err(domain(
            "entry parameters disagree with the Value(0..n) signature convention".into(),
        ));
    }
    Ok(())
}

/// The function-level checks of an admitted source that span its units (the
/// sidecar type hints, the observable), and the admitted body.
fn finish_admission(
    source: &Function,
    frame: SourceFrame,
    cfg: &SourceCfg,
    paths: Vec<SourceProgram>,
    dag: Option<DagBody>,
    loops: Option<LoopBody>,
    sites: SourceSites,
) -> Result<SourceBody, X86BodyRefusal> {
    let domain = |reason: String| unsupported(X86BodyUnsupported::SourceDomain(reason));
    // The admitted units: each path (slices 1 to 6), or each DAG block's
    // fragment (slice 9; slice 12: each region's), whose `types` hold every
    // value defined on every path into the block's end.
    let programs: Vec<&SourceProgram> = match (&dag, &loops) {
        (Some(dag), _) => dag.order.iter().map(|block| &dag.blocks[block]).collect(),
        (None, Some(loops)) => loops
            .regions
            .iter()
            .flat_map(|region| {
                region
                    .dag
                    .order
                    .iter()
                    .map(|block| &region.dag.blocks[block])
            })
            .collect(),
        (None, None) => paths.iter().collect(),
    };
    let several = dag.is_some() || loops.is_some() || paths.len() > 1;
    // Sidecar type hints must describe values this function defines, at the
    // type every path that defines them gives them. A hint for a value no
    // path defines, or one that retypes a value (a `Copy` hinted as another
    // type is a cast with semantics), is never inherited. (Slice 8: a private
    // slot address the LIR types as a by-value aggregate has that aggregate
    // type.)
    for (value, hint) in &source.value_types {
        let mut defined = programs
            .iter()
            .filter_map(|path| path.lir_type(value))
            .peekable();
        if defined.peek().is_none() || defined.any(|ty| ty != *hint) {
            return Err(domain(format!("inconsistent type hint for {value:?}")));
        }
    }
    // Slices 1 and 2: a body without a call returns exactly one value (a
    // void body's theorem would state nothing). With calls, the call
    // arguments are observable too, and with incoming-memory accesses
    // (slice 4) their addresses and stored values; a body with no result,
    // no call argument and no incoming access still has nothing to state.
    // Private stack contents are never observable. With several paths
    // (slice 6), which path runs is observable too: its calls, its accesses
    // and whether it returns or traps.
    let calls = programs.iter().any(|path| !path.calls.is_empty());
    let accesses = programs.iter().any(|path| !path.accesses.is_empty());
    let returns = programs.iter().any(|path| !path.return_tys.is_empty());
    if !calls && !accesses && !returns && !several {
        return Err(domain(
            "requires a B1, I8, I16, I32 or I64 result, a call or an incoming-memory access".into(),
        ));
    }
    let arguments = programs
        .iter()
        .flat_map(|path| &path.calls)
        .any(|call| !call.args.is_empty() || call.callee.is_some());
    let ends: Vec<SourceEnd> = programs
        .iter()
        .map(|path| path.end)
        .filter(|end| *end != SourceEnd::Continue)
        .collect();
    let ends_differ = ends.iter().any(|end| *end != ends[0]);
    let observable = returns || accesses || arguments || (several && (calls || ends_differ));
    if !observable {
        return Err(unsupported(X86BodyUnsupported::NoObservable));
    }
    // Slice 17: every indexed use bounded in each region that reaches it, and
    // at most [`indexed::MAX_SOURCE_CANDIDATES`] candidates in all.
    check_indexed_bounds(source, cfg, dag.as_ref(), loops.as_ref(), &programs)
        .map_err(|(_, refusal)| refusal)?;
    Ok(SourceBody {
        long_chain: dag.is_none()
            && loops.is_none()
            && paths.len() == 1
            && cfg.longest_path > MAX_PATH_INSTRUCTIONS,
        paths,
        dag,
        loops,
        sites,
        machine_slots: frame.machine_slots,
        dead: cfg.dead.clone(),
    })
}

/// Slice 17: every indexed use of the admitted units must be bounded in each
/// region that reaches it ([`indexed::check_bounds`]: the source's DAG, each
/// region of a source with loops or cut points, or an acyclic source's whole
/// CFG), and the source's indexed accesses may have at most
/// [`indexed::MAX_SOURCE_CANDIDATES`] candidate offsets in all. A refusal
/// names the region start it was found in (slice 16 replans around it).
fn check_indexed_bounds(
    source: &Function,
    cfg: &SourceCfg,
    dag: Option<&DagBody>,
    loops: Option<&LoopBody>,
    programs: &[&SourceProgram],
) -> Result<(), (Option<Block>, X86BodyRefusal)> {
    if programs.iter().all(|program| program.indexed.is_empty()) {
        return Ok(());
    }
    #[cfg(test)]
    if WITHOUT_INDEXED_BOUNDS.with(std::cell::Cell::get) {
        return Ok(());
    }
    // The select arms of every indexed access (an argument has none).
    let total: usize = programs
        .iter()
        .flat_map(|program| &program.indexed)
        .filter(|site| site.width > 0)
        .map(|site| site.candidates().len())
        .sum();
    if total > indexed::MAX_SOURCE_CANDIDATES {
        return Err((
            None,
            unsupported(X86BodyUnsupported::SourceDomain(format!(
                "its indexed private stack accesses have {total} candidate offsets in all (the \
                 lane admits {})",
                indexed::MAX_SOURCE_CANDIDATES
            ))),
        ));
    }
    let whole = source_regions(cfg);
    let regions: Vec<(Block, indexed::RegionView<'_>)> = match (loops, dag) {
        (Some(loops), _) => loops
            .regions
            .iter()
            .map(|region| {
                (
                    region.dag.order[0],
                    indexed::RegionView {
                        order: &region.dag.order,
                        predecessors: &region.dag.predecessors,
                        successors: &region.dag.successors,
                    },
                )
            })
            .collect(),
        (None, Some(dag)) => vec![(
            dag.order[0],
            indexed::RegionView {
                order: &dag.order,
                predecessors: &dag.predecessors,
                successors: &dag.successors,
            },
        )],
        (None, None) => whole
            .iter()
            .map(|region| {
                (
                    region.start,
                    indexed::RegionView {
                        order: &region.order,
                        predecessors: &region.predecessors,
                        successors: &region.successors,
                    },
                )
            })
            .collect(),
    };
    indexed::check_bounds(source, &regions, programs)
}

/// The admitted source of a one-path body (the chain of slices 1 to 5).
#[cfg(test)]
fn admitted_source(source: &Function) -> Result<SourceProgram, X86BodyRefusal> {
    let mut body = admitted_body(source)?;
    assert_eq!(body.paths.len(), 1, "a one-path body");
    Ok(body.paths.remove(0))
}

/// The source state a path carries across a block boundary: what each
/// value is and what each private byte holds. On a path it flows block to
/// block; at a DAG join (slice 9) it is the merge of the states the incoming
/// edges bring ([`merge_admitted`]).
#[derive(Clone)]
struct AdmitState {
    /// Every defined value's carrier (a private stack address as `I64`).
    types: HashMap<Value, Carrier>,
    /// The exact affine value of an affine `I64`.
    affine: HashMap<Value, Affine>,
    /// The bits of each constant (for shift amounts and address offsets).
    constants: HashMap<Value, u64>,
    /// Private stack addresses.
    frame: HashMap<Value, FrameAddr>,
    /// Slice 17: private stack addresses at a non-constant offset.
    indexed: HashMap<Value, IndexedAddr>,
    /// Every byte of every slot something wrote.
    slot_bytes: Vec<Vec<Option<SlotByte>>>,
    /// Slice 8: the aggregate type of every value the LIR types as a
    /// by-value aggregate.
    aggregates: HashMap<Value, Type>,
    /// Slice 8: the call sites whose aggregate result may hold an address
    /// derived from an escaped slot (some slot had escaped when they ran).
    tainted_sites: HashSet<usize>,
    /// Slice 7: the slots whose address escaped to a call so far on this path
    /// (each call may read and write them, and every later call too, through
    /// an address an earlier one retained).
    escaped: std::collections::BTreeSet<u32>,
    /// Slice 7: the values that may hold an address derived from an escaped
    /// slot: a call's result, an incoming load's bytes or a call-defined slot
    /// byte once any slot escaped, and anything computed from one. An
    /// incoming-memory access through such a value could touch an escaped
    /// slot, which the byte model of private slots would not see: it is
    /// outside the domain.
    tainted: HashSet<Value>,
}

impl AdmitState {
    /// The state at the function's entry: the parameters.
    fn entry(frame_facts: &SourceFrame) -> Self {
        let SourceFrame {
            slot_sizes, params, ..
        } = frame_facts;
        let mut types: HashMap<Value, Carrier> = params
            .iter()
            .enumerate()
            .filter_map(|(i, param)| Some((Value(i as u32), param.abi.scalar()?)))
            .collect();
        let affine: HashMap<Value, Affine> = params
            .iter()
            .enumerate()
            .filter(|(_, param)| param.abi == ParamAbi::Scalar(Carrier::I64))
            .filter_map(|(i, _)| Some((Value(i as u32), parameter_affine(i)?)))
            .collect();
        let mut frame: HashMap<Value, FrameAddr> = HashMap::new();
        let mut slot_bytes: Vec<Vec<Option<SlotByte>>> = slot_sizes
            .iter()
            .map(|size| vec![None; *size as usize])
            .collect();
        // Slice 8: an aggregate parameter is the address of its private copy,
        // whose bytes are the eightbytes the caller passed in its argument
        // registers, each the low bytes of one register.
        let mut aggregates: HashMap<Value, Type> = HashMap::new();
        for (i, param) in params.iter().enumerate() {
            let ParamAbi::Aggregate { aggregate, slot } = &param.abi else {
                continue;
            };
            let value = Value(i as u32);
            frame.insert(
                value,
                FrameAddr {
                    slot: *slot,
                    offset: 0,
                },
            );
            types.insert(value, Carrier::I64);
            aggregates.insert(value, aggregate.ty.clone());
            for (lane, root) in aggregate.lanes.iter().zip(&param.roots) {
                for byte in 0..lane.bytes {
                    slot_bytes[*slot as usize][(lane.offset + byte) as usize] =
                        Some(SlotByte::Entry { root: *root, byte });
                }
            }
        }
        Self {
            types,
            affine,
            constants: HashMap::new(),
            frame,
            indexed: HashMap::new(),
            slot_bytes,
            aggregates,
            tainted_sites: HashSet::new(),
            escaped: std::collections::BTreeSet::new(),
            tainted: HashSet::new(),
        }
    }
}

/// Admit one entry-to-end path (from [`enumerate_paths`]) as a chain: the
/// slice 1-5 instruction rules, with the path's `Brif` decisions recorded
/// and its join parameters checked. `sites` numbers the call, load and
/// symbol sites the paths share.
fn admit_path(
    source: &Function,
    frame_facts: &SourceFrame,
    spec: &[(Block, Option<usize>)],
    sites: &mut SourceSites,
) -> Result<SourceProgram, X86BodyRefusal> {
    let mut state = AdmitState::entry(frame_facts);
    admit_blocks(source, frame_facts, spec, sites, &mut state, false, 0)
}

/// Each edge's test of a conditional terminator on `carrier`, in successor
/// order (a `Brif`'s `then`, then `else`; a `Switch`'s cases, then its
/// default). A `Switch` case constant must be the adapter's normalized form
/// for the selector's carrier and (slice 9) no two cases may denote one bit
/// pattern, so the edges' tests partition the values.
fn branch_tests(
    opcode: &L,
    carrier: Carrier,
    block_id: Block,
) -> Result<Vec<BranchTest>, X86BodyRefusal> {
    let domain = |reason: String| unsupported(X86BodyUnsupported::SourceDomain(reason));
    // Slice 11: a branch on an `I128` or on a float bit pattern is outside
    // the lane (the selector tests a register pair or an SSE register;
    // neither is modelled).
    if !carrier.is_word() {
        return Err(domain(format!(
            "the branch in block {block_id:?} tests a {carrier:?} value (an i128 or float \
             branch, outside the lane)"
        )));
    }
    match opcode {
        L::Brif { .. } => Ok(vec![BranchTest::Nonzero(true), BranchTest::Nonzero(false)]),
        L::Switch { cases, .. } => {
            // A case constant is the adapter's normalized form for the
            // selector's carrier (a bool 0 or 1, a narrow value zero-extended,
            // a 32/64-bit value sign-extended): the one w-bit pattern it
            // denotes. Any other constant makes no claim.
            let bits = carrier.bits();
            let canonical = |case: i64| match carrier {
                Carrier::B1 => matches!(case, 0 | 1),
                Carrier::I8 | Carrier::I16 => (0..1i64 << bits).contains(&case),
                Carrier::I32 => i32::try_from(case).is_ok(),
                Carrier::I64 => true,
                // Refused above: a branch on an `I128` or a float.
                Carrier::I128 | Carrier::F32 | Carrier::F64 => false,
            };
            if let Some((case, _)) = cases.iter().find(|(case, _)| !canonical(*case)) {
                return Err(domain(format!(
                    "the Switch in block {block_id:?} has case {case}, which is not a \
                     normalized {bits}-bit constant"
                )));
            }
            let pattern = |case: i64| (case as u64) & carrier.mask();
            let patterns: Vec<u64> = cases.iter().map(|(case, _)| pattern(*case)).collect();
            if patterns.iter().collect::<HashSet<_>>().len() != patterns.len() {
                return Err(domain(format!(
                    "the Switch in block {block_id:?} has two cases of one value"
                )));
            }
            // One test per distinct target, in [`switch_targets`] order (the
            // source's edges): a target one case reaches is that case's test,
            // the default alone its own; slice 14: a target several reach is
            // their disjunction ([`BranchTest::Cases`]).
            let L::Switch { default, .. } = opcode else {
                unreachable!("matched above");
            };
            Ok(switch_targets(cases, *default)
                .into_iter()
                .map(|target| {
                    let reaching: Vec<u64> = cases
                        .iter()
                        .zip(&patterns)
                        .filter(|((_, to), _)| *to == target)
                        .map(|(_, pattern)| *pattern)
                        .collect();
                    match (reaching.as_slice(), target == *default) {
                        ([only], false) => BranchTest::Case(*only),
                        ([], true) => BranchTest::Default(patterns.clone()),
                        _ => BranchTest::Cases {
                            cases: reaching,
                            default: (target == *default).then(|| patterns.clone()),
                        },
                    }
                })
                .collect())
        }
        _ => unreachable!("a conditional terminator"),
    }
}

/// Admit the instructions of `spec`'s blocks in order from `state` (the
/// state at the first block's entry), leaving the state at the last block's
/// end in `state`. On a path (`dag == false`) a conditional terminator takes
/// the edge `spec` records and the last block must end the path. A DAG block
/// (`dag`, slice 9: `spec` is that one block) records the test of each of
/// its edges in successor order and may end in a transfer
/// ([`SourceEnd::Continue`]). Slice 12: the last `tail` instructions before
/// a DAG block's terminator are the copies into a loop header's parameters
/// on the edge to it, which the cut-point relation states
/// ([`CutEdge`]); they are not admitted into the block's state.
fn admit_blocks(
    source: &Function,
    frame_facts: &SourceFrame,
    spec: &[(Block, Option<usize>)],
    sites: &mut SourceSites,
    state: &mut AdmitState,
    dag: bool,
    tail: usize,
) -> Result<SourceProgram, X86BodyRefusal> {
    let domain = |reason: String| unsupported(X86BodyUnsupported::SourceDomain(reason));
    let SourceFrame {
        sret,
        slot_sizes,
        params,
        return_tys,
        return_roots,
        returned_aggregate,
        result_slots,
        ..
    } = frame_facts;
    let AdmitState {
        types,
        affine,
        constants,
        frame,
        indexed,
        slot_bytes,
        aggregates,
        tainted_sites,
        escaped,
        tainted,
    } = state;
    let mut definitions = Vec::new();
    // Slice 17: the indexed accesses and arguments, and the bytes indexed
    // stores define, in order.
    let mut indexed_sites: Vec<IndexedSite> = Vec::new();
    let mut byte_definitions: Vec<(usize, usize)> = Vec::new();
    let mut calls: Vec<SourceCall> = Vec::new();
    let mut accesses: Vec<SourceAccess> = Vec::new();
    let mut floats: Vec<SourceFloat> = Vec::new();
    let mut events: Vec<SourceEvent> = Vec::new();
    let mut end = None;
    let mut returned: Vec<Returned> = Vec::new();
    let mut branches: Vec<SourceBranch> = Vec::new();
    let mut stops: Vec<SourceStop> = Vec::new();
    // The path's instructions in execution order, each with its LIR
    // location; `position` counts every instruction but the `Jump`s and
    // `Brif`s (the flattened chain's numbering on a one-path body).
    let steps = spec.iter().flat_map(|(block_id, _)| {
        source.blocks[block_id]
            .instructions
            .iter()
            .enumerate()
            .map(move |(index, inst)| (*block_id, index, inst))
    });
    let mut position = 0usize;
    let mut entered = source.entry_block;
    for (block_id, index, inst) in steps {
        // Slice 12: the edge copies into a loop header's parameters.
        let length = source.blocks[&block_id].instructions.len();
        if dag && index + 1 < length && index + 1 + tail >= length {
            continue;
        }
        // Entering a join (slice 6): its parameters are the values the
        // predecessor's copies defined on this path, at their declared type.
        if block_id != entered {
            entered = block_id;
            for (value, ty) in &source.blocks[&block_id].params {
                if frame.contains_key(value)
                    || indexed.contains_key(value)
                    || Carrier::of(ty).is_none_or(|ty| types.get(value) != Some(&ty))
                {
                    return Err(domain(format!(
                        "block {block_id:?} parameter {value:?} is not defined at its type on \
                         every path into the block"
                    )));
                }
            }
        }
        match &inst.opcode {
            L::Jump { .. } => continue,
            L::Brif { .. } | L::Switch { .. } => {
                // The tested value is a scalar the path defined; the path
                // takes the edge `spec` records ([`enumerate_paths`]), and a DAG
                // block (slice 9) records every edge's test.
                let value = inst.args[0];
                if frame.contains_key(&value) || indexed.contains_key(&value) {
                    return Err(domain(format!(
                        "the branch in block {block_id:?} tests a private stack address"
                    )));
                }
                let carrier = types.get(&value).copied().ok_or_else(|| {
                    domain(format!(
                        "the branch in block {block_id:?} tests undefined {value:?}"
                    ))
                })?;
                let tests = branch_tests(&inst.opcode, carrier, block_id)?;
                let taken: Vec<BranchTest> = if dag {
                    tests
                } else {
                    let edge = spec
                        .iter()
                        .find(|(block, _)| *block == block_id)
                        .and_then(|(_, edge)| *edge)
                        .expect("a path records the edge of every branch it runs");
                    vec![tests[edge].clone()]
                };
                for test in taken {
                    branches.push(SourceBranch {
                        value,
                        carrier,
                        test,
                        block: block_id,
                        index,
                    });
                }
                continue;
            }
            _ => {}
        }
        let position = {
            position += 1;
            position - 1
        };
        if end.is_some() {
            return Err(domain(format!(
                "instruction {position} follows the end of the chain"
            )));
        }
        let outside =
            |what: &str| domain(format!("instruction {position} ({:?}) {what}", inst.opcode));
        // A private stack address is never a value: using one as anything
        // but a load/store address makes its slot escape.
        let ty_of = |value: &Value| {
            if frame.contains_key(value) || indexed.contains_key(value) {
                return Err(outside(
                    "uses a private stack address as a value (the slot's address escapes)",
                ));
            }
            types
                .get(value)
                .copied()
                .ok_or_else(|| domain(format!("instruction {position} uses undefined {value:?}")))
        };
        let arity = match &inst.opcode {
            L::Iconst { .. }
            | L::Iconst128 { .. }
            | L::StackAddr { .. }
            | L::GlobalRef { .. }
            | L::ExternRef { .. } => Some((0, 1)),
            L::Copy
            | L::Bitcast { .. }
            | L::Uextend { .. }
            | L::Sextend { .. }
            | L::Trunc { .. }
            | L::Load { .. }
            | L::AtomicLoad { .. }
            | L::StructGep { .. }
            | L::Bnot
            | L::Ineg
            | L::CtPop => Some((1, 1)),
            // Slice 10: `[value, overflow]`.
            L::CheckedUadd
            | L::CheckedUsub
            | L::CheckedUmul
            | L::CheckedSadd
            | L::CheckedSsub
            | L::CheckedSmul => Some((2, 2)),
            L::Iadd
            | L::Isub
            | L::Imul
            | L::Band
            | L::Bor
            | L::Bxor
            | L::Ishl
            | L::Ushr
            | L::Sshr
            | L::Icmp { .. } => Some((2, 1)),
            // OD-185: an array element's address, `[base, index]`.
            L::ArrayGep { .. } => Some((2, 1)),
            // Slice 14: division and remainder, and the divide-by-zero guard
            // the adapter emits before a division annotated `DivNonZero`.
            L::Udiv | L::Sdiv | L::Urem | L::Srem => Some((2, 1)),
            L::GuardDivZero { .. } => Some((1, 0)),
            L::Select { .. } => Some((3, 1)),
            L::Store { .. } | L::AtomicStore { .. } => Some((2, 0)),
            L::Return => Some((
                if *sret {
                    0
                } else {
                    // One value per declared result: an aggregate or (slice
                    // 11) an `I128` is one value in two lanes.
                    source.signature.returns.len()
                },
                0,
            )),
            L::Trap => Some((0, 0)),
            // Checked below: up to six arguments, at most two results (and,
            // slice 10, an indirect call's leading function pointer).
            L::Call { .. } => None,
            L::CallIndirect if !inst.args.is_empty() => None,
            // Slice 13: the bulk-memory intrinsics, calls to the C runtime's
            // `memcpy`, `memmove` and `memset` (destination, source or fill
            // byte, length), each with no result.
            L::Memcpy | L::Memmove | L::Memset => Some((3, 0)),
            // Slice 15: a float constant is its bit pattern, and `Fneg` and
            // `Fabs` are exact operations on the sign bit (OD-73's bit-pattern
            // model; [`float_constant_bits`], [`FloatSignOp`]).
            L::Fconst { .. } => Some((0, 1)),
            L::Fneg | L::Fabs => Some((1, 1)),
            // Slice 21 (ruling OD-198): the four arithmetic operations and the
            // 64-bit integer conversions are rounding EVENTS (paired with the
            // machine row of the same operator key, their result one shared
            // free input), and a compare is exact over the bits.
            L::Fadd | L::Fsub | L::Fmul | L::Fdiv | L::Fcmp { .. } => Some((2, 1)),
            L::FcvtFromInt { .. } | L::FcvtFromUint { .. } | L::FcvtToInt { .. } => Some((1, 1)),
            // Slice 21 (ruling OD-201): `[value, address]`, the old value.
            L::AtomicRmw { .. } => Some((2, 1)),
            // Every other floating-point operation stays outside by name
            // (OD-73, OD-198): no root of the census needs one, and the
            // selector's `Fmin`/`Fmax` are not IEEE 754's minimum and maximum.
            L::Fsqrt
            | L::Ffloor
            | L::Fceil
            | L::Ftrunc
            | L::Fma
            | L::Fmuladd
            | L::Fmin
            | L::Fmax
            | L::FcvtToUint { .. }
            | L::FPExt
            | L::FPTrunc => {
                return Err(outside(
                    "is a floating-point operation outside the lane's rounding events (OD-198 \
                     admits Fadd, Fsub, Fmul, Fdiv, Fcmp and the 64-bit integer conversions)",
                ));
            }
            _ => {
                return Err(outside(
                    "is outside Iconst, Copy, same-carrier Bitcast, Iadd, Isub, Imul, Band, \
                     Bor, Bxor, bitwise not, negation, population count, Ishl, Ushr, Sshr, Uextend, \
                     Sextend, Trunc, Icmp, Select on a nonzero test, checked add/sub/mul, \
                     StackAddr, StructGep, ArrayGep, GlobalRef, ExternRef, scalar Load and \
                     Store (and their atomic forms), Memcpy, Memmove and Memset, direct and \
                     register-indirect calls, Return and Trap",
                ));
            }
        };
        if let Some(arity) = arity
            && (inst.args.len(), inst.results.len()) != arity
        {
            return Err(outside("has the wrong operand/result arity"));
        }
        let affine_of = |value: &Value| affine.get(value).copied();
        // A private stack address offset by `delta`, a value that is no
        // `I64` of this chain (slice 17 admits any other non-constant
        // offset): outside, named by what defines `delta` (the census
        // attributes it by this text).
        let non_constant_offset = |delta: &Value| {
            let defined_by = spec
                .iter()
                .flat_map(|(block, _)| source.blocks[block].instructions.iter())
                .find(|inst| inst.results.contains(delta))
                .map_or_else(
                    || "a parameter".to_owned(),
                    |inst| {
                        let opcode = format!("{:?}", inst.opcode);
                        opcode
                            .split([' ', '{', '('])
                            .next()
                            .unwrap_or_default()
                            .to_owned()
                    },
                );
            outside(&format!(
                "offsets a private stack address by a non-constant amount that is not an I64 \
                 of the chain (defined by {defined_by})"
            ))
        };
        // Private stack addresses: a slot's address, copied or offset by a
        // constant of this chain, is tracked exactly and defines no value.
        // Slice 17: offset by a non-constant amount it is INDEXED
        // ([`IndexedAddr`]), and stays indexed through copies, constant
        // offsets and field offsets.
        let private_of = |value: &Value| -> Option<Private> {
            frame
                .get(value)
                .map(|address| Private::Frame(*address))
                .or_else(|| indexed.get(value).map(|address| Private::Indexed(*address)))
        };
        let overflow = || outside("overflows a private stack offset");
        let address = match &inst.opcode {
            L::StackAddr { slot } => {
                if *slot as usize >= slot_sizes.len() {
                    return Err(outside("names a stack slot the function does not declare"));
                }
                Some(Private::Frame(FrameAddr {
                    slot: *slot,
                    offset: 0,
                }))
            }
            L::Copy | L::Bitcast { .. } if private_of(&inst.args[0]).is_some() => {
                if matches!(&inst.opcode, L::Bitcast { to_ty } if *to_ty != Type::I64)
                    || (matches!(inst.opcode, L::Bitcast { .. })
                        && aggregates.contains_key(&inst.args[0]))
                {
                    return Err(outside("reinterprets a private stack address"));
                }
                private_of(&inst.args[0])
            }
            L::StructGep {
                struct_ty,
                field_index,
            } if private_of(&inst.args[0]).is_some() => {
                let offset = field_offset(struct_ty, *field_index)
                    .and_then(|offset| i64::try_from(offset).ok())
                    .ok_or_else(|| {
                        outside("addresses a field of a type outside the layout model")
                    })?;
                Some(match private_of(&inst.args[0]).expect("checked above") {
                    Private::Frame(base) => {
                        Private::Frame(base.offset_by(offset).ok_or_else(overflow)?)
                    }
                    Private::Indexed(base) => {
                        Private::Indexed(base.offset_by(offset).ok_or_else(overflow)?)
                    }
                })
            }
            L::Iadd if inst.args.iter().any(|arg| private_of(arg).is_some()) => {
                let (base, delta) = match (private_of(&inst.args[0]), private_of(&inst.args[1])) {
                    (Some(base), None) => (base, inst.args[1]),
                    (None, Some(base)) => (base, inst.args[0]),
                    _ => return Err(outside("adds two private stack addresses")),
                };
                let constant = constants
                    .get(&delta)
                    .filter(|_| types.get(&delta) == Some(&Carrier::I64))
                    .copied();
                Some(match (base, constant) {
                    (Private::Frame(base), Some(delta)) => {
                        Private::Frame(base.offset_by(delta as i64).ok_or_else(overflow)?)
                    }
                    (Private::Indexed(base), Some(delta)) => {
                        Private::Indexed(base.offset_by(delta as i64).ok_or_else(overflow)?)
                    }
                    // Slice 17: a frame address plus an `I64` of the chain.
                    (Private::Frame(base), None) => {
                        if types.get(&delta) != Some(&Carrier::I64) {
                            return Err(non_constant_offset(&delta));
                        }
                        Private::Indexed(IndexedAddr {
                            slot: base.slot,
                            base: base.offset,
                            delta,
                            stride: 1,
                            modulus: indexed::modulus_of(source, delta, constants),
                        })
                    }
                    (Private::Indexed(_), None) => {
                        return Err(outside(
                            "adds a second non-constant amount to an indexed private stack \
                             address",
                        ));
                    }
                })
            }
            // OD-185: an element of an array at a private stack address, at
            // an `I64` index that is a constant of this chain, is the
            // address offset by `index * stride` ([`array_element_stride`]),
            // the exact integer product and sum, overflow refused (the
            // 64-bit wrapping address the selector computes is that offset
            // whenever the sum fits). Slice 17: at an `I64` index of the
            // chain that is no constant, of a frame address, it is INDEXED
            // with that stride ([`IndexedAddr::stride`]): the offset `c +
            // index * stride`. Any other index type, an element type outside
            // the layout model or of size zero, an index that is itself a
            // private address, and a second non-constant offset stay outside.
            L::ArrayGep { elem_ty } if inst.args.iter().any(|arg| private_of(arg).is_some()) => {
                let (base, index) = (inst.args[0], inst.args[1]);
                let Some(base) = private_of(&base) else {
                    return Err(outside(
                        "indexes an array by a private stack address (the slot's address \
                         escapes)",
                    ));
                };
                if private_of(&index).is_some() {
                    return Err(outside(
                        "indexes a private stack address by a private stack address",
                    ));
                }
                let stride = array_element_stride(elem_ty).ok_or_else(|| {
                    outside("indexes elements of a type outside the layout model")
                })?;
                if types.get(&index) != Some(&Carrier::I64) {
                    return Err(outside(
                        "indexes an array by a value other than an I64 (the selector scales \
                         the index register as it is)",
                    ));
                }
                let element = |k: u64| {
                    i64::try_from(stride)
                        .ok()
                        .and_then(|stride| (k as i64).checked_mul(stride))
                };
                Some(match (base, constants.get(&index).copied()) {
                    (Private::Frame(base), Some(k)) => Private::Frame(
                        element(k)
                            .and_then(|delta| base.offset_by(delta))
                            .ok_or_else(overflow)?,
                    ),
                    (Private::Indexed(base), Some(k)) => Private::Indexed(
                        element(k)
                            .and_then(|delta| base.offset_by(delta))
                            .ok_or_else(overflow)?,
                    ),
                    (Private::Frame(base), None) => {
                        if i64::try_from(stride).is_err() {
                            return Err(overflow());
                        }
                        Private::Indexed(IndexedAddr {
                            slot: base.slot,
                            base: base.offset,
                            delta: index,
                            stride,
                            modulus: indexed::stride_modulus(
                                stride,
                                indexed::modulus_of(source, index, constants),
                            ),
                        })
                    }
                    (Private::Indexed(_), None) => {
                        return Err(outside(
                            "adds a second non-constant amount to an indexed private stack \
                             address",
                        ));
                    }
                })
            }
            _ => None,
        };
        if let Some(address) = address {
            let result = inst.results[0];
            if types.insert(result, Carrier::I64).is_some() {
                return Err(domain(format!(
                    "instruction {position} redefines an SSA value"
                )));
            }
            let address = match address {
                Private::Frame(address) => address,
                Private::Indexed(address) => {
                    // An indexed address is a pointer, never an aggregate's
                    // bytes (an aggregate is passed or returned whole).
                    if matches!(
                        source.value_types.get(&result),
                        Some(Type::Struct(_) | Type::Array(..) | Type::Enum { .. })
                    ) {
                        return Err(outside(
                            "types an indexed private stack address as an aggregate",
                        ));
                    }
                    indexed.insert(result, address);
                    continue;
                }
            };
            frame.insert(result, address);
            // Slice 8: a copy of an aggregate value is that aggregate (a
            // `Copy` keeps its operand's type; a hint that says otherwise is
            // refused below), and a copy of a slot address that the LIR types
            // as a by-value aggregate (the adapter's call-argument temporary,
            // hinted with the callee's parameter type) is that aggregate: its
            // bytes at the address when it is used by value. OD-186: so is a
            // slot's own address (`StackAddr`) the LIR types as a by-value
            // aggregate, the adapter's by-value copy of an aggregate `Load`
            // (a fresh slot the bytes are moved into, `translate_load`): the
            // selector defines both at their hinted type
            // (`select_stack_addr`, `select_move_reg`), so its System V call
            // classifier passes their bytes. Any other slot address is a
            // pointer: an element or field address (`StructGep`,
            // `ArrayGep`) is defined at `I64` by the selector whatever its
            // hint (`select_struct_gep`, `select_array_gep`), so a hint of an
            // aggregate there stays inconsistent (refused below).
            let copied = match &inst.opcode {
                L::Copy => Some(aggregates.get(&inst.args[0]).cloned()),
                L::StackAddr { .. } => Some(None),
                _ => None,
            };
            if let Some(copied) = copied {
                match (copied, source.value_types.get(&result)) {
                    (Some(ty), _) => {
                        aggregates.insert(result, ty);
                    }
                    (
                        None,
                        Some(hint @ (Type::Struct(_) | Type::Array(..) | Type::Enum { .. })),
                    ) => {
                        aggregates.insert(result, hint.clone());
                    }
                    (None, _) => {}
                }
            }
            continue;
        }
        // Loads and stores: through a private stack address they read and
        // write the slot's bytes exactly; through any other address they
        // are an incoming-memory access of the world trace.
        match &inst.opcode {
            L::Load { ty, .. } | L::AtomicLoad { ty, .. } => {
                let carrier = Carrier::of(ty).ok_or_else(|| outside("loads a non-scalar type"))?;
                let atomic = atomic_access(
                    &inst.opcode,
                    carrier,
                    frame.contains_key(&inst.args[0]) || indexed.contains_key(&inst.args[0]),
                )
                .map_err(outside)?;
                let (op, value_affine) = match frame.get(&inst.args[0]) {
                    // Slice 17: a load through an indexed address reads the
                    // select over its candidates of what a load at each
                    // candidate offset reads, and claims its offset is one.
                    None if indexed.contains_key(&inst.args[0]) => {
                        let address = indexed[&inst.args[0]];
                        if carrier == Carrier::I128 {
                            return Err(outside(
                                "loads an i128 through an indexed private stack address",
                            ));
                        }
                        let size = slot_sizes[address.slot as usize];
                        let width = carrier.bytes();
                        let candidates =
                            indexed::candidates(size, width, address.modulus, address.residue());
                        if candidates.is_empty() {
                            return Err(outside(
                                "loads through an indexed private stack address no offset of \
                                 which fits its slot",
                            ));
                        }
                        if candidates.len() > indexed::MAX_CANDIDATES {
                            return Err(outside(&format!(
                                "loads through an indexed private stack address with {} \
                                 candidate offsets (the lane admits {})",
                                candidates.len(),
                                indexed::MAX_CANDIDATES
                            )));
                        }
                        let mut arms = Vec::with_capacity(candidates.len());
                        let mut derived = false;
                        for k in candidates {
                            let at = FrameAddr {
                                slot: address.slot,
                                offset: k,
                            };
                            let read: SlotBytes = stack_bytes(&at, carrier, slot_sizes)
                                .expect("a candidate fits its slot")
                                .map(|offset| {
                                    (
                                        FrameAddr {
                                            slot: address.slot,
                                            offset: offset as i64,
                                        },
                                        slot_bytes[address.slot as usize][offset],
                                    )
                                })
                                .collect();
                            if read.iter().any(|(_, byte)| *byte == Some(SlotByte::Dead)) {
                                return Err(outside(
                                    "reads a private stack byte its cut point leaves out as \
                                     dead",
                                ));
                            }
                            if read
                                .iter()
                                .any(|(_, byte)| byte.and_then(SlotByte::address).is_some())
                            {
                                return Err(outside(
                                    "reads through an indexed address a candidate byte holding a \
                                     private stack address stored as data",
                                ));
                            }
                            derived |= read.iter().any(|(_, byte)| {
                                byte.is_some_and(|byte| byte.tainted_in(tainted, tainted_sites))
                            });
                            let written: Option<Vec<SourceByte>> = read
                                .iter()
                                .map(|(_, byte)| byte.and_then(SlotByte::stored))
                                .collect();
                            let arm = match written.as_deref().and_then(whole_store) {
                                Some((value, stored)) if stored == carrier => {
                                    CandidateRead::Whole(value)
                                }
                                _ if carrier == Carrier::B1 => {
                                    if !matches!(
                                        read.as_slice(),
                                        [(_, Some(byte))] if byte.read_as_bool()
                                    ) {
                                        return Err(outside(
                                            "loads a bool through an indexed address from a \
                                             candidate byte no bool store or call wrote",
                                        ));
                                    }
                                    CandidateRead::Bytes(read)
                                }
                                _ => {
                                    for (at, byte) in &read {
                                        if byte.is_none() {
                                            sites.frame_byte(*at);
                                        }
                                    }
                                    CandidateRead::Bytes(read)
                                }
                            };
                            arms.push((k, arm));
                        }
                        if derived {
                            tainted.insert(inst.results[0]);
                        }
                        indexed_sites.push(IndexedSite {
                            address,
                            width,
                            size,
                            stops: stops.len(),
                            block: block_id,
                            index,
                        });
                        (SourceOp::IndexedLoad { address, arms }, None)
                    }
                    Some(address) => {
                        let bytes = stack_bytes(address, carrier, slot_sizes)
                            .ok_or_else(|| outside("reads outside its private stack slot"))?;
                        let read: Vec<(FrameAddr, Option<SlotByte>)> = bytes
                            .map(|offset| {
                                (
                                    FrameAddr {
                                        slot: address.slot,
                                        offset: offset as i64,
                                    },
                                    slot_bytes[address.slot as usize][offset],
                                )
                            })
                            .collect();
                        // Slice 17: a byte its cut point leaves out as dead
                        // is unreadable.
                        if read.iter().any(|(_, byte)| *byte == Some(SlotByte::Dead)) {
                            return Err(outside(
                                "reads a private stack byte its cut point leaves out as dead",
                            ));
                        }
                        // Slice 13: a private stack address an 8-byte store
                        // wrote as data, read back whole as an `I64`, is that
                        // address again (no SMT term: the walks track it as an
                        // address, and an access through it is private). Any
                        // other read of its bytes (a part, another width, a
                        // mix with other bytes) is outside the domain.
                        if read
                            .iter()
                            .any(|(_, byte)| byte.and_then(SlotByte::address).is_some())
                        {
                            let part: Vec<Option<SlotByte>> =
                                read.iter().map(|(_, byte)| *byte).collect();
                            let Some(whole) =
                                whole_address(&part).filter(|_| carrier == Carrier::I64)
                            else {
                                return Err(outside(
                                    "reads part of a private stack address stored as data",
                                ));
                            };
                            let result = inst.results[0];
                            if types.insert(result, Carrier::I64).is_some() {
                                return Err(domain(format!(
                                    "instruction {position} redefines an SSA value"
                                )));
                            }
                            frame.insert(result, whole);
                            continue;
                        }
                        // Slice 7: a byte a call defined may hold an address
                        // derived from an escaped slot, and so may a stored
                        // value that does.
                        // (Slice 8: so may a byte of an aggregate call result
                        // returned after a slot escaped; an aggregate
                        // parameter's bytes predate every escape.)
                        // (Slice 9: a join of bytes, some of which may;
                        // slice 12: a loop header's byte, likewise.)
                        if read.iter().any(|(_, byte)| {
                            byte.is_some_and(|byte| byte.tainted_in(tainted, tainted_sites))
                        }) {
                            tainted.insert(inst.results[0]);
                        }
                        let written: Option<Vec<SourceByte>> = read
                            .iter()
                            .map(|(_, byte)| byte.and_then(SlotByte::stored))
                            .collect();
                        match written.as_deref().and_then(whole_store) {
                            // One earlier store, read back whole at its type.
                            Some((value, stored)) if stored == carrier => {
                                (SourceOp::Copy(value), affine_of(&value))
                            }
                            // A bool is read from a byte a bool store wrote
                            // (above), or (slice 7) from one byte a call
                            // defined, or (slice 8) one byte of an aggregate
                            // parameter or call result, which is trust-ir's
                            // `Load Bool`: the bool `byte != 0`. From any
                            // other byte (an initial byte, part of another
                            // store) it is outside the domain.
                            _ if carrier == Carrier::B1 => {
                                if !matches!(
                                    read.as_slice(),
                                    [(_, Some(byte))] if byte.read_as_bool()
                                ) {
                                    return Err(outside(
                                        "loads a bool from a private byte no bool store or call \
                                         wrote",
                                    ));
                                }
                                (SourceOp::StackBytes(read), None)
                            }
                            // A byte no store on this path wrote is the
                            // slot's initial byte (slice 6): the one unknown
                            // the machine reads there too, `f{k}`.
                            _ => {
                                for (address, byte) in &read {
                                    if byte.is_none() {
                                        sites.frame_byte(*address);
                                    }
                                }
                                (SourceOp::StackBytes(read), None)
                            }
                        }
                    }
                    None => {
                        if ty_of(&inst.args[0])? != Carrier::I64 {
                            return Err(outside("loads through a non-pointer value"));
                        }
                        // Slice 7: once a slot escaped, an address computed
                        // from what a call returned or left in memory may
                        // point into it. Slice 15: such a load is an access of
                        // the world AND of the escaped slots' bytes, whose
                        // contents it observes like a call's (its value is
                        // then one function of equal memory on both sides).
                        let derived = tainted.contains(&inst.args[0]);
                        // Once a slot escaped, a call may have stored its
                        // address in incoming memory: the loaded bytes may
                        // be one.
                        if !escaped.is_empty() {
                            tainted.insert(inst.results[0]);
                        }
                        // A `bool` load reads a whole byte, which may hold
                        // any value, and defines `byte != 0`
                        // ([`Carrier::loaded_value`]): no validity premise.
                        // Slice 11: an `I128` load is two 8-byte loads, the
                        // low half at the address, then the high half 8
                        // bytes above it ([`SourceAccess`]).
                        let halves: &[(u32, u64)] = if carrier == Carrier::I128 {
                            &[(0, 0), (1, 8)]
                        } else {
                            &[(0, 0)]
                        };
                        let part_carrier = if carrier == Carrier::I128 {
                            Carrier::I64
                        } else {
                            carrier
                        };
                        let mut loads = Vec::with_capacity(halves.len());
                        for (part, offset) in halves {
                            let access = accesses.len();
                            let load = sites.load(block_id, index, *part, part_carrier);
                            let slot_reads = derived
                                .then(|| escaped_slot_reads(escaped, slot_bytes, sites))
                                .transpose()
                                .map_err(outside)?;
                            accesses.push(SourceAccess {
                                kind: AccessKind::Load(load),
                                stored_address: None,
                                atomic,
                                // Slice 21 (OD-201): an atomic `I128` load is
                                // the selector's `cmpxchg16b` pseudo, which
                                // reads both halves.
                                pseudo: (atomic && carrier == Carrier::I128)
                                    .then_some(AtomicPseudo::Cmpxchg16b(*part)),
                                slot_reads,
                                store_site: None,
                                address: inst.args[0],
                                offset: *offset,
                                part: None,
                                carrier: part_carrier,
                                address_affine: affine_of(&inst.args[0]).map(|a| {
                                    a.combine(Affine::constant(*offset, u64::MAX), false, u64::MAX)
                                }),
                                value_affine: None,
                                block: block_id,
                                index,
                            });
                            events.push(SourceEvent::Access(access));
                            loads.push(load);
                        }
                        match loads.as_slice() {
                            [load] => (SourceOp::MemoryLoad(*load), None),
                            [low, high] => (SourceOp::WideLoad(*low, *high), None),
                            _ => unreachable!("one or two halves"),
                        }
                    }
                };
                let result = inst.results[0];
                if types.insert(result, carrier).is_some() {
                    return Err(domain(format!(
                        "instruction {position} redefines an SSA value"
                    )));
                }
                if let Some(value_affine) = value_affine {
                    affine.insert(result, value_affine);
                }
                definitions.push(SourceDefinition {
                    result,
                    ty: carrier,
                    op,
                    block: block_id,
                    index,
                });
                continue;
            }
            L::Store { ty, .. } | L::AtomicStore { ty, .. } => {
                let carrier = Carrier::of(ty).ok_or_else(|| outside("stores a non-scalar type"))?;
                let (value, address) = (inst.args[0], inst.args[1]);
                let atomic = atomic_access(
                    &inst.opcode,
                    carrier,
                    frame.contains_key(&address) || indexed.contains_key(&address),
                )
                .map_err(outside)?;
                // Slice 17: an indexed address is never data.
                if indexed.contains_key(&value) {
                    return Err(outside("stores an indexed private stack address as data"));
                }
                // Slice 17: a store through an indexed address updates every
                // byte a candidate covers ([`indexed::update`]), each a new
                // [`SlotByte::Indexed`] defined where the store runs, and
                // claims its offset is a candidate.
                if let Some(target) = indexed.get(&address).copied() {
                    if frame.contains_key(&value) {
                        return Err(outside(
                            "stores a private stack address through an indexed address",
                        ));
                    }
                    if carrier == Carrier::I128 {
                        return Err(outside(
                            "stores an i128 through an indexed private stack address",
                        ));
                    }
                    if ty_of(&value)? != carrier {
                        return Err(outside("stores a value of another type"));
                    }
                    let slot = target.slot as usize;
                    let size = slot_sizes[slot];
                    let width = carrier.bytes();
                    let candidates =
                        indexed::candidates(size, width, target.modulus, target.residue());
                    if candidates.is_empty() {
                        return Err(outside(
                            "stores through an indexed private stack address no offset of \
                             which fits its slot",
                        ));
                    }
                    if candidates.len() > indexed::MAX_CANDIDATES {
                        return Err(outside(&format!(
                            "stores through an indexed private stack address with {} candidate \
                             offsets (the lane admits {})",
                            candidates.len(),
                            indexed::MAX_CANDIDATES
                        )));
                    }
                    let first = candidates[0];
                    let end = candidates[candidates.len() - 1] + i64::from(width);
                    let mut written = Vec::new();
                    for position in first..end {
                        let arms = indexed::covering(&candidates, width, position);
                        if arms.is_empty() {
                            continue;
                        }
                        let old = slot_bytes[slot][position as usize];
                        if old == Some(SlotByte::Dead) {
                            return Err(outside(
                                "updates through an indexed address a private stack byte its \
                                 cut point leaves out as dead",
                            ));
                        }
                        if old.and_then(SlotByte::address).is_some() {
                            return Err(outside(
                                "updates through an indexed address a candidate byte holding a \
                                 private stack address stored as data",
                            ));
                        }
                        let at = FrameAddr {
                            slot: target.slot,
                            offset: position,
                        };
                        if old.is_none() {
                            sites.frame_byte(at);
                        }
                        // As at a join ([`merge_admitted`]): a `bool` read of
                        // it is admitted when every byte it may be is a
                        // `bool` store's or one a `bool` read may read.
                        // Slice 20 (OD-194): the stored value's byte is
                        // readable as a direct read takes it ([`bool_readable`]).
                        let bool_read = bool_readable(old);
                        let derived = tainted.contains(&value)
                            || old.is_some_and(|byte| byte.tainted_in(tainted, tainted_sites));
                        written.push((at, arms, old, bool_read, derived));
                    }
                    for (at, arms, old, bool_read, derived) in written {
                        let id = sites.indexed_bytes.len();
                        sites.indexed_bytes.push(IndexedByte {
                            address: at,
                            store: target,
                            value,
                            carrier,
                            arms,
                            old,
                        });
                        byte_definitions.push((definitions.len(), id));
                        slot_bytes[slot][at.offset as usize] = Some(SlotByte::Indexed {
                            id,
                            bool_read,
                            tainted: derived,
                        });
                    }
                    indexed_sites.push(IndexedSite {
                        address: target,
                        width,
                        size,
                        stops: stops.len(),
                        block: block_id,
                        index,
                    });
                    continue;
                }
                // Slice 13: a private stack address stored as data, an 8-byte
                // store of the pointer (an aggregate-typed address is the
                // aggregate's bytes, never a pointer to store). Its value is
                // the address's term ([`frame_address_term`]), and from the
                // store on its slot is shared with whatever can read the
                // memory it went to: incoming memory (every later call, and
                // every incoming access through an address that may derive
                // from it, which observes it since slice 15) or a slot that
                // escaped. Into a slot that has not escaped it stays private
                // until that slot escapes, which takes it along
                // ([`escape_source`]).
                let stored_address = frame.get(&value).copied();
                if stored_address.is_some()
                    && (carrier != Carrier::I64 || aggregates.contains_key(&value))
                {
                    return Err(outside(
                        "stores a private stack address at another width or as an aggregate",
                    ));
                }
                if stored_address.is_none() && ty_of(&value)? != carrier {
                    return Err(outside("stores a value of another type"));
                }
                match frame.get(&address).copied() {
                    Some(address) => {
                        let bytes = stack_bytes(&address, carrier, slot_sizes)
                            .ok_or_else(|| outside("writes outside its private stack slot"))?;
                        for (byte, offset) in bytes.enumerate() {
                            slot_bytes[address.slot as usize][offset] =
                                Some(match stored_address {
                                    Some(stored) => SlotByte::Address {
                                        address: stored,
                                        byte: byte as u32,
                                    },
                                    None => SlotByte::Stored(SourceByte {
                                        value,
                                        carrier,
                                        byte: byte as u32,
                                    }),
                                });
                        }
                        if let Some(stored) = stored_address
                            && escaped.contains(&address.slot)
                        {
                            escape_source(escaped, slot_bytes, [stored.slot]);
                        }
                    }
                    None => {
                        if ty_of(&address)? != Carrier::I64 {
                            return Err(outside("stores through a non-pointer value"));
                        }
                        // Slice 15: a store through an address that may
                        // derive from an escaped slot observes the escaped
                        // slots' contents and may write any of their bytes:
                        // after it each is the store site's free input
                        // ([`access_byte_name`]) on both sides. Only a slot
                        // that had escaped before the store is reachable
                        // through such an address.
                        let derived = tainted.contains(&address);
                        // Slice 11: an `I128` store is two 8-byte stores, the
                        // low half at the address, then the high half.
                        let halves: &[(Option<u32>, u64)] = if carrier == Carrier::I128 {
                            &[(Some(0), 0), (Some(1), 8)]
                        } else {
                            &[(None, 0)]
                        };
                        for (part, offset) in halves {
                            let access = accesses.len();
                            let slot_reads = derived
                                .then(|| escaped_slot_reads(escaped, slot_bytes, sites))
                                .transpose()
                                .map_err(outside)?;
                            let store_site = derived
                                .then(|| sites.access_store(block_id, index, part.unwrap_or(0)));
                            if let Some(site) = store_site {
                                for slot in escaped.iter() {
                                    slot_bytes[*slot as usize]
                                        .fill(Some(SlotByte::AccessStore(site)));
                                }
                            }
                            accesses.push(SourceAccess {
                                kind: AccessKind::Store(value),
                                stored_address,
                                atomic,
                                pseudo: None,
                                slot_reads,
                                store_site,
                                address,
                                offset: *offset,
                                part: *part,
                                carrier: if part.is_some() {
                                    Carrier::I64
                                } else {
                                    carrier
                                },
                                address_affine: affine_of(&address).map(|a| {
                                    a.combine(Affine::constant(*offset, u64::MAX), false, u64::MAX)
                                }),
                                value_affine: (carrier == Carrier::I64)
                                    .then(|| affine_of(&value))
                                    .flatten(),
                                block: block_id,
                                index,
                            });
                            events.push(SourceEvent::Access(access));
                        }
                        // Slice 13: the stored address is in incoming memory,
                        // which every later call can read.
                        if let Some(stored) = stored_address {
                            escape_source(escaped, slot_bytes, [stored.slot]);
                        }
                    }
                }
                continue;
            }
            // Slice 21 (ruling OD-201): `AtomicRmw { op: Xchg }` of an `I32` or
            // `I64` through a non-private address, of any ordering, is trust-ir's
            // single-threaded `AtomicRMW` ("read old, compute new = old <op>
            // operand, write back, return old"; "with one thread every memory
            // ordering collapses to sequential consistency, so an atomic access
            // is its plain-memory counterpart", `ub-numerics-policy.md`, pin
            // `64a2a839`): an incoming load of the old bytes, then an incoming
            // store of the operand at the same address, both paired with the
            // selector's one `AtomicRmwCasLoop [dst, src, [base], 5]` row (its
            // `LOCK CMPXCHG` is a full barrier, so every ordering is met). Every
            // other read-modify-write stays outside by name.
            L::AtomicRmw { op, ty, .. } => {
                if *op != trust_cg_lower::instructions::AtomicRmwOp::Xchg {
                    return Err(outside(
                        "is an atomic read-modify-write other than an exchange",
                    ));
                }
                let carrier = Carrier::of(ty)
                    .filter(|carrier| matches!(carrier, Carrier::I32 | Carrier::I64))
                    .ok_or_else(|| {
                        outside("is an atomic exchange of a type other than I32 or I64")
                    })?;
                let (value, address) = (inst.args[0], inst.args[1]);
                if frame.contains_key(&address) || indexed.contains_key(&address) {
                    return Err(outside("is an atomic access of a private stack slot"));
                }
                if ty_of(&address)? != Carrier::I64 {
                    return Err(outside("exchanges through a non-pointer value"));
                }
                if ty_of(&value)? != carrier {
                    return Err(outside("exchanges a value of another type"));
                }
                if tainted.contains(&address) {
                    return Err(outside(
                        "exchanges through an address that may derive from an escaped slot",
                    ));
                }
                let result = inst.results[0];
                if types.insert(result, carrier).is_some() {
                    return Err(domain(format!(
                        "instruction {position} redefines an SSA value"
                    )));
                }
                // Once a slot escaped, a call may have stored its address in
                // incoming memory: the old bytes may be one.
                if !escaped.is_empty() {
                    tainted.insert(result);
                }
                let load = sites.load(block_id, index, 0, carrier);
                let address_affine = affine_of(&address);
                for (kind, load_half) in [
                    (AccessKind::Load(load), true),
                    (AccessKind::Store(value), false),
                ] {
                    events.push(SourceEvent::Access(accesses.len()));
                    accesses.push(SourceAccess {
                        kind,
                        stored_address: None,
                        atomic: true,
                        pseudo: Some(AtomicPseudo::Exchange { load: load_half }),
                        slot_reads: None,
                        store_site: None,
                        address,
                        offset: 0,
                        part: None,
                        carrier,
                        address_affine,
                        value_affine: (!load_half && carrier == Carrier::I64)
                            .then(|| affine_of(&value))
                            .flatten(),
                        block: block_id,
                        index,
                    });
                }
                definitions.push(SourceDefinition {
                    result,
                    ty: carrier,
                    op: SourceOp::MemoryLoad(load),
                    block: block_id,
                    index,
                });
                continue;
            }
            _ => {}
        }
        // Slice 14: `GuardDivZero` traps when its divisor is zero, a defined
        // trap and an observable end of the run ([`StopKind::Guard`]). One
        // bound to a discharged obligation is outside: the certified-
        // elimination kernel may delete its machine carrier, and no
        // obligation the adapter binds is replayed here (outside test
        // builds, the adapter binds none).
        if let L::GuardDivZero { obligation } = &inst.opcode {
            if obligation.is_some() {
                return Err(outside(
                    "is bound to a discharged obligation (the certified-elimination kernel may \
                     delete its machine carrier)",
                ));
            }
            let divisor = inst.args[0];
            let ty = ty_of(&divisor)?;
            // Slice 22 (ruling OD-202): an `I128` divisor's guard is the same
            // guard at 128 bits. The selector's carrier is `or d, lo, hi;
            // TrapDivZeroExact d` (`guard_div_zero_operand`), both rows
            // walked exactly; the solver judges that `lo | hi` is zero exactly
            // when the 128-bit divisor is.
            if !(ty.is_word() || ty == Carrier::I128) || ty == Carrier::B1 {
                return Err(outside("guards a B1 or float divisor"));
            }
            // A guard of a nonzero constant never fires: no stop. A 128-bit
            // constant with a high half is not in `constants` (it holds 64
            // bits): its own definition says whether it is nonzero.
            let never = constants
                .get(&divisor)
                .is_some_and(|k| crate::smt::mask(*k, ty.bits()) != 0)
                || (ty == Carrier::I128
                    && definitions.iter().any(|definition| {
                        definition.result == divisor
                            && matches!(definition.op, SourceOp::Wide { lo, hi } if lo | hi != 0)
                    }));
            if !never {
                stops.push(SourceStop {
                    events: events.len(),
                    kind: StopKind::Guard { divisor },
                    block: block_id,
                    index,
                });
            }
            continue;
        }
        // Checked arithmetic (slice 10): two results, the wrapping value and
        // the `bool` overflow ([`CheckedOp`]), of two `I64` operands (the
        // adapter maps exactly the 64-bit trust-ir `Overflow` to it and
        // lowers a narrower one to ordinary arithmetic and compares).
        if let Some(checked) = CheckedOp::of(&inst.opcode) {
            let (lhs, rhs) = (inst.args[0], inst.args[1]);
            let ty = ty_of(&lhs)?;
            if ty_of(&rhs)? != ty {
                return Err(outside("combines operands of different types"));
            }
            if ty != Carrier::I64 {
                return Err(outside("is checked arithmetic on a carrier other than I64"));
            }
            let value = SourceOp::Binary(checked.binary(), lhs, rhs);
            let value_affine = match checked.binary() {
                BinaryOp::Add | BinaryOp::Sub if ty == Carrier::I64 => affine_of(&lhs)
                    .zip(affine_of(&rhs))
                    .map(|(a, b)| a.combine(b, checked.binary() == BinaryOp::Sub, u64::MAX)),
                _ => None,
            };
            let folded = fold_constant(&value, ty, constants);
            let derived = inst.args.iter().any(|arg| tainted.contains(arg));
            for (result, ty, op) in [
                (inst.results[0], ty, value),
                (
                    inst.results[1],
                    Carrier::B1,
                    SourceOp::Overflow {
                        op: checked,
                        lhs,
                        rhs,
                    },
                ),
            ] {
                if types.insert(result, ty).is_some() {
                    return Err(domain(format!(
                        "instruction {position} redefines an SSA value"
                    )));
                }
                if derived {
                    tainted.insert(result);
                }
                definitions.push(SourceDefinition {
                    result,
                    ty,
                    op,
                    block: block_id,
                    index,
                });
            }
            if let Some(value_affine) = value_affine {
                affine.insert(inst.results[0], value_affine);
            }
            if let Some(folded) = folded {
                constants.insert(inst.results[0], folded);
                if ty == Carrier::I64 {
                    affine
                        .entry(inst.results[0])
                        .or_insert(Affine::constant(folded, u64::MAX));
                }
            }
            continue;
        }
        // Slice 22 (ruling OD-202): an `I128` division or remainder is the
        // selector's call of its runtime routine ([`i128_division_routine`]),
        // stated with the call arm below.
        let i128_division = matches!(inst.opcode, L::Udiv | L::Sdiv | L::Urem | L::Srem)
            && ty_of(&inst.args[0])? == Carrier::I128;
        let (op, ty, value_affine) = match &inst.opcode {
            // Slice 11: a 128-bit constant. LIR `Iconst { ty: I128 }`'s high
            // half is its `i64` immediate's sign extension, and `Iconst128`
            // states both halves (`trust_cg_lower::instructions::Opcode`). It
            // is a shift amount or a slot offset only when it fits 64 bits.
            L::Iconst {
                ty: Type::I128,
                imm,
            }
            | L::Iconst128 { lo: imm, .. } => {
                let (lo, hi) = match &inst.opcode {
                    L::Iconst128 { lo, hi } => (*lo as u64, *hi as u64),
                    _ => (*imm as u64, if *imm < 0 { u64::MAX } else { 0 }),
                };
                if hi == 0 {
                    constants.insert(inst.results[0], lo);
                }
                (SourceOp::Wide { lo, hi }, Carrier::I128, None)
            }
            L::Iconst { ty, imm } => {
                let ty = Carrier::of(ty).ok_or_else(|| outside("has a non-scalar type"))?;
                if ty.is_float() {
                    return Err(outside("is an integer constant of a float type"));
                }
                let bits = (*imm as u64) & ty.mask();
                if ty == Carrier::B1 && !matches!(*imm, 0 | 1) {
                    return Err(outside("is a B1 constant other than 0 or 1"));
                }
                constants.insert(inst.results[0], bits);
                let value_affine = (ty == Carrier::I64).then(|| Affine::constant(bits, u64::MAX));
                (SourceOp::Const(bits), ty, value_affine)
            }
            // Slice 15: a float constant is the bit pattern trust-ir gives it
            // ([`float_constant_bits`]). No constant is recorded for it: a
            // float is never an address offset or a shift amount.
            L::Fconst { ty, imm } => {
                let ty = Carrier::of(ty)
                    .filter(|carrier| carrier.is_float())
                    .ok_or_else(|| {
                        outside("is a float constant of a type other than F32 or F64")
                    })?;
                let bits = float_constant_bits(ty, *imm).ok_or_else(|| {
                    outside(
                        "is an f32 NaN constant (trust-ir narrows the f64 NaN with `as`, whose \
                         NaN payload is unspecified)",
                    )
                })?;
                (SourceOp::Const(bits), ty, None)
            }
            // Slice 15: `Fneg`/`Fabs` of a float bit pattern ([`FloatSignOp`]).
            L::Fneg | L::Fabs => {
                let ty = ty_of(&inst.args[0])?;
                if !ty.is_float() {
                    return Err(outside(
                        "negates or takes the magnitude of a non-float value",
                    ));
                }
                let op = if matches!(inst.opcode, L::Fneg) {
                    FloatSignOp::Neg
                } else {
                    FloatSignOp::Abs
                };
                (SourceOp::FloatSign(op, inst.args[0]), ty, None)
            }
            L::Copy => {
                let ty = ty_of(&inst.args[0])?;
                (SourceOp::Copy(inst.args[0]), ty, affine_of(&inst.args[0]))
            }
            L::Bitcast { to_ty } => {
                // A same-carrier integer bitcast is a signedness
                // reinterpretation (`i8 as u8`): the identity on the bits.
                // Slice 11: so is a bitcast between a float and the integer
                // of its width (`f32::to_bits`, `f64::from_bits`): the bit
                // pattern unchanged, the register file changed. Any other
                // bitcast changes the bits and is refused.
                let ty = ty_of(&inst.args[0])?;
                let to = Carrier::of(to_ty);
                let same_bits = matches!(
                    (ty, to),
                    (Carrier::F32, Some(Carrier::I32))
                        | (Carrier::I32, Some(Carrier::F32))
                        | (Carrier::F64, Some(Carrier::I64))
                        | (Carrier::I64, Some(Carrier::F64))
                );
                if to != Some(ty) && !same_bits {
                    return Err(outside("reinterprets its operand as another carrier"));
                }
                let to = to.expect("checked above");
                let value_affine = (to == Carrier::I64 && ty == Carrier::I64)
                    .then(|| affine_of(&inst.args[0]))
                    .flatten();
                (SourceOp::Copy(inst.args[0]), to, value_affine)
            }
            L::Iadd | L::Isub | L::Imul | L::Band | L::Bor | L::Bxor => {
                let (lhs, rhs) = (inst.args[0], inst.args[1]);
                let ty = ty_of(&lhs)?;
                if ty_of(&rhs)? != ty {
                    return Err(outside("combines operands of different types"));
                }
                if ty.is_float() {
                    return Err(outside("is integer arithmetic of a float bit pattern"));
                }
                let op = match &inst.opcode {
                    L::Iadd => BinaryOp::Add,
                    L::Isub => BinaryOp::Sub,
                    L::Imul => BinaryOp::Mul,
                    L::Band => BinaryOp::And,
                    L::Bor => BinaryOp::Or,
                    _ => BinaryOp::Xor,
                };
                if ty == Carrier::B1 && matches!(op, BinaryOp::Add | BinaryOp::Sub | BinaryOp::Mul)
                {
                    return Err(outside("is B1 arithmetic"));
                }
                let value_affine = match op {
                    BinaryOp::Add | BinaryOp::Sub if ty == Carrier::I64 => affine_of(&lhs)
                        .zip(affine_of(&rhs))
                        .map(|(a, b)| a.combine(b, op == BinaryOp::Sub, u64::MAX)),
                    _ => None,
                };
                (SourceOp::Binary(op, lhs, rhs), ty, value_affine)
            }
            // Slice 10: the bitwise complement and the population count of
            // an integer. trust-ir has no `not` of a `bool` (its validator
            // refuses `UnOpNotOnScalarBool`), so a `B1` operand stays
            // outside.
            L::Bnot => {
                let ty = ty_of(&inst.args[0])?;
                if ty == Carrier::B1 || ty.is_float() {
                    return Err(outside("complements a B1 value or a float bit pattern"));
                }
                (SourceOp::Not(inst.args[0]), ty, None)
            }
            L::Ineg => {
                let ty = ty_of(&inst.args[0])?;
                if ty == Carrier::B1 || ty.is_float() {
                    return Err(outside("negates a B1 value or a float bit pattern"));
                }
                (SourceOp::Neg(inst.args[0]), ty, None)
            }
            L::CtPop => {
                let ty = ty_of(&inst.args[0])?;
                if ty == Carrier::B1 || ty.is_float() {
                    return Err(outside(
                        "counts the bits of a B1 value or a float bit pattern",
                    ));
                }
                (SourceOp::Popcount(inst.args[0]), ty, None)
            }
            L::Ishl | L::Ushr | L::Sshr => {
                let ty = ty_of(&inst.args[0])?;
                if ty == Carrier::B1 || ty.is_float() {
                    return Err(outside("shifts a B1 value or a float bit pattern"));
                }
                let op = match inst.opcode {
                    L::Ishl => ShiftOp::Shl,
                    L::Ushr => ShiftOp::Lshr,
                    _ => ShiftOp::Ashr,
                };
                // An in-range constant amount of this chain: the LIR and the
                // machine then agree without a masking rule, and an
                // out-of-range amount (undefined behavior in trust-ir) never
                // enters.
                match constants.get(&inst.args[1]).copied() {
                    Some(amount) if amount < u64::from(ty.bits()) => {
                        (SourceOp::Shift(op, inst.args[0], amount as u32), ty, None)
                    }
                    Some(_) => return Err(outside("shifts by an out-of-range constant amount")),
                    // Slice 10: a variable amount of the value's own carrier
                    // (trust-ir's `BinOp` takes two operands of one width).
                    // In range it is trust-ir's shift; at an amount of the
                    // width or more trust-ir has undefined behavior
                    // (`shift_amount`), and the theorem states one refinement
                    // of it, the amount reduced modulo the width
                    // ([`SourceOp::VariableShift`]).
                    None => {
                        // Slice 11: the selector shifts an `I128` by a
                        // variable amount through its two halves and masks
                        // neither the amount nor its halves' counts to 128,
                        // so at an amount of 128 or more it computes no
                        // refinement this theorem states (OD-57 states the
                        // amount modulo the width). Slice 20 (ruling OD-194):
                        // it is stated as slice 10's shift by the amount
                        // modulo 128, admitted when the amount's own
                        // definition bounds it below 128 (`u128::
                        // unchecked_shl` masks it with 127 itself), where the
                        // two agree; the bound finder decides admission
                        // only: wherever the selector's result is not the
                        // modular shift, the theorem is refuted, never
                        // credited.
                        #[cfg(test)]
                        let unbounded = WITHOUT_SHIFT_BOUND.with(std::cell::Cell::get);
                        #[cfg(not(test))]
                        let unbounded = false;
                        if ty == Carrier::I128
                            && !unbounded
                            && indexed::shift_amount_bound(source, inst.args[1], types).is_none()
                        {
                            return Err(outside(
                                "shifts an i128 by a non-constant amount that no mask of its own \
                                 bounds below 128 (the selector's register-pair lowering does not \
                                 reduce it modulo 128)",
                            ));
                        }
                        if ty_of(&inst.args[1])? != ty {
                            return Err(outside("shifts by an amount of another type"));
                        }
                        (
                            SourceOp::VariableShift(op, inst.args[0], inst.args[1]),
                            ty,
                            None,
                        )
                    }
                }
            }
            L::Uextend { from_ty, to_ty } | L::Sextend { from_ty, to_ty } => {
                let signed = matches!(inst.opcode, L::Sextend { .. });
                let (Some(from), Some(to)) = (Carrier::of(from_ty), Carrier::of(to_ty)) else {
                    return Err(outside("extends a non-scalar type"));
                };
                if from.is_float() || to.is_float() {
                    return Err(outside("extends a float bit pattern"));
                }
                if ty_of(&inst.args[0])? != from || from.bits() >= to.bits() {
                    return Err(outside("is not a widening of its operand's type"));
                }
                // A `B1` source is the 1-bit value, so its sign extension
                // (`sign_ext` of that bit below) makes `true` all ones at
                // every width: trust-ir's `SExt` of a `Bool`, which widens
                // `as_signed()` of `InterpretInt { bits: 1 }` (ruling
                // OD-BODY-SEXT-BOOL-20261016). The selector's rows for it are
                // `-zext(b)` (`movzx` or a parameter's 32-bit copy, then
                // `neg`; an `I128`'s high half the `sar 63` of the low half).
                (
                    SourceOp::Extend {
                        signed,
                        value: inst.args[0],
                    },
                    to,
                    None,
                )
            }
            L::StructGep {
                struct_ty,
                field_index,
            } => {
                // `base + offset_of(field)`, the offset from the verify-owned
                // C layout ([`field_offset`]), wrapping like any address add.
                let base = inst.args[0];
                if ty_of(&base)? != Carrier::I64 {
                    return Err(outside("offsets a non-pointer value"));
                }
                let offset = field_offset(struct_ty, *field_index).ok_or_else(|| {
                    outside("addresses a field of a type outside the layout model")
                })?;
                let value_affine = affine_of(&base)
                    .map(|a| a.combine(Affine::constant(offset, u64::MAX), false, u64::MAX));
                let op = if offset == 0 {
                    SourceOp::Copy(base)
                } else {
                    SourceOp::Offset(base, offset)
                };
                (op, Carrier::I64, value_affine)
            }
            // OD-185: an array element's address over a pointer that is no
            // private stack address (an incoming pointer, a symbol, a call
            // result, an address derived from an escaped slot): `base +
            // index * stride` at 64 bits, wrapping ([`array_element_address`]).
            // The index is the 64-bit value itself: the adapter extends a
            // narrower trust-ir index to `I64` (`extend_index_to_i64_if_needed`)
            // before the opcode, and the selector scales the index register
            // as it is, so any other index type is outside.
            L::ArrayGep { elem_ty } => {
                let (base, index) = (inst.args[0], inst.args[1]);
                if ty_of(&base)? != Carrier::I64 {
                    return Err(outside("offsets a non-pointer value"));
                }
                if ty_of(&index)? != Carrier::I64 {
                    return Err(outside(
                        "indexes an array by a value other than an I64 (the selector scales \
                         the index register as it is)",
                    ));
                }
                let stride = array_element_stride(elem_ty).ok_or_else(|| {
                    outside("indexes elements of a type outside the layout model")
                })?;
                // Exact affine values only: at a constant index the offset
                // is that constant; at stride 1 it is the index itself.
                let value_affine = match (affine_of(&base), constants.get(&index)) {
                    (Some(base), Some(index)) => Some(base.combine(
                        Affine::constant(index.wrapping_mul(stride), u64::MAX),
                        false,
                        u64::MAX,
                    )),
                    (Some(base), None) if stride == 1 => {
                        affine_of(&index).map(|index| base.combine(index, false, u64::MAX))
                    }
                    _ => None,
                };
                (
                    SourceOp::ArrayElement {
                        base,
                        index,
                        stride,
                    },
                    Carrier::I64,
                    value_affine,
                )
            }
            L::Trunc { to_ty } => {
                let to = Carrier::of(to_ty).ok_or_else(|| outside("truncates to a non-scalar"))?;
                let from = ty_of(&inst.args[0])?;
                if from.is_float() || to.is_float() {
                    return Err(outside("truncates a float bit pattern"));
                }
                if from.bits() <= to.bits() {
                    return Err(outside("is not a narrowing of its operand's type"));
                }
                (SourceOp::Trunc(inst.args[0]), to, None)
            }
            // Slice 14: division and remainder of two operands of one integer
            // carrier ([`SourceOp::Divide`]), and the point at which trust-ir
            // makes it undefined ([`StopKind::Undefined`]). An `I128` division
            // is the selector's runtime-library call (slice 22, below); a
            // `bool` has no division.
            L::Udiv | L::Sdiv | L::Urem | L::Srem if !i128_division => {
                let (lhs, rhs) = (inst.args[0], inst.args[1]);
                let ty = ty_of(&lhs)?;
                if ty_of(&rhs)? != ty {
                    return Err(outside("divides operands of different types"));
                }
                if !ty.is_word() || ty == Carrier::B1 {
                    return Err(outside("divides a B1 or float value"));
                }
                let signed = matches!(inst.opcode, L::Sdiv | L::Srem);
                // A division by a constant other than 0 (and, signed, -1) is
                // defined for every dividend: no stop.
                let defined = constants.get(&rhs).is_some_and(|k| {
                    let k = crate::smt::mask(*k, ty.bits());
                    k != 0 && !(signed && k == crate::smt::mask(u64::MAX, ty.bits()))
                });
                if !defined {
                    stops.push(SourceStop {
                        events: events.len(),
                        kind: StopKind::Undefined { signed, lhs, rhs },
                        block: block_id,
                        index,
                    });
                }
                (
                    SourceOp::Divide {
                        signed,
                        remainder: matches!(inst.opcode, L::Urem | L::Srem),
                        lhs,
                        rhs,
                        constant: constants.get(&rhs).map(|k| crate::smt::mask(*k, ty.bits())),
                    },
                    ty,
                    None,
                )
            }
            L::Icmp { cond } => {
                // A branch-free compare (slice 5): the `bool` it produces is
                // returned, stored or passed; branches stay outside.
                let (lhs, rhs) = (inst.args[0], inst.args[1]);
                let ty = ty_of(&lhs)?;
                if ty_of(&rhs)? != ty {
                    return Err(outside("compares operands of different types"));
                }
                if ty.is_float() {
                    return Err(outside("compares float bit patterns as integers"));
                }
                // LIR orders a `B1` operand as a 1-bit integer (signed:
                // `true` is -1); no Rust comparison of `bool`s is signed, and
                // the selector compares the zero-extended 0/1 bytes, so a
                // signed order of two bools stays outside the domain.
                if ty == Carrier::B1 && signed_order(*cond) {
                    return Err(outside("orders B1 values as signed integers"));
                }
                (
                    SourceOp::Compare {
                        cond: *cond,
                        lhs,
                        rhs,
                    },
                    Carrier::B1,
                    None,
                )
            }
            L::Select { cond } => {
                // A branch-free select (slice 6): `args[1]` when `args[0] !=
                // 0`, else `args[2]`, all scalars. The other conditions
                // compare `args[0]` with zero some other way; they stay
                // outside.
                if *cond != IntCC::NotEqual {
                    return Err(outside("selects on a test other than `!= 0`"));
                }
                let (test, then, other) = (inst.args[0], inst.args[1], inst.args[2]);
                if !ty_of(&test)?.is_word() {
                    return Err(outside("selects on an i128 or float test"));
                }
                let ty = ty_of(&then)?;
                if ty_of(&other)? != ty {
                    return Err(outside("selects between values of different types"));
                }
                // Slice 11: an `I128` select is two `cmov`s of the halves;
                // a float select (an SSE blend) stays outside.
                if ty.is_float() {
                    return Err(outside("selects between float bit patterns"));
                }
                (SourceOp::Select { test, then, other }, ty, None)
            }
            L::GlobalRef { name } | L::ExternRef { name } => {
                // A symbol's address (slice 5): one free input per symbol
                // and form of reference, shared with the machine row that
                // takes the same address. It is an incoming-memory address
                // like any other; the theorem assumes nothing else about it.
                let symbol = SymbolRef {
                    name: name.clone(),
                    got: matches!(inst.opcode, L::ExternRef { .. }),
                };
                (SourceOp::Symbol(sites.symbol(symbol)), Carrier::I64, None)
            }
            L::Call { .. }
            | L::CallIndirect
            | L::Memcpy
            | L::Memmove
            | L::Memset
            | L::Udiv
            | L::Sdiv
            | L::Urem
            | L::Srem => {
                // A direct call names its callee; an indirect call (slice 10)
                // calls through its leading `I64` function pointer, which the
                // theorem observes like an argument (the callee is the
                // uninterpreted function of the world, that pointer and the
                // arguments).
                let (name, exact_module, callee, call_args) = match &inst.opcode {
                    L::Call { name, binding } => {
                        let exact_module = match binding {
                            DirectCallBinding::Interposable => false,
                            DirectCallBinding::ExactModuleFunction { .. } => true,
                            DirectCallBinding::DeclaredExternalFunction { .. }
                            | DirectCallBinding::NativeDependency { .. } => {
                                return Err(outside("binds a native dependency"));
                            }
                        };
                        (name.clone(), exact_module, None, &inst.args[..])
                    }
                    // Slice 13: LIR `Memcpy`, `Memmove` and `Memset` are calls
                    // to the C runtime's `memcpy`, `memmove` and `memset` by
                    // symbol (the selector lowers each to exactly that call,
                    // `select_memory_intrinsic_call`), under the call model of
                    // slices 3 and 7: an uninterpreted callee of the world and
                    // its arguments on both sides, so nothing about what it
                    // copies or fills is assumed (trusted: that the symbol is
                    // the C runtime's routine, whose effect is the
                    // intrinsic's). The selector passes the C signature's
                    // types, `(I64, I64, I64)` or `(I64, I32, I64)`, so each
                    // operand must be of it; a private address operand is a
                    // pointer, never an aggregate's bytes.
                    //
                    // OD-217: that trust is the routine contract OD-210
                    // guards: the routine is recorded, and a theorem whose
                    // module or link unit defines it, or which is the routine
                    // itself, is refused by the owner
                    // ([`check_trusted_routines`]).
                    L::Memcpy | L::Memmove | L::Memset => {
                        let symbol = memory_routine(&inst.opcode);
                        let middle = if matches!(inst.opcode, L::Memset) {
                            Carrier::I32
                        } else {
                            Carrier::I64
                        };
                        sites.routines.insert(symbol);
                        for (value, ty) in
                            inst.args.iter().zip([Carrier::I64, middle, Carrier::I64])
                        {
                            // Slice 17: outside by name.
                            if indexed.contains_key(value) {
                                return Err(outside(
                                    "passes an indexed private stack address to a C memory \
                                     routine",
                                ));
                            }
                            if !frame.contains_key(value) && ty_of(value)? != ty {
                                return Err(outside(
                                    "passes an operand of another type than the C runtime \
                                     routine's",
                                ));
                            }
                        }
                        (symbol.to_owned(), false, None, &inst.args[..])
                    }
                    // Slice 22 (ruling OD-202): an `I128` division or
                    // remainder (the arm above takes every other) is the
                    // selector's call of its runtime routine by symbol
                    // (`select_i128_div_libcall`), under the same call model:
                    // its two `I128` operands are the call's arguments
                    // (RDI:RSI, RDX:RCX), its result the call's one `I128`
                    // result (RAX:RDX), a free input both sides share, so no
                    // division is stated and no undefined stop either (the
                    // call is total). Trusted: that the routine the link binds
                    // to the name returns trust-ir's division on trust-ir's
                    // defined domain (OD-202), as slice 13 trusts `memcpy`,
                    // and (OD-211) writes no memory the caller observes, has
                    // no effect on the world and returns; a routine the module
                    // under proof or (OD-216) its link unit defines is refused
                    // by the owner ([`check_trusted_routines`]).
                    L::Udiv | L::Sdiv | L::Urem | L::Srem => {
                        if ty_of(&inst.args[1])? != Carrier::I128 {
                            return Err(outside("divides operands of different types"));
                        }
                        // OD-210: recorded for the check of the module's
                        // (and, OD-216, its link unit's) own definitions
                        // ([`check_trusted_routines`]).
                        sites.routines.insert(i128_division_routine(&inst.opcode));
                        (
                            i128_division_routine(&inst.opcode).to_owned(),
                            false,
                            None,
                            &inst.args[..],
                        )
                    }
                    _ => {
                        let callee = inst.args[0];
                        if ty_of(&callee)? != Carrier::I64 {
                            return Err(outside("calls through a non-pointer value"));
                        }
                        (String::new(), false, Some(callee), &inst.args[1..])
                    }
                };
                if inst.results.len() > SYSV_RETURN_ROOTS.len() {
                    return Err(outside(
                        "returns more than two values (the System V RAX:RDX return pair)",
                    ));
                }
                // Each argument: a scalar; a private stack address passed as
                // a pointer (slice 7), a 64-bit argument that makes its slot
                // escape to this call and every later one; or (slice 8) an
                // aggregate the LIR types as one, passed by value: the bytes
                // at its address now, one System V eightbyte per argument
                // register. Its slot does not escape.
                let mut args = Vec::with_capacity(call_args.len());
                let intrinsic = matches!(inst.opcode, L::Memcpy | L::Memmove | L::Memset);
                for value in call_args {
                    // Slice 17: an indexed private address, observed as its
                    // slot's address plus its offset, claimed into the slot
                    // or one past it; the slot escapes.
                    if let Some(address) = indexed.get(value).copied() {
                        let size = slot_sizes[address.slot as usize];
                        // No select reads an argument: only its claim is stated,
                        // so the candidate bounds do not apply.
                        if indexed::candidates(size, 0, address.modulus, address.residue())
                            .is_empty()
                        {
                            return Err(outside(
                                "passes an indexed private stack address no offset of which lies \
                                 in its slot",
                            ));
                        }
                        indexed_sites.push(IndexedSite {
                            address,
                            width: 0,
                            size,
                            stops: stops.len(),
                            block: block_id,
                            index,
                        });
                        args.push(CallArg::Indexed(address));
                        continue;
                    }
                    let arg = match (frame.get(value), aggregates.get(value)) {
                        (Some(address), Some(ty)) if !intrinsic => {
                            let aggregate = classify_aggregate(ty).map_err(|reason| {
                                outside(&format!(
                                    "passes an aggregate argument outside the System V INTEGER \
                                     register class: {reason}"
                                ))
                            })?;
                            let range = stack_range(address, aggregate.size, slot_sizes)
                                .ok_or_else(|| {
                                    outside("passes an aggregate that extends past its slot")
                                })?;
                            let lanes = aggregate
                                .lanes
                                .iter()
                                .map(|lane| {
                                    let first = range.start + lane.offset as usize;
                                    (first..first + lane.bytes as usize)
                                        .map(|offset| {
                                            let byte = slot_bytes[address.slot as usize][offset];
                                            let at = FrameAddr {
                                                slot: address.slot,
                                                offset: offset as i64,
                                            };
                                            if byte.is_none() {
                                                sites.frame_byte(at);
                                            }
                                            (at, byte)
                                        })
                                        .collect()
                                })
                                .collect::<Vec<SlotBytes>>();
                            if lanes
                                .iter()
                                .flatten()
                                .any(|(_, byte)| *byte == Some(SlotByte::Dead))
                            {
                                return Err(outside(
                                    "passes an aggregate holding a private stack byte its cut \
                                     point leaves out as dead",
                                ));
                            }
                            // Slice 13: an eightbyte that is a whole stored
                            // private address reaches the callee in its
                            // register as that address (the machine loads it
                            // back as one, [`CallArg::register_frames`]), and
                            // its slot escapes; part of one is outside.
                            if lanes.iter().any(|lane| {
                                let part: Vec<Option<SlotByte>> =
                                    lane.iter().map(|(_, byte)| *byte).collect();
                                part.iter()
                                    .any(|byte| byte.and_then(SlotByte::address).is_some())
                                    && whole_address(&part).is_none()
                            }) {
                                return Err(outside(
                                    "passes an aggregate holding part of a private stack address",
                                ));
                            }
                            CallArg::Aggregate(lanes)
                        }
                        (Some(address), _) => CallArg::Frame(*address),
                        (None, _) => CallArg::Scalar(*value, ty_of(value)?),
                    };
                    args.push(arg);
                }
                // Each argument's registers (slice 11: an `I128` takes two
                // INTEGER registers, a float one SSE register).
                // Slice 13: an `I8`/`I16`/`I32`/`I64` scalar or a private
                // address past the six INTEGER registers goes in the next
                // eightbyte of the outgoing argument area ([`stack_arguments`]).
                let Some((args, stack_args)) = stack_arguments(args) else {
                    return Err(outside(
                        "passes more than six register arguments (or eight SSE ones) and an \
                         argument other than an I8, I16, I32, I64, I128 or private address on the \
                         stack",
                    ));
                };
                let arg_roots: Vec<u16> =
                    argument_roots(args.iter().map(|arg| (arg.registers(), arg.sse())))
                        .expect("the register arguments fit their registers")
                        .into_iter()
                        .flatten()
                        .collect();
                // Slice 15: a function that takes a B1 parameter may pass a B1
                // argument. Its register holds a psABI or a clean 32-bit bool
                // depending on the caller (module documentation), and the
                // argument is observed as the clean 32-bit bool every callee
                // the backend meets reads, under every caller view walked: the
                // psABI view's caller clears bits 1..7 only, so a lowering
                // that forwards the 32-bit register is refuted, and one that
                // first zero-extends its low byte (the selector's `movzx`
                // since slice 15) is not.
                // A callee whose argument 0 is its hidden return buffer
                // (slice 7; the selector places it as the first integer
                // argument, as System V requires) returns through that
                // buffer and nothing else.
                if callee.is_none()
                    && source.sret_arg_callees.contains(&name)
                    && (!matches!(
                        args.first(),
                        Some(CallArg::Frame(..) | CallArg::Scalar(_, Carrier::I64))
                    ) || !inst.results.is_empty())
                {
                    return Err(outside(
                        "calls a return-buffer callee without a leading pointer argument or \
                         with a result",
                    ));
                }
                let arg_affine = args
                    .iter()
                    .flat_map(|arg| match arg {
                        CallArg::Scalar(value, Carrier::I64) => vec![affine_of(value)],
                        other => vec![None; other.registers()],
                    })
                    .collect();
                let k = calls.len();
                // Each result lane's type is the callee's declared result,
                // carried only by the sidecar type hint: scalars in RAX (and
                // RDX), or (slice 8) one aggregate whose eightbytes return
                // there, into the private slot the selector allocates.
                let result_slot = result_slots.get(&(block_id, index)).cloned();
                let results = match &result_slot {
                    Some(_) => Vec::new(),
                    // Slice 22: a division's one result is its operands' `I128`.
                    None if i128_division => vec![(inst.results[0], Carrier::I128)],
                    None => inst
                        .results
                        .iter()
                        .map(|result| match source.value_types.get(result) {
                            Some(ty) => match Carrier::of(ty) {
                                Some(carrier) => Ok((*result, carrier)),
                                None => Err(outside(&aggregate_refusal("call result", ty))),
                            },
                            None => Err(outside("has no scalar result type")),
                        })
                        .collect::<Result<Vec<_>, _>>()?,
                };
                // Slice 11: an `I128` result is the RAX:RDX pair and must be
                // the call's only result; a float result is in XMM0 (XMM1
                // for a second float lane).
                if results.len() > 1 && results.iter().any(|(_, carrier)| *carrier == Carrier::I128)
                {
                    return Err(outside(
                        "returns an i128 beside another value (more than the RAX:RDX pair)",
                    ));
                }
                let results_ty: Vec<ResultLane> = match &result_slot {
                    Some((_, aggregate)) => aggregate
                        .lanes
                        .iter()
                        .zip(SYSV_RETURN_ROOTS)
                        .map(|(lane, root)| ResultLane::eightbyte(*lane, root))
                        .collect(),
                    None => match results.as_slice() {
                        [(_, Carrier::I128)] => SYSV_RETURN_ROOTS
                            .iter()
                            .map(|root| ResultLane::half(*root))
                            .collect(),
                        _ => {
                            let roots =
                                result_roots(results.iter().map(|(_, carrier)| carrier.is_float()))
                                    .expect("at most two results");
                            results
                                .iter()
                                .zip(roots)
                                .map(|((_, carrier), root)| {
                                    ResultLane::scalar(*carrier, results.len(), root)
                                })
                                .collect()
                        }
                    },
                };
                let site = sites.call(block_id, index, &results_ty);
                // Slice 7: the call reads every slot that escaped to it or
                // to an earlier call (a callee may retain an escaped
                // address, and a later callee may use it), then leaves each
                // of their bytes as it chooses: the call-defined input
                // `d{site}s{slot}o{offset}` of every byte, padding and bytes
                // past the passed address included.
                // Slice 13: with each slot that escapes, every slot whose
                // address its bytes hold ([`escape_source`]).
                let passed: Vec<u32> = args
                    .iter()
                    .chain(stack_args.iter().map(|(arg, _)| arg))
                    .flat_map(CallArg::register_frames)
                    .flatten()
                    .map(|address| address.slot)
                    .chain(args.iter().filter_map(|arg| match arg {
                        CallArg::Indexed(address) => Some(address.slot),
                        _ => None,
                    }))
                    .collect();
                escape_source(escaped, slot_bytes, passed);
                let slot_reads = escaped_slot_reads(escaped, slot_bytes, sites).map_err(outside)?;
                for slot in escaped.iter() {
                    slot_bytes[*slot as usize].fill(Some(SlotByte::Call(site)));
                }
                calls.push(SourceCall {
                    site,
                    name,
                    exact_module,
                    callee,
                    args,
                    arg_roots,
                    stack_args,
                    slot_reads,
                    arg_affine,
                    results: results_ty,
                    block: block_id,
                    index,
                });
                events.push(SourceEvent::Call(k));
                // Slice 8: an aggregate result is the address of its private
                // slot, whose bytes are the eightbytes the callee returned:
                // each the low bytes of RAX or RDX, the free input
                // `r{site}`/`q{site}`. Once a slot escaped, they may hold an
                // address derived from it.
                if let Some((slot, aggregate)) = result_slot {
                    let result = inst.results[0];
                    if types.insert(result, Carrier::I64).is_some() {
                        return Err(domain(format!(
                            "instruction {position} redefines an SSA value"
                        )));
                    }
                    frame.insert(result, FrameAddr { slot, offset: 0 });
                    aggregates.insert(result, aggregate.ty.clone());
                    for (lane, eightbyte) in aggregate.lanes.iter().enumerate() {
                        for byte in 0..eightbyte.bytes {
                            slot_bytes[slot as usize][(eightbyte.offset + byte) as usize] =
                                Some(SlotByte::Result {
                                    site,
                                    lane,
                                    byte,
                                    width: eightbyte.bits(),
                                });
                        }
                    }
                    if !escaped.is_empty() {
                        tainted_sites.insert(site);
                    }
                    continue;
                }
                // Record each result lane as a definition.
                for (lane, (result, ty)) in results.into_iter().enumerate() {
                    if types.insert(result, ty).is_some() {
                        return Err(domain(format!(
                            "instruction {position} redefines an SSA value"
                        )));
                    }
                    // Slice 7: once a slot escaped, a call may return an
                    // address derived from it.
                    if !escaped.is_empty() {
                        tainted.insert(result);
                    }
                    definitions.push(SourceDefinition {
                        result,
                        ty,
                        op: SourceOp::CallResult(site, lane),
                        block: block_id,
                        index,
                    });
                }
                continue;
            }
            L::Trap => {
                // The path ends in a trap (slice 6): reaching it is the
                // path's observable end, after whatever calls and accesses
                // precede it (a diverging call's arguments, or none).
                end = Some(SourceEnd::Trap);
                continue;
            }
            L::Return => {
                if *sret {
                    // The buffer parameter (Value(0)) is what RAX returns.
                    returned = vec![Returned::Value(Value(0), Carrier::I64)];
                } else if let Some(aggregate) = returned_aggregate {
                    // Slice 8: an aggregate result is the bytes at the
                    // returned private address now, one System V eightbyte
                    // in RAX, then RDX.
                    let value = inst.args[0];
                    let address = frame.get(&value).copied().ok_or_else(|| {
                        outside("returns an aggregate that is not at a private stack address")
                    })?;
                    if aggregates.get(&value).is_some_and(|ty| *ty != aggregate.ty) {
                        return Err(outside("returns an aggregate of another type"));
                    }
                    let range =
                        stack_range(&address, aggregate.size, slot_sizes).ok_or_else(|| {
                            outside("returns an aggregate that extends past its slot")
                        })?;
                    // Slice 13: a returned private address (the machine moves
                    // it as an address, not bits) stays outside; slice 17: so
                    // does a dead byte.
                    if slot_bytes[address.slot as usize][range.clone()]
                        .iter()
                        .any(|byte| {
                            byte.and_then(SlotByte::address).is_some()
                                || *byte == Some(SlotByte::Dead)
                        })
                    {
                        return Err(outside(
                            "returns an aggregate holding a private stack address",
                        ));
                    }
                    for lane in &aggregate.lanes {
                        let first = range.start + lane.offset as usize;
                        returned.push(Returned::Bytes(
                            (first..first + lane.bytes as usize)
                                .map(|offset| {
                                    let byte = slot_bytes[address.slot as usize][offset];
                                    let at = FrameAddr {
                                        slot: address.slot,
                                        offset: offset as i64,
                                    };
                                    if byte.is_none() {
                                        sites.frame_byte(at);
                                    }
                                    (at, byte)
                                })
                                .collect(),
                        ));
                    }
                } else if let [ReturnLane::Half(0), ReturnLane::Half(1)] = return_tys.as_slice() {
                    // Slice 11: an `I128` result, its low half in RAX and its
                    // high half in RDX.
                    let value = inst.args[0];
                    if ty_of(&value)? != Carrier::I128 {
                        return Err(outside("returns a value of another type"));
                    }
                    returned = vec![Returned::Half(value, 0), Returned::Half(value, 1)];
                } else {
                    for (value, return_ty) in inst.args.iter().zip(return_tys.iter()) {
                        let ReturnLane::Scalar(return_ty) = *return_ty else {
                            unreachable!("only an aggregate or i128 result has other lanes");
                        };
                        let returned_ty = ty_of(value)?;
                        // A narrow I8/I16 result lane may be carried by an I32
                        // value; the selector returns its low bits
                        // (`narrow_return_widened`).
                        let widened = matches!(return_ty, Carrier::I8 | Carrier::I16)
                            && returned_ty == Carrier::I32;
                        if returned_ty != return_ty && !widened {
                            return Err(outside("returns a value of another type"));
                        }
                        returned.push(Returned::Value(*value, returned_ty));
                    }
                }
                end = Some(SourceEnd::Return);
                continue;
            }
            // Slice 21 (ruling OD-198): `Fadd`, `Fsub`, `Fmul` and `Fdiv` of two
            // patterns of one format, the IEEE 754 operation at that format
            // rounding to nearest even (trust-ir `ub-numerics-policy.md` §2,
            // `interpret::eval_float_binop`; any NaN result is only required to
            // be a NaN), are rounding events: the next event of the world
            // trace, paired with the machine row of the same operator key,
            // whose operands the theorem claims equal to these and whose
            // result is this one's free input [`float_event_name`].
            L::Fadd | L::Fsub | L::Fmul | L::Fdiv => {
                let (lhs, rhs) = (inst.args[0], inst.args[1]);
                let format = ty_of(&lhs)?;
                if !format.is_float() || ty_of(&rhs)? != format {
                    return Err(outside(
                        "is floating-point arithmetic of operands other than two patterns of \
                         one format",
                    ));
                }
                let op = match inst.opcode {
                    L::Fadd => FloatEventOp::Add,
                    L::Fsub => FloatEventOp::Sub,
                    L::Fmul => FloatEventOp::Mul,
                    _ => FloatEventOp::Div,
                };
                let key = FloatKey::arithmetic(op, format);
                let site = sites.float(block_id, index, key.result_bits());
                events.push(SourceEvent::Float(floats.len()));
                floats.push(SourceFloat {
                    site,
                    key,
                    args: vec![lhs, rhs],
                    unsigned: false,
                    block: block_id,
                    index,
                });
                (SourceOp::FloatEvent(site), format, None)
            }
            // Slice 21 (OD-198): `FcvtFromInt`/`FcvtFromUint` of an `I64` to an
            // `F32` or `F64` (trust-ir `SIToFP`/`UIToFP`: the exact integer,
            // signed or unsigned, rounded once to nearest even at the result's
            // format, never through `f64` for an `F32`), a rounding event. A
            // narrower integer stays outside by name.
            L::FcvtFromInt { src_ty } | L::FcvtFromUint { src_ty } => {
                let unsigned = matches!(inst.opcode, L::FcvtFromUint { .. });
                if *src_ty != Type::I64 || ty_of(&inst.args[0])? != Carrier::I64 {
                    return Err(outside(
                        "converts an integer narrower than I64 to a float (only the 64-bit \
                         conversions are rounding events of the lane, OD-198)",
                    ));
                }
                let format = source
                    .value_types
                    .get(&inst.results[0])
                    .and_then(Carrier::of)
                    .filter(|carrier| carrier.is_float())
                    .ok_or_else(|| {
                        outside("converts to a float whose type the LIR does not record")
                    })?;
                let key = FloatKey {
                    op: FloatEventOp::FromInt64,
                    format,
                    rounding: Rounding::NearestEven,
                };
                let site = sites.float(block_id, index, key.result_bits());
                events.push(SourceEvent::Float(floats.len()));
                floats.push(SourceFloat {
                    site,
                    key,
                    args: vec![inst.args[0]],
                    unsigned,
                    block: block_id,
                    index,
                });
                (SourceOp::FloatEvent(site), format, None)
            }
            // Slice 21 (OD-199): `FcvtToInt { dst_ty: I64 }` of an `F64`, the
            // saturating conversion ([`saturating_f64_to_i64`]) whose in-range
            // value is a rounding event (truncation toward zero). Any other
            // pair of types stays outside by name.
            L::FcvtToInt { dst_ty } => {
                let value = inst.args[0];
                if *dst_ty != Type::I64 || ty_of(&value)? != Carrier::F64 {
                    return Err(outside(
                        "converts a float to an integer other than an F64 to an I64 (OD-199)",
                    ));
                }
                let key = FloatKey {
                    op: FloatEventOp::ToInt64,
                    format: Carrier::F64,
                    rounding: Rounding::TowardZero,
                };
                let site = sites.float(block_id, index, key.result_bits());
                events.push(SourceEvent::Float(floats.len()));
                floats.push(SourceFloat {
                    site,
                    key,
                    args: vec![value],
                    unsigned: false,
                    block: block_id,
                    index,
                });
                (SourceOp::FloatToInt { value, site }, Carrier::I64, None)
            }
            // Slice 21: `Fcmp { cond }` of two patterns of one format, exactly
            // ([`FloatRelation::holds`]); no rounding, no event.
            L::Fcmp { cond } => {
                let (lhs, rhs) = (inst.args[0], inst.args[1]);
                let format = ty_of(&lhs)?;
                if !format.is_float() || ty_of(&rhs)? != format {
                    return Err(outside(
                        "compares operands other than two float patterns of one format",
                    ));
                }
                (
                    SourceOp::FloatCompare {
                        cond: *cond,
                        format,
                        lhs,
                        rhs,
                    },
                    Carrier::B1,
                    None,
                )
            }
            _ => unreachable!("opcode admitted above"),
        };
        let result = inst.results[0];
        if types.insert(result, ty).is_some() {
            return Err(domain(format!(
                "instruction {position} redefines an SSA value"
            )));
        }
        if let Some(value_affine) = value_affine {
            affine.insert(result, value_affine);
        }
        // Slice 7: a value computed from one that may derive from an escaped
        // slot's address may too.
        if inst.args.iter().any(|arg| tainted.contains(arg)) {
            tainted.insert(result);
        }
        // An integer operation of constants of this chain is itself a
        // constant (exact wrapping semantics at the result width): such a
        // value may offset a private stack address or be a shift amount.
        if let Some(value) = fold_constant(&op, ty, constants) {
            constants.insert(result, value);
            if ty == Carrier::I64 {
                affine
                    .entry(result)
                    .or_insert(Affine::constant(value, u64::MAX));
            }
        }
        definitions.push(SourceDefinition {
            result,
            ty,
            op,
            block: block_id,
            index,
        });
    }
    // A DAG block (slice 9) that ends in a transfer continues at a successor.
    let end = match end {
        Some(end) => end,
        None if dag => SourceEnd::Continue,
        None => return Err(domain("missing return".into())),
    };
    // A path that ends in a trap returns nothing: its observable is its
    // trace and the trap itself.
    let (return_tys, return_roots) = match end {
        SourceEnd::Return => (return_tys.clone(), return_roots.clone()),
        SourceEnd::Trap | SourceEnd::Continue => (Vec::new(), Vec::new()),
    };
    let return_affine = returned
        .iter()
        .zip(&return_tys)
        .map(|(returned, return_ty)| match (returned, return_ty) {
            (Returned::Value(value, Carrier::I64), ReturnLane::Scalar(Carrier::I64)) => {
                affine.get(value).copied()
            }
            _ => None,
        })
        .collect();
    Ok(SourceProgram {
        params: params.clone(),
        definitions,
        calls,
        accesses,
        floats,
        events,
        slot_sizes: slot_sizes.clone(),
        returned,
        return_tys,
        return_roots,
        end,
        return_affine,
        blocks: spec.iter().map(|(block, _)| *block).collect(),
        branches,
        types: types.clone(),
        aggregates: aggregates.clone(),
        stops,
        indexed: indexed_sites,
        byte_definitions,
    })
}

/// One private stack byte the edges into a DAG join leave differently
/// (slice 9): what each incoming edge brings, chosen at the join by the
/// edges' guards.
struct SlotMerge {
    /// The region of the join (slice 12; 0 for an acyclic body's DAG).
    region: usize,
    /// The join block.
    join: Block,
    address: FrameAddr,
    /// Each incoming edge's source block, in the join's predecessor order,
    /// and the byte that edge brings (`None`: the slot's initial byte).
    incoming: Vec<(Block, Option<SlotByte>)>,
}

/// The admitted DAG of a several-path source the slice-6 encoding does not
/// state (slice 9; [`SourceCfg::per_path`]): every block admitted once, in
/// topological order, from the merge of the states its incoming edges bring
/// ([`merge_admitted`]). Its theorem is linear in the blocks
/// ([`build_theorem`]).
struct DagBody {
    /// The blocks in topological order, the entry block first.
    order: Vec<Block>,
    /// Each block's successors in edge order.
    successors: HashMap<Block, Vec<Block>>,
    /// Each block's predecessors, in `order`.
    predecessors: HashMap<Block, Vec<Block>>,
    /// Each block's fragment: its definitions, calls, accesses and end, and
    /// (a conditional block) one [`SourceBranch`] per outgoing edge, in edge
    /// order. Its `types` hold every value defined on every path into the
    /// block's end.
    blocks: HashMap<Block, SourceProgram>,
    /// The scalar values each join's merged state keeps (every incoming edge
    /// defines them at one carrier), ascending: the builder joins each one's
    /// incoming terms.
    joined: HashMap<Block, Vec<Value>>,
    /// Every merged private byte ([`SlotByte::Merged`] names its index; a
    /// source with loops keeps them in [`LoopBody::merges`], and this is
    /// empty).
    merges: Vec<SlotMerge>,
    /// Slice 12: the cut point a region of a source with loops starts at,
    /// which qualifies its guard names (`c{H}x{B}`, `c{H}x{B}t{S}`); `None`
    /// for an acyclic body's DAG (`c{B}`, `c{B}t{S}`).
    prefix: Option<Block>,
    /// Slice 20 (ruling OD-192): the private bytes each join leaves DEAD
    /// because the paths into it leave them holding different values, one of
    /// them a stored private address, and no path from the join reads them
    /// before a store overwrites them ([`merge_admitted`]): unreadable after
    /// the join on both sides ([`SlotByte::Dead`], [`MachineByte::dead`]).
    /// Only joins with such a byte have an entry.
    join_dead: HashMap<Block, std::collections::BTreeSet<(u32, i64)>>,
}

/// Slice 20 (ruling OD-192): the private bytes live at the start of each
/// block of a source ([`split::live_bytes`], slice 17's one byte liveness),
/// computed when a DAG join first needs it.
struct JoinLiveness<'a> {
    source: &'a Function,
    cfg: &'a SourceCfg,
    live: std::cell::OnceCell<HashMap<Block, split::ByteSet>>,
}

impl<'a> JoinLiveness<'a> {
    fn new(source: &'a Function, cfg: &'a SourceCfg) -> Self {
        Self {
            source,
            cfg,
            live: std::cell::OnceCell::new(),
        }
    }

    /// The liveness already computed for `source` and `cfg`.
    fn known(
        source: &'a Function,
        cfg: &'a SourceCfg,
        live: HashMap<Block, split::ByteSet>,
    ) -> Self {
        Self {
            source,
            cfg,
            live: std::cell::OnceCell::from(live),
        }
    }

    /// Whether private byte `address` is DEAD at the start of `block`: no path
    /// from there reads it before a store overwrites it. A byte of a slot the
    /// LIR does not declare never is.
    fn dead(&self, block: Block, address: FrameAddr) -> bool {
        self.live
            .get_or_init(|| split::live_bytes(self.source, self.cfg))
            .get(&block)
            .is_some_and(|live| !live.contains(address.slot, address.offset))
    }
}

/// A view of the control flow a DAG is admitted over: an acyclic source's
/// whole CFG (slice 9) or one region of a source with loops (slice 12).
#[derive(Clone, Copy)]
struct DagView<'c> {
    order: &'c [Block],
    successors: &'c HashMap<Block, Vec<Block>>,
    predecessors: &'c HashMap<Block, Vec<Block>>,
}

/// One cut edge out of a region (slice 12): from a block of the region into
/// a loop header (its own region's start, a back edge; or another header).
#[derive(Clone)]
struct CutEdge {
    /// The source value each parameter of the header takes on this edge, in
    /// parameter order: the parameter itself, or the value the edge's copies
    /// (the last instructions before the block's `Jump`, run in order) give
    /// it, as a value of the block's state before them.
    values: Vec<Value>,
    /// The LIR index, in the edge's block, of the copy that defines each
    /// parameter on this edge, if any (the machine row lowering it names the
    /// register that holds the parameter: [`LoopPairing`]).
    copies: Vec<Option<usize>>,
    /// The source state at the edge, before the copies.
    state: AdmitState,
}

/// Admit a several-path source as a DAG (slice 9): each block once, in
/// topological order, under the slice 1-6 instruction rules, from the state
/// the paths into it share. A block with one predecessor starts from that
/// block's end state; a join from the merge of its predecessors' end states
/// ([`merge_admitted`]). Every check a path would make is made on every
/// path through the block, so the DAG admits a source exactly when each of
/// its paths would be admitted as a chain, except where a merge loses
/// precision (a value defined differently on different paths is no longer a
/// constant, an address offset or an affine value; a value some incoming
/// edge does not define is undefined), which only refuses more; and a join
/// whose incoming paths let different private slots escape is outside the
/// domain.
fn admitted_dag(
    source: &Function,
    frame_facts: &SourceFrame,
    cfg: &SourceCfg,
    sites: &mut SourceSites,
) -> Result<DagBody, X86BodyRefusal> {
    let view = DagView {
        order: &cfg.order,
        successors: &cfg.successors,
        predecessors: &cfg.predecessors,
    };
    let mut merges = Vec::new();
    let (mut dag, _) = admitted_region(
        source,
        frame_facts,
        view,
        AdmitState::entry(frame_facts),
        &HashSet::new(),
        sites,
        &mut merges,
        (0, None),
        &JoinLiveness::new(source, cfg),
    )?;
    dag.merges = merges;
    Ok(dag)
}

/// The number of instructions before a block's terminator that are the
/// copies into a loop header's parameters on its edge to it (slice 12): the
/// longest run of `Copy` instructions ending just before a `Jump` to a cut
/// point, each defining one of that header's parameters or a temporary that
/// only later copies of the run read (the adapter lowers a branch's block
/// arguments to such copies, in the predecessor or in a copy block of its
/// own, breaking a cycle of them through a temporary). Zero for any other
/// block. The copies run in order, each reading the state the earlier ones
/// left ([`CutEdge::values`]).
fn edge_copy_count(source: &Function, block: Block, cuts: &HashSet<Block>) -> usize {
    let instructions = &source.blocks[&block].instructions;
    let Some((L::Jump { dest }, body)) = instructions
        .split_last()
        .map(|(last, body)| (&last.opcode, body))
    else {
        return 0;
    };
    if !cuts.contains(dest) {
        return 0;
    }
    copy_run(source, body, *dest)
}

/// The length of the longest run of `Copy` instructions ending `body` that
/// are copies into `dest`'s parameters ([`edge_copy_count`]'s run, `body` the
/// instructions before a `Jump` to `dest`), the reads counted over every
/// block of `source`. Slice 24a measures it over a merged chain's
/// concatenation too ([`quotient`], refusal D10).
fn copy_run(
    source: &Function,
    body: &[trust_cg_lower::instructions::Instruction],
    dest: Block,
) -> usize {
    let params: HashSet<Value> = source.blocks[&dest]
        .params
        .iter()
        .map(|(value, _)| *value)
        .collect();
    // Every read of each value in the function.
    let mut reads: HashMap<Value, usize> = HashMap::new();
    for inst in source.blocks.values().flat_map(|block| &block.instructions) {
        for arg in &inst.args {
            *reads.entry(*arg).or_default() += 1;
        }
    }
    // The copies of the run found so far (from the end) and their reads.
    let mut run_reads: HashMap<Value, usize> = HashMap::new();
    let mut count = 0;
    for inst in body.iter().rev() {
        let [result] = inst.results.as_slice() else {
            break;
        };
        let temporary = run_reads.get(result).copied().unwrap_or(0) > 0
            && run_reads.get(result) == reads.get(result);
        if !matches!(inst.opcode, L::Copy)
            || inst.args.len() != 1
            || !(params.contains(result) || temporary)
        {
            break;
        }
        *run_reads.entry(inst.args[0]).or_default() += 1;
        count += 1;
    }
    count
}

/// Admit one DAG from `start`, the state at its first block's entry: an
/// acyclic source's whole CFG (slice 9, no cut points) or one region of a
/// source with loops (slice 12, `cuts` its cut points). Each block once, in
/// topological order, under the slice 1-6 instruction rules, from the state
/// the paths into it share. A block with one predecessor starts from that
/// block's end state; a join from the merge of its predecessors' end states
/// ([`merge_admitted`]). Every check a path would make is made on every
/// path through the block. `region` is the region's index (which the
/// [`SlotMerge`]s it makes record) and its guard prefix. Returns the DAG and
/// (slice 12) each cut edge out of it ([`CutEdge`]).
#[allow(clippy::too_many_arguments)]
fn admitted_region(
    source: &Function,
    frame_facts: &SourceFrame,
    view: DagView<'_>,
    start: AdmitState,
    cuts: &HashSet<Block>,
    sites: &mut SourceSites,
    merges: &mut Vec<SlotMerge>,
    region: (usize, Option<Block>),
    liveness: &JoinLiveness<'_>,
) -> Result<(DagBody, RegionCutEdges), X86BodyRefusal> {
    let domain = |reason: String| unsupported(X86BodyUnsupported::SourceDomain(reason));
    let mut exits: HashMap<Block, AdmitState> = HashMap::new();
    // Every value some path into a block's end defines: a join keeps only
    // the values every predecessor defines alike, and a block may redefine
    // none of the others (on some path that is an SSA redefinition, which a
    // chain refuses).
    let mut defined: HashMap<Block, HashSet<Value>> = HashMap::new();
    // How many successors of each block are still to be admitted: its end
    // state is dropped after the last (a block with a cut edge keeps it).
    let mut pending: HashMap<Block, usize> = view
        .successors
        .iter()
        .map(|(block, targets)| (*block, targets.len()))
        .collect();
    let mut blocks = HashMap::new();
    let mut joined = HashMap::new();
    let mut join_dead = HashMap::new();
    let mut cut_edges: RegionCutEdges = HashMap::new();
    let mut start = Some(start);
    for block in view.order {
        let predecessors = &view.predecessors[block];
        let (mut state, mut ever) = match predecessors.as_slice() {
            [] => {
                let state = start.take().expect("one block starts the DAG");
                let ever: HashSet<Value> = state.types.keys().copied().collect();
                (state, ever)
            }
            [only] => (exits[only].clone(), defined[only].clone()),
            several => {
                let (state, dead) =
                    merge_admitted(*block, several, &exits, merges, sites, region.0, liveness)?;
                if !dead.is_empty() {
                    join_dead.insert(*block, dead);
                }
                // A private address (slice 17: an indexed one too) is no
                // term the builder joins.
                let mut values: Vec<Value> = state
                    .types
                    .keys()
                    .filter(|value| {
                        !state.frame.contains_key(value) && !state.indexed.contains_key(value)
                    })
                    .copied()
                    .collect();
                values.sort_unstable_by_key(|value| value.0);
                joined.insert(*block, values);
                let ever: HashSet<Value> = several
                    .iter()
                    .flat_map(|predecessor| defined[predecessor].iter().copied())
                    .collect();
                (state, ever)
            }
        };
        for predecessor in predecessors {
            let left = pending.get_mut(predecessor).expect("a predecessor");
            *left -= 1;
            if *left == 0 {
                exits.remove(predecessor);
            }
        }
        let before: HashSet<Value> = state.types.keys().copied().collect();
        // Slice 12: the copies into a loop header's parameters on a cut edge
        // are the edge's, stated by the cut-point relation ([`CutEdge`]).
        let tail = edge_copy_count(source, *block, cuts);
        let fragment = admit_blocks(
            source,
            frame_facts,
            &[(*block, None)],
            sites,
            &mut state,
            true,
            tail,
        )?;
        let mut redefined: Vec<Value> = state
            .types
            .keys()
            .filter(|value| !before.contains(value) && ever.contains(value))
            .copied()
            .collect();
        redefined.sort_unstable_by_key(|value| value.0);
        if let Some(value) = redefined.first() {
            return Err(domain(format!(
                "block {block:?} redefines {value:?}, which a path into it already defined"
            )));
        }
        // Slice 12: each cut edge out of the block, with the value each of
        // its header's parameters takes there (the edge copies run in order,
        // each reading the state the earlier ones left).
        for target in &view.successors[block] {
            if !cuts.contains(target) {
                continue;
            }
            let instructions = &source.blocks[block].instructions;
            let copies_run = if instructions
                .last()
                .is_some_and(|last| matches!(last.opcode, L::Jump { dest } if dest == *target))
            {
                instructions.len() - 1 - tail..instructions.len() - 1
            } else {
                0..0
            };
            let mut taken: HashMap<Value, (Value, usize)> = HashMap::new();
            for index in copies_run {
                let inst = &instructions[index];
                let read = taken
                    .get(&inst.args[0])
                    .map_or(inst.args[0], |(value, _)| *value);
                taken.insert(inst.results[0], (read, index));
            }
            let mut values = Vec::new();
            let mut copies = Vec::new();
            for (param, _) in &source.blocks[target].params {
                let (value, copy) = match taken.get(param) {
                    Some((value, index)) => (*value, Some(*index)),
                    None => (*param, None),
                };
                if !state.types.contains_key(&value) {
                    return Err(domain(format!(
                        "loop header {target:?} parameter {param:?} is not defined on the edge \
                         from block {block:?}"
                    )));
                }
                values.push(value);
                copies.push(copy);
            }
            cut_edges.insert(
                (*block, *target),
                CutEdge {
                    values,
                    copies,
                    state: state.clone(),
                },
            );
        }
        ever.extend(state.types.keys().copied());
        defined.insert(*block, ever);
        if !view.successors[block].is_empty() {
            exits.insert(*block, state);
        }
        blocks.insert(*block, fragment);
    }
    Ok((
        DagBody {
            order: view.order.to_vec(),
            successors: view.successors.clone(),
            predecessors: view.predecessors.clone(),
            blocks,
            joined,
            merges: Vec::new(),
            prefix: region.1,
            join_dead,
        },
        cut_edges,
    ))
}

/// The admission state at the entry of DAG join `join` (slice 9): what the
/// end states of its predecessors (`incoming`, in the join's predecessor
/// order) agree on, and a [`SlotByte::Merged`] byte wherever they disagree.
///
/// A value is kept when every incoming edge defines it at one carrier and,
/// if it is a private stack address, at one address (the builder joins its
/// incoming terms by the edges' guards); its affine value, constant and
/// aggregate type only when every edge gives the same one. The values that
/// may derive from an escaped slot are the union of the edges'. Every slot
/// byte the edges leave alike (a stored byte only while its value is kept)
/// is kept; any other is merged, each incoming byte resolved later in its
/// edge's terms. The escaped slots are the union of the edges' (slice 13),
/// closed under the addresses the merged bytes hold ([`escape_source`]): a
/// slot that escaped on some path into the join is treated as escaped on
/// every path through it. That over-approximates what a later callee can
/// reach on a path where it did not escape, which is sound: the theorem
/// then states that the slot's bytes are equal on both sides at each later
/// call (stronger than such a path needs) and that the call leaves them as
/// free inputs, of which leaving them unchanged is one choice; and more
/// incoming accesses observe (and a store redefines) its bytes under the
/// retention rule, likewise stronger.
///
/// Slice 20 (ruling OD-192): a byte the edges leave differently, one of them
/// holding a stored private address, is DEAD after the join when no path from
/// the join reads it before a store overwrites it (`liveness`, slice 17's one
/// byte liveness): unreadable, so a later read of it refuses (a liveness
/// error only refuses), and the machine's byte there is unreadable too
/// ([`merge_machine`]). Returns the state and the bytes so made dead.
#[allow(clippy::type_complexity)]
fn merge_admitted(
    join: Block,
    incoming: &[Block],
    exits: &HashMap<Block, AdmitState>,
    merges: &mut Vec<SlotMerge>,
    sites: &mut SourceSites,
    region: usize,
    liveness: &JoinLiveness<'_>,
) -> Result<(AdmitState, std::collections::BTreeSet<(u32, i64)>), X86BodyRefusal> {
    let mut dead = std::collections::BTreeSet::new();
    let states: Vec<&AdmitState> = incoming.iter().map(|block| &exits[block]).collect();
    let first = states[0];
    let mut types = HashMap::new();
    let mut frame = HashMap::new();
    let mut indexed = HashMap::new();
    for (value, carrier) in &first.types {
        if states
            .iter()
            .any(|state| state.types.get(value) != Some(carrier))
        {
            continue;
        }
        let addresses: Vec<Option<&FrameAddr>> =
            states.iter().map(|state| state.frame.get(value)).collect();
        match addresses[0] {
            Some(address) if addresses.iter().all(|other| *other == Some(address)) => {
                frame.insert(*value, *address);
            }
            None if addresses.iter().all(Option::is_none) => {}
            _ => continue,
        }
        // Slice 17: an indexed address every edge leaves alike is kept; one
        // the edges leave differently (or indexed on some edges only) is
        // undefined after the join, so a use refuses.
        let offsets: Vec<Option<&IndexedAddr>> = states
            .iter()
            .map(|state| state.indexed.get(value))
            .collect();
        match offsets[0] {
            Some(address) if offsets.iter().all(|other| *other == Some(address)) => {
                indexed.insert(*value, *address);
            }
            None if offsets.iter().all(Option::is_none) => {}
            _ => continue,
        }
        types.insert(*value, *carrier);
    }
    fn agreed<T: Clone + PartialEq>(
        states: &[&AdmitState],
        types: &HashMap<Value, Carrier>,
        field: impl Fn(&AdmitState) -> &HashMap<Value, T>,
    ) -> HashMap<Value, T> {
        field(states[0])
            .iter()
            .filter(|(value, item)| {
                types.contains_key(*value)
                    && states
                        .iter()
                        .all(|state| field(state).get(*value) == Some(*item))
            })
            .map(|(value, item)| (*value, item.clone()))
            .collect()
    }
    let affine = agreed(&states, &types, |state| &state.affine);
    let constants = agreed(&states, &types, |state| &state.constants);
    let aggregates = agreed(&states, &types, |state| &state.aggregates);
    let tainted: HashSet<Value> = states
        .iter()
        .flat_map(|state| state.tainted.iter().copied())
        .collect();
    let tainted_sites: HashSet<usize> = states
        .iter()
        .flat_map(|state| state.tainted_sites.iter().copied())
        .collect();
    let mut slot_bytes = first.slot_bytes.clone();
    for (slot, bytes) in slot_bytes.iter_mut().enumerate() {
        for (offset, merged) in bytes.iter_mut().enumerate() {
            let brought: Vec<Option<SlotByte>> = states
                .iter()
                .map(|state| state.slot_bytes[slot][offset])
                .collect();
            let alike = brought.iter().all(|byte| *byte == brought[0]);
            let resolvable = match brought[0] {
                Some(SlotByte::Stored(byte)) => {
                    types.contains_key(&byte.value) && !frame.contains_key(&byte.value)
                }
                _ => true,
            };
            if alike && resolvable {
                continue;
            }
            // Slice 17: a byte dead on some edge is dead after the join (no
            // path from it reads the byte before overwriting it).
            if brought.contains(&Some(SlotByte::Dead)) {
                *merged = Some(SlotByte::Dead);
                continue;
            }
            let address = FrameAddr {
                slot: slot as u32,
                offset: offset as i64,
            };
            // Slice 13: a stored private address is tracked, never a byte
            // term a join may choose; a join of paths that leave different
            // bytes where one holds an address is outside the domain, unless
            // (slice 20, OD-192) the byte is dead at the join.
            if brought
                .iter()
                .any(|byte| byte.and_then(SlotByte::address).is_some())
            {
                if liveness.dead(join, address) {
                    *merged = Some(SlotByte::Dead);
                    dead.insert((address.slot, address.offset));
                    continue;
                }
                return Err(unsupported(X86BodyUnsupported::SourceDomain(format!(
                    "block {join:?} joins paths that leave {} holding different values, one of \
                     them a private stack address",
                    address.describe()
                ))));
            }
            // An edge that wrote nothing there brings the slot's initial
            // byte, the free input both sides read (slice 6).
            if brought.iter().any(Option::is_none) {
                sites.frame_byte(address);
            }
            // Slice 20 (OD-194): every incoming byte readable as a direct
            // read takes it ([`bool_readable`]).
            let bool_read = brought.iter().all(|byte| bool_readable(*byte));
            let tainted = brought.iter().zip(&states).any(|(byte, state)| {
                byte.is_some_and(|byte| byte.tainted_in(&state.tainted, &state.tainted_sites))
            });
            *merged = Some(SlotByte::Merged {
                id: merges.len(),
                bool_read,
                tainted,
            });
            merges.push(SlotMerge {
                region,
                join,
                address,
                incoming: incoming.iter().copied().zip(brought).collect(),
            });
        }
    }
    // Slice 13: the union of the edges' escaped slots, closed.
    let mut escaped = std::collections::BTreeSet::new();
    escape_source(
        &mut escaped,
        &slot_bytes,
        states
            .iter()
            .flat_map(|state| state.escaped.iter().copied()),
    );
    Ok((
        AdmitState {
            types,
            affine,
            constants,
            frame,
            indexed,
            slot_bytes,
            aggregates,
            tainted_sites,
            escaped,
            tainted,
        },
        dead,
    ))
}

/// A source with loops, admitted over its regions (slice 12): one DAG per
/// cut point, each admitted from the state its cut point assumes
/// ([`LoopHeader`]), the cut edges out of each recorded with the values they
/// give the header they enter ([`CutEdge`]).
struct LoopBody {
    /// One region per cut point, in [`SourceCfg::cut_points`] order: the
    /// entry block's first, then each loop header's (outermost first).
    regions: Vec<Region>,
    /// Each loop header's assumption.
    headers: HashMap<Block, LoopHeader>,
    /// Every merged private byte of every region ([`SlotByte::Merged`] names
    /// its index).
    merges: Vec<SlotMerge>,
    /// Slice 16: for a source stated in parts, each cut point's interface
    /// (every cut point but the entry, loop headers included, by block; then
    /// `headers` is empty). `None` for slice 12's loops.
    cuts: Option<std::collections::BTreeMap<Block, split::CutInterface>>,
    /// Slice 20 (ruling OD-194): every LIR block of a natural loop of the
    /// source: a row outside them runs at most once in a run, so an
    /// undefined-bits input it introduces is fixed for the run
    /// (`split::fixed_undefined`).
    in_loops: std::collections::BTreeSet<Block>,
}

/// One admitted region of a source with loops (slice 12).
struct Region {
    dag: DagBody,
    /// Each cut edge out of the region, by `(block, header)`.
    cuts: RegionCutEdges,
}

/// What the region of loop header `block` assumes at its start (slice 12),
/// which the cut-point relation states at every edge into the header. The
/// region starts from the state the header's one entry edge (from outside
/// its loop) brings, with, as free inputs shared by the two sides:
///
/// - each header parameter (the loop-carried values; a `Copy` on each edge
///   into the header defines it), [`header_value_name`];
/// - each private byte some edge into the header leaves other than the
///   entry edge does (a byte the loop may change), [`header_byte_name`].
///
/// Every other value and byte is the one the entry edge brings, exactly: no
/// edge into the header changes it (a value is defined once; a byte's
/// change makes it a header byte), so it holds at every visit of the header
/// what it held when the loop was entered. The assumption is a fixpoint
/// over every edge into the header ([`admitted_loops`]).
#[derive(Clone)]
struct LoopHeader {
    block: Block,
    /// The header's region (its index in [`LoopBody::regions`]).
    region: usize,
    /// The header's one entry edge from outside its loop: the region and
    /// the block it leaves.
    entry: (usize, Block),
    /// The header's parameters and their carriers, in order.
    params: Vec<(Value, Carrier)>,
    /// The parameters some edge gives a value that may derive from an
    /// escaped slot (slice 7's retention rule).
    tainted: HashSet<Value>,
    /// The bytes the loop may change, by `(slot, offset)`: whether every
    /// edge's byte is one a `bool` read may read, and whether some edge's
    /// may be tainted.
    bytes: std::collections::BTreeMap<(u32, i64), (bool, bool)>,
    /// The slots that escaped on some edge into the header (a call in the
    /// loop may let a slot escape that had not on entry: the header assumes
    /// it escaped, which only makes every call there observe and redefine
    /// its bytes on both sides).
    escaped: std::collections::BTreeSet<u32>,
    /// Slice 17 (ruling OD-184): the bytes DEAD at the header
    /// ([`split::live_bytes`]): left out of its relation and assumptions on
    /// both sides, unreadable in its region ([`SlotByte::Dead`]).
    dead: std::collections::BTreeSet<(u32, i64)>,
}

impl LoopHeader {
    /// The source state at the start of the header's region, from the
    /// state its entry edge brings.
    fn start(&self, entry: &CutEdge) -> AdmitState {
        let mut state = entry.state.clone();
        for (value, carrier) in &self.params {
            state.types.insert(*value, *carrier);
            state.affine.remove(value);
            state.constants.remove(value);
            state.frame.remove(value);
            state.indexed.remove(value);
            state.aggregates.remove(value);
            if self.tainted.contains(value) {
                state.tainted.insert(*value);
            } else {
                state.tainted.remove(value);
            }
        }
        for (&(slot, offset), &(bool_read, tainted)) in &self.bytes {
            state.slot_bytes[slot as usize][offset as usize] = Some(SlotByte::Header {
                header: self.block,
                bool_read,
                tainted,
            });
        }
        // Slice 17: a dead byte starts unreadable.
        for &(slot, offset) in &self.dead {
            state.slot_bytes[slot as usize][offset as usize] = Some(SlotByte::Dead);
        }
        // The slots that escaped on some edge into the header, closed under
        // the addresses the bytes hold (slice 13's transitive rule).
        let mut escaped = std::collections::BTreeSet::new();
        escape_source(
            &mut escaped,
            &state.slot_bytes,
            state
                .escaped
                .iter()
                .chain(&self.escaped)
                .copied()
                .collect::<Vec<_>>(),
        );
        state.escaped = escaped;
        state
    }
}

/// The most rounds [`admitted_loops`] and [`walk_loops`] take to reach their
/// fixpoints: each round only grows an assumption (a header byte, a tainted
/// parameter, an escaped slot, a register a loop writes), so a body that
/// needs more makes no claim.
const MAX_LOOP_ROUNDS: usize = 64;

/// Admit a source with loops over its regions (slice 12). The regions are
/// admitted in cut-point order (each header's entry edge leaves an earlier
/// region), each from its cut point's assumption: the function's entry
/// state, or a loop header's [`LoopHeader::start`]. Then every edge into each
/// header is compared with the header's assumption: a byte some edge leaves
/// differently becomes a header byte, a parameter some edge gives a tainted
/// value tainted, a slot some edge lets escape escaped; and every region is
/// admitted again, until no assumption grows. A loop header entered from
/// more than one edge outside its loop, a parameter that carries an `I128`
/// or a private stack address, or a parameter an edge does not define at its
/// type is outside the domain.
fn admitted_loops(
    source: &Function,
    frame_facts: &SourceFrame,
    cfg: &SourceCfg,
    sites: &mut SourceSites,
) -> Result<LoopBody, X86BodyRefusal> {
    let domain = |reason: String| unsupported(X86BodyUnsupported::SourceDomain(reason));
    let region_cfgs = source_regions(cfg);
    let cuts: HashSet<Block> = region_cfgs.iter().map(|region| region.start).collect();
    let mut headers: HashMap<Block, LoopHeader> = HashMap::new();
    // Slice 17: the private bytes live at each header (the one byte liveness
    // slice 16's cut points use too).
    let live = split::live_bytes(source, cfg);
    let liveness = JoinLiveness::known(source, cfg, live.clone());
    for (index, region) in region_cfgs.iter().enumerate().skip(1) {
        let header = region.start;
        let natural = cfg
            .loops
            .iter()
            .find(|lp| lp.header == header)
            .expect("every region but the first starts at a loop header");
        let entries: Vec<(usize, Block)> = region_cfgs
            .iter()
            .enumerate()
            .flat_map(|(q, other)| {
                other
                    .order
                    .iter()
                    .filter(|block| {
                        !natural.blocks.contains(block) && cfg.successors[block].contains(&header)
                    })
                    .map(move |block| (q, *block))
            })
            .collect();
        let [entry] = entries.as_slice() else {
            return Err(unsupported(X86BodyUnsupported::SourceShape(format!(
                "loop header {header:?} is entered from {} edges outside its loop (the lane \
                 admits one)",
                entries.len()
            ))));
        };
        let mut params = Vec::new();
        for (value, ty) in &source.blocks[&header].params {
            // Slice 20 (ruling OD-193): an `I128` is carried as two 64-bit
            // halves ([`ParamRoot::high`]).
            match Carrier::of(ty) {
                None => {
                    return Err(domain(format!(
                        "loop header {header:?} carries {value:?} of type {ty:?} (a non-scalar \
                         loop-carried value, outside the lane)"
                    )));
                }
                Some(carrier) => params.push((*value, carrier)),
            }
        }
        headers.insert(
            header,
            LoopHeader {
                block: header,
                region: index,
                entry: *entry,
                params,
                tainted: HashSet::new(),
                bytes: std::collections::BTreeMap::new(),
                escaped: std::collections::BTreeSet::new(),
                dead: split::dead_bytes(source, &live, header),
            },
        );
    }
    let base_sites = sites.clone();
    for _ in 0..MAX_LOOP_ROUNDS {
        *sites = base_sites.clone();
        let mut merges = Vec::new();
        let mut regions: Vec<Region> = Vec::with_capacity(region_cfgs.len());
        for (index, region) in region_cfgs.iter().enumerate() {
            let start = match headers.get(&region.start) {
                None => AdmitState::entry(frame_facts),
                Some(header) => {
                    let (q, block) = header.entry;
                    header.start(&regions[q].cuts[&(block, header.block)])
                }
            };
            let view = DagView {
                order: &region.order,
                successors: &region.successors,
                predecessors: &region.predecessors,
            };
            let (dag, cut_edges) = admitted_region(
                source,
                frame_facts,
                view,
                start,
                &cuts,
                sites,
                &mut merges,
                (index, Some(region.start)),
                &liveness,
            )?;
            regions.push(Region {
                dag,
                cuts: cut_edges,
            });
        }
        // Compare every edge into each header with its assumption.
        let mut grown = false;
        let mut header_blocks: Vec<Block> = headers.keys().copied().collect();
        header_blocks.sort_unstable();
        for block in header_blocks {
            let header = headers.get_mut(&block).expect("a header");
            let (q, from) = header.entry;
            let start = header.start(&regions[q].cuts[&(from, block)]);
            let incoming: Vec<&CutEdge> = regions
                .iter()
                .flat_map(|region| region.cuts.iter())
                .filter(|((_, to), _)| *to == block)
                .map(|(_, edge)| edge)
                .collect();
            let mut bytes: std::collections::BTreeMap<(u32, i64), (bool, bool)> =
                std::collections::BTreeMap::new();
            for edge in &incoming {
                for slot in &edge.state.escaped {
                    grown |= header.escaped.insert(*slot);
                }
                for ((param, carrier), value) in header.params.iter().zip(&edge.values) {
                    if edge.state.frame.contains_key(value)
                        || edge.state.indexed.contains_key(value)
                        || edge.state.aggregates.contains_key(value)
                    {
                        return Err(domain(format!(
                            "loop header {block:?} carries {param:?}, which an edge gives a \
                             private stack address (outside the lane)"
                        )));
                    }
                    if edge.state.types.get(value) != Some(carrier) {
                        return Err(domain(format!(
                            "loop header {block:?} parameter {param:?} is not defined at its \
                             type on every edge into it"
                        )));
                    }
                    if edge.state.tainted.contains(value) {
                        grown |= header.tainted.insert(*param);
                    }
                }
                for (slot, slot_bytes) in edge.state.slot_bytes.iter().enumerate() {
                    for (offset, byte) in slot_bytes.iter().enumerate() {
                        let key = (slot as u32, offset as i64);
                        // Slice 17: a byte dead at the header is neither a
                        // header byte nor checked unchanged.
                        if header.dead.contains(&key) {
                            continue;
                        }
                        let assumed = start.slot_bytes[slot][offset];
                        if !header.bytes.contains_key(&key) && *byte == assumed {
                            continue;
                        }
                        // A byte live at the header that an edge leaves dead
                        // (a liveness error): unreadable, no claim.
                        if *byte == Some(SlotByte::Dead) {
                            return Err(domain(format!(
                                "loop header {block:?} is entered on a path that leaves {} \
                                 unreadable, a byte live at the header",
                                FrameAddr {
                                    slot: key.0,
                                    offset: key.1,
                                }
                                .describe()
                            )));
                        }
                        // Slice 13: a stored private address is tracked,
                        // never a free input a header may assume (as a
                        // join's bytes, [`merge_admitted`]).
                        if byte.and_then(SlotByte::address).is_some() {
                            return Err(domain(format!(
                                "loop header {block:?} is entered on paths that leave {} \
                                 holding different values, one of them a private stack address",
                                FrameAddr {
                                    slot: key.0,
                                    offset: key.1,
                                }
                                .describe()
                            )));
                        }
                        // Slice 20 (OD-194): as a direct read takes it.
                        let readable = bool_readable(*byte);
                        let tainted = byte.is_some_and(|byte| {
                            byte.tainted_in(&edge.state.tainted, &edge.state.tainted_sites)
                        });
                        let entry = bytes.entry(key).or_insert((true, false));
                        entry.0 &= readable;
                        entry.1 |= tainted;
                    }
                }
            }
            // A byte the entry edge leaves unwritten is the slot's initial
            // byte on the first visit (the free input both sides read).
            for key in bytes.keys() {
                if start.slot_bytes[key.0 as usize][key.1 as usize].is_none()
                    || incoming
                        .iter()
                        .any(|edge| edge.state.slot_bytes[key.0 as usize][key.1 as usize].is_none())
                {
                    sites.frame_byte(FrameAddr {
                        slot: key.0,
                        offset: key.1,
                    });
                }
            }
            // Every byte some edge changes is a header byte, with the
            // attributes of every edge's byte there (the header's own byte
            // on an edge that leaves it is the assumption's: the attributes
            // only fall or rise once).
            let mut all = bytes.clone();
            for key in header.bytes.keys() {
                all.entry(*key).or_insert((true, false));
            }
            if all != header.bytes {
                header.bytes = all;
                grown = true;
            }
        }
        if !grown {
            return Ok(LoopBody {
                regions,
                headers,
                merges,
                cuts: None,
                in_loops: cfg
                    .loops
                    .iter()
                    .flat_map(|lp| lp.blocks.iter().copied())
                    .collect(),
            });
        }
    }
    Err(unsupported(X86BodyUnsupported::SourceShape(format!(
        "the loop headers' assumptions do not reach a fixpoint in {MAX_LOOP_ROUNDS} rounds"
    ))))
}

/// Whether `cond` orders its operands as signed integers.
fn signed_order(cond: IntCC) -> bool {
    matches!(
        cond,
        IntCC::SignedLessThan
            | IntCC::SignedLessThanOrEqual
            | IntCC::SignedGreaterThan
            | IntCC::SignedGreaterThanOrEqual
    )
}

/// Exact LIR `Icmp` semantics: whether `cond` holds of `lhs` and `rhs` (two
/// terms of the operands' carrier width), as an SMT Boolean.
fn compare_holds(cond: IntCC, lhs: E, rhs: E) -> E {
    match cond {
        IntCC::Equal => lhs.eq_expr(rhs),
        IntCC::NotEqual => lhs.eq_expr(rhs).not_expr(),
        IntCC::SignedLessThan => lhs.bvslt(rhs),
        IntCC::SignedLessThanOrEqual => lhs.bvsle(rhs),
        IntCC::SignedGreaterThan => lhs.bvsgt(rhs),
        IntCC::SignedGreaterThanOrEqual => lhs.bvsge(rhs),
        IntCC::UnsignedLessThan => lhs.bvult(rhs),
        IntCC::UnsignedLessThanOrEqual => lhs.bvule(rhs),
        IntCC::UnsignedGreaterThan => lhs.bvugt(rhs),
        IntCC::UnsignedGreaterThanOrEqual => lhs.bvuge(rhs),
    }
}

/// The value of a source operation all of whose operands are constants of
/// the chain, at `ty`'s width, or `None`. Exact LIR semantics: wrapping
/// arithmetic, logical and in-range constant shifts, extensions, truncation
/// and copies.
fn fold_constant(op: &SourceOp, ty: Carrier, constants: &HashMap<Value, u64>) -> Option<u64> {
    // Slice 11: no constant of an `I128` (beyond its `Iconst`, recorded when
    // it fits 64 bits) or of a float bit pattern is derived; none is needed
    // for an address or a shift amount.
    if !ty.is_word() {
        return None;
    }
    let mask = ty.mask();
    let value = match op {
        SourceOp::Const(bits) => *bits,
        SourceOp::Copy(v) => *constants.get(v)?,
        SourceOp::Binary(op, a, b) => {
            let (a, b) = (*constants.get(a)?, *constants.get(b)?);
            match op {
                BinaryOp::Add => a.wrapping_add(b),
                BinaryOp::Sub => a.wrapping_sub(b),
                BinaryOp::Mul => a.wrapping_mul(b),
                BinaryOp::And => a & b,
                BinaryOp::Or => a | b,
                BinaryOp::Xor => a ^ b,
            }
        }
        SourceOp::Shift(op, v, amount) => {
            let v = *constants.get(v)?;
            match op {
                ShiftOp::Shl => v << amount,
                ShiftOp::Lshr => (v & mask) >> amount,
                // Arithmetic shifts of constants are not needed for
                // addresses; no constant is derived.
                ShiftOp::Ashr => return None,
            }
        }
        SourceOp::Extend {
            signed: false,
            value,
        }
        | SourceOp::Trunc(value) => *constants.get(value)?,
        SourceOp::Offset(base, offset) => constants.get(base)?.wrapping_add(*offset),
        SourceOp::ArrayElement {
            base,
            index,
            stride,
        } => constants
            .get(base)?
            .wrapping_add(constants.get(index)?.wrapping_mul(*stride)),
        // Slice 10: no constant is derived from these (none is needed for an
        // address or a shift amount).
        SourceOp::Extend { signed: true, .. }
        | SourceOp::Wide { .. }
        | SourceOp::WideLoad(..)
        | SourceOp::Overflow { .. }
        | SourceOp::VariableShift(..)
        | SourceOp::Not(_)
        | SourceOp::Neg(_)
        | SourceOp::Popcount(_)
        | SourceOp::FloatSign(..)
        // Slice 21: nor from a floating-point operation.
        | SourceOp::FloatEvent(_)
        | SourceOp::FloatToInt { .. }
        | SourceOp::FloatCompare { .. }
        | SourceOp::CallResult(..)
        | SourceOp::Symbol(_)
        | SourceOp::Compare { .. }
        | SourceOp::Select { .. }
        | SourceOp::MemoryLoad(_)
        | SourceOp::StackBytes(_)
        | SourceOp::IndexedLoad { .. }
        // Slice 14: nor from a division (which may be undefined).
        | SourceOp::Divide { .. } => return None,
    };
    Some(value & mask)
}

/// Byte offsets of a `carrier`-typed access at `address` inside its slot, or
/// `None` when any byte lies outside the slot.
fn stack_bytes(
    address: &FrameAddr,
    carrier: Carrier,
    slot_sizes: &[u32],
) -> Option<std::ops::Range<usize>> {
    stack_range(address, carrier.bytes(), slot_sizes)
}

/// Byte offsets of a `bytes`-wide access at `address` inside its slot.
fn stack_range(
    address: &FrameAddr,
    bytes: u32,
    slot_sizes: &[u32],
) -> Option<std::ops::Range<usize>> {
    let size = i64::from(*slot_sizes.get(address.slot as usize)?);
    let end = address.offset.checked_add(i64::from(bytes))?;
    (address.offset >= 0 && end <= size).then_some(address.offset as usize..end as usize)
}

/// `(size, align)` of a LIR type under the C layout LIR `StructGep` indexes
/// (x86-64 System V sizes and alignments; an `i128` is 16-byte aligned).
/// Verify-owned: it does not call the selector's `Type::offset_of`, so a
/// layout bug the two shared would not self-attest. `None` for a type outside
/// the model (an enum).
fn layout(ty: &Type) -> Option<(u64, u64)> {
    Some(match ty {
        Type::B1 | Type::I8 => (1, 1),
        Type::I16 | Type::F16 => (2, 2),
        Type::I32 | Type::F32 => (4, 4),
        Type::I64 | Type::F64 | Type::V64 => (8, 8),
        Type::I128 | Type::V128 => (16, 16),
        Type::Struct(fields) => {
            let (mut end, mut align) = (0u64, 1u64);
            for field in fields {
                let (size, field_align) = layout(field)?;
                end = end
                    .checked_next_multiple_of(field_align)?
                    .checked_add(size)?;
                align = align.max(field_align);
            }
            (end.checked_next_multiple_of(align)?, align)
        }
        // Elements are packed at their size (which includes a struct
        // element's tail padding).
        Type::Array(element, count) => {
            let (size, align) = layout(element)?;
            (size.checked_mul(u64::from(*count))?, align)
        }
        _ => return None,
    })
}

/// The byte stride of LIR `ArrayGep { elem_ty }` (OD-185): the element's
/// natural-C size under the verify-owned layout ([`layout`]). That is the
/// opcode's one meaning: it carries a repr-less LIR element type, and the
/// selector resolves it only as `elem_ty.bytes()` (`select_array_gep`); the
/// adapter writes any other stride out as `Iadd`/`Imul`
/// (`emit_array_element_ptr`). A unit test compares this with the
/// selector's `Type::bytes`. `None` outside the layout model (an enum) and
/// for a zero-sized element, which the selector refuses.
fn array_element_stride(elem_ty: &Type) -> Option<u64> {
    layout(elem_ty)
        .map(|(size, _)| size)
        .filter(|size| *size != 0)
}

/// The offset of element `index` at `stride` bytes per element, at 64 bits,
/// wrapping (OD-185): the index itself at stride 1, as `lea [b + i]` states
/// it, else its product with the stride, as the scaled `lea` and `imul`
/// state it.
fn array_element_offset(index: E, stride: u64) -> E {
    if stride == 1 {
        index
    } else {
        index.bvmul(E::bv_const(stride, 64))
    }
}

/// The address LIR `ArrayGep` computes (OD-185): `base + index * stride` at
/// 64 bits, wrapping ([`array_element_offset`]). At a stride of 3, 5 or 9 it
/// is spelled `(base + index * (stride - 1)) + index`, the selector's own
/// `lea; add` (`select_array_gep`): the same value by distributivity in
/// `Z/2^64` (a unit test sweeps it), and the spelling host qualification
/// certifies (the product form timed out at 30 s on AY build 12713). One
/// spelling per stride, never chosen per function.
fn array_element_address(base: E, index: E, stride: u64) -> E {
    if matches!(stride, 3 | 5 | 9) {
        return base
            .bvadd(array_element_offset(index.clone(), stride - 1))
            .bvadd(index);
    }
    base.bvadd(array_element_offset(index, stride))
}

/// The index of a scaled-index address over a private stack address: a
/// 64-bit constant the walk knows (OD-185), or the index's term (slice 17).
enum SibIndex {
    Constant(u64),
    Term(E),
}

/// The private stack address `address + index*scale + disp`, the one the
/// `LeaSib` walk writes and a scaled-index access (slice 25) reaches: at a
/// constant index `k` (OD-185) the address offset by the exact integer
/// `k*scale + disp`; at any other index (slice 17) the indexed address whose
/// offset adds the scaled index term ([`array_element_offset`]), then the
/// displacement. `None`: an offset overflows `i64`.
fn sib_private(
    address: MachinePrivate,
    index: SibIndex,
    scale: u8,
    disp: i32,
) -> Option<MachinePrivate> {
    match index {
        SibIndex::Constant(k) => (k as i64)
            .checked_mul(i64::from(scale))
            .and_then(|delta| delta.checked_add(i64::from(disp)))
            .and_then(|delta| address.offset_by(delta)),
        SibIndex::Term(index) => address
            .indexed_by(array_element_offset(index, u64::from(scale)))
            .offset_by(i64::from(disp)),
    }
}

/// The effective address `base + index*scale + sext(disp)` mod 2^64 of a
/// scaled-index operand (Intel SDM Vol. 2A §2.1.5) over two 64-bit values,
/// with its affine value: the one `LeaSib` writes and a scaled-index access
/// (slice 25) reaches. `base + index*scale` is [`array_element_address`]'s
/// one spelling (the `*1` omitted), then `+ disp` when it is not zero. The
/// affine value is kept at scale 1, and (OD-185) at a constant index, whose
/// product is a constant.
fn sib_bits(
    base: (E, Option<Affine>),
    index: (E, Option<Affine>),
    scale: u8,
    disp: i32,
) -> (E, Option<Affine>) {
    let (base, base_affine) = base;
    let (index, index_affine) = index;
    let disp = i64::from(disp) as u64;
    let scale = u64::from(scale);
    let mut affine = if scale == 1 {
        base_affine
            .zip(index_affine)
            .map(|(a, b)| a.combine(b, false, u64::MAX))
    } else {
        base_affine
            .zip(index_affine.and_then(Affine::as_constant))
            .map(|(a, k)| {
                let offset = Affine::constant(k.wrapping_mul(scale), u64::MAX);
                a.combine(offset, false, u64::MAX)
            })
    };
    let mut expr = array_element_address(base, index, scale);
    if disp != 0 {
        expr = expr.bvadd(E::bv_const(disp, 64));
        affine = affine.map(|a| a.combine(Affine::constant(disp, u64::MAX), false, u64::MAX));
    }
    (expr, affine)
}

/// The address `[base + disp]` through a register that holds bits (slice
/// 4), with its affine value: the register's value itself at displacement
/// 0, else that value plus the sign-extended displacement.
fn base_disp_bits(base: Slot, disp: i64) -> (E, Option<Affine>) {
    let delta = disp as u64;
    if delta == 0 {
        (base.expr, base.affine)
    } else {
        (
            base.expr.bvadd(E::bv_const(delta, 64)),
            base.affine
                .map(|a| a.combine(Affine::constant(delta, u64::MAX), false, u64::MAX)),
        )
    }
}

/// Byte offset of field `index` of a `StructGep`'s struct or array type.
fn field_offset(ty: &Type, index: u32) -> Option<u64> {
    match ty {
        Type::Struct(fields) => {
            let mut end = 0u64;
            for (i, field) in fields.iter().enumerate() {
                let (size, align) = layout(field)?;
                let offset = end.checked_next_multiple_of(align)?;
                if i == index as usize {
                    return Some(offset);
                }
                end = offset.checked_add(size)?;
            }
            None
        }
        Type::Array(element, count) if index < *count => {
            layout(element)?.0.checked_mul(u64::from(index))
        }
        _ => None,
    }
}

/// One System V INTEGER eightbyte of a register-passed aggregate (slice 8):
/// the aggregate's bytes `offset .. offset + bytes` travel in the low `bytes`
/// bytes of one general-purpose register (psABI §3.2.3). Every eightbyte but
/// the last is full (8 bytes).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct Eightbyte {
    offset: u32,
    bytes: u32,
}

impl Eightbyte {
    /// Bits of its register the value occupies: the bits a callee or caller
    /// may read. The bits above are not the aggregate's (System V leaves them
    /// unspecified).
    fn bits(self) -> u32 {
        self.bytes * 8
    }

    /// Bits of the register the call row's metadata declares for this lane:
    /// the register width that holds `bytes` bytes (1 -> 8, 2 -> 16, 3 or 4
    /// -> 32, else 64). Metadata only (register allocation and TV-5 read it);
    /// the theorem observes [`Self::bits`].
    fn register_bits(self) -> u32 {
        match self.bytes {
            1 => 8,
            2 => 16,
            3 | 4 => 32,
            _ => 64,
        }
    }
}

/// An aggregate the lane passes or returns by value in general-purpose
/// registers (slice 8), with its System V classification.
#[derive(Debug, Clone, PartialEq, Eq)]
struct Aggregate {
    ty: Type,
    size: u32,
    align: u32,
    lanes: Vec<Eightbyte>,
}

/// The System V AMD64 classification of a by-value aggregate (psABI §3.2.3),
/// verify-owned: it does not call the selector's classifier, so a
/// classification bug the two shared would not self-attest (a unit test
/// compares the two through the real selector's output). Admitted exactly
/// when the aggregate is a `Struct` or `Array` of 1 to 16 bytes under the
/// verify-owned C layout ([`layout`]) whose every leaf is a `B1`, `I8`,
/// `I16`, `I32` or `I64` field lying wholly inside one eightbyte, and every
/// eightbyte holds a field: then each eightbyte is INTEGER and travels in one
/// general-purpose register. Anything else is refused by name: an enum (the
/// selector classifies no enum), MEMORY class (over 16 bytes, passed on the
/// stack or through a hidden buffer), an SSE eightbyte (a floating-point
/// field), an `I128` or vector field, or an eightbyte with no field.
fn classify_aggregate(ty: &Type) -> Result<Aggregate, String> {
    fn leaves(ty: &Type, base: u64, eightbytes: &mut [bool; 2]) -> Result<(), String> {
        match ty {
            Type::Struct(fields) => {
                for (index, field) in fields.iter().enumerate() {
                    let offset = field_offset(ty, index as u32)
                        .ok_or_else(|| "a field outside the layout model".to_owned())?;
                    leaves(field, base + offset, eightbytes)?;
                }
                Ok(())
            }
            Type::Array(element, count) => {
                let (size, _) =
                    layout(element).ok_or_else(|| "a field outside the layout model".to_owned())?;
                for index in 0..u64::from(*count) {
                    leaves(element, base + size * index, eightbytes)?;
                }
                Ok(())
            }
            Type::B1 | Type::I8 | Type::I16 | Type::I32 | Type::I64 => {
                let size = u64::from(Carrier::of(ty).expect("an integer leaf").bytes());
                let end = base + size;
                if end > 16 || base / 8 != (end - 1) / 8 {
                    return Err("a field that straddles an eightbyte".into());
                }
                eightbytes[(base / 8) as usize] = true;
                Ok(())
            }
            // Slice 11: an `I128` field occupies two whole INTEGER
            // eightbytes (psABI §3.2.3 classifies `__int128` as a struct of
            // two longs), so it must start an aggregate of 16 bytes.
            Type::I128 => {
                if base != 0 {
                    return Err("an i128 field that does not fill both eightbytes".into());
                }
                *eightbytes = [true, true];
                Ok(())
            }
            Type::F16 | Type::F32 | Type::F64 => {
                Err("an SSE eightbyte (a floating-point field)".into())
            }
            Type::V64 | Type::V128 => Err("a vector field".into()),
            Type::Enum { .. } => Err("an enum field".into()),
        }
    }
    if matches!(ty, Type::Enum { .. }) {
        return Err("an enum (the selector classifies no enum)".into());
    }
    if !matches!(ty, Type::Struct(_) | Type::Array(..)) {
        return Err("not an aggregate".into());
    }
    let (size, align) = layout(ty).ok_or_else(|| "a field outside the layout model".to_owned())?;
    if size == 0 {
        return Err("an empty aggregate".into());
    }
    if size > 16 {
        return Err("over 16 bytes (MEMORY class)".into());
    }
    let mut eightbytes = [false; 2];
    leaves(ty, 0, &mut eightbytes)?;
    let size = size as u32;
    let lanes: Vec<Eightbyte> = (0..size.div_ceil(8))
        .map(|k| Eightbyte {
            offset: 8 * k,
            bytes: (size - 8 * k).min(8),
        })
        .collect();
    if lanes
        .iter()
        .any(|lane| !eightbytes[(lane.offset / 8) as usize])
    {
        return Err("an eightbyte with no field".into());
    }
    Ok(Aggregate {
        ty: ty.clone(),
        size,
        align: align as u32,
        lanes,
    })
}

/// The one store whose bytes `read` are, whole and in order, if there is one:
/// then reading them back is that stored value itself.
fn whole_store(read: &[SourceByte]) -> Option<(Value, Carrier)> {
    let first = read.first()?;
    (first.carrier.bytes() as usize == read.len()
        && read.iter().enumerate().all(|(i, byte)| {
            byte.value == first.value && byte.carrier == first.carrier && byte.byte == i as u32
        }))
    .then_some((first.value, first.carrier))
}

/// Whether a LIR load or store is an atomic access the lane admits (slice
/// 13, ruling OD-83 in `docs/decision-record.md`), or why it is outside the
/// domain. trust-ir's reference semantics is single-threaded
/// (`interpret`: with one thread every memory ordering collapses to
/// sequential consistency, so an atomic access is its plain-memory
/// counterpart), and the theorem states exactly that: an admitted atomic
/// access is the plain access of the same bytes of incoming memory, paired
/// only with one machine access of the same width that carries the
/// selector's atomic origin (one `mov`, never split). What the ordering
/// means between threads, and that x86-TSO gives a plain `mov` the ordering
/// it needs, is not this theorem's claim. Admitted: an `AtomicLoad` of any
/// ordering a load may have (`Relaxed`, `Acquire`, `SeqCst`) and a `Relaxed`
/// or `Release` `AtomicStore`, of a `B1`/`I8`/`I16`/`I32`/`I64` through a
/// non-private address. A `SeqCst` `AtomicStore` stays outside by name: the
/// x86 selector lowers it to a plain `mov`, which x86-TSO may reorder with a
/// later load (the bridge emits a sequentially consistent store as an
/// exchange, `AtomicRmw Xchg`, instead). Read-modify-write, compare-exchange,
/// fences, `I128` and private-slot atomics stay outside. Slice 21 (ruling
/// OD-201): an `I128` `AtomicLoad` is admitted, paired only with the
/// selector's `AtomicLoadCmpxchg16b` pseudo row ([`AtomicPseudo`]); an
/// `AtomicRmw { op: Xchg }` is admitted by its own arm in [`admit_blocks`].
fn atomic_access(opcode: &L, carrier: Carrier, private: bool) -> Result<bool, &'static str> {
    use trust_cg_lower::instructions::AtomicOrdering as Ordering;
    match opcode {
        L::AtomicLoad { ordering, .. } => {
            if !matches!(
                ordering,
                Ordering::Relaxed | Ordering::Acquire | Ordering::SeqCst
            ) {
                return Err("is an atomic load with an ordering a load cannot have");
            }
        }
        L::AtomicStore { ordering, .. } => match ordering {
            Ordering::Relaxed | Ordering::Release => {}
            Ordering::SeqCst => {
                return Err(
                    "is a sequentially consistent atomic store (the x86 selector lowers it to a \
                     plain mov, which x86-TSO may reorder with a later load; OD-83)",
                );
            }
            _ => return Err("is an atomic store with an ordering a store cannot have"),
        },
        _ => return Ok(false),
    }
    // Slice 21 (ruling OD-201): an `I128` atomic load is the selector's
    // `AtomicLoadCmpxchg16b` pseudo row, paired as one row with both halves.
    // An `I128` atomic store and a float atomic stay outside.
    let wide_load = carrier == Carrier::I128 && matches!(opcode, L::AtomicLoad { .. });
    if !carrier.is_word() && !wide_load {
        return Err("is an atomic access of an i128 store or a float");
    }
    if private {
        return Err("is an atomic access of a private stack slot");
    }
    Ok(true)
}

/// Let `slots` escape (slice 13): each of them, and every slot whose address
/// an escaped slot's bytes hold as data ([`SlotByte::Address`]), transitively.
/// Whoever can read an escaped slot can follow an address stored in it, so
/// the slot that address names is shared from then on too. A slot that had
/// escaped already took along the addresses it held then, and an address
/// stored into it later escapes at that store.
fn escape_source(
    escaped: &mut std::collections::BTreeSet<u32>,
    slot_bytes: &[Vec<Option<SlotByte>>],
    slots: impl IntoIterator<Item = u32>,
) {
    let mut pending: Vec<u32> = slots.into_iter().collect();
    while let Some(slot) = pending.pop() {
        if escaped.insert(slot) {
            pending.extend(
                slot_bytes[slot as usize]
                    .iter()
                    .filter_map(|byte| byte.and_then(SlotByte::address))
                    .map(|address| address.slot),
            );
        }
    }
}

/// The contents of every escaped slot now, ascending by slot, each byte
/// nothing wrote registered as the slot's initial byte `f{k}`: what a call
/// reads (slice 7), and (slice 15) an access through an address that may
/// derive from an escaped slot.
fn escaped_slot_reads(
    escaped: &std::collections::BTreeSet<u32>,
    slot_bytes: &[Vec<Option<SlotByte>>],
    sites: &mut SourceSites,
) -> Result<EscapedSlotReads, &'static str> {
    let reads: EscapedSlotReads = escaped
        .iter()
        .map(|slot| (*slot, slot_bytes[*slot as usize].clone()))
        .collect();
    // Slice 17: an escaped slot's byte is read here; a dead one is unreadable.
    if reads
        .iter()
        .any(|(_, bytes)| bytes.contains(&Some(SlotByte::Dead)))
    {
        return Err(
            "observes an escaped slot's private stack byte its cut point leaves out as dead",
        );
    }
    for (slot, bytes) in &reads {
        for (offset, byte) in bytes.iter().enumerate() {
            if byte.is_none() {
                sites.frame_byte(FrameAddr {
                    slot: *slot,
                    offset: offset as i64,
                });
            }
        }
    }
    Ok(reads)
}

/// The machine's [`escape_source`] over its own private bytes (slice 13).
fn escape_machine(
    escaped: &mut std::collections::BTreeSet<u32>,
    stack: &[Vec<Option<MachineByte>>],
    slots: impl IntoIterator<Item = u32>,
) {
    let mut pending: Vec<u32> = slots.into_iter().collect();
    while let Some(slot) = pending.pop() {
        if escaped.insert(slot) {
            pending.extend(
                stack[slot as usize]
                    .iter()
                    .filter_map(|byte| byte.as_ref().and_then(|byte| byte.frame))
                    .map(|address| address.slot),
            );
        }
    }
}

/// The free input naming the address of private stack slot `slot` (slice
/// 13): one 64-bit input per slot, shared by the source and every walk (the
/// slot binding by index makes it the same slot on both sides). The theorem
/// assumes nothing about it (no alignment, no distinctness from another slot
/// or from incoming memory): it appears only as DATA, a stored or observed
/// address, never as an access's address, which the walks resolve without
/// the solver.
fn slot_address_name(slot: u32) -> String {
    format!("slot{slot}")
}

/// The slot a [`slot_address_name`] names.
fn parse_slot_address_name(name: &str) -> Option<u32> {
    let digits = name.strip_prefix("slot")?;
    (!digits.is_empty() && digits.bytes().all(|b| b.is_ascii_digit()))
        .then(|| digits.parse().ok())
        .flatten()
}

/// The 64-bit term of private stack address `address` as data (slice 13):
/// its slot's address plus its offset, wrapping.
fn frame_address_term(address: FrameAddr) -> E {
    let base = E::var(slot_address_name(address.slot), 64);
    match address.offset {
        0 => base,
        offset => base.bvadd(E::bv_const(offset as u64, 64)),
    }
}

/// The address a chunk of slot bytes is, when it is exactly the eight bytes
/// of one stored private address in order (slice 13).
fn whole_address(part: &[Option<SlotByte>]) -> Option<FrameAddr> {
    let address = part.first()?.and_then(SlotByte::address)?;
    (part.len() == 8
        && part.iter().enumerate().all(|(i, byte)| {
            *byte
                == Some(SlotByte::Address {
                    address,
                    byte: i as u32,
                })
        }))
    .then_some(address)
}

/// The value a chunk of source slot bytes is, when it is exactly one store's
/// bytes in order: that store's value at its memory width (slice 7), or
/// (slice 13) a stored private address's term.
fn source_whole_store(part: &[Option<SlotByte>], value: &dyn Fn(&Value) -> E) -> Option<E> {
    if let Some(address) = whole_address(part) {
        return Some(frame_address_term(address));
    }
    let stored: Vec<SourceByte> = part
        .iter()
        .map(|byte| byte.and_then(SlotByte::stored))
        .collect::<Option<_>>()?;
    let (stored_value, carrier) = whole_store(&stored)?;
    Some(carrier.memory_value(value(&stored_value)))
}

// ---------------------------------------------------------------------------
// Machine skeleton (control only)
// ---------------------------------------------------------------------------

/// One owned machine row in chain (execution) order.
#[derive(Clone, Copy)]
struct Row<'m> {
    ordinal: usize,
    block: Block,
    inst: &'m X86ISelInst,
}

/// The laid-out machine body with its control structure validated block by
/// block ([`machine_skeleton`]); [`machine_path`] pairs it with each source
/// path.
struct MachineCfg<'m> {
    machine: &'m X86ISelFunction,
    /// Walk ordinal of each laid-out block's first row.
    ordinals: HashMap<Block, usize>,
    /// Whether any row is a conditional jump.
    has_jcc: bool,
    /// The one-to-one correspondence of machine and LIR blocks
    /// ([`block_correspondence`]), or why there is none.
    correspondence: Result<Correspondence, String>,
}

/// Which machine block lowers which LIR block (slice 6), found from the
/// rows' TV-1 lowering provenance, never from block ids: optimizer passes at
/// O1+ renumber, merge and delete blocks (`renumber_blocks_contiguous` maps
/// the surviving blocks to `0..n`), so an id names no LIR block reliably,
/// while each row keeps the stamp of the LIR instruction it lowers wherever a
/// pass moves it.
struct Correspondence {
    /// LIR block -> the machine block that lowers it.
    lowering: HashMap<Block, Block>,
    /// Machine block -> the LIR block it lowers.
    origin: HashMap<Block, Block>,
    /// Slice 14: each jump-table dispatch block ([`dispatch_blocks`]) -> the
    /// machine block whose final `jmp` reaches it (the lowering of the LIR
    /// block whose `Switch` it dispatches). It lowers no LIR block of its
    /// own: a route through it is a route of its owner ([`block_routes`]).
    /// Slice 20 (ruling OD-191): likewise each block of the selector's binary
    /// search over a `Switch` ([`search_blocks`]) -> the machine block that
    /// lowers the `Switch`'s LIR block.
    dispatch: HashMap<Block, Block>,
    /// Slice 20: the dispatch blocks that are binary-search blocks (the
    /// others are jump-table dispatch blocks).
    search: HashSet<Block>,
    /// Slice 24c (ruling OD-228): the checked segments the correspondence is
    /// stated over ([`block_correspondence_over`]); none for every other
    /// pair. A segment's machine block is `lowering` of its head only.
    segments: segment::Segments,
}

impl Correspondence {
    /// Slice 24c: the machine block whose rows lower `lir`: its own, or (a
    /// segment member) its segment's. No production path reads it: every
    /// stamp search (the plan's and the pieces' stamped rows, the loop and
    /// cut pairings) reads `lowering`, so a copy that runs inside a segment
    /// makes no claim. Only the test seam's two mutants
    /// (`s24c-member-rewalk`, `s24c-cut-pairing-machine-of`) substitute it for
    /// `lowering`, to show what reading a member through its segment's
    /// machine block would state.
    fn machine_of(&self, lir: Block) -> Option<Block> {
        self.lowering
            .get(&lir)
            .copied()
            .or_else(|| self.segments.of_member(lir).map(|segment| segment.machine))
    }
}

/// Slice 14: every machine block that is the selector's jump-table dispatch
/// (`emit_x86_jump_table`), with its table: exactly the four rows `lea b,
/// [rip + table]`, `mov e, [b + n*8]`, `add e, b` (tied, or `add t, e, b`)
/// and `jmp e`/`jmp t`, each over 64-bit registers, the table one of the
/// function's, its recorded successors exactly the table's distinct targets.
/// No other indirect jump, scaled-index load of a table or table address is
/// admitted.
fn dispatch_blocks(machine: &X86ISelFunction) -> HashMap<Block, u32> {
    let mut dispatch = HashMap::new();
    for (block, body) in &machine.blocks {
        let [lea, load, add, jump] = body.insts.as_slice() else {
            continue;
        };
        let (
            [base, O::JumpTableIndex(table)],
            [
                entry,
                O::SibMemAddr {
                    base: load_base,
                    index,
                    scale: 8,
                    disp: 0,
                },
            ],
            [jump_target],
        ) = (
            lea.operands.as_slice(),
            load.operands.as_slice(),
            jump.operands.as_slice(),
        )
        else {
            continue;
        };
        let added = match add.operands.as_slice() {
            [sum, addend] if sum == entry && addend == base => Some(sum),
            [sum, augend, addend] if augend == entry && addend == base => Some(sum),
            _ => None,
        };
        let Some(targets) = machine.jump_tables.get(*table as usize).map(|t| &t.targets) else {
            continue;
        };
        let mut distinct: Vec<Block> = targets.clone();
        distinct.sort();
        distinct.dedup();
        let mut recorded = body.successors.clone();
        recorded.sort();
        if lea.opcode == X86Opcode::LeaRip
            && load.opcode == X86Opcode::MovRMSib
            && add.opcode == X86Opcode::AddRR
            && jump.opcode == X86Opcode::JmpR
            && added == Some(jump_target)
            && load_base.as_ref() == base
            && [base, entry, index.as_ref(), jump_target]
                .iter()
                .all(|operand| gpr64(operand).is_some())
            && recorded == distinct
        {
            dispatch.insert(*block, *table);
        }
    }
    dispatch
}

/// Slice 20 (ruling OD-191): the machine blocks of the selector's balanced
/// binary search over a `Switch` (`emit_switch_bst`), each with the LIR block
/// whose `Switch` it dispatches. For each live LIR block `B` that ends in a
/// `Switch`, `B`'s machine blocks are the laid-out blocks whose
/// source-attributed rows all name `B` (the block that lowers `B`, and its
/// search blocks); a SEARCH block of `B` is one of them, not the machine's
/// first block nor a jump-table dispatch block, every row of which is
/// stamped with that `Switch` itself, made only of `cmp r, imm` and `jcc`
/// rows ended by one `jmp`, and every predecessor of which is another of
/// `B`'s machine blocks. The block that lowers `B` is reached from another LIR
/// block's machine block (or is the machine's first block), so it is never
/// one. The recognizer only CHOOSES which blocks a route of `B` walks through
/// ([`block_routes`]): every compare and branch of a route is walked with its
/// Intel SDM meaning and the theorem judges the conditions under which the
/// machine takes it, so a wrong search (a case under the wrong half, a target
/// swapped, an order that sends a case elsewhere) is refuted, never
/// credited; a block it misses breaks the correspondence (no claim).
fn search_blocks(
    source: &Function,
    machine: &X86ISelFunction,
    dead: &std::collections::BTreeSet<Block>,
    tables: &HashMap<Block, u32>,
) -> HashMap<Block, Block> {
    // Each laid-out block's one LIR block, when its stamped rows name one.
    let mut named: HashMap<Block, Block> = HashMap::new();
    for block in &machine.block_order {
        let mut lir = machine.blocks[block]
            .insts
            .iter()
            .filter_map(|inst| inst.lowering_provenance.source_id())
            .map(|id| Block(id.block));
        if let Some(first) = lir.next()
            && lir.all(|other| other == first)
        {
            named.insert(*block, first);
        }
    }
    let mut predecessors: HashMap<Block, Vec<Block>> = HashMap::new();
    for block in &machine.block_order {
        for successor in &machine.blocks[block].successors {
            predecessors.entry(*successor).or_default().push(*block);
        }
    }
    let mut search = HashMap::new();
    let mut switches: Vec<(&Block, &trust_cg_lower::function::BasicBlock)> = source
        .blocks
        .iter()
        .filter(|(block, body)| {
            !dead.contains(*block)
                && matches!(
                    body.instructions.last().map(|inst| &inst.opcode),
                    Some(L::Switch { .. })
                )
        })
        .collect();
    switches.sort_by_key(|(block, _)| **block);
    for (lir, body) in switches {
        let stamp = trust_cg_ir::provenance::SourceInstId {
            block: lir.0,
            index: (body.instructions.len() - 1) as u32,
        };
        let mine: HashSet<Block> = named
            .iter()
            .filter(|(_, named)| *named == lir)
            .map(|(block, _)| *block)
            .collect();
        for block in &machine.block_order {
            if !mine.contains(block)
                || *block == machine.block_order[0]
                || tables.contains_key(block)
            {
                continue;
            }
            let insts = &machine.blocks[block].insts;
            let Some((last, tree)) = insts.split_last() else {
                continue;
            };
            let shaped = last.opcode == X86Opcode::Jmp
                && tree.iter().all(|inst| match inst.opcode {
                    X86Opcode::CmpRI => matches!(
                        inst.operands.as_slice(),
                        [register, O::Imm(_)] if gpr(register).is_some()
                    ),
                    X86Opcode::Jcc => true,
                    _ => false,
                })
                && insts
                    .iter()
                    .all(|inst| inst.lowering_provenance.source_id() == Some(stamp));
            let reached = predecessors.get(block).is_some_and(|from| {
                !from.is_empty() && from.iter().all(|from| mine.contains(from) && from != block)
            });
            if shaped && reached {
                search.insert(*block, *lir);
            }
        }
    }
    search
}

/// One row of a machine path: a `jcc` records whether the path takes it.
#[derive(Clone, Copy)]
struct PathRow<'m> {
    row: Row<'m>,
    taken: Option<bool>,
    /// Slice 14: at an indirect `jmp` through a jump table, the machine block
    /// the route continues to ([`block_routes`]); `None` at any other row.
    jump: Option<Block>,
}

/// A GPR root named by an operand: a virtual register or a physical GPR64.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
enum Root {
    Virtual(u32),
    Physical(u16),
}

impl Root {
    fn describe(self) -> String {
        match self {
            Self::Virtual(id) => format!("v{id}"),
            Self::Physical(root) => root_name(root),
        }
    }
}

/// The name of a physical root: a GPR64 (`rax` .. `r15`) or (slice 11) an
/// SSE register (`xmm0` .. `xmm15`, encodings 64 to 79).
fn root_name(root: u16) -> String {
    static_root_name(root).to_owned()
}

/// [`root_name`] for a refusal that carries a static name.
fn static_root_name(root: u16) -> &'static str {
    const XMM_NAMES: [&str; 16] = [
        "xmm0", "xmm1", "xmm2", "xmm3", "xmm4", "xmm5", "xmm6", "xmm7", "xmm8", "xmm9", "xmm10",
        "xmm11", "xmm12", "xmm13", "xmm14", "xmm15",
    ];
    match root {
        0..=15 => ROOT_NAMES[root as usize],
        _ => XMM_NAMES[usize::from(root - XMM_ROOTS.start)],
    }
}

/// A register operand: its root and the width the operand names (32 or 64).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct Reg {
    root: Root,
    bits: u32,
}

fn gpr(operand: &O) -> Option<Reg> {
    match operand {
        O::VReg(vreg) => {
            let bits = match vreg.class {
                RegClass::Gpr64 => 64,
                RegClass::Gpr32 => 32,
                _ => return None,
            };
            Some(Reg {
                root: Root::Virtual(vreg.id),
                bits,
            })
        }
        O::PReg(preg) => match preg.encoding() {
            root @ 0..=15 => Some(Reg {
                root: Root::Physical(root),
                bits: 64,
            }),
            alias @ 16..=31 => Some(Reg {
                root: Root::Physical(alias - GPR32_ALIAS_BASE),
                bits: 32,
            }),
            _ => None,
        },
        _ => None,
    }
}

fn gpr64(operand: &O) -> Option<Reg> {
    gpr(operand).filter(|reg| reg.bits == 64)
}

/// An SSE register operand (slice 11): a virtual register of class `Fpr32`
/// or `Fpr64` (the low 32 or 64 bits of an XMM register, the width it
/// names), or a physical XMM register, whose low 64 bits the walk models
/// (the bits above are never read: no admitted row reads more than the low
/// 64). Its root holds those 64 bits.
fn xmm(operand: &O) -> Option<Reg> {
    match operand {
        O::VReg(vreg) => {
            let bits = match vreg.class {
                RegClass::Fpr64 => 64,
                RegClass::Fpr32 => 32,
                _ => return None,
            };
            Some(Reg {
                root: Root::Virtual(vreg.id),
                bits,
            })
        }
        O::PReg(preg) if XMM_ROOTS.contains(&preg.encoding()) => Some(Reg {
            root: Root::Physical(preg.encoding()),
            bits: 64,
        }),
        _ => None,
    }
}

/// A physical 16-bit (`bits == 16`) or low-byte (`bits == 8`) alias, as the
/// root whose low bits it names. Only an extension's source may be one.
fn narrow_alias(operand: &O, bits: u32) -> Option<Root> {
    let O::PReg(preg) = operand else {
        return None;
    };
    let base = match bits {
        16 => GPR16_ALIAS_BASE,
        8 => GPR8_ALIAS_BASE,
        _ => return None,
    };
    let encoding = preg.encoding();
    (base..base + 16)
        .contains(&encoding)
        .then(|| Root::Physical(encoding - base))
}

/// Slice 23 (OD-205): the width of a variable shift row (`shl`/`shr`/`sar r,
/// cl`) one of whose operands is a physical register's 8- or 16-bit alias
/// (`None` for any other row).
fn narrow_variable_shift(inst: &X86ISelInst) -> Option<u32> {
    if !matches!(
        inst.opcode,
        X86Opcode::ShlRR | X86Opcode::ShrRR | X86Opcode::SarRR
    ) {
        return None;
    }
    [8, 16].into_iter().find(|&bits| {
        inst.operands
            .iter()
            .any(|operand| narrow_alias(operand, bits).is_some())
    })
}

/// The source operand of an extension row reading `bits` low bits: a 32- or
/// 64-bit register, or the physical alias naming exactly those bits.
fn extension_source(operand: &O, bits: u32) -> Option<Root> {
    gpr(operand)
        .map(|reg| reg.root)
        .or_else(|| narrow_alias(operand, bits))
}

/// Low bits an extension row reads from its source.
fn extension_source_bits(opcode: X86Opcode) -> u32 {
    match opcode {
        X86Opcode::Movzx | X86Opcode::MovsxB => 8,
        X86Opcode::MovzxW | X86Opcode::MovsxW => 16,
        _ => 32,
    }
}

/// A scalar `[base + disp]` load or store row (slice 4), from the encoder:
/// `MovRM8`/`MovRM16` are `mov r8/r16, m` (8A / 66 8B), which write only the
/// destination's low bits (the rest is undefined after register allocation,
/// which treats the destination as a pure definition); `MovzxRM8`/`MovzxRM16`
/// are `movzx r32, m8/m16` (0F B6 / 0F B7), which write the whole register with
/// the bytes zero-extended; `MovRM32` is `mov r32, m` (8B), which zero-extends;
/// `MovRM` is `mov r64, m` (REX.W 8B);
/// `MovMR8/16/32` and `MovMR` store the source register's low 1/2/4/8 bytes
/// (88, 66 89, 89, REX.W 89), never more bits than the register operand
/// names. Slice 25: a scaled-index row has its base-only sibling's form
/// ([`sib_access`]).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct MemoryAccessForm {
    bytes: u32,
    load: bool,
    /// A load that writes the whole 64-bit destination (REX.W).
    full: bool,
    /// A zero-extending narrow load (`movzx r32, m8/m16`).
    zero_extends: bool,
    /// Slice 11: an SSE scalar load or store (`movss`/`movsd` of 4 or 8
    /// bytes), whose register operand is an XMM register. A load writes the
    /// bytes zero-extended to the whole register (Intel SDM MOVSS/MOVSD with
    /// a memory source); a store writes the register's low 4 or 8 bytes.
    sse: bool,
}

fn memory_access(opcode: X86Opcode) -> Option<MemoryAccessForm> {
    let (bytes, load) = match opcode {
        X86Opcode::MovRM8 | X86Opcode::MovzxRM8 => (1, true),
        X86Opcode::MovRM16 | X86Opcode::MovzxRM16 => (2, true),
        X86Opcode::MovRM32 => (4, true),
        X86Opcode::MovRM => (8, true),
        X86Opcode::MovMR8 => (1, false),
        X86Opcode::MovMR16 => (2, false),
        X86Opcode::MovMR32 => (4, false),
        X86Opcode::MovMR => (8, false),
        X86Opcode::MovssRM => (4, true),
        X86Opcode::MovsdRM => (8, true),
        X86Opcode::MovssMR => (4, false),
        X86Opcode::MovsdMR => (8, false),
        _ => return None,
    };
    Some(MemoryAccessForm {
        bytes,
        load,
        full: load && bytes == 8,
        zero_extends: matches!(opcode, X86Opcode::MovzxRM8 | X86Opcode::MovzxRM16),
        sse: matches!(
            opcode,
            X86Opcode::MovssRM | X86Opcode::MovsdRM | X86Opcode::MovssMR | X86Opcode::MovsdMR
        ),
    })
}

/// The base of a `[base + disp]` memory operand.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum MemoryBase {
    /// A 64-bit register.
    Register(Reg),
    /// A private stack slot, before frame layout (`StackSlot(s)`).
    Slot(u32),
}

fn memory_base(operand: &O) -> Option<(MemoryBase, i32)> {
    let O::MemAddr { base, disp } = operand else {
        return None;
    };
    match base.as_ref() {
        O::StackSlot(slot) => Some((MemoryBase::Slot(*slot), *disp)),
        other => gpr64(other).map(|reg| (MemoryBase::Register(reg), *disp)),
    }
}

/// Slice 25 (OD-227): the base-only row of a scaled-index load or store row.
/// The encoder emits each with its sibling's opcode byte and REX rule and a
/// SIB ModRM (`emit_sib_mem_operand`), so it moves its sibling's bytes with
/// its sibling's extension, at the effective address the SIB operand names.
fn sib_sibling(opcode: X86Opcode) -> Option<X86Opcode> {
    Some(match opcode {
        X86Opcode::MovRMSib => X86Opcode::MovRM,
        X86Opcode::MovRM32Sib => X86Opcode::MovRM32,
        X86Opcode::MovzxRM8Sib => X86Opcode::MovzxRM8,
        X86Opcode::MovRM8Sib => X86Opcode::MovRM8,
        X86Opcode::MovsdRMSib => X86Opcode::MovsdRM,
        X86Opcode::MovssRMSib => X86Opcode::MovssRM,
        X86Opcode::MovMRSib => X86Opcode::MovMR,
        X86Opcode::MovMR32Sib => X86Opcode::MovMR32,
        X86Opcode::MovMR8Sib => X86Opcode::MovMR8,
        _ => return None,
    })
}

/// Slice 25: a scaled-index load or store row's form, its sibling's
/// ([`sib_sibling`]).
fn sib_access(opcode: X86Opcode) -> Option<MemoryAccessForm> {
    sib_sibling(opcode).and_then(memory_access)
}

/// The base of a scaled-index operand the walk states (slice 25).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SibBase {
    /// A virtual 64-bit register.
    Register(Reg),
    /// A private stack slot, before frame layout (`StackSlot(s)`).
    Slot(u32),
}

/// A scaled-index operand `[base + index*scale + disp]` the walk states
/// (slice 25, [`sib_operand`]).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct SibOperand {
    base: SibBase,
    index: Reg,
    scale: u8,
    disp: i32,
}

/// Slice 25: `[base + index*scale + disp]` with a virtual 64-bit register or
/// a stack slot as its base, a virtual 64-bit register as its index and a
/// scale of 1, 2, 4 or 8. A physical component is outside, so RBP and RSP
/// stay reachable only through slice 13's `[base + disp]` rules.
fn sib_operand(operand: &O) -> Option<SibOperand> {
    let O::SibMemAddr {
        base,
        index,
        scale,
        disp,
    } = operand
    else {
        return None;
    };
    let virtual64 = |operand: &O| match operand {
        O::VReg(_) => gpr64(operand),
        _ => None,
    };
    let base = match base.as_ref() {
        O::StackSlot(slot) => SibBase::Slot(*slot),
        other => SibBase::Register(virtual64(other)?),
    };
    let index = virtual64(index)?;
    matches!(scale, 1 | 2 | 4 | 8).then_some(SibOperand {
        base,
        index,
        scale: *scale,
        disp: *disp,
    })
}

/// The register operand of a load or store of `access` (slices 4, 8 and
/// 11): an XMM register for an SSE access, of which a store reads no more
/// bits than it names; else a general-purpose register, which a full load
/// fills whole (64 bits) and of which a store reads no more bits than it
/// names (register allocation keeps only the low 32 bits of a 32-bit
/// register: it spills and reloads four bytes, and coalesces a 32-bit copy,
/// so an 8-byte store of one would read bits the allocated code does not
/// preserve), or (slice 8) a physical register's 8- or 16-bit alias of a byte
/// or word access (`mov al, m8`, `mov [m], dx`: the selector moves a one- or
/// two-byte aggregate eightbyte through the ABI register at its own width).
/// With `virtual_only` (a slice-25 scaled-index row) only a virtual register.
fn access_value_ok(access: MemoryAccessForm, operand: &O, virtual_only: bool) -> bool {
    if virtual_only && !matches!(operand, O::VReg(_)) {
        return false;
    }
    let narrow = access.bytes <= 2 && narrow_alias(operand, access.bytes * 8).is_some();
    match (access.load, access.sse) {
        (true, true) => xmm(operand).is_some(),
        (false, true) => xmm(operand).is_some_and(|reg| access.bytes * 8 <= reg.bits),
        (true, false) => gpr(operand).is_some_and(|reg| !access.full || reg.bits == 64) || narrow,
        (false, false) => gpr(operand).is_some_and(|reg| access.bytes * 8 <= reg.bits) || narrow,
    }
}

/// Slice 25: `inst` is a scaled-index load or store row the walk states: its
/// value register virtual and of its sibling's width ([`access_value_ok`]),
/// its address a [`sib_operand`], and its flags exactly its opcode's memory
/// flags.
fn sib_access_shaped(inst: &X86ISelInst) -> bool {
    let Some(access) = sib_access(inst.opcode) else {
        return false;
    };
    inst.flags == inst.opcode.default_flags()
        && match (access.load, inst.operands.as_slice()) {
            (true, [value, address]) | (false, [address, value]) => {
                access_value_ok(access, value, true) && sib_operand(address).is_some()
            }
            _ => false,
        }
}

/// The operation of a memory-destination `add`/`xor` row (slice 25).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RmwOp {
    Add,
    Xor,
}

/// Slice 25 (OD-227): a memory-destination `add`/`xor` row of a 64-bit
/// register (`REX.W 01 /r`, `REX.W 31 /r`: `DEST <- DEST op SRC` at the
/// effective address, Intel SDM ADD, XOR), its operation, and whether its
/// address is a scaled-index operand.
fn read_modify_write(opcode: X86Opcode) -> Option<(RmwOp, bool)> {
    match opcode {
        X86Opcode::AddMR => Some((RmwOp::Add, false)),
        X86Opcode::XorMR => Some((RmwOp::Xor, false)),
        X86Opcode::AddMRSib => Some((RmwOp::Add, true)),
        X86Opcode::XorMRSib => Some((RmwOp::Xor, true)),
        _ => None,
    }
}

/// Slice 25: `inst` is a read-modify-write row the walk states: `[base +
/// disp]` through a virtual 64-bit base, or `[base + index*scale + disp]`
/// ([`sib_operand`]) with a virtual register (never a stack slot) as its
/// base, then a virtual 64-bit source register, carrying exactly its
/// opcode's memory flags.
fn read_modify_write_shaped(inst: &X86ISelInst, sib: bool) -> bool {
    let virtual64 = |operand: &O| matches!(operand, O::VReg(_)) && gpr64(operand).is_some();
    inst.flags == inst.opcode.default_flags()
        && match inst.operands.as_slice() {
            [address, source] if virtual64(source) => {
                if sib {
                    sib_operand(address)
                        .is_some_and(|operand| matches!(operand.base, SibBase::Register(_)))
                } else {
                    matches!(address, O::MemAddr { base, .. } if virtual64(base))
                }
            }
            _ => false,
        }
}

/// Check one row's opcode, flags, side metadata and operand shape. Only the
/// admitted row forms pass; everything else makes no claim. A direct call's
/// ABI metadata is only shape-checked here; the walk compares it with the
/// source call it is paired with.
fn check_row_shape(row: usize, inst: &X86ISelInst) -> Result<(), X86BodyRefusal> {
    let refuse = |detail: String| unsupported(X86BodyUnsupported::MachineRow { row, detail });
    let expected_flags = inst.opcode.default_flags();
    if matches!(inst.opcode, X86Opcode::Call | X86Opcode::CallR) {
        // Register arguments of the System V table and results in RAX, then
        // RDX (slice 5), at widths a scalar carrier defines (slice 11: and
        // the SSE argument registers XMM0-XMM7 and result registers XMM0 and
        // XMM1, at 32 or 64 bits); no sret or variadic AL form. Which
        // register each argument and result lane takes is compared with the
        // paired source call's by the walk ([`check_call_row`]).
        let widths = [8, 16, 32, 64];
        let arguments_shaped = inst.call_arg_regs.iter().all(|arg| {
            let bits = u32::from(arg.read_bits);
            (SYSV_ARGUMENT_ROOTS.contains(&arg.reg.encoding()) && widths.contains(&bits))
                || (SYSV_SSE_ARGUMENT_ROOTS.contains(&arg.reg.encoding())
                    && matches!(bits, 32 | 64))
        });
        // Each class's result registers in their System V order: RAX, then
        // RDX, and (slice 11) XMM0, then XMM1.
        let result_shaped = inst.call_result_regs.as_ref().is_some_and(|results| {
            let (mut integer, mut sse) = (SYSV_RETURN_ROOTS.iter(), SYSV_SSE_RETURN_ROOTS.iter());
            results.len() <= SYSV_RETURN_ROOTS.len()
                && results.iter().all(|result| {
                    let (bits, root) = (u32::from(result.defined_bits), result.reg.encoding());
                    if XMM_ROOTS.contains(&root) {
                        sse.next() == Some(&root) && matches!(bits, 32 | 64)
                    } else {
                        integer.next() == Some(&root) && widths.contains(&bits)
                    }
                })
        });
        let mut metadata = inst.flags;
        metadata.remove(expected_flags);
        // A direct call through its symbol, which may carry the metadata
        // flags; or (slice 10) `call r64` through a 64-bit register, which
        // carries none (the selector stamps neither on an indirect call).
        let target_shaped = match inst.opcode {
            X86Opcode::Call => {
                inst.flags.contains(expected_flags)
                    && CALL_METADATA_FLAGS.contains(metadata)
                    && matches!(inst.operands.as_slice(), [O::Symbol(_)])
            }
            _ => {
                inst.flags == expected_flags
                    && matches!(inst.operands.as_slice(), [callee] if gpr64(callee).is_some())
            }
        };
        if inst.proof_origin.is_none() && arguments_shaped && result_shaped && target_shaped {
            return Ok(());
        }
        return Err(refuse(format!(
            "{:?} with operands {:?}, flags {:?}, argument registers {:?} and result registers \
             {:?}",
            inst.opcode, inst.operands, inst.flags, inst.call_arg_regs, inst.call_result_regs
        )));
    }
    // Slice 13: a scalar atomic load or store is the plain `mov` of its width
    // with the selector's atomic origin (`select_atomic_load`/`_store`); the
    // walk pairs it only with an atomic source access (OD-83). Every other
    // origin stays outside.
    let atomic_row = match inst.proof_origin {
        Some(X86ProofOrigin::AtomicLoad) => matches!(
            inst.opcode,
            X86Opcode::MovzxRM8 | X86Opcode::MovzxRM16 | X86Opcode::MovRM32 | X86Opcode::MovRM
        ),
        Some(X86ProofOrigin::AtomicStore) => matches!(
            inst.opcode,
            X86Opcode::MovMR8 | X86Opcode::MovMR16 | X86Opcode::MovMR32 | X86Opcode::MovMR
        ),
        _ => false,
    };
    if (inst.proof_origin.is_some() && !atomic_row)
        || !inst.call_arg_regs.is_empty()
        || inst.call_result_regs.is_some()
        || !inst.internal_return_regs.is_empty()
    {
        return Err(refuse(format!(
            "{:?} carries call, internal-return or proof-origin metadata",
            inst.opcode
        )));
    }
    if inst.opcode == X86Opcode::Ud2 {
        // The trap after a diverging call: control only.
        if inst.flags == expected_flags && inst.operands.is_empty() {
            return Ok(());
        }
        return Err(refuse(format!(
            "Ud2 with operands {:?} and flags {:?}",
            inst.operands, inst.flags
        )));
    }
    // Slice 10: the one-operand `mul r/m32` or `mul r/m64` of a register,
    // whose implicit operands are EAX/RAX (read and written) and EDX/RDX
    // (written); the selector marks those implicit effects as a side effect.
    if inst.opcode == X86Opcode::Mul {
        if inst.flags == expected_flags
            && matches!(inst.operands.as_slice(), [source] if gpr(source).is_some())
        {
            return Ok(());
        }
        return Err(refuse(format!(
            "Mul with operands {:?} and flags {:?}",
            inst.operands, inst.flags
        )));
    }
    // Slice 14: the one-operand `div`/`idiv r/m32` or `r/m64` of a register
    // (implicit EDX:EAX or RDX:RAX dividend, quotient and remainder written
    // to EAX/RAX and EDX/RDX), `cdq`/`cqo` (EDX/RDX from the sign of
    // EAX/RAX), and the `TrapDivZeroExact` carrier of one register (the
    // pipeline expands it to `test d, d; je -> ud2` after this theorem's
    // subject); the selector marks each as a side effect.
    if matches!(
        inst.opcode,
        X86Opcode::Div | X86Opcode::Idiv | X86Opcode::TrapDivZeroExact
    ) {
        if inst.flags == expected_flags
            && matches!(inst.operands.as_slice(), [source] if gpr(source).is_some())
        {
            return Ok(());
        }
        return Err(refuse(format!(
            "{:?} with operands {:?} and flags {:?}",
            inst.opcode, inst.operands, inst.flags
        )));
    }
    if matches!(inst.opcode, X86Opcode::Cqo | X86Opcode::Cdq) {
        if inst.flags == expected_flags && inst.operands.is_empty() {
            return Ok(());
        }
        return Err(refuse(format!(
            "{:?} with operands {:?} and flags {:?}",
            inst.opcode, inst.operands, inst.flags
        )));
    }
    // Slice 11: the three-operand `adc d, a, b` and `sbb d, a, b` (`d = a +
    // b + CF`, `d = a - b - CF`) of one width, with which the selector adds
    // and subtracts the high halves of an `I128`; the selector marks the
    // implicit read of CF as a side effect. The two-operand (tied) form stays
    // outside.
    if matches!(inst.opcode, X86Opcode::AdcRR | X86Opcode::SbbRR) {
        let regs: Option<Vec<Reg>> = inst.operands.iter().map(gpr).collect();
        if inst.flags == expected_flags
            && regs.is_some_and(|regs| {
                regs.len() == 3 && regs.windows(2).all(|pair| pair[0].bits == pair[1].bits)
            })
        {
            return Ok(());
        }
        return Err(refuse(format!(
            "{:?} with operands {:?} and flags {:?}",
            inst.opcode, inst.operands, inst.flags
        )));
    }
    // A scalar load or store through `[base + disp]` (slice 4) carries
    // exactly its opcode's memory flags; every other row carries none.
    if let Some(access) = memory_access(inst.opcode) {
        // Its register operand names exactly the bits it moves
        // ([`access_value_ok`]).
        let shaped = inst.flags == expected_flags
            && match (access.load, inst.operands.as_slice()) {
                (true, [value, address]) | (false, [address, value]) => {
                    access_value_ok(access, value, false) && memory_base(address).is_some()
                }
                _ => false,
            };
        if shaped {
            return Ok(());
        }
        return Err(refuse(format!(
            "{:?} with operands {:?} and flags {:?}",
            inst.opcode, inst.operands, inst.flags
        )));
    }
    // Slice 21 (ruling OD-201): the selector's two atomic pseudo rows, each
    // one row through a register base, carrying exactly its opcode's memory
    // flags. `AtomicLoadCmpxchg16b [m]` (`xor eax, eax; xor edx, edx; xor
    // ebx, ebx; xor ecx, ecx; lock cmpxchg16b [m]`, `encode.rs`) and
    // `AtomicRmwCasLoop [dst, src, [m], kind]` of 32- or 64-bit registers of
    // one width, of the exchange kind 5 only (`mov rax, [m]; L: mov r10, src;
    // lock cmpxchg [m], r10; jne L; mov dst, rax`).
    if inst.opcode == X86Opcode::AtomicLoadCmpxchg16b {
        if inst.flags == expected_flags
            && matches!(
                inst.operands.as_slice(),
                [address] if matches!(memory_base(address), Some((MemoryBase::Register(_), _)))
            )
        {
            return Ok(());
        }
        return Err(refuse(format!(
            "{:?} with operands {:?} and flags {:?}",
            inst.opcode, inst.operands, inst.flags
        )));
    }
    if inst.opcode == X86Opcode::AtomicRmwCasLoop {
        if inst.flags == expected_flags
            && matches!(
                inst.operands.as_slice(),
                [dst, src, address, O::Imm(5)]
                    if gpr(dst).zip(gpr(src)).is_some_and(|(dst, src)| dst.bits == src.bits)
                        && matches!(memory_base(address), Some((MemoryBase::Register(_), _)))
            )
        {
            return Ok(());
        }
        return Err(refuse(format!(
            "{:?} with operands {:?} and flags {:?} (slice 21 admits the exchange, kind 5)",
            inst.opcode, inst.operands, inst.flags
        )));
    }
    // Slice 25 (OD-227): a scaled-index load or store of a virtual register
    // through `[base + index*scale + disp]` ([`sib_access_shaped`]), at its
    // base-only sibling's width and extension. A `MovRMSib` not so shaped
    // may still be the slice-14 jump-table load below.
    if sib_access(inst.opcode).is_some() {
        if sib_access_shaped(inst) {
            return Ok(());
        }
        if inst.opcode != X86Opcode::MovRMSib {
            return Err(refuse(format!(
                "{:?} with operands {:?} and flags {:?}",
                inst.opcode, inst.operands, inst.flags
            )));
        }
    }
    // Slice 25: a memory-destination `add`/`xor` of a virtual 64-bit register
    // into incoming memory ([`read_modify_write_shaped`]).
    if let Some((_, sib)) = read_modify_write(inst.opcode) {
        if read_modify_write_shaped(inst, sib) {
            return Ok(());
        }
        return Err(refuse(format!(
            "{:?} with operands {:?} and flags {:?} (slice 25 admits a virtual base, a virtual \
             index and a virtual 64-bit source)",
            inst.opcode, inst.operands, inst.flags
        )));
    }
    // Slice 14: the jump-table dispatch's `mov r64, [table + index*8]`, which
    // reads the table (the walk admits it only through a table's address),
    // carrying its opcode's memory flag; a physical component is admitted
    // here.
    if inst.opcode == X86Opcode::MovRMSib {
        if inst.flags == expected_flags
            && matches!(
                inst.operands.as_slice(),
                [dst, O::SibMemAddr { base, index, scale: 8, disp: 0 }]
                    if gpr64(dst).is_some() && gpr64(base).is_some() && gpr64(index).is_some()
            )
        {
            return Ok(());
        }
        return Err(refuse(format!(
            "{:?} with operands {:?} and flags {:?}",
            inst.opcode, inst.operands, inst.flags
        )));
    }
    // Slice 15: `movss`/`movsd xmm, [rip + constant]`, the selector's load of a
    // float constant or sign mask from the function's constant pool (the
    // entry's bytes are checked against the row's width in
    // [`machine_skeleton`]). It reads read-only data, carrying exactly its
    // opcode's memory flag.
    if matches!(inst.opcode, X86Opcode::MovssRipRel | X86Opcode::MovsdRipRel) {
        if inst.flags == expected_flags
            && matches!(inst.operands.as_slice(), [dst, O::ConstPoolEntry(_)] if xmm(dst).is_some())
        {
            return Ok(());
        }
        return Err(refuse(format!(
            "{:?} with operands {:?} and flags {:?}",
            inst.opcode, inst.operands, inst.flags
        )));
    }
    // A compare (slice 5) or a test (slice 6) writes only RFLAGS, which the
    // selector marks as a side effect; `cmp r, r`/`test r, r` of one width or
    // `cmp r, imm32`/`test r, imm32`. `mov r64, [rip + symbol@GOT]` reads the
    // symbol's GOT slot.
    if matches!(
        inst.opcode,
        X86Opcode::CmpRR
            | X86Opcode::CmpRI
            | X86Opcode::TestRR
            | X86Opcode::TestRI
            | X86Opcode::BtRI
            | X86Opcode::MovRipRel
            | X86Opcode::Ucomisd
            | X86Opcode::Ucomiss
    ) {
        let same_width = |a: &O, b: &O| gpr(a).zip(gpr(b)).is_some_and(|(a, b)| a.bits == b.bits);
        let shaped = inst.flags == expected_flags
            && match (inst.opcode, inst.operands.as_slice()) {
                (X86Opcode::CmpRR | X86Opcode::TestRR, [lhs, rhs]) => same_width(lhs, rhs),
                // `bt r, imm8`: `trust_cg_ir` groups it with the compares as a
                // flag-only side effect and as producing no value, and the
                // peephole emits `[reg, imm]` with operand 0 a pure use. The
                // bit index must be in range for the operand's width, which is
                // what `encode_bt_cf`'s own debug assertion requires; out of
                // range is refused here rather than modelled.
                (X86Opcode::BtRI, [src, O::Imm(imm)]) => {
                    gpr(src).is_some_and(|reg| u32::try_from(*imm).is_ok_and(|k| k < reg.bits))
                }
                (X86Opcode::CmpRI, [lhs, O::Imm(imm)]) => {
                    gpr(lhs).is_some() && i32::try_from(*imm).is_ok()
                }
                // The encoder emits `test r/m64, imm32` (REX.W) whatever the
                // register's width, so only a 64-bit register is the row it
                // encodes.
                (X86Opcode::TestRI, [lhs, O::Imm(imm)]) => {
                    gpr64(lhs).is_some() && i32::try_from(*imm).is_ok()
                }
                (X86Opcode::MovRipRel, [dst, O::Symbol(_)]) => gpr64(dst).is_some(),
                // Slice 21: `ucomisd`/`ucomiss a, b` of two XMM registers,
                // which writes only ZF, PF and CF (and clears OF, SF, AF).
                (X86Opcode::Ucomisd | X86Opcode::Ucomiss, [lhs, rhs]) => {
                    xmm(lhs).is_some() && xmm(rhs).is_some()
                }
                _ => false,
            };
        if shaped {
            return Ok(());
        }
        return Err(refuse(format!(
            "{:?} with operands {:?} and flags {:?}",
            inst.opcode, inst.operands, inst.flags
        )));
    }
    if inst.flags != expected_flags
        || !inst
            .flags
            .intersection(
                InstFlags::IS_CALL
                    .union(InstFlags::READS_MEMORY)
                    .union(InstFlags::WRITES_MEMORY)
                    .union(InstFlags::HAS_SIDE_EFFECTS),
            )
            .is_empty()
    {
        // Name the OPERANDS, not just the opcode and flags: which shape a
        // refused row carries (a physical SIB component, a sign-extending or
        // vector SIB load, a memory-operand multiply or compare, a volatile
        // form) decides what admitting it needs. Slice 25 states the virtual
        // scaled-index loads and stores and the memory-destination
        // `add`/`xor` above; a register-base, register-index store among them
        // needs no aliasing reasoning, as the world trace pairs incoming
        // accesses by position.
        return Err(refuse(format!(
            "{:?} with operands {:?} carries flags {:?}",
            inst.opcode, inst.operands, inst.flags
        )));
    }
    let same_width = |operands: &[O]| {
        let regs: Option<Vec<Reg>> = operands.iter().map(gpr).collect();
        regs.is_some_and(|regs| regs.windows(2).all(|pair| pair[0].bits == pair[1].bits))
    };
    // Slice 8: the two-operand (tied) form of `shl`, `shr` and `or`, which
    // computes `d = d op s` and which register allocation keeps tied (a def
    // and a use of `d`), is the three-operand row `[d, d, s]` ([`untied`]).
    if let Some(untied) = untied(inst) {
        return check_row_shape(row, &untied);
    }
    // Slice 23 (OD-205): a variable shift (`shl`/`shr`/`sar r, cl`) is stated
    // at 32 and 64 bits only, where x86 masks the count to log2 of the width
    // (5 or 6 bits), which is what the walk's barrel reads
    // ([`shift_modulo_width`]). At 8 and 16 bits x86 masks it to 5 bits too
    // (modulo 32), so `shl al, cl` with CL = 8 is zero where a 3-stage
    // barrel leaves AL whole: such a row is refused by name, never stated.
    if let Some(narrow) = narrow_variable_shift(inst) {
        return Err(refuse(format!(
            "{:?} with operands {:?} is a {narrow}-bit variable shift: x86 masks its count \
             to 5 bits (modulo 32), not to log2 of its width, so the walk states variable \
             shifts at 32 and 64 bits only",
            inst.opcode, inst.operands
        )));
    }
    // A row the lane states as another whose shape is already checked: the
    // `xor d, d` zeroing idiom as `mov d, 0`, the in-place `inc`/`dec` as
    // `add`/`sub d, d, 1` ([`restated_row`]). Without the first, the idiom
    // reached the three-operand ALU arm and was refused on arity, which was
    // the FIRST uncovered row of 120 refusals across the 18 beat-llvm
    // programs -- the whole machine-row frontier (2026-10-14).
    if let Some(restated) = restated_row(inst) {
        return check_row_shape(row, &restated);
    }
    // Slice 13: `sub rsp, n` / `add rsp, n` around a call with stack
    // arguments (an aligned, bounded outgoing argument area; the walk pairs
    // them with the call).
    if matches!(inst.opcode, X86Opcode::SubRI | X86Opcode::AddRI)
        && let [O::PReg(preg), O::Imm(bytes)] = inst.operands.as_slice()
        && preg.encoding() == RSP
    {
        if (1..=i64::from(MAX_SLOT_BYTES)).contains(bytes) && bytes % 16 == 0 {
            return Ok(());
        }
        return Err(refuse(format!("{:?} adjusts RSP by {bytes}", inst.opcode)));
    }
    let shaped = match inst.opcode {
        // Slice 15: a copy between a 32- and a 64-bit register (either way
        // round) too, which the selector emits to move a narrow aggregate
        // eightbyte into its argument register; the walk keeps only its low
        // 32 bits ([`walk_rows`]).
        X86Opcode::MovRR => {
            inst.operands.len() == 2 && inst.operands.iter().all(|operand| gpr(operand).is_some())
        }
        // Slice 15: the three-operand `pxor`, `andps` and `andpd d, s, m`
        // (`d = s ^ m`, `d = s & m` over the whole XMM register) of XMM
        // registers, with which the selector flips or clears a float's sign
        // bit; register allocation copies `s` into `d` first (a full
        // 128-bit `movdqa`). The two-operand forms stay outside.
        X86Opcode::Pxor | X86Opcode::Andps | X86Opcode::Andpd => {
            inst.operands.len() == 3 && inst.operands.iter().all(|operand| xmm(operand).is_some())
        }
        X86Opcode::MovRR32 => {
            inst.operands.len() == 2 && inst.operands.iter().all(|operand| gpr(operand).is_some())
        }
        X86Opcode::Movzx
        | X86Opcode::MovzxW
        | X86Opcode::MovsxB
        | X86Opcode::MovsxW
        | X86Opcode::Movsx => matches!(
            inst.operands.as_slice(),
            [dst, src] if gpr(dst).is_some()
                && extension_source(src, extension_source_bits(inst.opcode)).is_some()
        ),
        X86Opcode::MovRI => matches!(
            inst.operands.as_slice(),
            [dst, O::Imm(_)] if gpr(dst).is_some()
        ),
        // Slice 15: of mixed 32- and 64-bit registers too (the selector's
        // assembly of a narrow aggregate eightbyte in its argument register,
        // `or edx, r64`); the walk keeps only the low 32 bits of such a row.
        X86Opcode::AddRR
        | X86Opcode::SubRR
        | X86Opcode::ImulRR
        | X86Opcode::AndRR
        | X86Opcode::OrRR
        | X86Opcode::XorRR => {
            inst.operands.len() == 3 && inst.operands.iter().all(|operand| gpr(operand).is_some())
        }
        // Slice 10: `not` and `popcnt` of one width, `dst = op(src)` (the
        // two-operand form is untied: register allocation copies `src` into
        // `dst` first; the one-operand in-place `not` stays outside).
        X86Opcode::Not | X86Opcode::Neg | X86Opcode::Popcnt => {
            inst.operands.len() == 2 && same_width(&inst.operands)
        }
        // Slice 10: `shl`/`shr`/`sar dst, src` by CL (the count is the
        // implicit RCX; the two-operand form is untied). The one-operand
        // in-place form is slice 11's tied row ([`untied`]).
        X86Opcode::ShlRR | X86Opcode::ShrRR | X86Opcode::SarRR => {
            inst.operands.len() == 2 && same_width(&inst.operands)
        }
        // Slice 11: SSE register moves of a float bit pattern. `movss` and
        // `movsd` copy the low 32 or 64 bits of one XMM register to another;
        // `movd`/`movq` move the low 32 or 64 bits between an XMM register
        // and a general-purpose register of that width.
        X86Opcode::MovssRR | X86Opcode::MovsdRR => matches!(
            inst.operands.as_slice(),
            [dst, src] if xmm(dst).is_some() && xmm(src).is_some()
        ),
        X86Opcode::MovdFromXmm | X86Opcode::MovqFromXmm => matches!(
            inst.operands.as_slice(),
            [dst, src] if xmm(src).is_some() && gpr(dst).is_some_and(|reg| {
                reg.bits == if inst.opcode == X86Opcode::MovdFromXmm { 32 } else { 64 }
            })
        ),
        X86Opcode::MovdToXmm | X86Opcode::MovqToXmm => matches!(
            inst.operands.as_slice(),
            [dst, src] if xmm(dst).is_some() && gpr(src).is_some_and(|reg| {
                reg.bits == if inst.opcode == X86Opcode::MovdToXmm { 32 } else { 64 }
            })
        ),
        // Slice 21 (ruling OD-198): the scalar SSE rounding rows. `addsd`,
        // `subsd`, `mulsd`, `divsd` (and the `ss` forms) `[dst, a, b]` of XMM
        // registers (three-operand before register allocation, which ties
        // `dst` to `a`); `cvtsi2sd`/`cvtsi2ss xmm, r64`; `cvttsd2si` and
        // `cvtsd2si r64, xmm`. Each reads the low 64 (32) bits of its XMM
        // operands, whatever width the register names.
        X86Opcode::Addsd
        | X86Opcode::Subsd
        | X86Opcode::Mulsd
        | X86Opcode::Divsd
        | X86Opcode::Addss
        | X86Opcode::Subss
        | X86Opcode::Mulss
        | X86Opcode::Divss => {
            inst.operands.len() == 3 && inst.operands.iter().all(|operand| xmm(operand).is_some())
        }
        X86Opcode::Cvtsi2sd | X86Opcode::Cvtsi2ss => matches!(
            inst.operands.as_slice(),
            [dst, src] if xmm(dst).is_some() && gpr64(src).is_some()
        ),
        X86Opcode::Cvttsd2si | X86Opcode::Cvtsd2si => matches!(
            inst.operands.as_slice(),
            [dst, src] if gpr64(dst).is_some() && xmm(src).is_some()
        ),
        // `imul dst, lhs, imm32` (slice 16): the low bits of the signed
        // product, which `bvmul` gives exactly at the operand width.
        X86Opcode::AddRI
        | X86Opcode::SubRI
        | X86Opcode::AndRI
        | X86Opcode::OrRI
        | X86Opcode::XorRI
        | X86Opcode::ImulRRI => matches!(
            inst.operands.as_slice(),
            [dst, lhs, O::Imm(imm)]
                if same_width(&[dst.clone(), lhs.clone()]) && i32::try_from(*imm).is_ok()
        ),
        X86Opcode::ShlRI | X86Opcode::ShrRI | X86Opcode::SarRI => matches!(
            inst.operands.as_slice(),
            [dst, lhs, O::Imm(count)]
                if same_width(&[dst.clone(), lhs.clone()]) && (0..256).contains(count)
        ),
        // `rol dst, src, imm8`: `(src << k) | (src >>u (width - k))`, the same
        // shift-by-immediate form as the three above. A count whose MASKED
        // value is zero stays outside, so both halves below shift by less
        // than the width (the identity rotate is not a row the selector
        // emits, and admitting it would need a third case for no gain).
        X86Opcode::RolRI => matches!(
            inst.operands.as_slice(),
            [dst, lhs, O::Imm(count)]
                if same_width(&[dst.clone(), lhs.clone()])
                    && (0..256).contains(count)
                    && gpr(dst)
                        .is_some_and(|reg| (*count as u64) & u64::from(reg.bits - 1) != 0)
        ),
        // `lea dst, [base + disp]` over a register, or over a private stack
        // slot (the slot's address).
        X86Opcode::Lea => matches!(
            inst.operands.as_slice(),
            [dst, address] if gpr64(dst).is_some() && memory_base(address).is_some()
        ),
        // The SIB scales the encoder accepts (`validate_sib_mem_operand`).
        X86Opcode::LeaSib => matches!(
            inst.operands.as_slice(),
            [dst, O::SibMemAddr { base, index, scale, .. }]
                if gpr64(dst).is_some()
                    && gpr64(base).is_some()
                    && gpr64(index).is_some()
                    && matches!(scale, 1 | 2 | 4 | 8)
        ),
        // `lea r64, [rip + symbol]` (slice 5), or (slice 14) of a jump
        // table, which only its dispatch block takes ([`dispatch_blocks`]).
        X86Opcode::LeaRip => matches!(
            inst.operands.as_slice(),
            [dst, O::Symbol(_) | O::JumpTableIndex(_)] if gpr64(dst).is_some()
        ),
        // Slice 14: the indirect `jmp r64` of a jump-table dispatch.
        X86Opcode::JmpR => matches!(inst.operands.as_slice(), [target] if gpr64(target).is_some()),
        // `setcc r8` into the low byte of a register the operand names at 32
        // or 64 bits (slice 5).
        X86Opcode::Setcc => matches!(
            inst.operands.as_slice(),
            [dst, O::CondCode(_)] if gpr(dst).is_some()
        ),
        // `cmovcc dst, src` (slice 6) of 64-bit (`Cmovcc`) or 32-bit
        // (`Cmovcc32`) registers.
        X86Opcode::Cmovcc | X86Opcode::Cmovcc32 => matches!(
            inst.operands.as_slice(),
            [dst, src, O::CondCode(_)]
                if gpr(dst).zip(gpr(src)).is_some_and(|(dst, src)| {
                    let bits = if inst.opcode == X86Opcode::Cmovcc { 64 } else { 32 };
                    dst.bits == bits && src.bits == bits
                })
        ),
        X86Opcode::Jmp => matches!(inst.operands.as_slice(), [O::Block(_)]),
        // `jcc target` (slice 6): a conditional jump on RFLAGS to a block.
        X86Opcode::Jcc => matches!(inst.operands.as_slice(), [O::CondCode(_), O::Block(_)]),
        X86Opcode::Ret | X86Opcode::Nop => inst.operands.is_empty(),
        _ => false,
    };
    if shaped {
        Ok(())
    } else {
        Err(refuse(format!(
            "{:?} with operands {:?}",
            inst.opcode, inst.operands
        )))
    }
}

/// The three-operand row `[d, d, x]` that a two-operand (tied) row `[d, x]`
/// computes, `d = d op x` (slice 8), or `None` for any other row. The
/// encoder emits the two-operand form in place, and register allocation
/// treats its destination as a def and a use (`first_operand_is_def_and_use`
/// in the x86-64 pipeline), so the value it reads is the destination's own.
/// Only the forms the selector's eightbyte moves emit are admitted: `shl d,
/// imm` and `or d, s` (assembling a partial eightbyte) and `shr d, imm`
/// (taking one apart), and (slice 10) `and d, imm`, with which the selector
/// masks a narrow `CtPop` operand. Every other two-operand row stays outside:
/// the optimizer's `xor r, r` zeroing idiom, for one, reads no value of `r`,
/// which this rule would wrongly name an undefined read.
/// The `mov d, 0` that the optimizer's `xor d, d` zeroing idiom computes
/// (`XorRR` with both operands the same GPR root at the same width), or
/// `None` for any other row.
///
/// `xor d, d` is `d := 0` for EVERY prior value of `d`, so it reads no value
/// of `d`. That is exactly why [`untied`] must NOT rewrite it -- that rule
/// states a two-operand row as `d = d op s`, which would name an undefined
/// read of `d` -- and why it is stated here as the constant row instead,
/// reusing `MovRI`'s checked shape and walk rather than adding a second
/// model of a write of zero. The obligation is `after(d) = 0`, which is not
/// the degenerate `X == X` class: it distinguishes a wrong lowering.
///
/// The REAL opcode's flag effect is kept: the walk clobbers RFLAGS from
/// `row.inst.opcode`, not from the rewritten row, because `xor` writes flags
/// and `mov` does not. Without that a later `setcc` would be judged against
/// stale flags.
/// The `add d, d, 1` / `sub d, d, 1` that the one-operand `inc d` / `dec d`
/// computes, or `None` for any other row.
///
/// `inc` and `dec` are the in-place forms register allocation ties (a def and
/// a use of `d`), so like the tied ALU rows of slice 8 they are stated as the
/// three-operand row they compute -- here reusing `AddRI`/`SubRI`'s checked
/// shape and walk, which is exact: `imm32` sign-extended to the operand
/// width, and 1 is 1 at every width.
///
/// `inc` and `dec` leave CF UNCHANGED where `add`/`sub` write it. That costs
/// nothing because the walk clobbers RFLAGS to `Unmodelled` from the real
/// opcode (both are in [`writes_unmodelled_flags`]), so a later reader makes
/// no claim either way -- conservative in the safe direction.
fn in_place_step(inst: &X86ISelInst) -> Option<X86ISelInst> {
    let opcode = match inst.opcode {
        X86Opcode::Inc => X86Opcode::AddRI,
        X86Opcode::Dec => X86Opcode::SubRI,
        _ => return None,
    };
    let [destination] = inst.operands.as_slice() else {
        return None;
    };
    gpr(destination)?;
    let mut row = inst.clone();
    row.opcode = opcode;
    row.operands = vec![destination.clone(), destination.clone(), O::Imm(1)];
    Some(row)
}

/// The row the lane STATES for a machine row it does not model directly: the
/// `xor d, d` zeroing idiom and the in-place `inc`/`dec`. Both restate a row
/// as one whose shape and walk are already checked, rather than adding a
/// second model of the same semantics.
///
/// Flags are not laundered by a restatement: every opcode here and every
/// target has `InstFlags::EMPTY` for its default, and the row's own flags are
/// carried over, so [`check_row_shape`]'s gate still requires the original to
/// have carried exactly its own. The RFLAGS clobber is read from the real
/// opcode at the walk, never from the restated row.
fn restated_row(inst: &X86ISelInst) -> Option<X86ISelInst> {
    zeroing_idiom(inst).or_else(|| in_place_step(inst))
}

fn zeroing_idiom(inst: &X86ISelInst) -> Option<X86ISelInst> {
    if inst.opcode != X86Opcode::XorRR {
        return None;
    }
    let [left, right] = inst.operands.as_slice() else {
        return None;
    };
    let (destination, source) = (gpr(left)?, gpr(right)?);
    if destination.root != source.root || destination.bits != source.bits {
        return None;
    }
    let mut row = inst.clone();
    row.opcode = X86Opcode::MovRI;
    row.operands = vec![left.clone(), O::Imm(0)];
    Some(row)
}

fn untied(inst: &X86ISelInst) -> Option<X86ISelInst> {
    // Slice 14: and the tied `add d, s` of the jump-table dispatch and its
    // bound check's `sub n, min` (the pipeline's two-address rule,
    // `first_operand_is_def_and_use`, ties `[d, s]` and `[d, imm]` of every
    // binary row); `sub rsp, n` stays the outgoing area's own form (slice
    // 13).
    let tied = matches!(
        inst.opcode,
        X86Opcode::OrRR | X86Opcode::ShlRI | X86Opcode::ShrRI | X86Opcode::AndRI | X86Opcode::AddRR
    ) || (inst.opcode == X86Opcode::SubRI
        && !matches!(inst.operands.first(), Some(O::PReg(preg)) if preg.encoding() == RSP));
    // Slice 11: the one-operand `shl d, cl`, `shr d, cl` and `sar d, cl`
    // (`d = d op CL`), with which the selector shifts the halves of an
    // `I128`; register allocation ties its one operand (a def and a use).
    let tied_by_cl = matches!(
        inst.opcode,
        X86Opcode::ShlRR | X86Opcode::ShrRR | X86Opcode::SarRR
    );
    match inst.operands.as_slice() {
        [destination, source] if tied => {
            let mut three = inst.clone();
            three.operands = vec![destination.clone(), destination.clone(), source.clone()];
            Some(three)
        }
        [destination] if tied_by_cl => {
            let mut two = inst.clone();
            two.operands = vec![destination.clone(), destination.clone()];
            Some(two)
        }
        _ => None,
    }
}

/// Whether an operand names a stack slot, at any nesting depth. Recurses
/// through memory operands because a slot can appear as a base or a SIB
/// index, not only bare.
fn operand_mentions_stack_slot(operand: &O) -> bool {
    match operand {
        O::StackSlot(_) => true,
        O::MemAddr { base, .. } => operand_mentions_stack_slot(base),
        O::SibMemAddr { base, index, .. } => {
            operand_mentions_stack_slot(base) || operand_mentions_stack_slot(index)
        }
        _ => false,
    }
}

/// Whether a row references a stack slot anywhere except the places the
/// walk models a slot: the base of the `[slot + disp]` operand of `lea` or of
/// a scalar load/store row, and (slice 25) the base of a scaled-index load's
/// or store's own address operand whose index names no slot. A slot as a SIB
/// index, on `LeaSib` or on a read-modify-write row, a bare operand or the
/// operand of any other row is outside the domain.
fn row_mentions_unmodelled_stack_slot(inst: &X86ISelInst) -> bool {
    let modelled = inst.opcode == X86Opcode::Lea || memory_access(inst.opcode).is_some();
    // The address operand of a scaled-index load (operand 1) or store (0).
    let sib_address = sib_access(inst.opcode).map(|access| usize::from(access.load));
    inst.operands
        .iter()
        .enumerate()
        .any(|(position, operand)| match operand {
            O::MemAddr { base, .. } if modelled && matches!(base.as_ref(), O::StackSlot(_)) => {
                false
            }
            O::SibMemAddr { base, index, .. }
                if sib_address == Some(position)
                    && matches!(base.as_ref(), O::StackSlot(_))
                    && (!operand_mentions_stack_slot(index)
                        || mutated("s25-scan-exempts-index")) =>
            {
                false
            }
            other => operand_mentions_stack_slot(other),
        })
}

/// The stack-slot scan: every row of `machine` against
/// [`row_mentions_unmodelled_stack_slot`], in one fixed order, so that its
/// refusal names the same row on every run (`machine.blocks` is a `HashMap`,
/// whose iteration order differs from one map to the next). The blocks
/// `block_order` names come first, each where it is first named, each row at
/// the ordinal the walk gives it (the rows of the blocks laid out before its
/// own, plus its index; a name with no body has no rows, and a name repeated
/// adds none); then every block `block_order` omits, by ascending id, each row
/// at its index in its block. Every block is visited, so the verdict is the
/// one an unordered scan gives. `None` when no row offends; otherwise the
/// refusal detail: the first offending row's block, ordinal (or index),
/// opcode and operands, and the number of offending rows.
fn unmodelled_stack_slot_rows(machine: &X86ISelFunction) -> Option<String> {
    let mut named: HashSet<Block> = HashSet::new();
    let mut scanned: Vec<(Block, Option<usize>, &[X86ISelInst])> = Vec::new();
    let mut ordinal = 0usize;
    for block in &machine.block_order {
        let Some(body) = machine.blocks.get(block) else {
            continue;
        };
        if !named.insert(*block) {
            continue;
        }
        scanned.push((*block, Some(ordinal), &body.insts));
        ordinal += body.insts.len();
    }
    let mut omitted: Vec<(Block, Option<usize>, &[X86ISelInst])> = machine
        .blocks
        .iter()
        .filter(|(block, _)| !named.contains(*block))
        .map(|(block, body)| (*block, None, body.insts.as_slice()))
        .collect();
    omitted.sort_by_key(|(block, _, _)| *block);
    scanned.extend(omitted);
    let mut first = None;
    let mut count = 0usize;
    for (block, start, insts) in scanned {
        for (index, inst) in insts.iter().enumerate() {
            if !row_mentions_unmodelled_stack_slot(inst) {
                continue;
            }
            count += 1;
            if first.is_none() {
                let row = match start {
                    Some(start) => format!("{}", start + index),
                    None => format!("(not laid out) index {index}"),
                };
                first = Some((block, row, inst));
            }
        }
    }
    let (block, row, inst) = first?;
    Some(format!(
        "a row that references a stack slot outside a modelled `[slot + disp]` operand or \
         scaled-index base: block {block:?} row {row}, {:?} with operands {:?} ({count} such {})",
        inst.opcode,
        inst.operands,
        if count == 1 { "row" } else { "rows" },
    ))
}

fn machine_skeleton<'m>(
    source: &Function,
    machine: &'m X86ISelFunction,
    slots: &[trust_cg_lower::function::StackSlotInfo],
    dead: &std::collections::BTreeSet<Block>,
) -> Result<MachineCfg<'m>, X86BodyRefusal> {
    machine_skeleton_bounded(
        source,
        machine,
        slots,
        dead,
        MAX_MACHINE_BLOCKS,
        MAX_MACHINE_ROWS,
    )
}

/// [`machine_skeleton`] within `max_blocks` laid-out blocks and `max_rows`
/// rows (slice 16: a function stated in parts has its own bounds).
fn machine_skeleton_bounded<'m>(
    source: &Function,
    machine: &'m X86ISelFunction,
    slots: &[trust_cg_lower::function::StackSlotInfo],
    dead: &std::collections::BTreeSet<Block>,
    max_blocks: usize,
    max_rows: usize,
) -> Result<MachineCfg<'m>, X86BodyRefusal> {
    let function = |reason: &str| unsupported(X86BodyUnsupported::MachineFunction(reason.into()));
    if machine.name != source.name {
        return Err(function("machine and source name different functions"));
    }
    // Slice 14: each machine-function table is its own refusal (until slice
    // 14 one: "constant pool, jump tables, EH, guard obligations or an
    // outgoing call area"). A jump table is admitted when it is the table of
    // exactly one dispatch block ([`dispatch_blocks`]), which the walk
    // models from the table's own targets; the others stay outside.
    if !machine.eh_info.is_empty() {
        return Err(function("exception-handling tables (EH)"));
    }
    if !machine.guard_obligations.is_empty() {
        return Err(function(
            "guard obligations (the certified-elimination kernel may delete a trap carrier)",
        ));
    }
    if machine.max_outgoing_call_bytes != 0 {
        return Err(function("an outgoing call area"));
    }
    let dispatch = dispatch_blocks(machine);
    for table in 0..machine.jump_tables.len() as u32 {
        let users = dispatch.values().filter(|used| **used == table).count();
        let addressed = machine
            .blocks
            .values()
            .flat_map(|block| block.insts.iter())
            .filter(|inst| inst.operands.contains(&O::JumpTableIndex(table)))
            .count();
        if users != 1 || addressed != 1 {
            return Err(function(&format!(
                "jump table {table} outside the selector's dispatch idiom (one `lea`, scaled \
                 load, `add` and indirect `jmp` block per table)"
            )));
        }
    }
    // Slice 15: a constant-pool entry is admitted only as the source of a
    // `movss`/`movsd` load of exactly its bytes (4 or 8): the walk takes the
    // loaded bits from the entry's data. Any other row naming an entry, or an
    // entry of another size, makes no claim.
    for inst in machine.blocks.values().flat_map(|block| block.insts.iter()) {
        for operand in &inst.operands {
            let O::ConstPoolEntry(index) = operand else {
                continue;
            };
            let bytes = match inst.opcode {
                X86Opcode::MovssRipRel => 4,
                X86Opcode::MovsdRipRel => 8,
                _ => {
                    return Err(function(&format!(
                        "constant pool entry {index} read by {:?} (only a `movss`/`movsd` load \
                         of exactly its bytes is admitted)",
                        inst.opcode
                    )));
                }
            };
            if machine
                .const_pool_entries
                .get(*index)
                .is_none_or(|entry| entry.data.len() != bytes)
            {
                return Err(function(&format!(
                    "a {bytes}-byte scalar SSE load of constant-pool entry {index}, which does not \
                     hold {bytes} bytes"
                )));
            }
        }
    }
    // The walk binds machine `StackSlot(s)` to source slot `s`: the two slot
    // tables must be the same table (the selector copies the source's, then,
    // slice 8, appends the private copy of each aggregate parameter and the
    // slot of each aggregate call result; [`SourceBody::machine_slots`]).
    // Soundness does not rest on that binding: the source defines every byte
    // of those slots (from the argument and result registers), the machine
    // its own by the stores it walks, and a machine read of a byte it never
    // wrote is a free input the source does not share.
    if machine.stack_slots != slots {
        return Err(function(
            "stack slots that differ from the LIR source's slot table and its aggregate copies",
        ));
    }
    // A row may reference a slot only where the walk models one: the base of
    // the `[slot + disp]` operand of `lea` or of a scalar load/store (slice
    // 4), or (slice 25) the base of a scaled-index load's or store's own
    // address operand over an index that names no slot
    // ([`row_mentions_unmodelled_stack_slot`]). The row allowlist admits no
    // other slot operand (a scaled-index index is a virtual register,
    // [`sib_operand`]); this scan makes it a check, so a future arm cannot
    // silently widen it. The refusal names the first such row in layout
    // order and counts them ([`unmodelled_stack_slot_rows`]).
    if let Some(detail) = unmodelled_stack_slot_rows(machine) {
        return Err(function(&detail));
    }
    if machine.blocks.is_empty() || machine.blocks.len() > max_blocks {
        return Err(function(&format!("requires one to {max_blocks} blocks")));
    }
    // Walk ordinals follow the verifier: `block_order`, then each block's
    // instructions. Check every row's shape before judging control flow, so
    // an out-of-domain row anywhere makes no claim.
    let mut ordinals: HashMap<Block, usize> = HashMap::new();
    let mut next = 0usize;
    let mut laid_out = HashSet::new();
    // One register class per virtual register id.
    let mut classes: HashMap<u32, RegClass> = HashMap::new();
    for block in &machine.block_order {
        let Some(body) = machine.blocks.get(block) else {
            return Err(mismatch(X86BodyMismatch::Layout(format!(
                "block_order names {block:?}, which has no body"
            ))));
        };
        if !laid_out.insert(*block) {
            return Err(mismatch(X86BodyMismatch::Layout(format!(
                "block_order names {block:?} twice"
            ))));
        }
        ordinals.insert(*block, next);
        for (index, inst) in body.insts.iter().enumerate() {
            check_row_shape(next + index, inst)?;
            for operand in &inst.operands {
                let vregs: Vec<_> = match operand {
                    O::VReg(vreg) => vec![*vreg],
                    O::MemAddr { base, .. } => match base.as_ref() {
                        O::VReg(vreg) => vec![*vreg],
                        _ => vec![],
                    },
                    O::SibMemAddr { base, index, .. } => [base.as_ref(), index.as_ref()]
                        .into_iter()
                        .filter_map(|operand| match operand {
                            O::VReg(vreg) => Some(*vreg),
                            _ => None,
                        })
                        .collect(),
                    _ => vec![],
                };
                for vreg in vregs {
                    if *classes.entry(vreg.id).or_insert(vreg.class) != vreg.class {
                        return Err(unsupported(X86BodyUnsupported::MachineRow {
                            row: next + index,
                            detail: format!("v{} is named with two register classes", vreg.id),
                        }));
                    }
                }
            }
        }
        next += body.insts.len();
        if next > max_rows {
            return Err(function(&format!("more than {max_rows} rows")));
        }
    }
    if let Some(block) = machine
        .blocks
        .keys()
        .filter(|block| !laid_out.contains(*block))
        .min()
    {
        return Err(mismatch(X86BodyMismatch::UnreachableBlock {
            block: *block,
        }));
    }
    if machine.sig.params != source.signature.params
        || machine.sig.returns != source.signature.returns
    {
        return Err(mismatch(X86BodyMismatch::Signature));
    }
    // The control structure of every laid-out block (slice 6): conditional
    // jumps anywhere, then at most one final `jmp`, `ret` or `ud2`, else a
    // fallthrough to the next block in layout. The recorded successors are
    // exactly the targets of those transfers, as a set: the selector records
    // each edge once, and the branch-layout pass (O1+) inverts a `jcc` and
    // swaps its fallthrough without reordering them.
    for (position, current) in machine.block_order.iter().enumerate() {
        let current = *current;
        let body = &machine.blocks[&current];
        let first = ordinals[&current];
        let mut targets: Vec<Block> = Vec::new();
        let mut conditional = false;
        let mut exit = None;
        for (index, inst) in body.insts.iter().enumerate() {
            let ordinal = first + index;
            let last = index + 1 == body.insts.len();
            let control = |detail: &str| {
                mismatch(X86BodyMismatch::Control {
                    block: current,
                    row: Some(ordinal),
                    detail: detail.into(),
                })
            };
            match inst.opcode {
                X86Opcode::Jcc => {
                    let [O::CondCode(_), O::Block(target)] = inst.operands.as_slice() else {
                        unreachable!("row shape checked above");
                    };
                    if !machine.blocks.contains_key(target) {
                        return Err(control("jumps to a block with no body"));
                    }
                    conditional = true;
                    if !targets.contains(target) {
                        targets.push(*target);
                    }
                }
                X86Opcode::Jmp => {
                    if !last {
                        return Err(control("transfers control before the end of its block"));
                    }
                    let [O::Block(target)] = inst.operands.as_slice() else {
                        unreachable!("row shape checked above");
                    };
                    if !machine.blocks.contains_key(target) {
                        return Err(control("jumps to a block with no body"));
                    }
                    exit = Some(Some(*target));
                }
                X86Opcode::Ret => {
                    if !last {
                        return Err(control("returns before the end of its block"));
                    }
                    exit = Some(None);
                }
                // Slice 14: the indirect `jmp` of a jump-table dispatch block
                // transfers to each of its table's targets (checked against
                // the recorded successors below), and nowhere else.
                X86Opcode::JmpR => {
                    let Some(table) = dispatch.get(&current) else {
                        return Err(function(
                            "an indirect jump outside the selector's jump-table dispatch",
                        ));
                    };
                    for target in &machine.jump_tables[*table as usize].targets {
                        if !targets.contains(target) {
                            targets.push(*target);
                        }
                    }
                    exit = Some(None);
                }
                // A trap ends its block like a return.
                X86Opcode::Ud2 => {
                    if !last {
                        return Err(unsupported(X86BodyUnsupported::MachineRow {
                            row: ordinal,
                            detail: "Ud2 that does not end a block without successors".into(),
                        }));
                    }
                    exit = Some(None);
                }
                _ => {}
            }
        }
        let exit = match exit {
            Some(exit) => exit,
            // Fallthrough: the next block in layout.
            None => match machine.block_order.get(position + 1) {
                Some(following) => Some(*following),
                None => {
                    return Err(mismatch(X86BodyMismatch::Control {
                        block: current,
                        row: None,
                        detail: "ends without a return or jump and does not fall through to \
                                 its single recorded successor"
                            .into(),
                    }));
                }
            },
        };
        if let Some(exit) = exit
            && !targets.contains(&exit)
        {
            targets.push(exit);
        }
        let mut recorded = body.successors.clone();
        recorded.sort();
        let mut transfers = targets.clone();
        transfers.sort();
        if recorded != transfers {
            let last = body.insts.last().map(|inst| inst.opcode);
            let row = body.insts.len().checked_sub(1).map(|index| first + index);
            let detail = match (conditional, last) {
                (false, Some(X86Opcode::Jmp)) => {
                    "jumps to a block other than its single recorded successor".to_owned()
                }
                (false, Some(X86Opcode::Ret)) => "returns but records successors".to_owned(),
                (false, Some(X86Opcode::Ud2)) => {
                    return Err(unsupported(X86BodyUnsupported::MachineRow {
                        row: row.expect("a Ud2 row"),
                        detail: "Ud2 that does not end a block without successors".into(),
                    }));
                }
                (false, _) => "ends without a return or jump and does not fall through to its \
                               single recorded successor"
                    .to_owned(),
                (true, _) => format!(
                    "records successors {:?} where its jumps and fallthrough give {targets:?}",
                    body.successors
                ),
            };
            return Err(mismatch(X86BodyMismatch::Control {
                block: current,
                row: if conditional { None } else { row },
                detail,
            }));
        }
    }
    Ok(MachineCfg {
        machine,
        ordinals,
        has_jcc: machine
            .blocks
            .values()
            .flat_map(|block| &block.insts)
            .any(|inst| inst.opcode == X86Opcode::Jcc),
        correspondence: block_correspondence(source, machine, dead),
    })
}

/// The one-to-one correspondence of the laid-out machine blocks and the LIR
/// blocks (slice 6), or why there is none. It holds exactly when:
///
/// - every laid-out machine block's source-attributed rows name one LIR block
///   (their TV-1 stamps' block; the verifier cross-checks each stamp's
///   instruction digest against the LIR source, TV-2), its ORIGIN, and no
///   two machine blocks have one origin;
/// - every LIR block NOT in `dead` is some machine block's origin, the
///   machine's entry block lowering the LIR entry block;
/// - each such machine block's successors are, through their origins, exactly
///   its origin's LIR successors (as sets).
///
/// `dead` is [`SourceCfg::dead`], the LIR blocks no entry-to-end path reaches.
/// One of them may have a machine block (the selector lays dead blocks out) or
/// none (a pass pruned it); either way nothing is required of it, and NOTHING
/// IS CLAIMED ABOUT IT. That costs no soundness, because such a machine block
/// cannot run: the machine's entry block lowers the live LIR entry, and the
/// third condition makes every live-origin block's successors' origins exactly
/// its origin's LIR successors -- which are live, a live block's successors
/// being reachable. By induction every machine block reachable from the
/// machine entry has a live origin, so a dead-origin block is off the chain.
/// [`walk_machine_for_callers`] relies on exactly that induction. Over
/// segments ([`block_correspondence_over`]) it still holds: a segment's
/// machine block has a live origin (its head), and its successors' origins
/// are exactly the segment's exit targets, each a live block's successor.
///
/// A block with no attributed row or rows of several LIR blocks (a merge, a
/// tail duplicated into its predecessor, a row moved across blocks), a
/// block the selector or a pass added (a switch search node, a split edge),
/// a LIR block with no machine block (merged, if-converted, proved
/// unreachable), and a retargeted transfer (a jump threaded past a block, a
/// return duplicated into a predecessor) all break it (an if-converted
/// region over its checked segments excepted, slice 24c, below). Under it every source
/// path has exactly one paired machine path (the pairing can only disagree
/// on a `jcc`'s condition, which the theorem judges), so a machine CFG
/// without it makes no claim: its control is never named a mismatch.
///
/// The correspondence is read from the TV-1 lowering stamps, which this owner
/// TRUSTS: TV-2 checks a stamp's instruction digest and op class only after the
/// theorem, and accepts a restamp onto another real instruction of a compatible
/// class. Soundness does not rest on the stamps: whatever path they pair, the
/// theorem requires the machine's `jcc` conditions along it to hold whenever the
/// source path's do, so a forged pairing can only lose credit. A stamp set that
/// forges a correspondence the code does not have makes a CORRECT body fail
/// closed (refuted, or, when a trap block's and a return block's stamps are
/// swapped under equal successor sets, a named control mismatch); it never
/// credits a wrong one (2026-10-01: 17,669 stamp-perturbation x mutation cases,
/// every credited case correct by an independent interpreter).
///
/// Slice 24a (ruling OD-226): a block merge breaks it on the original pair;
/// where the walk needs it, the owner then states the pair's merged-chain
/// quotient ([`quotient`]), and this function, unchanged, judges the quotient
/// pair with every condition above. The caller annotates a refusal with why a
/// several-block machine block was not contracted
/// ([`quotient::Quotient::annotate`]). Slice 24c (ruling OD-228): where it
/// still fails, the owner states the pair over the checked segments the
/// stamps choose ([`segment::correspondence`], [`block_correspondence_over`]).
fn block_correspondence(
    source: &Function,
    machine: &X86ISelFunction,
    dead: &std::collections::BTreeSet<Block>,
) -> Result<Correspondence, String> {
    block_correspondence_over(source, machine, dead, &segment::Segments::none())
        .map_err(|(reason, _)| reason)
}

/// Slice 24c (ruling OD-228): [`block_correspondence`] over checked
/// `segments` ([`segment::check`]; [`segment::Segments::none`] for every
/// other pair, byte for byte the slice-6 rule). The machine block `m` of a
/// segment lowers its head `h` (`lowering[h] = m`, `origin[m] = h`: the map
/// stays one to one) and COVERS its other members, which no other machine
/// block may name ("both lower"); every live LIR block is lowered or
/// covered; a covered member's own successors are not compared, and `m`'s
/// must be, through their origins, EXACTLY the segment's exit targets (as
/// sets). Every refusal names where it failed ([`segment::Failing`]).
fn block_correspondence_over(
    source: &Function,
    machine: &X86ISelFunction,
    dead: &std::collections::BTreeSet<Block>,
    segments: &segment::Segments,
) -> Result<Correspondence, (String, segment::Failing)> {
    let at_machine = |block: Block| segment::Failing {
        machine: Some(block),
        lir: None,
    };
    let mut lowering: HashMap<Block, Block> = HashMap::new();
    let mut origin: HashMap<Block, Block> = HashMap::new();
    // Slice 24c: every LIR block some machine block lowers or covers, and
    // that block.
    let mut claimed: HashMap<Block, Block> = HashMap::new();
    // Slice 14: a jump-table dispatch block lowers no LIR block of its own;
    // it is part of the one block whose final `jmp` reaches it (below).
    // Slice 20 (OD-191): so is each block of a `Switch`'s binary search.
    let tables = dispatch_blocks(machine);
    let searched = search_blocks(source, machine, dead, &tables);
    for block in &machine.block_order {
        if tables.contains_key(block) || searched.contains_key(block) {
            continue;
        }
        // Slice 24c: a segment's machine block lowers its head and covers
        // its other members.
        if let Some(segment) = segments.of_machine(*block) {
            for member in &segment.members {
                if let Some(other) = claimed.insert(*member, *block) {
                    return Err((
                        format!(
                            "machine blocks {other:?} and {block:?} both lower LIR block \
                             {member:?}"
                        ),
                        at_machine(*block),
                    ));
                }
            }
            lowering.insert(segment.head, *block);
            origin.insert(*block, segment.head);
            continue;
        }
        let named: std::collections::BTreeSet<u32> = machine.blocks[block]
            .insts
            .iter()
            .filter_map(|inst| inst.lowering_provenance.source_id())
            .map(|id| id.block)
            .collect();
        let lir = match named.iter().copied().collect::<Vec<_>>().as_slice() {
            [only] => Block(*only),
            [] => {
                return Err((
                    format!("machine block {block:?} has no row attributed to a LIR instruction"),
                    at_machine(*block),
                ));
            }
            several => {
                // Say WHAT SHAPE the set is, not just that it has several
                // members. "lowers rows of several LIR blocks" is the same
                // message for a merged straight-line chain, an if-converted
                // diamond, a rotated loop header and a row a pass moved, and
                // those need different treatments. Each member is printed
                // with its live LIR predecessors and successors, and the row
                // COUNT it contributes, so the shape is readable directly.
                let live = |b: &Block| source.blocks.contains_key(b) && !dead.contains(b);
                let mut shape = String::new();
                for id in several {
                    let member = Block(*id);
                    let rows = machine.blocks[block]
                        .insts
                        .iter()
                        .filter(|inst| {
                            inst.lowering_provenance
                                .source_id()
                                .is_some_and(|sid| sid.block == *id)
                        })
                        .count();
                    let mut predecessors: Vec<Block> = source
                        .blocks
                        .keys()
                        .filter(|from| {
                            live(from) && lir_successors(&source.blocks[from]).contains(&member)
                        })
                        .copied()
                        .collect();
                    predecessors.sort_unstable();
                    let successors = source
                        .blocks
                        .get(&member)
                        .map(lir_successors)
                        .unwrap_or_default();
                    shape.push_str(&format!(
                        " {member:?}[{rows} row(s), pred {predecessors:?}, succ {successors:?}\
                         {}]",
                        if live(&member) { "" } else { ", DEAD" },
                    ));
                }
                return Err((
                    format!(
                        "machine block {block:?} lowers rows of several LIR blocks {several:?}:\
                         {shape}"
                    ),
                    at_machine(*block),
                ));
            }
        };
        if !source.blocks.contains_key(&lir) {
            return Err((
                format!("machine block {block:?} names LIR block {lir:?}, which has no body"),
                at_machine(*block),
            ));
        }
        if let Some(other) = claimed.insert(lir, *block) {
            return Err((
                format!("machine blocks {other:?} and {block:?} both lower LIR block {lir:?}"),
                at_machine(*block),
            ));
        }
        lowering.insert(lir, *block);
        origin.insert(*block, lir);
    }
    let mut lir_blocks: Vec<Block> = source
        .blocks
        .keys()
        .filter(|block| !dead.contains(*block))
        .copied()
        .collect();
    lir_blocks.sort();
    if let Some(missing) = lir_blocks.iter().find(|block| !claimed.contains_key(block)) {
        return Err((
            format!("LIR block {missing:?} has no machine block (merged, if-converted or removed)"),
            segment::Failing {
                machine: None,
                lir: Some(*missing),
            },
        ));
    }
    if origin.get(&machine.block_order[0]) != Some(&source.entry_block) {
        return Err((
            "the machine's first block does not lower the LIR entry block".into(),
            segment::Failing::default(),
        ));
    }
    // Slice 14: each dispatch block's owner: the one block that transfers to
    // it, with its final `jmp`, and whose LIR block the dispatch's rows are
    // stamped with (the `Switch` it dispatches).
    let mut dispatch: HashMap<Block, Block> = HashMap::new();
    for table_block in tables.keys() {
        let owners: Vec<Block> = machine
            .block_order
            .iter()
            .filter(|block| machine.blocks[*block].successors.contains(table_block))
            .copied()
            .collect();
        let [owner] = owners.as_slice() else {
            return Err((
                format!(
                    "jump-table dispatch block {table_block:?} is reached from {} blocks",
                    owners.len()
                ),
                at_machine(*table_block),
            ));
        };
        let jumps = matches!(
            machine.blocks[owner].insts.last().map(|inst| (inst.opcode, inst.operands.as_slice())),
            Some((X86Opcode::Jmp, [O::Block(target)])) if target == table_block
        );
        let stamped = machine.blocks[table_block].insts.iter().all(|inst| {
            inst.lowering_provenance
                .source_id()
                .map(|id| Block(id.block))
                == origin.get(owner).copied()
        });
        if !jumps || !stamped || tables.contains_key(owner) {
            return Err((
                format!(
                    "jump-table dispatch block {table_block:?} is not the tail of the block that \
                     lowers its Switch"
                ),
                at_machine(*table_block),
            ));
        }
        dispatch.insert(*table_block, *owner);
    }
    // Slice 20: each search block's owner, the block that lowers its
    // `Switch`'s LIR block.
    let mut search = HashSet::new();
    let mut searches: Vec<(&Block, &Block)> = searched.iter().collect();
    searches.sort();
    for (block, lir) in searches {
        let Some(owner) = lowering.get(lir) else {
            return Err((
                format!(
                    "binary-search block {block:?} dispatches LIR block {lir:?}, which no \
                     machine block lowers"
                ),
                at_machine(*block),
            ));
        };
        dispatch.insert(*block, *owner);
        search.insert(*block);
    }
    for lir in &lir_blocks {
        // Slice 24c: a covered member's successors are its segment's; the
        // segment's machine block must reach exactly its exit targets.
        if segments.inner(*lir).is_some() {
            continue;
        }
        let segment = segments.of_head(*lir);
        let body = &machine.blocks[&lowering[lir]];
        let expected: std::collections::BTreeSet<Block> = match segment {
            Some(segment) => segment.targets().into_iter().collect(),
            None => lir_successors(&source.blocks[lir]).into_iter().collect(),
        };
        // A dispatch block's successors are its owner's (slice 20: through
        // every search block of its owner's `Switch`, transitively).
        let mut reached: Vec<Block> = Vec::new();
        let mut work: Vec<Block> = body.successors.clone();
        let mut walked: HashSet<Block> = HashSet::new();
        while let Some(successor) = work.pop() {
            if tables.contains_key(&successor) {
                reached.extend(machine.blocks[&successor].successors.iter().copied());
            } else if searched.get(&successor) == Some(lir) {
                if walked.insert(successor) {
                    work.extend(machine.blocks[&successor].successors.iter().copied());
                }
            } else {
                reached.push(successor);
            }
        }
        let actual: Option<std::collections::BTreeSet<Block>> = reached
            .into_iter()
            .map(|successor| origin.get(&successor).copied())
            .collect();
        let Some(segment) = segment else {
            if actual.as_ref() != Some(&expected) {
                return Err((
                    format!(
                        "machine block {:?} (LIR block {lir:?}) continues to LIR blocks \
                         {actual:?} where the LIR block continues to {expected:?}",
                        lowering[lir]
                    ),
                    at_machine(lowering[lir]),
                ));
            }
            continue;
        };
        let holds = match &actual {
            Some(actual) if mutated("s24c-equality-to-subset") => actual.is_subset(&expected),
            Some(actual) => *actual == expected,
            None => false,
        };
        if !holds {
            return Err((
                format!(
                    "machine block {:?} (the segment of {lir:?}: {:?}) continues to LIR blocks \
                     {actual:?} where the segment exits to {expected:?}",
                    lowering[lir], segment.members
                ),
                at_machine(lowering[lir]),
            ));
        }
    }
    Ok(Correspondence {
        lowering,
        origin,
        dispatch,
        search,
        segments: segments.clone(),
    })
}

/// The targets of a LIR block's terminator (an admitted body's: `Jump`,
/// `Brif`, `Switch`, `Return`, `Trap`).
fn lir_successors(block: &trust_cg_lower::function::BasicBlock) -> Vec<Block> {
    match block.instructions.last().map(|inst| &inst.opcode) {
        Some(L::Jump { dest }) => vec![*dest],
        Some(L::Brif {
            then_dest,
            else_dest,
            ..
        }) => vec![*then_dest, *else_dest],
        Some(L::Switch { cases, default }) => cases
            .iter()
            .map(|(_, target)| *target)
            .chain(std::iter::once(*default))
            .collect(),
        _ => Vec::new(),
    }
}

/// The machine rows of a one-path source whose machine has no conditional
/// jump (slices 1 to 5): the chain from the entry block, following each
/// block's `jmp` or fallthrough to its `ret` or `ud2`, whatever the blocks'
/// ids or number (an optimizer may merge or renumber them). A block reached
/// twice (a cycle) is [`X86BodyMismatch::Control`]. Every block the chain
/// reaches is added to `visited`.
fn machine_chain<'m>(
    cfg: &MachineCfg<'m>,
    visited: &mut HashSet<Block>,
) -> Result<Vec<PathRow<'m>>, X86BodyRefusal> {
    let machine = cfg.machine;
    let mut rows = Vec::new();
    let mut current = machine.block_order[0];
    loop {
        if !visited.insert(current) {
            return Err(mismatch(X86BodyMismatch::Control {
                block: current,
                row: None,
                detail: "is reached twice: the machine chain is cyclic".into(),
            }));
        }
        let body = &machine.blocks[&current];
        let first = cfg.ordinals[&current];
        let mut next = None;
        let mut ended = false;
        for (index, inst) in body.insts.iter().enumerate() {
            let row = Row {
                ordinal: first + index,
                block: current,
                inst,
            };
            match (inst.opcode, inst.operands.as_slice()) {
                (X86Opcode::Jmp, [O::Block(target)]) => next = Some(*target),
                (X86Opcode::Ret | X86Opcode::Ud2, _) => ended = true,
                _ => {}
            }
            rows.push(PathRow {
                row,
                taken: None,
                jump: None,
            });
        }
        if ended {
            return Ok(rows);
        }
        // The skeleton checked the block's transfers: its `jmp` target, or
        // the next block in layout it falls through to.
        current = match next {
            Some(target) => target,
            None => {
                let position = machine
                    .block_order
                    .iter()
                    .position(|block| *block == current)
                    .expect("walked blocks are laid out");
                machine.block_order[position + 1]
            }
        };
    }
}

/// The machine rows one source path runs through (slice 6), paired by the
/// block correspondence ([`block_correspondence`]): from the machine block
/// that lowers the LIR entry block, rows run in order; a `jcc` is TAKEN
/// exactly when its target lowers the source path's next block, else not
/// taken (the walk states which, and the theorem the condition under which
/// the machine does so); a `jmp` or a fallthrough reaches the block that
/// lowers the next one; the path's last block ends in its `ret` or `ud2`.
/// Every block the pairing reaches is added to `visited`.
///
/// Every step is a real machine transfer, so the paired rows are what the
/// machine executes whenever the theorem's `jcc` literals hold: the pairing
/// only chooses which machine path each source path is judged against. Under
/// the correspondence it always finds one (the successor sets agree); a
/// `jcc` whose fallthrough also reaches its target is ambiguous. Anything it
/// cannot pair makes no claim, never a named mismatch. Slice 24c (OD-228): a
/// path through a segment runs its machine block once, from its head to the
/// block that lowers the path's exit target (members take no machine step),
/// after the segment's effects rule holds on the path
/// ([`segment::path_effects`]).
fn machine_path<'m>(
    cfg: &MachineCfg<'m>,
    correspondence: &Correspondence,
    program: &SourceProgram,
    visited: &mut HashSet<Block>,
) -> Result<Vec<PathRow<'m>>, X86BodyRefusal> {
    let machine = cfg.machine;
    let no_claim = |detail: String| unsupported(X86BodyUnsupported::MachineFunction(detail));
    let lowering = |lir: &Block| {
        if mutated("s24c-member-rewalk") {
            correspondence.machine_of(*lir)
        } else {
            correspondence.lowering.get(lir).copied()
        }
    };
    // Slice 24c (OD-228): the effects rule of every segment the path enters,
    // before any pairing.
    segment::path_effects(&correspondence.segments, program)?;
    let mut rows = Vec::new();
    let mut current = machine.block_order[0];
    if Some(current) != program.blocks.first().and_then(lowering) {
        return Err(no_claim(
            "the machine's first block does not lower the path's first block".into(),
        ));
    }
    for next in program
        .blocks
        .iter()
        .skip(1)
        .map(Some)
        .chain(std::iter::once(None))
    {
        visited.insert(current);
        // Slice 24c: consecutive members of one segment take no machine
        // step; its machine block's route is taken at the exit.
        if let Some(next) = next
            && correspondence
                .segments
                .inner(*next)
                .is_some_and(|segment| segment.machine == current)
            && !mutated("s24c-member-rewalk")
        {
            continue;
        }
        let next_machine = match next {
            Some(next) => Some(lowering(next).ok_or_else(|| {
                no_claim(format!("the source block {next:?} has no machine block"))
            })?),
            None => None,
        };
        match next_machine {
            // Slice 14: the route to the next block ([`block_routes`]),
            // through a jump-table dispatch block too; a path states one.
            Some(next) => {
                let routes = block_routes(cfg, correspondence, current, next)?;
                let [route] = routes.as_slice() else {
                    return Err(no_claim(format!(
                        "block {current:?} reaches block {next:?} by {} routes, which one path \
                         does not state",
                        routes.len()
                    )));
                };
                visited.extend(route.iter().map(|path_row| path_row.row.block));
                rows.extend(route.iter().copied());
            }
            None => rows.extend(block_rows(cfg, correspondence, current, None)?),
        }
        let Some(next_machine) = next_machine else {
            break;
        };
        current = next_machine;
    }
    Ok(rows)
}

/// The rows machine block `current` runs on the way to machine block `next`
/// (`None`: the path ends in `current`), paired as [`machine_path`]
/// describes: rows in order; a `jcc` TAKEN exactly when its target is
/// `next` (then the block's later rows do not run), else not taken; a `jmp`
/// or the fallthrough must reach `next`, and a last block must end in its
/// `ret` or `ud2`. A path walks it once per block; a DAG (slice 9) once per
/// outgoing edge. Anything it cannot pair makes no claim.
fn block_rows<'m>(
    cfg: &MachineCfg<'m>,
    correspondence: &Correspondence,
    current: Block,
    next_machine: Option<Block>,
) -> Result<Vec<PathRow<'m>>, X86BodyRefusal> {
    let machine = cfg.machine;
    let no_claim = |detail: String| unsupported(X86BodyUnsupported::MachineFunction(detail));
    let mut rows = Vec::new();
    let body = &machine.blocks[&current];
    let first = cfg.ordinals[&current];
    let position = machine
        .block_order
        .iter()
        .position(|block| *block == current)
        .expect("walked blocks are laid out");
    // Where control goes when this block's rows from `index` on do not
    // jump: the exit of the block (its final `jmp` target, or its
    // fallthrough), `None` for a `ret`/`ud2`.
    let exit_after = |index: usize| -> Option<Block> {
        for inst in &body.insts[index..] {
            match (inst.opcode, inst.operands.as_slice()) {
                (X86Opcode::Jmp, [O::Block(target)]) => return Some(*target),
                (X86Opcode::Ret | X86Opcode::Ud2, _) => return None,
                _ => {}
            }
        }
        machine.block_order.get(position + 1).copied()
    };
    let mut moved = None;
    let mut ended = false;
    for (index, inst) in body.insts.iter().enumerate() {
        let ordinal = first + index;
        let row = Row {
            ordinal,
            block: current,
            inst,
        };
        match (inst.opcode, inst.operands.as_slice()) {
            (X86Opcode::Jcc, [_, O::Block(target)]) => {
                let taken = next_machine == Some(*target);
                if taken {
                    // Unambiguous: the fallthrough continuation must not
                    // reach the same block by another jump.
                    let also = body.insts[index + 1..].iter().any(|later| {
                        matches!(
                            (later.opcode, later.operands.as_slice()),
                            (X86Opcode::Jcc, [_, O::Block(other)])
                                | (X86Opcode::Jmp, [O::Block(other)])
                                if other == target
                        )
                    }) || exit_after(index + 1) == Some(*target);
                    if also {
                        return Err(unsupported(X86BodyUnsupported::MachineRow {
                            row: ordinal,
                            detail: format!(
                                "Jcc to {target:?} whose fallthrough also reaches {target:?}"
                            ),
                        }));
                    }
                }
                rows.push(PathRow {
                    row,
                    taken: Some(taken),
                    jump: None,
                });
                if taken {
                    moved = Some(*target);
                    break;
                }
            }
            (X86Opcode::Jmp, [O::Block(target)]) => {
                rows.push(PathRow {
                    row,
                    taken: None,
                    jump: None,
                });
                moved = Some(*target);
            }
            (X86Opcode::Ret | X86Opcode::Ud2, _) => {
                rows.push(PathRow {
                    row,
                    taken: None,
                    jump: None,
                });
                ended = true;
            }
            _ => rows.push(PathRow {
                row,
                taken: None,
                jump: None,
            }),
        }
    }
    let Some(next_machine) = next_machine else {
        // The path's last block: it must end in its `ret` or `ud2`.
        if !ended {
            return Err(no_claim(format!(
                "block {current:?} continues where the source path ends"
            )));
        }
        return Ok(rows);
    };
    if ended {
        return Err(no_claim(format!(
            "block {current:?} ends where the source path continues to block {:?}",
            correspondence.origin[&next_machine]
        )));
    }
    let target = moved.or_else(|| machine.block_order.get(position + 1).copied());
    if target != Some(next_machine) {
        return Err(no_claim(format!(
            "block {current:?} transfers control to {target:?} where the source path \
             continues to block {:?}",
            correspondence.origin[&next_machine]
        )));
    }
    Ok(rows)
}

/// Slice 14: every ROUTE by which machine block `current` reaches machine
/// block `next`, each the rows it runs ([`PathRow`]s, `jcc` directions
/// recorded): for each `jcc` to `next`, the rows up to it with every earlier
/// `jcc` not taken and it taken; and, when the block's exit (its final `jmp`
/// or its fallthrough) is `next`, every row with every `jcc` not taken. A
/// `Switch` several of whose cases share a target (one source edge,
/// [`switch_targets`]) is lowered to a compare chain with one `je` per case,
/// and its default's `jmp` may reach the same block: the machine reaches the
/// block exactly when one of these routes' `jcc` literals all hold, and the
/// routes exclude each other (each requires the `jcc`s before its own not
/// taken). With one route this is [`block_rows`]'s pairing, row for row.
/// A route that reaches a `ret` or `ud2` first, or a `jmp` elsewhere, is no
/// route. Every route is a real machine transfer, so pairing an edge with
/// all of them decides nothing the theorem does not state.
///
/// Slice 20 (ruling OD-191): a route continues depth first through every
/// binary-search block of `current`'s `Switch` ([`search_blocks`]) that a
/// `jcc` taken or the exit reaches: a route to a target is then the rows of
/// `current` and of each search block on one root-to-leaf path of the tree,
/// each `jcc` taken or not (the default is reached by several such routes).
/// A route that would enter one search block twice is no route.
fn block_routes<'m>(
    cfg: &MachineCfg<'m>,
    correspondence: &Correspondence,
    current: Block,
    next_machine: Block,
) -> Result<Vec<Vec<PathRow<'m>>>, X86BodyRefusal> {
    let no_claim = |detail: String| unsupported(X86BodyUnsupported::MachineFunction(detail));
    let mut routes = Vec::new();
    let mut entered = Vec::new();
    routes_through(
        cfg,
        correspondence,
        current,
        current,
        Vec::new(),
        next_machine,
        &mut entered,
        &mut routes,
    );
    if routes.is_empty() {
        return Err(no_claim(format!(
            "block {current:?} has no route to block {next_machine:?}, where the source \
             continues to block {:?}",
            correspondence.origin[&next_machine]
        )));
    }
    Ok(routes)
}

/// The routes of [`block_routes`] from the rows of machine block `block` (the
/// owner `owner`, or one of its search blocks), after the rows `prefix` that
/// lead to it; `entered` holds the search blocks the route has entered.
#[allow(clippy::too_many_arguments)]
fn routes_through<'m>(
    cfg: &MachineCfg<'m>,
    correspondence: &Correspondence,
    owner: Block,
    block: Block,
    mut prefix: Vec<PathRow<'m>>,
    next_machine: Block,
    entered: &mut Vec<Block>,
    routes: &mut Vec<Vec<PathRow<'m>>>,
) {
    let machine = cfg.machine;
    let body = &machine.blocks[&block];
    let first = cfg.ordinals[&block];
    let position = machine
        .block_order
        .iter()
        .position(|laid| *laid == block)
        .expect("walked blocks are laid out");
    // A search block of `owner`'s `Switch` that a route may enter (once).
    let searchable = |target: &Block, entered: &[Block]| {
        correspondence.search.contains(target)
            && correspondence.dispatch.get(target) == Some(&owner)
            && !entered.contains(target)
    };
    let mut exit = machine.block_order.get(position + 1).copied();
    for (index, inst) in body.insts.iter().enumerate() {
        let row = Row {
            ordinal: first + index,
            block,
            inst,
        };
        match (inst.opcode, inst.operands.as_slice()) {
            (X86Opcode::Jcc, [_, O::Block(target)]) => {
                let mut taken = prefix.clone();
                taken.push(PathRow {
                    row,
                    taken: Some(true),
                    jump: None,
                });
                if *target == next_machine {
                    routes.push(taken);
                } else if searchable(target, entered) {
                    entered.push(*target);
                    routes_through(
                        cfg,
                        correspondence,
                        owner,
                        *target,
                        taken,
                        next_machine,
                        entered,
                        routes,
                    );
                    entered.pop();
                }
                prefix.push(PathRow {
                    row,
                    taken: Some(false),
                    jump: None,
                });
            }
            (X86Opcode::Jmp, [O::Block(target)]) => {
                prefix.push(PathRow {
                    row,
                    taken: None,
                    jump: None,
                });
                exit = Some(*target);
                break;
            }
            (X86Opcode::Ret | X86Opcode::Ud2, _) => {
                prefix.push(PathRow {
                    row,
                    taken: None,
                    jump: None,
                });
                exit = None;
                break;
            }
            _ => prefix.push(PathRow {
                row,
                taken: None,
                jump: None,
            }),
        }
    }
    match exit {
        Some(exit) if exit == next_machine => routes.push(prefix),
        // Slice 20: on into a search block of the same `Switch`.
        Some(exit) if searchable(&exit, entered) => {
            entered.push(exit);
            routes_through(
                cfg,
                correspondence,
                owner,
                exit,
                prefix,
                next_machine,
                entered,
                routes,
            );
            entered.pop();
        }
        // Slice 14: the block's final `jmp` reaches its jump-table dispatch
        // block: one route continues through the dispatch's rows to every
        // target its table names, the indirect `jmp` recording which
        // ([`PathRow::jump`]; the walk states the table indices that lead
        // there).
        Some(exit)
            if block == owner
                && !correspondence.search.contains(&exit)
                && correspondence.dispatch.get(&exit) == Some(&owner) =>
        {
            let table = &machine.blocks[&exit];
            if table.successors.contains(&next_machine) {
                let first = cfg.ordinals[&exit];
                let mut route = prefix;
                for (index, inst) in table.insts.iter().enumerate() {
                    route.push(PathRow {
                        row: Row {
                            ordinal: first + index,
                            block: exit,
                            inst,
                        },
                        taken: None,
                        jump: (inst.opcode == X86Opcode::JmpR).then_some(next_machine),
                    });
                }
                routes.push(route);
            }
        }
        _ => {}
    }
}

// ---------------------------------------------------------------------------
// Machine translator (x86 stream only)
// ---------------------------------------------------------------------------

/// The full 64-bit content of one root.
#[derive(Clone)]
struct Slot {
    expr: E,
    /// Exact affine value over the `I64` source parameters, or `None` when the
    /// value depends on anything else (a preserved root's entry value, a
    /// narrow parameter's register, a non-affine operation); no refusal is
    /// derived then.
    affine: Option<Affine>,
}

/// What a register root holds.
#[derive(Clone)]
enum RegValue {
    /// Bits: the root's full 64-bit content.
    Bits(Slot),
    /// A private stack address (slice 4). It is only ever a load/store
    /// address or copied/offset into another register; reading it as bits
    /// makes the slot escape, which is outside the domain.
    Frame(FrameAddr),
    /// Slice 9: the paths into a DAG join leave the root holding different
    /// private addresses, or an address on some and bits on others. Any read
    /// of it is outside the domain (no claim); a write redefines it.
    Mixed,
    /// Slice 12: at a loop header, a root some edge into the header leaves
    /// other than the entry edge does (the loop writes it) and that is paired
    /// with no header parameter. Any read of it is outside the domain (no
    /// claim): the machine's loop-carried registers must be exactly the
    /// source's header parameters. A write redefines it.
    Carried,
    /// Slice 14: a value of a jump-table dispatch ([`TableValue`]), no SMT
    /// term. Only the dispatch's own rows read it; any other read is outside
    /// the domain.
    Dispatch(TableValue),
    /// Slice 17: a private stack address at a non-constant offset
    /// ([`MachineIndexed`]). Like a frame address it is only ever an access's
    /// address, copied or offset into another register, or a call's
    /// argument; reading it as bits makes the slot escape (no claim).
    Indexed(MachineIndexed),
}

/// A machine private stack address at a non-constant offset (slice 17):
/// slot `slot` plus the constant `base` plus the 64-bit term `offset`,
/// wrapping. Its offset is whatever the rows that formed it compute (`add` of
/// a frame register and a value, `lea` with a scaled index), judged as a term
/// by the solver, never matched against the source's.
#[derive(Clone, PartialEq)]
struct MachineIndexed {
    slot: u32,
    base: i64,
    offset: E,
}

impl MachineIndexed {
    /// The address plus a constant.
    fn offset_by(&self, delta: i64) -> Option<Self> {
        Some(Self {
            slot: self.slot,
            base: self.base.checked_add(delta)?,
            offset: self.offset.clone(),
        })
    }

    /// The full offset into the slot, as one term ([`indexed::offset_term`]).
    fn term(&self) -> E {
        indexed::offset_term(self.base, self.offset.clone())
    }
}

/// A value of a jump-table dispatch (slice 14): the walk tracks the table's
/// address, the entry loaded from it and the target address formed from that
/// entry, never their bits, as it tracks a private stack address. Trusted:
/// that the codegen emits table `table` into the function's own `.text`
/// after its body, entry `i` the 8-byte signed delta of the block
/// `targets[i]` names from the table's base, and patches the RIP-relative
/// `lea` to that base (the pipeline's `jt_fixups`), as a symbol's address is
/// trusted; the targets themselves are the selector's table, which the walk
/// reads.
#[derive(Clone, PartialEq)]
enum TableValue {
    /// The address of jump table `table` (`lea r, [rip + table]`).
    Base(u32),
    /// The entry at `index` (a 64-bit term) of the table (`mov r, [b +
    /// index*8]`).
    Entry { table: u32, index: E },
    /// The address of the block that entry names (`add r, b`).
    Target { table: u32, index: E },
}

/// One byte of a machine private stack slot: byte `byte` (low byte 0) of the
/// `width`-bit `term` a store wrote.
#[derive(Clone)]
struct MachineByte {
    term: E,
    width: u32,
    byte: u32,
    /// Exact affine value of a 64-bit stored term, when known.
    affine: Option<Affine>,
    /// Slice 13: the private stack address an 8-byte store wrote as data
    /// (`term` is its [`frame_address_term`]).
    frame: Option<FrameAddr>,
    /// Slice 17 (OD-184): a byte its cut point leaves out as dead: unreadable
    /// (a read makes no claim), `term` meaningless.
    dead: bool,
}

impl MachineByte {
    /// A byte its cut point leaves out as dead (slice 17).
    fn dead() -> Self {
        Self {
            term: E::bv_const(0, 8),
            width: 8,
            byte: 0,
            affine: None,
            frame: None,
            dead: true,
        }
    }

    fn expr(&self) -> E {
        if self.width == 8 {
            self.term.clone()
        } else {
            self.term.clone().extract(8 * self.byte + 7, 8 * self.byte)
        }
    }
}

/// Where a load or store row's `[base + disp]` operand or (slice 25) its
/// scaled-index operand ([`SibAddress`]) points.
enum AccessTarget {
    /// A private stack address.
    Stack(FrameAddr),
    /// Slice 13: the incoming stack eightbyte of parameter `index`, at this
    /// frame-pointer displacement (a load only).
    StackParameter(usize, i32),
    /// Slice 13: this offset of the open outgoing argument area (a store
    /// only).
    Outgoing(usize),
    /// Incoming memory at this 64-bit address (with its exact affine value
    /// when known).
    Incoming(E, Option<Affine>),
    /// Slice 17: a private stack address at a non-constant offset.
    Indexed(MachineIndexed),
}

/// A private stack address the machine walk tracks (slice 17): at a constant
/// offset, or indexed.
#[derive(Clone)]
enum MachinePrivate {
    Frame(FrameAddr),
    Indexed(MachineIndexed),
}

impl MachinePrivate {
    fn offset_by(&self, delta: i64) -> Option<Self> {
        match self {
            Self::Frame(address) => address.offset_by(delta).map(Self::Frame),
            Self::Indexed(address) => address.offset_by(delta).map(Self::Indexed),
        }
    }

    /// The address plus the 64-bit term `amount` (an indexed address).
    fn indexed_by(&self, amount: E) -> Self {
        match self {
            Self::Frame(address) => Self::Indexed(MachineIndexed {
                slot: address.slot,
                base: address.offset,
                offset: amount,
            }),
            Self::Indexed(address) => Self::Indexed(MachineIndexed {
                slot: address.slot,
                base: address.base,
                offset: address.offset.clone().bvadd(amount),
            }),
        }
    }

    fn slot(&self) -> u32 {
        match self {
            Self::Frame(address) => address.slot,
            Self::Indexed(address) => address.slot,
        }
    }
}

/// Slice 25: whether a `MovRMSib` row is a data load (the walk's memory
/// branch), not slice 14's jump-table load: it has the whole scaled-index
/// access shape ([`sib_access_shaped`]: a virtual destination and virtual
/// components), and its base is a stack slot or a register that holds no
/// jump-table dispatch value. A table is read only by its dispatch block's
/// own load (the walk's jump-table arm refuses a read of it in any other
/// block), and a data load is never read as a table.
fn sib_routes_to_memory(inst: &X86ISelInst, state: &HashMap<Root, RegValue>) -> bool {
    if !sib_access_shaped(inst) && !mutated("s25-routing-operand-only") {
        return false;
    }
    match inst
        .operands
        .get(1)
        .and_then(sib_operand)
        .map(|operand| operand.base)
    {
        Some(SibBase::Slot(_)) => true,
        Some(SibBase::Register(reg)) => {
            !matches!(state.get(&reg.root), Some(RegValue::Dispatch(_)))
        }
        None => false,
    }
}

/// The address a scaled-index operand reaches (slice 25, the walk's
/// `sib_address`): a private stack address, or 64-bit bits with their affine
/// value.
enum SibAddress {
    Private(MachinePrivate),
    Bits(E, Option<Affine>),
}

/// One machine incoming-memory access as the walk saw it, paired with the
/// source access in the same trace position.
struct WalkedAccess {
    /// Walk ordinal of the load/store row.
    row: usize,
    /// The 64-bit address.
    address: E,
    address_affine: Option<Affine>,
    /// A store's value at its memory width; `None` for a load.
    value: Option<E>,
    value_affine: Option<Affine>,
    /// Slice 15: an access through an address that may derive from an
    /// escaped slot: the escaped slots' contents at the access, in
    /// [`slot_chunks`] items (empty for any other access).
    slots: Vec<E>,
    /// Slice 14: the machine's `(stopped, trapped)` bits when it reaches
    /// the access ([`MachineState::stopped`]).
    stop: (E, E),
}

/// Low `bits` bits of a 64-bit root value.
fn low(expr: E, bits: u32) -> E {
    if bits == 64 {
        expr
    } else {
        expr.extract(bits - 1, 0)
    }
}

/// Zero-extend a `bits`-bit value to the 64-bit root it is written into.
fn widen(expr: E, bits: u32) -> E {
    if bits == 64 {
        expr
    } else {
        expr.zero_ext(64 - bits)
    }
}

/// One machine direct call as the walk saw it.
struct WalkedCall {
    /// Walk ordinal of the `Call` row.
    row: usize,
    /// Slice 10: the 64-bit callee register of a `CallR` row at the call
    /// (`None` for a direct `Call`).
    callee: Option<E>,
    /// Each argument register at the call, at its ABI width (the bits the
    /// callee reads), in System V order; an argument that passes a private
    /// stack address (slice 7) is checked by the walk and not listed.
    args: Vec<E>,
    /// Exact affine value of each 64-bit argument, when known (`None` for a
    /// private stack address), one per argument.
    arg_affine: Vec<Option<Affine>>,
    /// The contents, at the call, of every slot whose address escaped to it
    /// or an earlier call (slice 7), in [`slot_chunks`] items, ascending by
    /// slot.
    slots: Vec<E>,
    /// Slice 14: the machine's `(stopped, trapped)` bits when it reaches
    /// the call ([`MachineState::stopped`]).
    stop: (E, E),
}

/// Slice 21 (ruling OD-198): one SSE rounding row the walk paired with the
/// source's next rounding event: the operands it read, which the theorem
/// observes against the source event's ([`SourceFloat::args`]), and (an
/// unsigned source conversion) the claimed-clear bit 63, `#b0`.
struct WalkedFloat {
    /// Walk ordinal of the row.
    row: usize,
    /// The operands at the event's operand width, in order (then `#b0` for
    /// the top-bit claim of an unsigned conversion).
    args: Vec<E>,
    /// The machine's `(stopped, trapped)` bits when it reaches the row
    /// (slice 14).
    stop: (E, E),
}

/// One walk of one machine path under one caller convention. Its
/// definitions and undefined values live in the convention's
/// [`MachineNames`], which every path's walk shares.
struct Walked {
    /// Entry names of every argument and preserved root, in declaration order
    /// (the builder declares a preserved root only where it is read).
    entry_names: Vec<String>,
    /// Caller-view definitions of B1 argument registers, in parameter order.
    abi_views: Vec<(String, E)>,
    /// The full 64-bit result registers at the RET, in result-lane order
    /// (RAX, then RDX); empty for a void body or a path that traps.
    returns: Vec<E>,
    return_affine: Vec<Option<Affine>>,
    calls: Vec<WalkedCall>,
    /// Incoming-memory accesses, paired in order with the source's.
    accesses: Vec<WalkedAccess>,
    /// Slice 21: the rounding rows paired with the source's rounding events,
    /// in order.
    floats: Vec<WalkedFloat>,
    /// The condition under which the machine runs this path (slice 6): for
    /// each `jcc` on it, in order, the x86 condition over the flags it reads
    /// when the path takes the jump, else its negation.
    literals: Vec<E>,
    bound_rows: Vec<usize>,
    /// Slice 14: the machine's `(stopped, trapped)` bits at the end of the
    /// walk ([`MachineState::stopped`]).
    end_stop: (E, E),
    /// Slice 17: the in-bounds claim of each indexed access and argument the
    /// walk ran ([`indexed::in_bounds`]), in row order.
    indexed: Vec<E>,
}

/// Where an undefined machine value is read, which names its free input:
/// the bits a narrow load or a `setcc` at this row leaves undefined. (A
/// private stack byte the body never wrote is the slot's initial byte,
/// `f{k}`, which the source and every walk share.)
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
enum UndefinedSite {
    Row(usize),
}

/// The names one caller convention's walks give machine values, shared by
/// the walks of every path of a body (slice 6): a row that defines the same
/// expression on two paths (their shared prefix) defines one name, and an
/// undefined value read at one site is one free input on every path. On a
/// one-path body the numbering is the chain's own (slices 1 to 5).
#[derive(Clone)]
struct MachineNames {
    convention: BoolArguments,
    /// Several paths (slice 6): a row whose value is another name's (a
    /// copy) defines no name of its own; see [`build_theorem`].
    elide_aliases: bool,
    /// Each definition in creation order: its name, expression and row.
    definitions: Vec<(String, E, usize)>,
    defined: HashMap<(usize, E), String>,
    /// Each undefined value's free input and width, in creation order.
    undefined: Vec<(String, u32)>,
    undefined_at: HashMap<UndefinedSite, E>,
    /// Slice 14: each `div`/`idiv` of a canonical dividend, in walk order
    /// ([`pair_divisions`]).
    divisions: Vec<MachineDivision>,
    /// Slice 23 (OD-205): each arithmetic row's operator key, operands and
    /// the names it defines from them, in walk order ([`pair_arithmetic`]).
    arith: Vec<MachineArith>,
    /// Slice 21 (OD-198): each FP leaf of a rounding row the walk paired
    /// with no source event ([`BoolArguments::float_leaf_name`]) and its
    /// width, in creation order, and the row that names it.
    float_leaves: Vec<(String, u32)>,
    float_leaf_at: HashMap<usize, E>,
}

/// Slice 14: a `div`/`idiv` whose dividend the walk took as its low half
/// extended (the selector's zero or `cqo`/`cdq` high half), so that its
/// quotient and remainder are [`division`] of `dividend` and `divisor`, as
/// the source's are: what [`pair_divisions`] needs to restate them.
#[derive(Clone)]
struct MachineDivision {
    /// The LIR instruction the row is stamped with (block, index).
    stamp: (Block, usize),
    signed: bool,
    /// The width the row divides at (32 or 64).
    bits: u32,
    dividend: E,
    divisor: E,
    /// The names of the values the row writes to RAX and RDX.
    quotient: String,
    remainder: String,
}

/// Slice 23 (ruling OD-205): one machine arithmetic row as the walk
/// transcribed it: the LIR instruction its TV-1 stamp names, its operator key
/// ([`ArithKey`]), its operands `(c, d)` as the walk read them, and each name
/// the row defines from `K(c, d)` with the part of it the name holds. A
/// record is only a candidate: [`pair_arithmetic`] pairs it only when each
/// name's definition is that part of `K(c, d)` (the row's own transcription)
/// and the stamp names exactly one source operation of the same key.
#[derive(Clone)]
struct MachineArith {
    stamp: (Block, usize),
    key: ArithKey,
    operands: (E, E),
    results: Vec<(String, ArithPart)>,
}

/// Which part of `K(c, d)` a machine name holds, at the row's width and
/// zero-extended to the 64-bit register ([`widen`]) as the walk writes it.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ArithPart {
    /// The whole value (a product's low half, a quotient, a remainder, a
    /// shifted value).
    Whole,
    /// The high half of a widening product (`mul`'s RDX).
    High,
}

impl ArithPart {
    /// The term a name holding this part of `value` (the key's term at the
    /// row's operand width `bits`) is defined as.
    fn of(self, value: E, bits: u32) -> E {
        match self {
            Self::Whole => widen(value, bits),
            Self::High => widen(value.extract(2 * bits - 1, bits), bits),
        }
    }
}

impl MachineNames {
    /// Slice 23 (OD-205): record an arithmetic row ([`MachineArith`]) once
    /// per name it defines.
    fn record_arith(&mut self, arith: MachineArith) {
        let known = self.arith.iter().any(|recorded| {
            recorded.key == arith.key
                && recorded
                    .results
                    .iter()
                    .map(|(name, _)| name)
                    .eq(arith.results.iter().map(|(name, _)| name))
        });
        if !known {
            self.arith.push(arith);
        }
    }

    fn new(convention: BoolArguments, elide_aliases: bool) -> Self {
        Self {
            convention,
            elide_aliases,
            definitions: Vec::new(),
            defined: HashMap::new(),
            undefined: Vec::new(),
            undefined_at: HashMap::new(),
            divisions: Vec::new(),
            arith: Vec::new(),
            float_leaves: Vec::new(),
            float_leaf_at: HashMap::new(),
        }
    }

    /// Slice 21 (OD-198): the FP leaf naming the result of the rounding row
    /// `row` that no source event pairs, `width` bits: one free input per
    /// row, which the theorem holds for every value of (the real result's
    /// among them).
    fn float_leaf(&mut self, row: usize, width: u32) -> E {
        let (leaves, convention) = (&mut self.float_leaves, self.convention);
        self.float_leaf_at
            .entry(row)
            .or_insert_with(|| {
                let name = convention.float_leaf_name(leaves.len());
                leaves.push((name.clone(), width));
                E::var(name, width)
            })
            .clone()
    }

    /// The name of the value row `row` writes, `expr`.
    fn define(&mut self, row: usize, expr: E) -> String {
        if self.elide_aliases
            && let E::Var { name, .. } = &expr
        {
            return name.clone();
        }
        if let Some(name) = self.defined.get(&(row, expr.clone())) {
            return name.clone();
        }
        let name = self.convention.machine_name(self.definitions.len());
        self.definitions.push((name.clone(), expr.clone(), row));
        self.defined.insert((row, expr), name.clone());
        name
    }

    /// Slice 14: the expression a name this walk defined stands for, or
    /// `None` for any other term (a free input, a constant, a term).
    fn definition(&self, expr: &E) -> Option<&E> {
        let E::Var { name, .. } = expr else {
            return None;
        };
        self.definitions
            .iter()
            .rev()
            .find(|(defined, _, _)| defined == name)
            .map(|(_, expr, _)| expr)
    }

    /// The free input naming the undefined value read at `site`.
    fn undefined(&mut self, site: UndefinedSite, width: u32) -> E {
        let (undefined, convention) = (&mut self.undefined, self.convention);
        self.undefined_at
            .entry(site)
            .or_insert_with(|| {
                let name = convention.undefined_name(undefined.len());
                undefined.push((name.clone(), width));
                E::var(name, width)
            })
            .clone()
    }
}

/// The walks of one path a theorem states: the psABI walk always; the
/// clean-bool walk too exactly when the function takes and returns a `B1`,
/// the one case in which the two caller conventions pass or read different
/// bits (module documentation). The choice depends on the signature alone.
struct Walks {
    psabi: Walked,
    clean: Option<Walked>,
}

/// The walks of every path, and the names they share per convention.
struct BodyWalks {
    paths: Vec<Walks>,
    /// Slice 9: the walks of a DAG body ([`walk_dag`]).
    dag: Option<DagWalks>,
    /// Slice 12: the walks of a body with loops ([`walk_loops`]).
    loops: Option<LoopWalks>,
    psabi: MachineNames,
    clean: Option<MachineNames>,
    /// Every private stack byte some path reads unwritten (source or
    /// machine): the `k`-th is the free input `f{k}`.
    frame_bytes: Vec<FrameAddr>,
}

/// An edge's machine literals for the psABI and optional clean-bool walks.
type ConventionEdgeLiterals = (Vec<E>, Option<Vec<E>>);

/// The walks of a DAG body under the conventions its signature needs (slice
/// 9; [`walk_dag`]).
struct DagWalks {
    /// Each block's walks: its calls, accesses and (a returning block) its
    /// returns. The entry block's carry the entry facts.
    blocks: HashMap<Block, Walks>,
    /// The machine's `jcc` literals on each source edge `(from, to)`, in row
    /// order: the psABI walk's, then the clean-bool walk's.
    edges: HashMap<(Block, Block), ConventionEdgeLiterals>,
    /// Slice 24c (OD-228): each segment of the DAG, for the member guard
    /// ([`segment::guard_members`]).
    segments: Vec<segment::Segment>,
}

/// The walks of a body with loops (slice 12; [`walk_loops`]).
struct LoopWalks {
    /// Each region's walks, in [`LoopBody::regions`] order.
    regions: Vec<DagWalks>,
    /// Each region's cut edges: the machine state at the end of the edge's
    /// walk under the psABI convention, then the clean-bool one.
    cut_exits: Vec<ConventionCutExitStates>,
    /// Each loop header's parameters' machine registers ([`ParamRoot`]).
    pairing: HashMap<Block, Vec<ParamRoot>>,
}

/// The machine register that holds a loop header's parameter at the header
/// (slice 12), and how the cut-point relation states it: the register's low
/// [`ParamRoot::stated_bits`] bits are the parameter's value zero-extended,
/// and the bits above them are free. The register is the one the machine's
/// copy of the parameter on the header's entry edge writes (that row's TV-1
/// stamp names the LIR copy); the theorem checks the relation on every edge
/// into the header, so a wrong register is refuted, never assumed.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct ParamRoot {
    /// The register (slice 20: of an `I128`, the one holding its low half).
    root: Root,
    /// Slice 20 (ruling OD-193): of an `I128` parameter or item, the
    /// register holding its high half (the selector carries an `I128` as a
    /// pair of 64-bit registers); `None` for every other carrier.
    high: Option<Root>,
    /// The parameter's own bits (its carrier's).
    value_bits: u32,
    /// The bits the relation states: the value's own, and a `bool` as the
    /// backend's clean 32-bit carrier (under the psABI view, its byte).
    bits: u32,
}

impl ParamRoot {
    /// The bits the relation states under a caller convention: a `bool`
    /// parameter's register is the backend's clean 32-bit bool under the
    /// clean-bool view and only its byte (bits 1 to 7 clear) under the
    /// psABI view, where a `bool` argument register holds the caller's
    /// garbage in bits 8 and up (the selector copies it unextended); every
    /// other parameter's are its own.
    fn stated_bits(self, convention: BoolArguments) -> u32 {
        if self.value_bits == 1 && convention == BoolArguments::PsAbi {
            8
        } else {
            self.bits
        }
    }

    /// The register's 64-bit content at the header under `convention`: the
    /// parameter's free input `x{H}v{i}` zero-extended to the stated bits,
    /// under the free input naming the bits above ([`header_upper_name`]).
    /// Slice 20: an `I128`'s low register holds its low half `x{H}v{i}l`.
    fn template(self, header: Block, i: usize, convention: BoolArguments) -> E {
        if self.high.is_some() {
            return E::var(header_half_name(header, i, false), 64);
        }
        let bits = self.stated_bits(convention);
        let value = fit(
            E::var(header_value_name(header, i), self.value_bits),
            self.value_bits,
            bits,
        );
        if bits == 64 {
            value
        } else {
            E::var(header_upper_name(header, i, convention), 64 - bits).concat(value)
        }
    }

    /// The register's 64-bit content at the header when every edge into it
    /// leaves the bits above the parameter's own zero ([`zero_above`],
    /// checked syntactically on each edge by [`walk_loops`]): the
    /// parameter's free input `x{H}v{i}` zero-extended to 64 bits.
    fn clean_template(self, header: Block, i: usize) -> E {
        if self.high.is_some() {
            return E::var(header_half_name(header, i, false), 64);
        }
        fit(
            E::var(header_value_name(header, i), self.value_bits),
            self.value_bits,
            64,
        )
    }

    /// The relation's two terms on an edge under `convention`: the source's
    /// value zero-extended to the stated bits, and the register's low bits.
    fn relation(self, source: E, register: E, convention: BoolArguments) -> (E, E) {
        let bits = self.stated_bits(convention);
        (fit(source, self.value_bits, bits), low(register, bits))
    }

    /// The free inputs naming the parameter at the header: `x{H}v{i}` of its
    /// own bits, or (slice 20, an `I128`) its halves `x{H}v{i}l` and
    /// `x{H}v{i}h`, 64 bits each.
    fn value_names(self, header: Block, i: usize) -> Vec<(String, u32)> {
        match self.high {
            Some(_) => vec![
                (header_half_name(header, i, false), 64),
                (header_half_name(header, i, true), 64),
            ],
            None => vec![(header_value_name(header, i), self.value_bits)],
        }
    }

    /// Slice 20 (ruling OD-193): the high register of an `I128` and its
    /// content at the header, the high half `x{H}v{i}h`.
    fn high_template(self, header: Block, i: usize) -> Option<(Root, E)> {
        self.high
            .map(|high| (high, E::var(header_half_name(header, i, true), 64)))
    }

    /// The relation's pairs on an edge: [`Self::relation`]'s one, or (slice
    /// 20, an `I128`) two, the source value's low 64 bits against the low
    /// register's and its high 64 bits against the high register's
    /// (`high_register`, its content on the edge).
    fn relations(
        self,
        source: E,
        register: E,
        high_register: Option<E>,
        convention: BoolArguments,
    ) -> Vec<(E, E)> {
        match (self.high, high_register) {
            (Some(_), Some(high)) => vec![
                (source.clone().extract(63, 0), low(register, 64)),
                (source.extract(127, 64), low(high, 64)),
            ],
            _ => vec![self.relation(source, register, convention)],
        }
    }

    /// The registers this item holds: its register, and an `I128`'s high one.
    fn roots(self) -> impl Iterator<Item = Root> {
        std::iter::once(self.root).chain(self.high)
    }
}

/// Whether `operand` names virtual register `id`: itself, or as a memory
/// operand's base or index.
fn names_virtual(operand: &O, id: u32) -> bool {
    match operand {
        O::VReg(vreg) => vreg.id == id,
        O::MemAddr { base, .. } => names_virtual(base, id),
        O::SibMemAddr { base, index, .. } => names_virtual(base, id) || names_virtual(index, id),
        _ => false,
    }
}

/// Slice 20 (ruling OD-193): the two 64-bit registers that hold an `I128`
/// item, from the rows stamped with its copy or definition (`rows`, in row
/// order). Its OUTPUTS are the 64-bit virtual registers some row of the
/// group writes whose last write no later row of the group names (in any
/// operand, a memory operand's base or index included): the group's
/// temporaries (a 128-bit product's partial products, a shift's spill and
/// selects) are named again, its result pair is not. The pair is the last
/// two outputs by that write, the lower virtual register the low half (the
/// selector allocates a pair's low half first: `define_block_params`,
/// `select_move_reg`, every `I128` definition). The stamps only CHOOSE the
/// pair: the relation states both halves on every edge into the cut, so a
/// wrong choice is refuted, never credited. `None` unless the group has two
/// such outputs.
fn i128_pair(rows: &[&X86ISelInst]) -> Option<(Reg, Reg)> {
    let mut outputs: Vec<Reg> = Vec::new();
    for (k, inst) in rows.iter().enumerate() {
        let Some(reg) = destination_reg(inst) else {
            continue;
        };
        let Root::Virtual(id) = reg.root else {
            continue;
        };
        if reg.bits != 64
            || rows[k + 1..].iter().any(|later| {
                later
                    .operands
                    .iter()
                    .any(|operand| names_virtual(operand, id))
            })
        {
            continue;
        }
        outputs.retain(|known| known.root != reg.root);
        outputs.push(reg);
    }
    match outputs.as_slice() {
        [.., a, b] => match (a.root, b.root) {
            (Root::Virtual(x), Root::Virtual(y)) => Some(if x < y { (*a, *b) } else { (*b, *a) }),
            _ => None,
        },
        _ => None,
    }
}

impl BodyWalks {
    fn frame_byte(&self, address: FrameAddr) -> usize {
        self.frame_bytes
            .iter()
            .position(|known| *known == address)
            .expect("every unwritten byte a path reads is registered")
    }
}

/// What RFLAGS holds during a machine walk (slice 5).
#[derive(Clone)]
enum Flags {
    /// Nothing defined them: the entry state, or a callee's clobber.
    Undefined,
    /// An ALU row wrote them; its flag semantics are not modelled, so a
    /// reader makes no claim.
    Unmodelled,
    /// `cmp lhs, rhs` at `bits` bits wrote them.
    Compare { lhs: E, rhs: E, bits: u32 },
    /// `test lhs, rhs` at `bits` bits wrote them (slice 6).
    Test { lhs: E, rhs: E, bits: u32 },
    /// A register-register `add`, `sub` or `imul` of a value, or a `mul`,
    /// wrote them (slice 10): the flags it defines.
    Alu(Box<AluFlags>),
}

impl Flags {
    /// Whether x86 condition `cc` holds of these flags (the shared x86 EFLAGS
    /// model), or the refusal of reading flags no compare or test wrote.
    fn condition(
        &self,
        cc: trust_cg_ir::X86CondCode,
        row: usize,
        opcode: X86Opcode,
    ) -> Result<E, X86BodyRefusal> {
        let eflags = match self {
            Self::Compare { lhs, rhs, bits } => {
                crate::x86_64_eflags::encode_cmp_eflags(lhs.clone(), rhs.clone(), *bits)
            }
            Self::Test { lhs, rhs, bits } => {
                crate::x86_64_eflags::encode_test_eflags(lhs.clone(), rhs.clone(), *bits)
            }
            Self::Alu(flags) => {
                return flags.condition(cc).ok_or_else(|| {
                    mismatch(X86BodyMismatch::UndefinedRead {
                        row,
                        operand: format!(
                            "rflags ({cc:?} reads a flag its writer leaves undefined)"
                        ),
                    })
                });
            }
            Self::Undefined => {
                return Err(mismatch(X86BodyMismatch::UndefinedRead {
                    row,
                    operand: "rflags".into(),
                }));
            }
            Self::Unmodelled => {
                return Err(unsupported(X86BodyUnsupported::MachineRow {
                    row,
                    detail: format!(
                        "{opcode:?} reads flags that no compare or test row of its block wrote"
                    ),
                }));
            }
        };
        Ok(crate::x86_64_eflags::eval_x86_condition(cc, &eflags))
    }
}

/// The admitted rows that write RFLAGS other than a compare: every ALU form
/// (a shift by a masked count of zero leaves them unchanged, which the walk
/// does not rely on either), and (slice 10) `popcnt`, `not` (which the SDM
/// says writes none; the walk does not rely on that), `mul` and the shifts by
/// CL. Every one is
/// first taken to leave flags no reader may use; the walk then models the
/// flags of exactly the register-register `add`, `sub` and `imul` of a value
/// and of `mul` (slice 10, [`AluFlags`]).
fn writes_unmodelled_flags(opcode: X86Opcode) -> bool {
    // Slice 25: a memory-destination `add`/`xor` writes every status flag
    // (the walk then states an `add`'s as `AddRR`'s).
    if read_modify_write(opcode).is_some() && !mutated("s25-rmw-flags-not-clobbered") {
        return true;
    }
    matches!(
        opcode,
        X86Opcode::AddRR
            | X86Opcode::SubRR
            | X86Opcode::ImulRR
            | X86Opcode::ImulRRI
            | X86Opcode::Inc
            | X86Opcode::Dec
            | X86Opcode::AndRR
            | X86Opcode::OrRR
            | X86Opcode::XorRR
            | X86Opcode::AddRI
            | X86Opcode::SubRI
            | X86Opcode::AndRI
            | X86Opcode::OrRI
            | X86Opcode::XorRI
            | X86Opcode::ShlRI
            | X86Opcode::ShrRI
            | X86Opcode::SarRI
            // `rol` writes only CF and OF and leaves SF/ZF/AF/PF UNAFFECTED,
            // which is not the shift mask (the opcode's own doc warns of it).
            // Clobbering to `Unmodelled` errs the safe way: a later reader of
            // a flag `rol` really did preserve makes no claim, so the lane
            // loses credit rather than granting it wrongly.
            | X86Opcode::RolRI
            | X86Opcode::Not
            | X86Opcode::Neg
            | X86Opcode::Popcnt
            | X86Opcode::Mul
            | X86Opcode::ShlRR
            | X86Opcode::ShrRR
            | X86Opcode::SarRR
            // Slice 21: the atomic pseudo rows' `lock cmpxchg16b`/`lock
            // cmpxchg` write ZF (and the CAS loop's the other status flags).
            | X86Opcode::AtomicLoadCmpxchg16b
            | X86Opcode::AtomicRmwCasLoop
    )
}

/// The status flags an arithmetic row defines (slice 10), each `None` where
/// the Intel SDM leaves it undefined. A reader of an undefined flag is
/// [`X86BodyMismatch::UndefinedRead`] of `rflags`, as after a call.
#[derive(Clone)]
struct AluFlags {
    cf: Option<E>,
    zf: Option<E>,
    sf: Option<E>,
    of: Option<E>,
    pf: Option<E>,
}

impl AluFlags {
    /// Every status flag the shared EFLAGS model defines.
    fn all(flags: crate::x86_64_eflags::EflagsFlags) -> Self {
        Self {
            cf: Some(flags.cf),
            zf: Some(flags.zf),
            sf: Some(flags.sf),
            of: Some(flags.of_),
            pf: Some(flags.pf),
        }
    }

    /// `add lhs, rhs` at `bits` (Intel SDM ADD: every status flag set
    /// according to the result), the shared EFLAGS model
    /// (`x86_64_eflags::encode_add_eflags`).
    fn add(lhs: E, rhs: E, bits: u32) -> Self {
        Self::all(crate::x86_64_eflags::encode_add_eflags(lhs, rhs, bits))
    }

    /// `sub lhs, rhs` at `bits`: the flags of `cmp lhs, rhs` (Intel SDM SUB
    /// and CMP set every status flag alike), the shared EFLAGS model.
    fn sub(lhs: E, rhs: E, bits: u32) -> Self {
        Self::all(crate::x86_64_eflags::encode_cmp_eflags(lhs, rhs, bits))
    }

    /// `imul dst, lhs, rhs` at `bits` (Intel SDM IMUL, two- and three-operand
    /// forms: `TMP_XP := lhs * rhs` at twice the width, `DEST :=
    /// truncate(TMP_XP)`, and CF and OF are set exactly when
    /// `SignExtend(DEST) != TMP_XP`; SF, ZF, AF and PF are undefined).
    fn imul(lhs: E, rhs: E, bits: u32) -> Self {
        let full = lhs.sign_ext(bits).bvmul(rhs.sign_ext(bits));
        let truncated = full.clone().extract(bits - 1, 0);
        let overflow = truncated.sign_ext(bits).eq_expr(full).not_expr();
        Self::carry_and_overflow(overflow)
    }

    /// Only CF (`BT`), the rest undefined.
    ///
    /// Intel SDM Vol 2A, BT: `CF := bit(r, k)`, the operand is left unchanged,
    /// and OF, SF, ZF, AF and PF are ARCHITECTURALLY UNDEFINED. So every
    /// condition code that reads one of those must refuse, which is what
    /// leaving them `None` makes [`AluFlags::condition`] do — a `jcc e` after
    /// a `bt` is an `UndefinedRead`, not a credited branch. `cf` is the
    /// BOOLEAN of the shared 1-bit model
    /// ([`crate::x86_64_semantics::encode_bt_cf`]).
    fn carry_only(cf: E) -> Self {
        Self {
            cf: Some(cf),
            zf: None,
            sf: None,
            of: None,
            pf: None,
        }
    }

    /// `bt src, k` at `bits`: CF is bit `k` of `src`, nothing else defined.
    fn bit_test(src: E, k: u32) -> Self {
        let cf_bit = crate::x86_64_semantics::encode_bt_cf(src, k);
        Self::carry_only(cf_bit.eq_expr(E::bv_const(1, 1)))
    }

    /// Only CF and OF, both `flag` (IMUL and MUL); the rest undefined.
    fn carry_and_overflow(flag: E) -> Self {
        Self {
            cf: Some(flag.clone()),
            zf: None,
            sf: None,
            of: Some(flag),
            pf: None,
        }
    }

    /// Whether x86 condition `cc` holds, through the shared condition
    /// evaluation (`x86_64_eflags::eval_x86_condition`), or `None` when `cc`
    /// reads a flag this row leaves undefined.
    fn condition(&self, cc: trust_cg_ir::X86CondCode) -> Option<E> {
        use trust_cg_ir::X86CondCode as C;
        let reads: &[&Option<E>] = match cc {
            C::O | C::NO => &[&self.of],
            C::B | C::AE => &[&self.cf],
            C::E | C::NE => &[&self.zf],
            C::BE | C::A => &[&self.cf, &self.zf],
            C::S | C::NS => &[&self.sf],
            C::P | C::NP => &[&self.pf],
            C::L | C::GE => &[&self.sf, &self.of],
            C::LE | C::G => &[&self.zf, &self.sf, &self.of],
        };
        if reads.iter().any(|flag| flag.is_none()) {
            return None;
        }
        // A flag `cc` does not read never reaches the result; `false` stands
        // in for it.
        let flag = |flag: &Option<E>| flag.clone().unwrap_or(E::bool_const(false));
        let eflags = crate::x86_64_eflags::EflagsFlags {
            cf: flag(&self.cf),
            zf: flag(&self.zf),
            sf: flag(&self.sf),
            of_: flag(&self.of),
            pf: flag(&self.pf),
        };
        Some(crate::x86_64_eflags::eval_x86_condition(cc, &eflags))
    }
}

/// Pair every source path with its machine path and walk each under the
/// caller conventions the signature needs. The control of every path is
/// paired first, before any value is walked. A one-path source whose machine
/// has no conditional jump is its machine chain ([`machine_chain`]; a
/// laid-out block off the chain is [`X86BodyMismatch::UnreachableBlock`], as
/// in slices 1 to 5, unless it lowers a LIR block no source path reaches);
/// any other pairing needs the block correspondence
/// ([`block_correspondence`]), without which there is no claim. A DAG body
/// (slice 9) is walked block by block ([`walk_dag`]).
fn walk_machine_for_callers(
    source: &Function,
    body: &SourceBody,
    cfg: &MachineCfg<'_>,
    encoding: PathEncoding,
) -> Result<BodyWalks, X86BodyRefusal> {
    let clean_bool =
        source.signature.returns.contains(&Type::B1) && source.signature.params.contains(&Type::B1);
    // Slice 12: a body with loops, region by region from the cut points'
    // assumptions ([`walk_loops`]).
    if let Some(loops) = &body.loops {
        let correspondence = cfg.correspondence.as_ref().map_err(|reason| {
            unsupported(X86BodyUnsupported::MachineFunction(format!(
                "the machine blocks do not correspond one to one with the LIR blocks: {reason}"
            )))
        })?;
        // Slice 16: a source stated in parts, from its cut interfaces.
        let pairing = match &loops.cuts {
            Some(cuts) => split::cut_pairing(source, loops, cuts, cfg, correspondence)?,
            None => loop_pairing(loops, cfg, correspondence)?,
        };
        let mut psabi = MachineNames::new(BoolArguments::PsAbi, encoding.elide_aliases);
        let mut clean =
            clean_bool.then(|| MachineNames::new(BoolArguments::Clean32, encoding.elide_aliases));
        let mut frame_bytes = body.sites.frame_bytes.clone();
        let walk = |names: &mut MachineNames, frame_bytes: &mut Vec<FrameAddr>| match &loops.cuts {
            Some(cuts) => split::walk_cuts(
                loops,
                cuts,
                &body.sites,
                cfg,
                correspondence,
                &pairing,
                names,
                frame_bytes,
            ),
            None => walk_loops(
                loops,
                &body.sites,
                cfg,
                correspondence,
                &pairing,
                names,
                frame_bytes,
            ),
        };
        let psabi_walks = walk(&mut psabi, &mut frame_bytes)?;
        let mut clean_walks = clean
            .as_mut()
            .map(|names| walk(names, &mut frame_bytes))
            .transpose()?;
        let mut regions = Vec::with_capacity(psabi_walks.len());
        let mut cut_exits = Vec::with_capacity(psabi_walks.len());
        for (index, (blocks, edges, exits)) in psabi_walks.into_iter().enumerate() {
            let mut clean_region = clean_walks
                .as_mut()
                .map(|walks| std::mem::take(&mut walks[index]));
            let blocks = blocks
                .into_iter()
                .map(|(block, psabi)| {
                    let clean = clean_region.as_mut().map(|(blocks, _, _)| {
                        blocks.remove(&block).expect("every block is walked")
                    });
                    (block, Walks { psabi, clean })
                })
                .collect();
            let edges = edges
                .into_iter()
                .map(|(edge, psabi)| {
                    let clean = clean_region
                        .as_mut()
                        .map(|(_, edges, _)| edges.remove(&edge).expect("every edge is walked"));
                    (edge, (psabi, clean))
                })
                .collect();
            let exits = exits
                .into_iter()
                .map(|(edge, psabi)| {
                    let clean = clean_region.as_mut().map(|(_, _, exits)| {
                        exits.remove(&edge).expect("every cut edge is walked")
                    });
                    (edge, (psabi, clean))
                })
                .collect();
            regions.push(DagWalks {
                blocks,
                edges,
                segments: segment::in_dag(&correspondence.segments, &loops.regions[index].dag),
            });
            cut_exits.push(exits);
        }
        return Ok(BodyWalks {
            paths: Vec::new(),
            dag: None,
            loops: Some(LoopWalks {
                regions,
                cut_exits,
                pairing,
            }),
            psabi,
            clean,
            frame_bytes,
        });
    }
    if let Some(dag) = &body.dag {
        let correspondence = cfg.correspondence.as_ref().map_err(|reason| {
            unsupported(X86BodyUnsupported::MachineFunction(format!(
                "the machine blocks do not correspond one to one with the LIR blocks: {reason}"
            )))
        })?;
        let mut psabi = MachineNames::new(BoolArguments::PsAbi, encoding.elide_aliases);
        let mut clean =
            clean_bool.then(|| MachineNames::new(BoolArguments::Clean32, encoding.elide_aliases));
        let mut frame_bytes = body.sites.frame_bytes.clone();
        let (psabi_blocks, psabi_edges) = walk_dag(
            dag,
            &body.sites,
            cfg,
            correspondence,
            &mut psabi,
            &mut frame_bytes,
        )?;
        let mut clean_walks = clean
            .as_mut()
            .map(|names| {
                walk_dag(
                    dag,
                    &body.sites,
                    cfg,
                    correspondence,
                    names,
                    &mut frame_bytes,
                )
            })
            .transpose()?;
        let blocks = psabi_blocks
            .into_iter()
            .map(|(block, psabi)| {
                let clean = clean_walks
                    .as_mut()
                    .map(|(blocks, _)| blocks.remove(&block).expect("every block is walked"));
                (block, Walks { psabi, clean })
            })
            .collect();
        let edges = psabi_edges
            .into_iter()
            .map(|(edge, psabi)| {
                let clean = clean_walks
                    .as_mut()
                    .map(|(_, edges)| edges.remove(&edge).expect("every edge is walked"));
                (edge, (psabi, clean))
            })
            .collect();
        return Ok(BodyWalks {
            paths: Vec::new(),
            dag: Some(DagWalks {
                blocks,
                edges,
                segments: segment::in_dag(&correspondence.segments, dag),
            }),
            loops: None,
            psabi,
            clean,
            frame_bytes,
        });
    }
    let mut visited = HashSet::new();
    // The loop and DAG bodies have returned: this is [`states_machine_chain`],
    // which slice 24a's quotient reads too.
    let paths = if states_machine_chain(body, cfg) {
        let chain = machine_chain(cfg, &mut visited)?;
        let mut off_chain: Vec<Block> = cfg
            .machine
            .blocks
            .keys()
            .filter(|block| !visited.contains(*block))
            .copied()
            .collect();
        off_chain.sort_unstable();
        if let Some(block) = off_chain.first() {
            // A laid-out block off the chain is a mismatch (slices 1 to 5)
            // UNLESS it lowers a LIR block no source path reaches. Then it is
            // dead code the selector laid out, the theorem claims nothing
            // about it, and the correspondence proves it cannot run: see
            // [`block_correspondence`] for the induction. Accounting for it
            // needs that correspondence, which this branch otherwise does not;
            // without one, a source with dead blocks is refused rather than
            // called a mismatch, because a correct body must never be.
            let accounted = off_chain.iter().all(|block| {
                cfg.correspondence.as_ref().is_ok_and(|correspondence| {
                    correspondence
                        .origin
                        .get(block)
                        .is_some_and(|lir| body.dead.contains(lir))
                })
            });
            if !accounted {
                if body.dead.is_empty() {
                    return Err(mismatch(X86BodyMismatch::UnreachableBlock {
                        block: *block,
                    }));
                }
                return Err(unsupported(X86BodyUnsupported::MachineFunction(format!(
                    "machine block {block:?} is off the chain from the entry block and is not \
                     shown to lower one of the {} LIR blocks no source path reaches",
                    body.dead.len()
                ))));
            }
        }
        vec![chain]
    } else {
        let correspondence = cfg.correspondence.as_ref().map_err(|reason| {
            unsupported(X86BodyUnsupported::MachineFunction(format!(
                "the machine blocks do not correspond one to one with the LIR blocks: {reason}"
            )))
        })?;
        let paths = body
            .paths
            .iter()
            .map(|program| machine_path(cfg, correspondence, program, &mut visited))
            .collect::<Result<Vec<_>, _>>()?;
        // Under the correspondence every laid-out block lowers a LIR block,
        // and every LIR block is on a source path.
        if let Some(block) = cfg
            .machine
            .block_order
            .iter()
            .filter(|block| !visited.contains(*block))
            .min()
        {
            return Err(unsupported(X86BodyUnsupported::MachineFunction(format!(
                "machine block {block:?} is on no paired path"
            ))));
        }
        paths
    };
    let several = (body.paths.len() > 1 || (body.long_chain && encoding.trim_long_chains))
        && encoding.elide_aliases;
    let mut psabi = MachineNames::new(BoolArguments::PsAbi, several);
    let mut clean = clean_bool.then(|| MachineNames::new(BoolArguments::Clean32, several));
    let mut frame_bytes = body.sites.frame_bytes.clone();
    let mut walks = Vec::with_capacity(paths.len());
    for (program, rows) in body.paths.iter().zip(&paths) {
        let consts = cfg.machine;
        let psabi_walk = walk_machine(
            program,
            &body.sites,
            rows,
            &mut psabi,
            &mut frame_bytes,
            consts,
        )?;
        let clean_walk = clean
            .as_mut()
            .map(|names| walk_machine(program, &body.sites, rows, names, &mut frame_bytes, consts))
            .transpose()?;
        walks.push(Walks {
            psabi: psabi_walk,
            clean: clean_walk,
        });
    }
    Ok(BodyWalks {
        paths: walks,
        dag: None,
        loops: None,
        psabi,
        clean,
        frame_bytes,
    })
}

/// The register a value row writes (its first operand), or `None` for a row
/// that writes no register operand (a compare, a test, a store, a transfer).
fn destination_reg(inst: &X86ISelInst) -> Option<Reg> {
    if matches!(
        inst.opcode,
        X86Opcode::CmpRR
            | X86Opcode::CmpRI
            | X86Opcode::TestRR
            | X86Opcode::TestRI
            | X86Opcode::Jcc
            | X86Opcode::Jmp
            | X86Opcode::JmpR
            | X86Opcode::Ret
            | X86Opcode::Ud2
            | X86Opcode::Nop
            | X86Opcode::Call
            | X86Opcode::CallR
            // Slice 14: their operand is read; RAX and RDX are implicit.
            | X86Opcode::Div
            | X86Opcode::Idiv
            | X86Opcode::Cqo
            | X86Opcode::Cdq
            | X86Opcode::TrapDivZeroExact
    ) || memory_access(inst.opcode)
        .or_else(|| sib_access(inst.opcode))
        .is_some_and(|form| !form.load)
        // Slice 25: a memory-destination `add`/`xor` writes memory only.
        || read_modify_write(inst.opcode).is_some()
    {
        return None;
    }
    let first = inst.operands.first()?;
    gpr(first).or_else(|| xmm(first))
}

/// The machine register that holds each parameter of each loop header
/// (slice 12; [`ParamRoot`]): on the header's entry edge, the register the
/// last machine row stamped with the LIR copy into the parameter writes.
/// The stamps (TV-1 provenance) only CHOOSE the pairing: the theorem states
/// the relation on every edge into the header, so a wrong choice is refuted
/// or (a register no edge defines) makes no claim, never credit. A
/// parameter whose copy no row lowers, two parameters in one register, a
/// register narrower than the parameter, or a callee-saved one makes no
/// claim.
fn loop_pairing(
    loops: &LoopBody,
    cfg: &MachineCfg<'_>,
    correspondence: &Correspondence,
) -> Result<HashMap<Block, Vec<ParamRoot>>, X86BodyRefusal> {
    let no_claim = |detail: String| unsupported(X86BodyUnsupported::MachineFunction(detail));
    let mut pairing = HashMap::new();
    let mut headers: Vec<&LoopHeader> = loops.headers.values().collect();
    headers.sort_unstable_by_key(|header| header.region);
    for header in headers {
        let block = header.block;
        let (region, from) = header.entry;
        let edge = &loops.regions[region].cuts[&(from, block)];
        let lowered =
            |lir: &Block| {
                correspondence.lowering.get(lir).copied().ok_or_else(|| {
                    no_claim(format!("the source block {lir:?} has no machine block"))
                })
            };
        let rows = block_rows(cfg, correspondence, lowered(&from)?, Some(lowered(&block)?))?;
        let mut roots: Vec<ParamRoot> = Vec::with_capacity(header.params.len());
        for ((param, carrier), copy) in header.params.iter().zip(&edge.copies) {
            let Some(index) = copy else {
                return Err(no_claim(format!(
                    "loop header {block:?} parameter {param:?} has no copy on its entry edge"
                )));
            };
            let stamp = trust_cg_ir::provenance::SourceInstId {
                block: from.0,
                index: *index as u32,
            };
            // Slice 20 (OD-193): an `I128` is a pair of 64-bit registers,
            // the copy's two `mov`s.
            let pair = (*carrier == Carrier::I128).then(|| {
                let stamped: Vec<&X86ISelInst> = rows
                    .iter()
                    .filter(|row| row.row.inst.lowering_provenance.source_id() == Some(stamp))
                    .map(|row| row.row.inst)
                    .collect();
                i128_pair(&stamped)
            });
            if pair == Some(None) {
                return Err(no_claim(format!(
                    "no two virtual 64-bit registers of the entry edge of loop header {block:?} \
                     hold the copy into its i128 parameter {param:?}"
                )));
            }
            let pair = pair.flatten();
            let Some(reg) = pair.map(|(low, _)| low).or_else(|| {
                rows.iter()
                    .rev()
                    .find(|row| row.row.inst.lowering_provenance.source_id() == Some(stamp))
                    .and_then(|row| destination_reg(row.row.inst))
            }) else {
                return Err(no_claim(format!(
                    "no machine row of the entry edge of loop header {block:?} writes a register \
                     as the copy into its parameter {param:?}"
                )));
            };
            // The bits the relation states: the value's own, and a `bool`
            // as the backend's clean 32-bit carrier (slice 20: an `I128`'s
            // each half, 64).
            let bits = match carrier.bits() {
                1 => 32,
                128 => 64,
                bits => bits,
            };
            if reg.bits < bits {
                return Err(no_claim(format!(
                    "loop header {block:?} parameter {param:?} is held in a {}-bit register",
                    reg.bits
                )));
            }
            if let Root::Physical(physical) = reg.root
                && SYSV_PRESERVED_ROOTS.contains(&physical)
            {
                return Err(no_claim(format!(
                    "loop header {block:?} parameter {param:?} is held in a callee-saved register"
                )));
            }
            let high = pair.map(|(_, high)| high.root);
            let held: Vec<Root> = std::iter::once(reg.root).chain(high).collect();
            if held.iter().any(|root| {
                roots
                    .iter()
                    .any(|known| known.roots().any(|known| known == *root))
            }) || high == Some(reg.root)
            {
                return Err(no_claim(format!(
                    "two parameters of loop header {block:?} are held in {}",
                    reg.root.describe()
                )));
            }
            roots.push(ParamRoot {
                root: reg.root,
                high,
                value_bits: carrier.bits(),
                bits,
            });
        }
        pairing.insert(block, roots);
    }
    Ok(pairing)
}

/// Whether two register contents are the same (slice 12): the same term,
/// the same private address, both undefined, both mixed or both carried.
fn same_reg(a: Option<&RegValue>, b: Option<&RegValue>) -> bool {
    match (a, b) {
        (None, None) => true,
        (Some(RegValue::Bits(a)), Some(RegValue::Bits(b))) => {
            a.expr == b.expr && a.affine == b.affine
        }
        (Some(RegValue::Frame(a)), Some(RegValue::Frame(b))) => a == b,
        (Some(RegValue::Indexed(a)), Some(RegValue::Indexed(b))) => a == b,
        (Some(RegValue::Mixed), Some(RegValue::Mixed))
        | (Some(RegValue::Carried), Some(RegValue::Carried)) => true,
        _ => false,
    }
}

/// Whether two machine private bytes are the same (slice 12).
fn same_byte(a: &Option<MachineByte>, b: &Option<MachineByte>) -> bool {
    match (a, b) {
        (None, None) => true,
        (Some(a), Some(b)) => {
            a.term == b.term
                && a.width == b.width
                && a.byte == b.byte
                && a.affine == b.affine
                && a.frame == b.frame
                && a.dead == b.dead
        }
        _ => false,
    }
}

/// The machine state at the start of loop header `header`'s region (slice
/// 12): the state its entry edge brings (`entry`), with each parameter's
/// register its template ([`ParamRoot::template`]), every other register
/// the loop writes ([`RegValue::Carried`]: no claim on a read), each header
/// byte the free input the source shares, the slots that escaped on some
/// source edge into the header escaped (the machine's calls pass exactly
/// the source's slots, checked call by call, and the walk checks that no
/// machine edge lets another escape), and no flags (they never cross a
/// block).
fn machine_header_start(
    header: &LoopHeader,
    roots: &[ParamRoot],
    written: &HashSet<Root>,
    wide: &HashSet<usize>,
    entry: &MachineState,
    convention: BoolArguments,
) -> MachineState {
    let mut state = entry.clone();
    for root in written {
        state.regs.insert(*root, RegValue::Carried);
    }
    for (i, root) in roots.iter().enumerate() {
        let expr = if wide.contains(&i) {
            root.template(header.block, i, convention)
        } else {
            root.clean_template(header.block, i)
        };
        state
            .regs
            .insert(root.root, RegValue::Bits(Slot { expr, affine: None }));
        // Slice 20 (OD-193): an `I128`'s high register, its high half.
        if let Some((high, expr)) = root.high_template(header.block, i) {
            state
                .regs
                .insert(high, RegValue::Bits(Slot { expr, affine: None }));
        }
    }
    for &(slot, offset) in header.bytes.keys() {
        state.stack[slot as usize][offset as usize] = Some(MachineByte {
            term: E::var(
                header_byte_name(header.block, FrameAddr { slot, offset }),
                8,
            ),
            width: 8,
            byte: 0,
            affine: None,
            frame: None,
            dead: false,
        });
    }
    // Slice 17: a byte dead at the header starts unreadable.
    for &(slot, offset) in &header.dead {
        state.stack[slot as usize][offset as usize] = Some(MachineByte::dead());
    }
    // The source's escaped slots at the header, closed under the addresses
    // the machine's bytes hold (slice 13's transitive rule).
    let mut escaped = std::collections::BTreeSet::new();
    escape_machine(
        &mut escaped,
        &state.stack,
        state
            .escaped
            .iter()
            .chain(&header.escaped)
            .copied()
            .collect::<Vec<_>>(),
    );
    state.escaped = escaped;
    state.flags = Flags::Unmodelled;
    // Slice 14: an instance of the region starts with the machine running
    // (the cut edge that entered it required that wherever the source runs).
    state.stopped = bit_zero();
    state.trapped = bit_zero();
    state
}

/// Walk a body with loops under one caller convention (slice 12), region by
/// region in cut-point order, each from its cut point's assumption: the
/// machine's entry state, or a loop header's [`machine_header_start`] from
/// the state its entry edge's walk leaves. Then every edge into each header
/// is compared with the header's assumption: a register some edge leaves
/// other than the start holds (and that pairs no parameter) is one the loop
/// writes, and every region is walked again, until no such register is
/// left. A private byte the machine's loop changes that the source's does
/// not (no header byte), a slot it lets escape that the source's does not,
/// and a parameter's register that holds no bits on some edge into its
/// header make no claim. Returns each region's walks.
#[allow(clippy::too_many_arguments)]
fn walk_loops(
    loops: &LoopBody,
    sites: &SourceSites,
    cfg: &MachineCfg<'_>,
    correspondence: &Correspondence,
    pairing: &HashMap<Block, Vec<ParamRoot>>,
    names: &mut MachineNames,
    frame_bytes: &mut Vec<FrameAddr>,
) -> Result<Vec<RegionWalk>, X86BodyRefusal> {
    let no_claim = |detail: String| unsupported(X86BodyUnsupported::MachineFunction(detail));
    let base_names = names.clone();
    let base_frame_bytes = frame_bytes.clone();
    let mut written: HashMap<Block, HashSet<Root>> = HashMap::new();
    // The parameters whose register some edge into the header leaves with
    // bits above the parameter's own that are not known to be 0: the header
    // assumes those bits a free input. Every other parameter's register is
    // assumed to hold exactly the zero-extended parameter, which each edge
    // is checked to leave (a greatest fixpoint: an assumption is dropped,
    // and every region walked again, when some edge breaks it; by induction
    // over a run's visits of the header, a register every edge leaves zero
    // above the parameter, given that assumption at the header, holds zero
    // there at every visit).
    let mut wide: HashMap<Block, HashSet<usize>> = HashMap::new();
    let mut headers: Vec<&LoopHeader> = loops.headers.values().collect();
    headers.sort_unstable_by_key(|header| header.region);
    let none = HashSet::new();
    let none_wide = HashSet::new();
    for _ in 0..MAX_LOOP_ROUNDS {
        *names = base_names.clone();
        *frame_bytes = base_frame_bytes.clone();
        let mut walks: Vec<RegionWalk> = Vec::with_capacity(loops.regions.len());
        for (index, region) in loops.regions.iter().enumerate() {
            let first = region.dag.order[0];
            let (start, entry_facts) = match loops.headers.get(&first) {
                None => {
                    check_machine_entry(cfg, correspondence, first)?;
                    let (initial, entry_names, abi_views) =
                        MachineState::entry(&region.dag.blocks[&first], names.convention);
                    (initial, Some((entry_names, abi_views)))
                }
                Some(header) => {
                    let (q, from) = header.entry;
                    let start = machine_header_start(
                        header,
                        &pairing[&first],
                        written.get(&first).unwrap_or(&none),
                        wide.get(&first).unwrap_or(&none_wide),
                        &walks[q].2[&(from, first)],
                        names.convention,
                    );
                    (start, None)
                }
            };
            debug_assert!(index > 0 || entry_facts.is_some());
            let mut walk = walk_region(
                &region.dag,
                sites,
                cfg,
                correspondence,
                names,
                frame_bytes,
                start,
            )?;
            if let Some((entry_names, abi_views)) = entry_facts {
                let entry_walk = walk.0.get_mut(&first).expect("the entry block is walked");
                entry_walk.entry_names = entry_names;
                entry_walk.abi_views = abi_views;
            }
            walks.push(walk);
        }
        // Compare every edge into each header with its assumption.
        let mut grown = false;
        let defs: HashMap<&str, &E> = names
            .definitions
            .iter()
            .map(|(name, expr, _)| (name.as_str(), expr))
            .collect();
        for header in &headers {
            let block = header.block;
            let roots = &pairing[&block];
            let (q, from) = header.entry;
            let start = machine_header_start(
                header,
                roots,
                written.get(&block).unwrap_or(&none),
                wide.get(&block).unwrap_or(&none_wide),
                &walks[q].2[&(from, block)],
                names.convention,
            );
            let mut edges: Vec<(&(Block, Block), &MachineState)> = walks
                .iter()
                .flat_map(|walk| walk.2.iter())
                .filter(|((_, to), _)| *to == block)
                .collect();
            edges.sort_unstable_by_key(|((from, _), _)| *from);
            for ((edge_from, _), exit) in edges {
                // Slice 13: the selector opens and closes an outgoing
                // argument area around one call, in one block.
                if exit.outgoing.is_some() {
                    return Err(no_claim(format!(
                        "the machine enters loop header {block:?} from block {edge_from:?} with \
                         an outgoing argument area open"
                    )));
                }
                if let Some(slot) = exit
                    .escaped
                    .iter()
                    .find(|slot| !header.escaped.contains(slot))
                {
                    return Err(no_claim(format!(
                        "the machine lets private stack slot {slot} escape on the edge from block \
                         {edge_from:?} into loop header {block:?}, where its LIR source does not"
                    )));
                }
                let mut keys: Vec<Root> =
                    start.regs.keys().chain(exit.regs.keys()).copied().collect();
                keys.sort_unstable_by_key(|root| match root {
                    Root::Physical(root) => (0, u32::from(*root)),
                    Root::Virtual(id) => (1, *id),
                });
                keys.dedup();
                for root in keys {
                    if roots
                        .iter()
                        .any(|paired| paired.roots().any(|held| held == root))
                        || written
                            .get(&block)
                            .is_some_and(|known| known.contains(&root))
                    {
                        continue;
                    }
                    if !same_reg(start.regs.get(&root), exit.regs.get(&root)) {
                        written.entry(block).or_default().insert(root);
                        grown = true;
                    }
                }
                for (i, paired) in roots.iter().enumerate() {
                    if paired.value_bits >= 64
                        || wide.get(&block).is_some_and(|known| known.contains(&i))
                    {
                        continue;
                    }
                    let clean = matches!(
                        exit.regs.get(&paired.root),
                        Some(RegValue::Bits(slot))
                            if zero_above(&slot.expr, paired.value_bits, &defs)
                    );
                    if !clean {
                        wide.entry(block).or_default().insert(i);
                        grown = true;
                    }
                }
                for (slot, bytes) in exit.stack.iter().enumerate() {
                    for (offset, byte) in bytes.iter().enumerate() {
                        // Slice 17: a byte dead at the header is neither
                        // related nor checked unchanged.
                        if header.dead.contains(&(slot as u32, offset as i64)) {
                            continue;
                        }
                        if header.bytes.contains_key(&(slot as u32, offset as i64)) {
                            // Slice 17: a related byte an edge leaves
                            // unreadable makes no claim.
                            if byte.as_ref().is_some_and(|byte| byte.dead) {
                                return Err(no_claim(format!(
                                    "the machine leaves private stack slot {slot} byte {offset} \
                                     unreadable on the edge from block {edge_from:?} into loop \
                                     header {block:?}, a byte its loop changes"
                                )));
                            }
                            // Slice 13: a stored private address is
                            // tracked, never a free input a header assumes.
                            if byte.as_ref().is_some_and(|byte| byte.frame.is_some()) {
                                return Err(no_claim(format!(
                                    "the machine leaves a private stack address in slot {slot} \
                                     byte {offset} on the edge from block {edge_from:?} into \
                                     loop header {block:?}, a byte its loop changes"
                                )));
                            }
                            continue;
                        }
                        if !same_byte(&start.stack[slot][offset], byte) {
                            return Err(no_claim(format!(
                                "the machine changes private stack slot {slot} byte {offset} on \
                                 the edge from block {edge_from:?} into loop header {block:?}, \
                                 which its LIR source does not"
                            )));
                        }
                    }
                }
            }
        }
        if grown {
            continue;
        }
        // The fixpoint: each parameter's register holds bits on every edge
        // into its header, and every unwritten byte the relation reads at a
        // header byte is registered.
        for header in &headers {
            let block = header.block;
            for walk in &walks {
                for ((edge_from, to), exit) in &walk.2 {
                    if *to != block {
                        continue;
                    }
                    for (root, (param, _)) in pairing[&block].iter().zip(&header.params) {
                        for held in root.roots() {
                            if !matches!(exit.regs.get(&held), Some(RegValue::Bits(_))) {
                                return Err(no_claim(format!(
                                    "{} holds no value on the edge from block {edge_from:?} into \
                                     loop header {block:?}, whose parameter {param:?} it holds",
                                    held.describe()
                                )));
                            }
                        }
                    }
                    for &(slot, offset) in header.bytes.keys() {
                        if exit.stack[slot as usize][offset as usize].is_none() {
                            register_frame_byte(frame_bytes, FrameAddr { slot, offset });
                        }
                    }
                }
            }
        }
        return Ok(walks);
    }
    Err(no_claim(format!(
        "the loop headers' machine assumptions do not reach a fixpoint in {MAX_LOOP_ROUNDS} rounds"
    )))
}

/// The pseudo-row of a machine definition that joins the values the edges
/// into a DAG block bring (slice 9); [`SourceBoundX86Body::machine_definitions`]
/// lists only definitions of real rows.
const JOIN_ROW: usize = usize::MAX;

/// The guard of DAG block `block` (slice 9) as a 1-bit term, 1 exactly when
/// the source's run reaches the block: the constant 1 for the entry block,
/// the guard of its one incoming edge, or (a join) the defined name `c{b}`,
/// the disjunction of its incoming edges' guards. (Slice 12: in the region
/// of cut point `H`, relative to that region's run, `c{H}x{b}`.)
fn dag_block_guard(dag: &DagBody, block: Block) -> E {
    match dag.predecessors[&block].as_slice() {
        [] => E::bv_const(1, 1),
        [only] => dag_edge_guard(dag, *only, block),
        _ => E::var(dag_guard_name(dag, block, None), 1),
    }
}

/// The guard of DAG edge `from -> to` (slice 9) as a 1-bit term, 1 exactly
/// when the source's run takes the edge: `from`'s guard when `from` ends in a
/// `Jump`, else the defined name `c{from}t{to}`, `from`'s guard and the
/// edge's branch test. (Slice 12: `c{H}x{from}t{to}` in the region of `H`.)
fn dag_edge_guard(dag: &DagBody, from: Block, to: Block) -> E {
    if dag.blocks[&from].branches.is_empty() {
        dag_block_guard(dag, from)
    } else {
        E::var(dag_guard_name(dag, from, Some(to)), 1)
    }
}

/// The name of a join's guard (`to` none) or of a conditional edge's.
fn dag_guard_name(dag: &DagBody, block: Block, to: Option<Block>) -> String {
    let prefix = dag
        .prefix
        .map_or_else(String::new, |start| format!("{}x", start.0));
    match to {
        None => format!("c{prefix}{}", block.0),
        Some(to) => format!("c{prefix}{}t{}", block.0, to.0),
    }
}

/// Whether a 1-bit guard term holds.
fn guard_holds(guard: E) -> E {
    guard.eq_expr(E::bv_const(1, 1))
}

/// `(ite c_1 v_1 (ite c_2 v_2 ... v_n))`: the value the incoming edge whose
/// guard holds brings (the last one is the fallback: at a reached join
/// exactly one incoming edge's guard holds, and at an unreached one the
/// value is never observed).
fn join_terms(incoming: Vec<(E, E)>) -> E {
    let mut incoming = incoming.into_iter().rev();
    let (_, mut chosen) = incoming.next().expect("a join has incoming edges");
    for (guard, value) in incoming {
        chosen = E::ite(guard_holds(guard), value, chosen);
    }
    chosen
}

/// Walk a DAG body under one caller convention (slice 9). Blocks run in the
/// source's topological order, each machine block the one that lowers it
/// ([`block_correspondence`], required). A block starts from its entry
/// state: the function's entry, its one predecessor's state on the edge
/// into it, or (a join) the merge of the states its incoming edges bring
/// ([`merge_machine`]), always with flags that do not cross the boundary. A
/// block that ends the function is walked to its `ret` or `ud2`; any other
/// is walked once per outgoing source edge ([`block_rows`]: the rows that
/// run on the way to the block that lowers the edge's target, the `jcc`
/// directions that take it), each walk from the block's entry state and each
/// against the block's fragment, so each edge runs exactly the block's
/// calls and accesses (and therefore all of them before any `jcc`). Returns
/// each block's walk (the first edge's, with every edge's bound rows) and
/// each edge's `jcc` literals.
#[allow(clippy::type_complexity)]
fn walk_dag(
    dag: &DagBody,
    sites: &SourceSites,
    cfg: &MachineCfg<'_>,
    correspondence: &Correspondence,
    names: &mut MachineNames,
    frame_bytes: &mut Vec<FrameAddr>,
) -> Result<(HashMap<Block, Walked>, HashMap<(Block, Block), Vec<E>>), X86BodyRefusal> {
    let entry_block = dag.order[0];
    let (initial, entry_names, abi_views) =
        MachineState::entry(&dag.blocks[&entry_block], names.convention);
    check_machine_entry(cfg, correspondence, entry_block)?;
    let (mut blocks, edges, _) =
        walk_region(dag, sites, cfg, correspondence, names, frame_bytes, initial)?;
    let entry_walk = blocks
        .get_mut(&entry_block)
        .expect("the entry block is walked");
    entry_walk.entry_names = entry_names;
    entry_walk.abi_views = abi_views;
    Ok((blocks, edges))
}

/// The machine's first laid-out block must lower the LIR entry block.
fn check_machine_entry(
    cfg: &MachineCfg<'_>,
    correspondence: &Correspondence,
    entry_block: Block,
) -> Result<(), X86BodyRefusal> {
    let no_claim = |detail: String| unsupported(X86BodyUnsupported::MachineFunction(detail));
    let lowered = correspondence
        .lowering
        .get(&entry_block)
        .copied()
        .ok_or_else(|| {
            no_claim(format!(
                "the source block {entry_block:?} has no machine block"
            ))
        })?;
    if cfg.machine.block_order.first() != Some(&lowered) {
        return Err(no_claim(
            "the machine's first block does not lower the LIR entry block".into(),
        ));
    }
    Ok(())
}

/// Walk one DAG (slice 9: a body's; slice 12: a region's) under one caller
/// convention from `initial`, the machine state at its first block's entry,
/// as [`walk_dag`] describes.
fn walk_region(
    dag: &DagBody,
    sites: &SourceSites,
    cfg: &MachineCfg<'_>,
    correspondence: &Correspondence,
    names: &mut MachineNames,
    frame_bytes: &mut Vec<FrameAddr>,
    initial: MachineState,
) -> Result<RegionWalk, X86BodyRefusal> {
    let no_claim = |detail: String| unsupported(X86BodyUnsupported::MachineFunction(detail));
    // Slice 15: the function's constant pool (a float constant's bits).
    let consts = cfg.machine;
    let entry_block = dag.order[0];
    let lowering = |lir: &Block| {
        correspondence
            .lowering
            .get(lir)
            .copied()
            .ok_or_else(|| no_claim(format!("the source block {lir:?} has no machine block")))
    };
    let mut initial = Some(initial);
    let mut exits: HashMap<(Block, Block), MachineState> = HashMap::new();
    let mut blocks: HashMap<Block, Walked> = HashMap::new();
    let mut edges: HashMap<(Block, Block), Vec<E>> = HashMap::new();
    for block in &dag.order {
        // Slice 24c (OD-228): a segment member other than its head has no
        // machine block, entry state or rows of its own: its head's walk
        // ([`segment::walk_head`]) stated it.
        if let Some(segment) = correspondence.segments.inner(*block) {
            if !blocks.contains_key(block) {
                return Err(unsupported(X86BodyUnsupported::Construction(format!(
                    "segment member {block:?} is walked before its head {:?}",
                    segment.head
                ))));
            }
            continue;
        }
        let lowered = lowering(block)?;
        let program = &dag.blocks[block];
        let mut entry = match dag.predecessors[block].as_slice() {
            [] => initial.take().expect("one block starts the DAG"),
            [only] => exits
                .remove(&(*only, *block))
                .expect("a predecessor is walked first"),
            several => {
                let incoming = several
                    .iter()
                    .map(|predecessor| {
                        (
                            dag_edge_guard(dag, *predecessor, *block),
                            exits
                                .remove(&(*predecessor, *block))
                                .expect("a predecessor is walked first"),
                        )
                    })
                    .collect();
                merge_machine(
                    *block,
                    incoming,
                    dag.join_dead.get(block),
                    names,
                    frame_bytes,
                )?
            }
        };
        // Flags never cross a block boundary (slice 6), whatever wrote them
        // (a compare, a test, or a slice-10 ALU row).
        if *block != entry_block
            && matches!(
                entry.flags,
                Flags::Compare { .. } | Flags::Test { .. } | Flags::Alu(_)
            )
        {
            entry.flags = Flags::Unmodelled;
        }
        // Slice 24c: a segment's head walks its machine block for the whole
        // segment.
        if let Some(segment) = correspondence.segments.of_head(*block) {
            segment::walk_head(
                segment,
                dag,
                sites,
                cfg,
                correspondence,
                names,
                frame_bytes,
                &entry,
                &mut blocks,
                &mut edges,
                &mut exits,
            )?;
            continue;
        }
        let targets = &dag.successors[block];
        if targets.is_empty() {
            let rows = block_rows(cfg, correspondence, lowered, None)?;
            let walked = walk_rows(
                program,
                sites,
                &rows,
                names,
                frame_bytes,
                consts,
                &mut entry,
            )?;
            blocks.insert(*block, walked);
            continue;
        }
        let mut first: Option<Walked> = None;
        for target in targets {
            // Slice 14: every route of the machine block to the target's
            // ([`block_routes`]); one route is the slice-9 pairing, row for
            // row.
            let routes = block_routes(cfg, correspondence, lowered, lowering(target)?)?;
            let (walked, state) =
                walk_routes(program, sites, &routes, names, frame_bytes, consts, &entry)?;
            edges.insert((*block, *target), walked.literals.clone());
            exits.insert((*block, *target), state);
            let Some(earliest) = first.as_mut() else {
                first = Some(walked);
                continue;
            };
            // Slice 14: every edge stops (or not) where the first does, so
            // the block's stop claims ([`stop_claims`], the first edge's end
            // stop) hold for each edge; the selector puts a trap carrier or a
            // `div` before a block's `jcc`s, never between them.
            if walked.end_stop != earliest.end_stop {
                return Err(no_claim(format!(
                    "the machine block that lowers block {block:?} stops differently on its \
                     edges"
                )));
            }
            // Every edge's rows extend the earliest edge's, and each edge's
            // walk ran exactly the block's calls and accesses (its end
            // checks), so they are the same rows from the same state: the
            // first edge's walk observes them for the block.
            debug_assert!(
                earliest.calls.len() == walked.calls.len()
                    && earliest
                        .calls
                        .iter()
                        .zip(&walked.calls)
                        .all(|(a, b)| a.row == b.row && a.args == b.args && a.slots == b.slots)
                    && earliest.accesses.len() == walked.accesses.len()
                    && earliest
                        .accesses
                        .iter()
                        .zip(&walked.accesses)
                        .all(|(a, b)| a.row == b.row && a.address == b.address)
                    && earliest.floats.len() == walked.floats.len()
                    && earliest
                        .floats
                        .iter()
                        .zip(&walked.floats)
                        .all(|(a, b)| a.row == b.row && a.args == b.args),
                "block {lowered:?} runs different calls, accesses or rounding events on its edges"
            );
            earliest.bound_rows.extend(walked.bound_rows);
            // Slice 17: every edge's in-bounds claims, each once (claimed
            // under the block's guard: stronger than the edge's).
            for claim in walked.indexed {
                if !earliest.indexed.contains(&claim) {
                    earliest.indexed.push(claim);
                }
            }
        }
        let mut walked = first.expect("a block with successors");
        walked.bound_rows.sort_unstable();
        walked.bound_rows.dedup();
        blocks.insert(*block, walked);
    }
    // What is left is the state of every cut edge (slice 12; a body's DAG has
    // none).
    Ok((blocks, edges, exits))
}

/// Walk the routes of one machine block to one successor ([`block_routes`])
/// from `entry` (slice 14). One route is walked as before: its walk and end
/// state. Several are each walked from `entry`; they must run the same calls
/// and accesses (they share every row before the first `jcc`, and the
/// selector's compare chain puts only compares and constants between its
/// `jcc`s), and the edge's machine literal is the disjunction, over the
/// routes, of the conjunction of each route's `jcc` literals: the machine
/// takes the edge exactly when one route's literals all hold, and at most one
/// does. The end state is the routes' states joined by those route
/// conditions ([`merge_machine`]: a value every route leaves alike is kept).
/// The walk returned observes the first route's calls and accesses, with
/// every route's bound rows.
#[allow(clippy::too_many_arguments)]
fn walk_routes(
    program: &SourceProgram,
    sites: &SourceSites,
    routes: &[Vec<PathRow<'_>>],
    names: &mut MachineNames,
    frame_bytes: &mut Vec<FrameAddr>,
    consts: &X86ISelFunction,
    entry: &MachineState,
) -> Result<(Walked, MachineState), X86BodyRefusal> {
    let mut walks: Vec<(Walked, MachineState)> = Vec::with_capacity(routes.len());
    for rows in routes {
        let mut state = entry.clone();
        let walked = walk_rows(program, sites, rows, names, frame_bytes, consts, &mut state)?;
        walks.push((walked, state));
    }
    if walks.len() == 1 {
        return Ok(walks.pop().expect("one route"));
    }
    let (first, _) = &walks[0];
    if walks.iter().any(|(walked, _)| {
        walked.end_stop != first.end_stop
            || walked.calls.len() != first.calls.len()
            || walked.accesses.len() != first.accesses.len()
            || walked
                .calls
                .iter()
                .zip(&first.calls)
                .any(|(a, b)| a.row != b.row || a.args != b.args || a.slots != b.slots)
            || walked
                .accesses
                .iter()
                .zip(&first.accesses)
                .any(|(a, b)| a.row != b.row || a.address != b.address || a.value != b.value)
            || walked.floats.len() != first.floats.len()
            || walked
                .floats
                .iter()
                .zip(&first.floats)
                .any(|(a, b)| a.row != b.row || a.args != b.args)
    }) {
        return Err(unsupported(X86BodyUnsupported::MachineFunction(
            "the routes of one machine block to one successor run different calls, accesses or \
             rounding events, or stop differently"
                .into(),
        )));
    }
    let conjunction = |literals: &[E]| {
        literals
            .iter()
            .cloned()
            .rev()
            .reduce(|tail, literal| literal.and_expr(tail))
            .unwrap_or(E::bool_const(true))
    };
    let conditions: Vec<E> = walks
        .iter()
        .map(|(walked, _)| conjunction(&walked.literals))
        .collect();
    let taken = conditions
        .iter()
        .cloned()
        .rev()
        .reduce(|tail, condition| condition.or_expr(tail))
        .expect("several routes");
    let bound_rows: Vec<usize> = walks
        .iter()
        .flat_map(|(walked, _)| walked.bound_rows.iter().copied())
        .collect();
    // Slice 17: every route's in-bounds claims, each once.
    let mut indexed_claims: Vec<E> = Vec::new();
    for claim in walks.iter().flat_map(|(walked, _)| walked.indexed.iter()) {
        if !indexed_claims.contains(claim) {
            indexed_claims.push(claim.clone());
        }
    }
    let incoming: Vec<(E, MachineState)> = conditions
        .into_iter()
        .zip(walks.iter().map(|(_, state)| state.clone()))
        .map(|(condition, state)| {
            (
                E::ite(condition, E::bv_const(1, 1), E::bv_const(0, 1)),
                state,
            )
        })
        .collect();
    let block = routes[0][0].row.block;
    let state = merge_machine(block, incoming, None, names, frame_bytes)?;
    let (mut walked, _) = walks.swap_remove(0);
    walked.literals = vec![taken];
    walked.indexed = indexed_claims;
    walked.bound_rows.extend(bound_rows);
    walked.bound_rows.sort_unstable();
    walked.bound_rows.dedup();
    Ok((walked, state))
}

/// The machine state at the entry of a DAG join (slice 9): the states
/// the incoming edges bring (`incoming`, each with its edge's guard, in the
/// join's predecessor order), merged by the SOURCE edges' guards. At a
/// reached join exactly one incoming guard holds (the source's edge tests
/// partition its runs), and the theorem requires the machine to have taken
/// that edge (its `jcc` literals), so the merged state is the state of the
/// machine path the source run is paired with; at an unreached one nothing
/// it holds is observed.
///
/// A root that every edge leaves holding bits holds their join (a new
/// definition when they differ); one every edge leaves holding one private
/// address holds it; one some edge leaves undefined is undefined (a read is
/// [`X86BodyMismatch::UndefinedRead`], as on that path); any other mix is
/// [`RegValue::Mixed`]. A private byte the edges leave differently is the
/// join of the bytes they bring (an unwritten one is the slot's initial
/// byte), a new definition. The escaped slots are the union of the edges',
/// closed (slice 13, as in [`merge_admitted`]). Flags are undefined when
/// some edge leaves them undefined (a call), else unmodelled.
///
/// Slice 20 (ruling OD-192): each byte of `dead`, the bytes the source's join
/// left dead ([`DagBody::join_dead`]), is unreadable after the join, whatever
/// the edges bring there.
fn merge_machine(
    join: Block,
    incoming: Vec<(E, MachineState)>,
    dead: Option<&std::collections::BTreeSet<(u32, i64)>>,
    names: &mut MachineNames,
    frame_bytes: &mut Vec<FrameAddr>,
) -> Result<MachineState, X86BodyRefusal> {
    let first = &incoming[0].1;
    // Slice 13: the selector opens and closes an outgoing argument area
    // around one call, in one block.
    if incoming.iter().any(|(_, state)| state.outgoing.is_some()) {
        return Err(unsupported(X86BodyUnsupported::MachineFunction(format!(
            "block {join:?} joins machine paths with an outgoing argument area open"
        ))));
    }
    let mut roots: Vec<Root> = first.regs.keys().copied().collect();
    roots.sort_unstable_by_key(|root| match root {
        Root::Physical(root) => (0, u32::from(*root)),
        Root::Virtual(id) => (1, *id),
    });
    let mut regs: HashMap<Root, RegValue> = HashMap::new();
    for root in roots {
        let values: Option<Vec<&RegValue>> = incoming
            .iter()
            .map(|(_, state)| state.regs.get(&root))
            .collect();
        let Some(values) = values else {
            continue;
        };
        let merged = match values.as_slice() {
            [RegValue::Bits(head), rest @ ..]
                if rest.iter().all(|value| matches!(value, RegValue::Bits(_))) =>
            {
                let slots: Vec<&Slot> = values
                    .iter()
                    .map(|value| match value {
                        RegValue::Bits(slot) => slot,
                        _ => unreachable!("matched above"),
                    })
                    .collect();
                if slots.iter().all(|slot| slot.expr == head.expr) {
                    RegValue::Bits(Slot {
                        expr: head.expr.clone(),
                        affine: head
                            .affine
                            .filter(|affine| slots.iter().all(|slot| slot.affine == Some(*affine))),
                    })
                } else {
                    let joined = join_terms(
                        incoming
                            .iter()
                            .zip(&slots)
                            .map(|((guard, _), slot)| (guard.clone(), slot.expr.clone()))
                            .collect(),
                    );
                    let name = names.define(JOIN_ROW, joined);
                    RegValue::Bits(Slot {
                        expr: E::var(&name, 64),
                        affine: None,
                    })
                }
            }
            [RegValue::Frame(head), rest @ ..]
                if rest
                    .iter()
                    .all(|value| matches!(value, RegValue::Frame(address) if address == head)) =>
            {
                RegValue::Frame(*head)
            }
            // Slice 17: an indexed address every edge leaves alike.
            [RegValue::Indexed(head), rest @ ..]
                if rest.iter().all(
                    |value| matches!(value, RegValue::Indexed(address) if address == head),
                ) =>
            {
                RegValue::Indexed(head.clone())
            }
            values
                if values
                    .iter()
                    .all(|value| matches!(value, RegValue::Carried)) =>
            {
                RegValue::Carried
            }
            _ => RegValue::Mixed,
        };
        regs.insert(root, merged);
    }
    let mut stack = first.stack.clone();
    for (slot, bytes) in stack.iter_mut().enumerate() {
        for (offset, merged) in bytes.iter_mut().enumerate() {
            let brought: Vec<&Option<MachineByte>> = incoming
                .iter()
                .map(|(_, state)| &state.stack[slot][offset])
                .collect();
            if dead.is_some_and(|dead| dead.contains(&(slot as u32, offset as i64))) {
                *merged = Some(MachineByte::dead());
                continue;
            }
            let alike = brought.iter().all(|byte| same_byte(byte, brought[0]));
            if alike {
                continue;
            }
            // Slice 17: a byte unreadable on some edge is unreadable after
            // the join (as the source's, [`merge_admitted`]).
            if brought
                .iter()
                .any(|byte| byte.as_ref().is_some_and(|byte| byte.dead))
            {
                *merged = Some(MachineByte::dead());
                continue;
            }
            let address = FrameAddr {
                slot: slot as u32,
                offset: offset as i64,
            };
            // Slice 13: a stored private address is tracked, never a byte
            // term a join may choose (as in the source's merge).
            if brought
                .iter()
                .any(|byte| byte.as_ref().is_some_and(|byte| byte.frame.is_some()))
            {
                return Err(unsupported(X86BodyUnsupported::MachineFunction(format!(
                    "block {join:?} joins machine paths that leave {} holding different values, \
                     one of them a private stack address",
                    address.describe()
                ))));
            }
            let joined = join_terms(
                incoming
                    .iter()
                    .zip(&brought)
                    .map(|((guard, _), byte)| {
                        let term = match byte {
                            Some(byte) => byte.expr(),
                            // A byte this edge never wrote: the slot's
                            // initial byte, shared with the source.
                            None => E::var(
                                frame_byte_name(register_frame_byte(frame_bytes, address)),
                                8,
                            ),
                        };
                        (guard.clone(), term)
                    })
                    .collect(),
            );
            let name = names.define(JOIN_ROW, joined);
            *merged = Some(MachineByte {
                term: E::var(&name, 8),
                width: 8,
                byte: 0,
                affine: None,
                frame: None,
                dead: false,
            });
        }
    }
    let flags = if incoming
        .iter()
        .any(|(_, state)| matches!(state.flags, Flags::Undefined))
    {
        Flags::Undefined
    } else {
        Flags::Unmodelled
    };
    // Slice 13: the union of the edges' escaped slots, closed.
    let mut escaped = std::collections::BTreeSet::new();
    escape_machine(
        &mut escaped,
        &stack,
        incoming
            .iter()
            .flat_map(|(_, state)| state.escaped.iter().copied()),
    );
    // Slice 14: whether the machine stopped (and how) on the edge taken,
    // joined like a register.
    let mut join_bit = |bits: Vec<E>| {
        if bits.iter().all(|bit| *bit == bits[0]) {
            return bits[0].clone();
        }
        let joined = join_terms(
            incoming
                .iter()
                .zip(bits)
                .map(|((guard, _), bit)| (guard.clone(), bit))
                .collect(),
        );
        E::var(names.define(JOIN_ROW, joined), 1)
    };
    let stopped = join_bit(
        incoming
            .iter()
            .map(|(_, state)| state.stopped.clone())
            .collect(),
    );
    let trapped = join_bit(
        incoming
            .iter()
            .map(|(_, state)| state.trapped.clone())
            .collect(),
    );
    Ok(MachineState {
        regs,
        stack,
        escaped,
        flags,
        outgoing: None,
        stopped,
        trapped,
    })
}

/// The result register of lane `lane` (RAX, then RDX) after the `k`-th call
/// returns `result` there: its defined low bits hold the free input
/// `r{k}`/`q{k}` (for a scalar [`Carrier::call_result_bits`]: a `B1` is 0 or
/// 1 in AL when it is the only result, and bit 0 alone when it is a lane of a
/// pair; for an aggregate's eightbyte, slice 8, its bytes), and every bit
/// above is the free input `g{k}`/`h{k}`: a caller may not rely on it.
fn call_result_register(k: usize, lane: usize, result: ResultLane) -> E {
    let bits = result.defined_bits;
    let defined = fit(
        E::var(call_result_name(k, lane), result.value_bits),
        result.value_bits,
        bits,
    );
    if bits == 64 {
        defined
    } else {
        E::var(call_garbage_name(k, lane), 64 - bits).concat(defined)
    }
}

/// Compare a machine `Call` row with the source call in the same position:
/// same callee symbol and binding, and the System V argument and result
/// registers the source signature implies, at the widths the callee reads
/// and defines. The selector records the same facts for register allocation
/// and TV-5; any disagreement is a wrong lowering.
fn check_call_row(row: usize, inst: &X86ISelInst, call: &SourceCall) -> Result<(), X86BodyRefusal> {
    let describe = |name: &str, exact: bool| {
        format!(
            "`{name}` ({})",
            if exact {
                "exact module function"
            } else {
                "by symbol"
            }
        )
    };
    // Slice 10: an indirect source call pairs only with `call r64`, whose
    // register the theorem observes against the source's function pointer,
    // and a direct one only with `call symbol`.
    let indirect = "an indirect call through a register".to_owned();
    match (inst.operands.as_slice(), call.callee) {
        ([O::Symbol(symbol)], None) => {
            let exact_module = inst.flags.contains(InstFlags::EXACT_MODULE_CALL);
            if *symbol != call.name || exact_module != call.exact_module {
                return Err(mismatch(X86BodyMismatch::CallTarget {
                    row,
                    expected: describe(&call.name, call.exact_module),
                    found: describe(symbol, exact_module),
                }));
            }
        }
        ([O::Symbol(symbol)], Some(_)) => {
            return Err(mismatch(X86BodyMismatch::CallTarget {
                row,
                expected: indirect,
                found: describe(symbol, inst.flags.contains(InstFlags::EXACT_MODULE_CALL)),
            }));
        }
        (_, None) => {
            return Err(mismatch(X86BodyMismatch::CallTarget {
                row,
                expected: describe(&call.name, call.exact_module),
                found: indirect,
            }));
        }
        (_, Some(_)) => {}
    }
    // Each argument register's declared width: a scalar's return bits, a
    // private address's 64, and (slice 8) each aggregate eightbyte's register
    // width.
    let widths: Vec<u32> = call
        .args
        .iter()
        .flat_map(|arg| match arg {
            // Slice 11: an `I128` declares both halves at 64 bits.
            CallArg::Scalar(_, Carrier::I128) => vec![64, 64],
            CallArg::Scalar(_, ty) => vec![ty.return_bits()],
            CallArg::Frame(..) | CallArg::Indexed(..) => vec![64],
            CallArg::Aggregate(lanes) => lanes
                .iter()
                .map(|lane| {
                    Eightbyte {
                        offset: 0,
                        bytes: lane.len() as u32,
                    }
                    .register_bits()
                })
                .collect(),
        })
        .collect();
    let expected_args: Vec<X86CallArgReg> = widths
        .iter()
        .zip(call.arg_roots.iter().copied())
        .map(|(bits, root)| {
            X86CallArgReg::new(trust_cg_ir::x86_64_regs::X86PReg::new(root), *bits as u16)
        })
        .collect();
    if inst.call_arg_regs != expected_args {
        return Err(mismatch(X86BodyMismatch::CallMetadata {
            row,
            detail: format!(
                "declares argument registers {:?} where the System V table gives {expected_args:?}",
                inst.call_arg_regs
            ),
        }));
    }
    let expected_results: Vec<X86CallResultReg> = call
        .results
        .iter()
        .map(|lane| {
            X86CallResultReg::new(
                trust_cg_ir::x86_64_regs::X86PReg::new(lane.root),
                lane.register_bits as u16,
            )
        })
        .collect();
    if inst.call_result_regs.as_deref() != Some(expected_results.as_slice()) {
        return Err(mismatch(X86BodyMismatch::CallMetadata {
            row,
            detail: format!(
                "declares result registers {:?} where the System V table gives \
                 {expected_results:?}",
                inst.call_result_regs
            ),
        }));
    }
    Ok(())
}

/// The machine state a walk carries across rows and blocks: the registers,
/// the private stack bytes, the escaped slots and RFLAGS. On a path it flows
/// row to row; at a DAG join (slice 9) it is the merge of the states the
/// incoming edges bring ([`merge_machine`]).
#[derive(Clone)]
struct MachineState {
    /// What each register root holds.
    regs: HashMap<Root, RegValue>,
    /// The private stack: every byte of every slot the body wrote.
    stack: Vec<Vec<Option<MachineByte>>>,
    /// Slice 7: the slots whose address the machine passed to a call so far.
    escaped: std::collections::BTreeSet<u32>,
    /// RFLAGS (slice 5).
    flags: Flags,
    /// Slice 13: the outgoing argument area a `sub rsp, n` opened for the
    /// next call's stack arguments, byte by byte, until its `add rsp, n`.
    outgoing: Option<Vec<Option<MachineByte>>>,
    /// Slice 14: a 1-bit term, 1 exactly when the machine has stopped short
    /// on this walk: a `div`/`idiv` faulted (#DE) or a `TrapDivZeroExact`
    /// carrier fired. The walk goes on past such a row (its later rows then
    /// state what a run that does not stop there computes); every claim
    /// after it requires this 0 where the source has not stopped.
    stopped: E,
    /// Slice 14: a 1-bit term, 1 exactly when the machine's first stop was a
    /// `TrapDivZeroExact` carrier firing (the trap a divide-by-zero guard
    /// asks for, not a #DE before it).
    trapped: E,
}

/// The 1-bit zero: nothing has stopped (slice 14).
fn bit_zero() -> E {
    E::bv_const(0, 1)
}

/// `condition` as a 1-bit term (slice 14).
fn bit_of(condition: E) -> E {
    E::ite(condition, E::bv_const(1, 1), E::bv_const(0, 1))
}

/// The 1-bit OR, without a term for an operand known to be zero (slice 14).
fn bit_or(a: E, b: E) -> E {
    if a == bit_zero() {
        b
    } else if b == bit_zero() {
        a
    } else {
        a.bvor(b)
    }
}

impl MachineState {
    /// The state at the function's entry under `convention`, with the entry
    /// names of every argument and preserved root (in declaration order) and
    /// the caller-view definitions of `B1` argument registers.
    #[allow(clippy::type_complexity)]
    fn entry(
        program: &SourceProgram,
        convention: BoolArguments,
    ) -> (Self, Vec<String>, Vec<(String, E)>) {
        let mut state: HashMap<Root, RegValue> = HashMap::new();
        let mut entry_names = Vec::new();
        let mut abi_views = Vec::new();
        for (i, param) in program.params.iter().enumerate() {
            for root in &param.roots {
                let name = entry_name(*root);
                let entry = E::var(&name, 64);
                let slot = match param.abi {
                    ParamAbi::Scalar(Carrier::B1) => {
                        // Bit 0 is the truth value; the convention says which
                        // bits above it the caller clears (module
                        // documentation).
                        let view = convention.view_name(i);
                        abi_views.push((view.clone(), convention.view(entry)));
                        Slot {
                            expr: E::var(view, 64),
                            affine: None,
                        }
                    }
                    ParamAbi::Scalar(ty) => Slot {
                        expr: entry,
                        affine: (ty == Carrier::I64).then(|| parameter_affine(i)).flatten(),
                    },
                    // Slice 8: an eightbyte of an aggregate parameter; only
                    // its bytes are the caller's (the source reads exactly
                    // those).
                    ParamAbi::Aggregate { .. } => Slot {
                        expr: entry,
                        affine: None,
                    },
                };
                state.insert(Root::Physical(*root), RegValue::Bits(slot));
                entry_names.push(name);
            }
            // Slice 13: a parameter on the stack is no register's; the walk
            // reads its eightbyte where a row loads it ([`AccessTarget::StackParameter`]).
            for disp in param.stack_eightbytes() {
                entry_names.push(stack_parameter_name(disp));
            }
        }
        for root in SYSV_PRESERVED_ROOTS {
            let name = entry_name(root);
            state.insert(
                Root::Physical(root),
                RegValue::Bits(Slot {
                    expr: E::var(&name, 64),
                    affine: None,
                }),
            );
            entry_names.push(name);
        }
        let machine = Self {
            regs: state,
            // The private stack: every byte of every slot the body wrote, and
            // the free input naming each byte it read before writing it.
            stack: program
                .slot_sizes
                .iter()
                .map(|size| vec![None; *size as usize])
                .collect(),
            escaped: std::collections::BTreeSet::new(),
            // RFLAGS (slice 5): undefined at entry (the psABI does not define
            // the status flags across a call boundary).
            flags: Flags::Undefined,
            outgoing: None,
            stopped: bit_zero(),
            trapped: bit_zero(),
        };
        (machine, entry_names, abi_views)
    }
}

fn walk_machine(
    program: &SourceProgram,
    sites: &SourceSites,
    path: &[PathRow<'_>],
    names: &mut MachineNames,
    frame_bytes: &mut Vec<FrameAddr>,
    consts: &X86ISelFunction,
) -> Result<Walked, X86BodyRefusal> {
    let (mut machine, entry_names, abi_views) = MachineState::entry(program, names.convention);
    let mut walked = walk_rows(
        program,
        sites,
        path,
        names,
        frame_bytes,
        consts,
        &mut machine,
    )?;
    walked.entry_names = entry_names;
    walked.abi_views = abi_views;
    Ok(walked)
}

/// The machine row an incoming-memory access belongs to.
struct RowCtx<'a> {
    program: &'a SourceProgram,
    /// The row's walk ordinal.
    row: usize,
    opcode: X86Opcode,
    /// The row carries the selector's atomic origin (OD-83).
    atomic: bool,
}

/// The walk state an incoming-memory access reads and advances.
struct IncomingWalk<'a> {
    /// The next event of the source's world trace.
    next_event: &'a mut usize,
    accesses: &'a mut Vec<WalkedAccess>,
    stack: &'a mut Vec<Vec<Option<MachineByte>>>,
    escaped: &'a mut std::collections::BTreeSet<u32>,
    frame_bytes: &'a mut Vec<FrameAddr>,
    stopped: &'a E,
    trapped: &'a E,
}

/// What an incoming-memory access writes: nothing (a load), a store row's
/// register operand (read only after every trace check), a private stack
/// address stored as data (slice 13), or (slice 25) a value the row itself
/// computes at the access's width, a read-modify-write's result.
enum Stored<'a> {
    Load,
    Register(&'a dyn Fn() -> Result<(Reg, Slot), X86BodyRefusal>),
    Frame(FrameAddr),
    Value(E, Option<Affine>),
}

/// The outcome of [`incoming_access`]: a load's bytes at the source
/// carrier's memory width, or a completed store.
enum Incoming {
    Loaded(E),
    Stored,
}

/// The next incoming-memory access of the world trace (slice 4), made by a
/// machine row at the 64-bit `address`: paired with the source's next event,
/// which must be a plain (or, OD-83, atomic exactly when the row is) access
/// of the row's width and kind that no pseudo row lowers (OD-201), checked in
/// that order. Slice 15: an access the source makes through an address that
/// may derive from an escaped slot observes those slots' contents too, and
/// such a store leaves each of their bytes as its site's free input, on both
/// sides. A read-modify-write row (slice 25) makes two such accesses, its
/// load and then its store.
fn incoming_access(
    ctx: &RowCtx<'_>,
    walk: &mut IncomingWalk<'_>,
    form: MemoryAccessForm,
    address: E,
    address_affine: Option<Affine>,
    stored: Stored<'_>,
) -> Result<Incoming, X86BodyRefusal> {
    let RowCtx {
        program,
        row,
        opcode,
        atomic,
    } = *ctx;
    let trace = |detail: String| {
        unsupported(X86BodyUnsupported::AccessTrace {
            detail: format!("row {row}: {detail}"),
        })
    };
    let Some(SourceEvent::Access(access)) = program.events.get(*walk.next_event) else {
        return Err(trace(format!(
            "an incoming-memory {} where the source's next event is {}",
            if form.load { "load" } else { "store" },
            describe_event(program, *walk.next_event)
        )));
    };
    let source_access = &program.accesses[*access];
    // Slice 21 (OD-201): an access the selector lowers to a pseudo row
    // pairs with no `mov`.
    if source_access.pseudo.is_some() {
        return Err(trace(format!(
            "a {opcode:?} paired with an atomic source access its pseudo row lowers"
        )));
    }
    // Slice 13: an atomic source access pairs only with a row of the
    // selector's atomic origin, and a plain one only with a plain row
    // (OD-83).
    if source_access.atomic != atomic {
        return Err(trace(format!(
            "{} machine access paired with {} source access",
            if atomic { "an atomic" } else { "a plain" },
            if source_access.atomic {
                "an atomic"
            } else {
                "a plain"
            }
        )));
    }
    if source_access.carrier.bytes() != form.bytes {
        return Err(trace(format!(
            "a {}-byte access paired with a {}-byte source access",
            form.bytes,
            source_access.carrier.bytes()
        )));
    }
    *walk.next_event += 1;
    // Slice 15: an access the source makes through an address that may
    // derive from an escaped slot reads (and a store may write) those slots'
    // bytes too: the machine must have let exactly the source's slots escape
    // (else no single trace states both, and the body makes no claim), and
    // their contents here are observed like a call's.
    let slots = match &source_access.slot_reads {
        None => Vec::new(),
        Some(reads) => {
            if !walk
                .escaped
                .iter()
                .copied()
                .eq(reads.iter().map(|(slot, _)| *slot))
            {
                return Err(unsupported(X86BodyUnsupported::MachineRow {
                    row,
                    detail: format!(
                        "the private stack slots escaped at access {access} ({:?}) are not the \
                         source's ({:?})",
                        walk.escaped,
                        reads.iter().map(|(slot, _)| *slot).collect::<Vec<_>>()
                    ),
                }));
            }
            machine_slot_chunks(walk.escaped, walk.stack.as_slice(), walk.frame_bytes)
                .map_err(|detail| unsupported(X86BodyUnsupported::MachineRow { row, detail }))?
        }
    };
    // A store through such an address leaves each byte of each escaped slot
    // as its site's free input, on both sides.
    let store_site = source_access.store_site;
    let redefine = |stack: &mut Vec<Vec<Option<MachineByte>>>,
                    escaped: &std::collections::BTreeSet<u32>| {
        if let Some(site) = store_site {
            for slot in escaped.iter() {
                for (offset, byte) in stack[*slot as usize].iter_mut().enumerate() {
                    let address = FrameAddr {
                        slot: *slot,
                        offset: offset as i64,
                    };
                    *byte = Some(MachineByte {
                        term: E::var(access_byte_name(site, address), 8),
                        width: 8,
                        byte: 0,
                        affine: None,
                        frame: None,
                        dead: false,
                    });
                }
            }
        }
    };
    let width = form.bytes * 8;
    let stop = (walk.stopped.clone(), walk.trapped.clone());
    let (value, value_affine) = match (stored, source_access.kind) {
        // The bytes the paired source load reads: both sides read the same
        // world at the same address (the observable states it). The machine
        // gets the bytes themselves; what they mean at the source type is
        // the source side's.
        (Stored::Load, AccessKind::Load(load)) => {
            walk.accesses.push(WalkedAccess {
                row,
                address,
                address_affine,
                value: None,
                value_affine: None,
                slots,
                stop,
            });
            return Ok(Incoming::Loaded(E::var(
                memory_load_name(load),
                source_access.carrier.memory_bits(),
            )));
        }
        // Slice 13: a private address stored to incoming memory, which every
        // later call can read.
        (Stored::Frame(stored), AccessKind::Store(_)) => {
            walk.accesses.push(WalkedAccess {
                row,
                address,
                address_affine,
                value: Some(frame_address_term(stored)),
                value_affine: None,
                slots,
                stop,
            });
            redefine(&mut *walk.stack, walk.escaped);
            escape_machine(walk.escaped, walk.stack.as_slice(), [stored.slot]);
            return Ok(Incoming::Stored);
        }
        (Stored::Register(source), AccessKind::Store(_)) => {
            let (reg, value) = source()?;
            (
                low(value.expr, width),
                (width == 64 && reg.bits == 64)
                    .then_some(value.affine)
                    .flatten(),
            )
        }
        (Stored::Value(value, value_affine), AccessKind::Store(_)) => (value, value_affine),
        _ => {
            return Err(trace(format!(
                "a {} paired with a source {}",
                if form.load { "load" } else { "store" },
                if form.load { "store" } else { "load" }
            )));
        }
    };
    walk.accesses.push(WalkedAccess {
        row,
        address,
        address_affine,
        value: Some(value),
        value_affine,
        slots,
        stop,
    });
    redefine(&mut *walk.stack, walk.escaped);
    Ok(Incoming::Stored)
}

/// Walk the rows of `path` from `machine` (the state before its first row),
/// pairing them with `program`'s calls, accesses and end, and leave the
/// state after its last row in `machine`. A path's walk starts at the
/// function's entry; a DAG block's (slice 9) at the merged state of its
/// entry, with `program` that block's fragment.
fn walk_rows(
    program: &SourceProgram,
    sites: &SourceSites,
    path: &[PathRow<'_>],
    names: &mut MachineNames,
    frame_bytes: &mut Vec<FrameAddr>,
    consts: &X86ISelFunction,
    machine: &mut MachineState,
) -> Result<Walked, X86BodyRefusal> {
    let MachineState {
        regs: state,
        stack,
        escaped,
        flags,
        outgoing,
        stopped,
        trapped,
    } = machine;
    let mut bound_rows = Vec::new();
    let mut literals = Vec::new();
    let mut calls: Vec<WalkedCall> = Vec::new();
    let mut accesses: Vec<WalkedAccess> = Vec::new();
    // Slice 21: the rounding rows paired with source rounding events.
    let mut floats: Vec<WalkedFloat> = Vec::new();
    // Slice 17: the in-bounds claims of the indexed accesses and arguments.
    let mut indexed_claims: Vec<E> = Vec::new();
    // The next event of the source's world trace the machine must follow.
    let mut next_event = 0usize;
    // The result registers at the RET, in lane order (RAX, then RDX).
    let mut observed: Vec<Slot> = Vec::new();
    let mut block = path.first().map(|first| first.row.block);
    // Tests only (`s24c-flags-reset-at-members`): the LIR block of the last
    // stamped row.
    let mut stamp_block: Option<u32> = None;
    for PathRow { row, taken, jump } in path {
        // A two-operand (tied) ALU row is walked as the three-operand row it
        // computes (slice 8, [`untied`]); the `xor d, d` zeroing idiom and the
        // in-place `inc`/`dec` as the rows they compute ([`restated_row`]).
        let untied_row = untied(row.inst).or_else(|| restated_row(row.inst));
        let inst = untied_row.as_ref().unwrap_or(row.inst);
        // Flags never cross a block boundary (slice 6): a flag reader after
        // one makes no claim (flags left undefined stay undefined).
        if block != Some(row.block) {
            block = Some(row.block);
            if matches!(
                flags,
                Flags::Compare { .. } | Flags::Test { .. } | Flags::Alu(_)
            ) {
                *flags = Flags::Unmodelled;
            }
        }
        if mutated("s24c-flags-reset-at-members")
            && let Some(id) = row.inst.lowering_provenance.source_id()
        {
            if stamp_block.is_some_and(|known| known != id.block) {
                *flags = Flags::Unmodelled;
            }
            stamp_block = Some(id.block);
        }
        let undefined = |root: Root| {
            mismatch(X86BodyMismatch::UndefinedRead {
                row: row.ordinal,
                operand: root.describe(),
            })
        };
        let escapes = |root: Root| {
            unsupported(X86BodyUnsupported::MachineRow {
                row: row.ordinal,
                detail: format!(
                    "{:?} reads the private stack address in {} as a value (the slot's address \
                     escapes)",
                    inst.opcode,
                    root.describe()
                ),
            })
        };
        let trace = |detail: String| {
            unsupported(X86BodyUnsupported::AccessTrace {
                detail: format!("row {}: {detail}", row.ordinal),
            })
        };
        // Slice 9: a root the paths into a DAG join leave holding different
        // private addresses, or an address on some paths and bits on others.
        let mixed = |root: Root| {
            unsupported(X86BodyUnsupported::MachineRow {
                row: row.ordinal,
                detail: format!(
                    "{:?} reads {}, which the paths into its block leave holding different \
                     kinds of value",
                    inst.opcode,
                    root.describe()
                ),
            })
        };
        // Slice 12: a root a loop carries that no header parameter pairs.
        let carried = |root: Root| {
            unsupported(X86BodyUnsupported::MachineRow {
                row: row.ordinal,
                detail: format!(
                    "{:?} reads {}, which its loop carries paired with no loop-header \
                     parameter",
                    inst.opcode,
                    root.describe()
                ),
            })
        };
        // Slice 14: a jump-table dispatch value read other than by the
        // dispatch's own rows.
        let dispatch_value = |root: Root| {
            unsupported(X86BodyUnsupported::MachineRow {
                row: row.ordinal,
                detail: format!(
                    "{:?} reads the jump-table address or entry in {} as a value",
                    inst.opcode,
                    root.describe()
                ),
            })
        };
        // A root's bits: never a private stack address.
        let bits_of = |root: Root| -> Result<Slot, X86BodyRefusal> {
            match state.get(&root) {
                None => Err(undefined(root)),
                Some(RegValue::Frame(_) | RegValue::Indexed(_)) => Err(escapes(root)),
                Some(RegValue::Mixed) => Err(mixed(root)),
                Some(RegValue::Carried) => Err(carried(root)),
                Some(RegValue::Dispatch(_)) => Err(dispatch_value(root)),
                Some(RegValue::Bits(slot)) => Ok(slot.clone()),
            }
        };
        // A register operand: a general-purpose register or (slice 11) an SSE
        // register, at the width it names.
        let root_of = |operand: &O| -> Result<(Reg, Slot), X86BodyRefusal> {
            let reg = gpr(operand)
                .or_else(|| xmm(operand))
                .expect("row shape checked");
            Ok((reg, bits_of(reg.root)?))
        };
        // A store's register operand: a 32- or 64-bit register, or (slice 8)
        // a physical register's 8- or 16-bit alias, which names its low bits,
        // or (slice 11) an SSE register.
        let store_source = |operand: &O| -> Result<(Reg, Slot), X86BodyRefusal> {
            if gpr(operand).is_some() || xmm(operand).is_some() {
                return root_of(operand);
            }
            let (root, bits) = [8, 16]
                .into_iter()
                .find_map(|bits| narrow_alias(operand, bits).map(|root| (root, bits)))
                .expect("row shape checked");
            Ok((Reg { root, bits }, bits_of(root)?))
        };
        // The operand's value at the width it names, with its affine value
        // only for a full 64-bit read.
        let read = |operand: &O| -> Result<(E, Option<Affine>, u32), X86BodyRefusal> {
            let (reg, slot) = root_of(operand)?;
            let affine = if reg.bits == 64 { slot.affine } else { None };
            Ok((low(slot.expr, reg.bits), affine, reg.bits))
        };
        let read_low = |operand: &O, bits: u32| -> Result<E, X86BodyRefusal> {
            Ok(low(root_of(operand)?.1.expr, bits))
        };
        // The private stack address a 64-bit register operand holds, if any.
        let frame_of = |operand: &O| match gpr64(operand).and_then(|reg| state.get(&reg.root)) {
            Some(RegValue::Frame(address)) => Some(*address),
            _ => None,
        };
        // Every ALU row writes RFLAGS with semantics this walk does not
        // model: a later `setcc` reading them makes no claim. (Such a row
        // reads no flag, so the update may precede its value.) Read from the
        // REAL opcode, not the rewritten row: `untied` keeps the opcode, but
        // [`zeroing_idiom`] restates a flag-writing `xor` as a `mov`, which
        // writes none.
        if writes_unmodelled_flags(row.inst.opcode) {
            *flags = Flags::Unmodelled;
        }
        // A compare (slice 5) writes only RFLAGS: `cmp lhs, rhs` at the width
        // its register operand names, an immediate sign-extended from 32
        // bits. The flags it defines are the shared x86 EFLAGS model of
        // `lhs - rhs` (`x86_64_eflags::encode_cmp_eflags`), read by `setcc`.
        // A test (slice 6) likewise: `test lhs, rhs` defines the flags of
        // `lhs & rhs` (`x86_64_eflags::encode_test_eflags`).
        // `bt src, k` (slice 19): CF becomes bit `k` of `src` and NOTHING
        // else is defined — the operand is unchanged and OF/SF/ZF/AF/PF are
        // architecturally undefined, so a reader of any of those refuses
        // through the partial model ([`AluFlags::carry_only`]). The row
        // defines no register: `trust_cg_ir` already classifies `BtRI` as
        // producing no value.
        if inst.opcode == X86Opcode::BtRI {
            let (src, _, bits) = read(&inst.operands[0])?;
            let O::Imm(imm) = &inst.operands[1] else {
                unreachable!("row shape checked");
            };
            let k = u32::try_from(*imm).expect("row shape checked the bit index");
            debug_assert!(k < bits, "row shape checked the bit index against width");
            *flags = Flags::Alu(Box::new(AluFlags::bit_test(low(src, bits), k)));
            bound_rows.push(row.ordinal);
            continue;
        }
        // Slice 21: `ucomisd`/`ucomiss a, b` writes ZF, PF and CF exactly from
        // the IEEE 754 relation of the low 64 (32) bits of its operands and
        // clears OF and SF (Intel SDM UCOMISD; [`FloatRelation::ucomis_flags`],
        // the bit-level predicates of `fp_bv_lowering`), read by `setcc`,
        // `cmovcc` and `jcc` through the shared condition evaluation.
        if matches!(inst.opcode, X86Opcode::Ucomisd | X86Opcode::Ucomiss) {
            let format = if inst.opcode == X86Opcode::Ucomisd {
                Carrier::F64
            } else {
                Carrier::F32
            };
            let lhs = read_low(&inst.operands[0], format.bits())?;
            let rhs = read_low(&inst.operands[1], format.bits())?;
            *flags = Flags::Alu(Box::new(
                FloatRelation::of(format, &lhs, &rhs).ucomis_flags(),
            ));
            bound_rows.push(row.ordinal);
            continue;
        }
        if matches!(
            inst.opcode,
            X86Opcode::CmpRR | X86Opcode::CmpRI | X86Opcode::TestRR | X86Opcode::TestRI
        ) {
            let (lhs, _, bits) = read(&inst.operands[0])?;
            let rhs = match &inst.operands[1] {
                O::Imm(imm) => E::bv_const(
                    (i64::from(*imm as i32) as u64) & crate::smt::mask(u64::MAX, bits),
                    bits,
                ),
                operand => read(operand)?.0,
            };
            *flags = if matches!(inst.opcode, X86Opcode::CmpRR | X86Opcode::CmpRI) {
                Flags::Compare { lhs, rhs, bits }
            } else {
                Flags::Test { lhs, rhs, bits }
            };
            bound_rows.push(row.ordinal);
            continue;
        }
        // A conditional jump (slice 6): the path takes it or not (the
        // pairing decided which), and the theorem states the condition under
        // which the machine does so.
        if inst.opcode == X86Opcode::Jcc {
            let O::CondCode(cc) = inst.operands[0] else {
                unreachable!("row shape checked");
            };
            let holds = flags.condition(cc, row.ordinal, inst.opcode)?;
            literals.push(if taken.expect("a Jcc row records its direction") {
                holds
            } else {
                holds.not_expr()
            });
            bound_rows.push(row.ordinal);
            continue;
        }
        // Slice 13: `sub rsp, n` opens the outgoing argument area of the next
        // call's stack arguments, and `add rsp, n` closes it after the call
        // (the selector's call sequence; the frame layout and the alignment
        // of RSP at the call are the post-allocation validators', as for
        // every call). Any other adjustment of RSP is outside the domain.
        if matches!(inst.opcode, X86Opcode::SubRI | X86Opcode::AddRI)
            && let [O::PReg(preg), O::Imm(bytes)] = inst.operands.as_slice()
            && preg.encoding() == RSP
        {
            match (inst.opcode, outgoing.as_ref()) {
                (X86Opcode::SubRI, None) => {
                    *outgoing = Some(vec![None; *bytes as usize]);
                }
                (X86Opcode::AddRI, Some(area)) if area.len() as i64 == *bytes => {
                    *outgoing = None;
                }
                _ => {
                    return Err(unsupported(X86BodyUnsupported::MachineRow {
                        row: row.ordinal,
                        detail: format!(
                            "{:?} adjusts RSP other than to open and close one call's outgoing \
                             argument area",
                            inst.opcode
                        ),
                    }));
                }
            }
            bound_rows.push(row.ordinal);
            continue;
        }
        // The 64-bit constant a register operand holds, when the walk's
        // exact folding knows it.
        let constant = |operand: &O| match gpr64(operand).and_then(|reg| state.get(&reg.root)) {
            Some(RegValue::Bits(slot)) => slot.affine.and_then(|affine| affine.as_constant()),
            _ => None,
        };
        // Private stack addresses (slice 4): `lea` of a slot, and a copy of
        // one or a constant offset from one, write an address, not bits.
        // Slice 17: `add` of a frame (or indexed) register and a value, and
        // `lea` with a scaled index over one, write an indexed address whose
        // offset is the term those rows compute.
        let private_of = |operand: &O| match gpr64(operand).and_then(|reg| state.get(&reg.root)) {
            Some(RegValue::Frame(address)) => Some(MachinePrivate::Frame(*address)),
            Some(RegValue::Indexed(address)) => Some(MachinePrivate::Indexed(address.clone())),
            _ => None,
        };
        let bits_in = |operand: &O| match gpr64(operand).and_then(|reg| state.get(&reg.root)) {
            Some(RegValue::Bits(slot)) => Some(slot.clone()),
            _ => None,
        };
        // Slice 25 (OD-227): the address a scaled-index access or
        // read-modify-write reaches, what `LeaSib` computes, by component,
        // base first. A stack-slot base is the slot's address, what `lea b,
        // [slot]` writes (an undeclared slot makes no claim); a register is
        // its private address or its 64-bit bits, with [`bits_of`]'s
        // refusals otherwise. A private base at a constant or a bits index is
        // [`sib_private`] (OD-185, slice 17), and so is a bits base at scale 1
        // over a private index (`b + i*1 = i + b*1`, as `add` reads either
        // side); any other private component is read as a value (it
        // escapes). Two bits components are [`sib_bits`], the effective
        // address the caller names as `LeaSib`'s row names its destination.
        let sib_address = |operand: &SibOperand| -> Result<SibAddress, X86BodyRefusal> {
            let component = |base: SibBase| match base {
                SibBase::Slot(slot) => {
                    if slot as usize >= program.slot_sizes.len()
                        && !mutated("s25-no-declared-slot-check")
                    {
                        return Err(unsupported(X86BodyUnsupported::MachineRow {
                            row: row.ordinal,
                            detail: format!("names stack slot {slot}, which is not declared"),
                        }));
                    }
                    let offset = if mutated("s25-slot-base-at-disp") {
                        i64::from(operand.disp)
                    } else {
                        0
                    };
                    Ok(SibAddress::Private(MachinePrivate::Frame(FrameAddr {
                        slot,
                        offset,
                    })))
                }
                SibBase::Register(reg) => match state.get(&reg.root) {
                    None => Err(undefined(reg.root)),
                    Some(RegValue::Mixed) => Err(mixed(reg.root)),
                    Some(RegValue::Carried) => Err(carried(reg.root)),
                    Some(RegValue::Dispatch(_)) => Err(dispatch_value(reg.root)),
                    Some(RegValue::Frame(address)) => {
                        Ok(SibAddress::Private(MachinePrivate::Frame(*address)))
                    }
                    Some(RegValue::Indexed(address)) => Ok(SibAddress::Private(
                        MachinePrivate::Indexed(address.clone()),
                    )),
                    Some(RegValue::Bits(slot)) => {
                        Ok(SibAddress::Bits(slot.expr.clone(), slot.affine))
                    }
                },
            };
            let base = component(operand.base)?;
            let index = component(SibBase::Register(operand.index))?;
            let scale = if mutated("s25-scale-ignored") {
                1
            } else {
                operand.scale
            };
            let disp = operand.disp;
            let term = |expr: E, affine: Option<Affine>| match affine.and_then(Affine::as_constant)
            {
                Some(k) => SibIndex::Constant(k),
                None => SibIndex::Term(expr),
            };
            let overflow = || {
                unsupported(X86BodyUnsupported::MachineRow {
                    row: row.ordinal,
                    detail: "overflows a private stack offset".into(),
                })
            };
            let commutes =
                (scale == 1 || mutated("s25-commute-every-scale")) && !mutated("s25-no-commute");
            match (base, index) {
                (SibAddress::Private(address), SibAddress::Bits(expr, affine)) => {
                    sib_private(address, term(expr, affine), scale, disp)
                        .map(SibAddress::Private)
                        .ok_or_else(overflow)
                }
                (SibAddress::Bits(expr, affine), SibAddress::Private(address)) if commutes => {
                    sib_private(address, term(expr, affine), scale, disp)
                        .map(SibAddress::Private)
                        .ok_or_else(overflow)
                }
                (_, SibAddress::Private(_)) => Err(escapes(operand.index.root)),
                (SibAddress::Bits(base, base_affine), SibAddress::Bits(index, index_affine)) => {
                    let (expr, affine) = if mutated("s25-disp-zero-extended") {
                        let (expr, affine) =
                            sib_bits((base, base_affine), (index, index_affine), scale, 0);
                        let disp = u64::from(disp as u32);
                        (
                            expr.bvadd(E::bv_const(disp, 64)),
                            affine.map(|a| {
                                a.combine(Affine::constant(disp, u64::MAX), false, u64::MAX)
                            }),
                        )
                    } else {
                        sib_bits((base, base_affine), (index, index_affine), scale, disp)
                    };
                    Ok(SibAddress::Bits(expr, affine))
                }
            }
        };
        let private_write: Option<Option<MachinePrivate>> = match inst.opcode {
            X86Opcode::Lea => match memory_base(&inst.operands[1]).expect("row shape checked") {
                (MemoryBase::Slot(slot), disp) => Some(Some(MachinePrivate::Frame(FrameAddr {
                    slot,
                    offset: i64::from(disp),
                }))),
                (MemoryBase::Register(reg), disp) => match state.get(&reg.root) {
                    Some(RegValue::Frame(address)) => Some(
                        address
                            .offset_by(i64::from(disp))
                            .map(MachinePrivate::Frame),
                    ),
                    Some(RegValue::Indexed(address)) => Some(
                        address
                            .offset_by(i64::from(disp))
                            .map(MachinePrivate::Indexed),
                    ),
                    _ => None,
                },
            },
            // A 64-bit copy only (slice 15: a mixed-width copy of an address
            // reads it as bits, which makes the slot escape: no claim).
            X86Opcode::MovRR if gpr64(&inst.operands[0]).is_some() => {
                private_of(&inst.operands[1]).map(Some)
            }
            // OD-185: `lea dst, [private + index*scale + disp]` with an
            // index register the walk knows as a 64-bit constant `k`, the
            // selector's `ArrayGep` of a private stack address at a constant
            // index (`select_array_gep`): the address offset by `k*scale +
            // disp`, the exact integer sum, overflow refused. Slice 17: at
            // any other index the indexed address whose offset adds the
            // scaled index term ([`array_element_offset`], the `LeaSib`
            // term), then the displacement.
            X86Opcode::LeaSib => {
                let O::SibMemAddr {
                    base,
                    index,
                    scale,
                    disp,
                } = &inst.operands[1]
                else {
                    unreachable!("row shape checked");
                };
                match (private_of(base), constant(index), bits_in(index)) {
                    (Some(address), Some(k), _) => {
                        Some(sib_private(address, SibIndex::Constant(k), *scale, *disp))
                    }
                    (Some(address), None, Some(index)) => Some(sib_private(
                        address,
                        SibIndex::Term(index.expr),
                        *scale,
                        *disp,
                    )),
                    (None, _, _) if *scale == 1 && mutated("s25-lea-sib-commutes") => {
                        private_of(index).zip(bits_in(base)).map(|(address, bits)| {
                            sib_private(address, SibIndex::Term(bits.expr), 1, *disp)
                        })
                    }
                    _ => None,
                }
            }
            X86Opcode::AddRR if gpr64(&inst.operands[0]).is_some() => {
                match (private_of(&inst.operands[1]), private_of(&inst.operands[2])) {
                    (Some(base), None) | (None, Some(base)) => {
                        let other = if private_of(&inst.operands[1]).is_some() {
                            &inst.operands[2]
                        } else {
                            &inst.operands[1]
                        };
                        bits_in(other).map(|slot| {
                            match slot.affine.and_then(|affine| affine.as_constant()) {
                                Some(delta) => base.offset_by(delta as i64),
                                None => Some(base.indexed_by(slot.expr)),
                            }
                        })
                    }
                    _ => None,
                }
            }
            X86Opcode::AddRI | X86Opcode::SubRI if gpr64(&inst.operands[0]).is_some() => {
                match (private_of(&inst.operands[1]), &inst.operands[2]) {
                    (Some(address), O::Imm(imm)) => {
                        let imm = i64::from(*imm as i32);
                        Some(if inst.opcode == X86Opcode::AddRI {
                            address.offset_by(imm)
                        } else {
                            imm.checked_neg().and_then(|delta| address.offset_by(delta))
                        })
                    }
                    _ => None,
                }
            }
            _ => None,
        };
        if let Some(address) = private_write {
            let address = address.ok_or_else(|| {
                unsupported(X86BodyUnsupported::MachineRow {
                    row: row.ordinal,
                    detail: "overflows a private stack offset".into(),
                })
            })?;
            if address.slot() as usize >= program.slot_sizes.len() {
                return Err(unsupported(X86BodyUnsupported::MachineRow {
                    row: row.ordinal,
                    detail: format!("names stack slot {}, which is not declared", address.slot()),
                }));
            }
            let destination = gpr(&inst.operands[0]).expect("row shape checked").root;
            if let Root::Physical(root) = destination
                && SYSV_PRESERVED_ROOTS.contains(&root)
            {
                return Err(mismatch(X86BodyMismatch::PreservedWrite {
                    row: row.ordinal,
                    register: ROOT_NAMES[root as usize],
                }));
            }
            state.insert(
                destination,
                match address {
                    MachinePrivate::Frame(address) => RegValue::Frame(address),
                    MachinePrivate::Indexed(address) => RegValue::Indexed(address),
                },
            );
            bound_rows.push(row.ordinal);
            continue;
        }
        // Slice 21 (ruling OD-201): the selector's two atomic pseudo rows, each
        // one row that makes two incoming accesses of the source's world
        // trace through `[base + disp]`, an incoming address as a scalar
        // access's (a private stack address, RBP or RSP makes no claim), with
        // the single-threaded meaning OD-83 gives an atomic access.
        if matches!(
            inst.opcode,
            X86Opcode::AtomicLoadCmpxchg16b | X86Opcode::AtomicRmwCasLoop
        ) {
            let operand = if inst.opcode == X86Opcode::AtomicLoadCmpxchg16b {
                &inst.operands[0]
            } else {
                &inst.operands[2]
            };
            let Some((MemoryBase::Register(base), disp)) = memory_base(operand) else {
                unreachable!("row shape checked");
            };
            let pseudo_row = |detail: &str| {
                unsupported(X86BodyUnsupported::MachineRow {
                    row: row.ordinal,
                    detail: format!("{:?} {detail}", inst.opcode),
                })
            };
            if matches!(base.root, Root::Physical(RBP | RSP)) {
                return Err(pseudo_row("accesses the frame through RBP or RSP"));
            }
            let slot = match state.get(&base.root) {
                None => return Err(undefined(base.root)),
                Some(RegValue::Bits(slot)) => slot.clone(),
                Some(RegValue::Frame(_) | RegValue::Indexed(_)) => {
                    return Err(pseudo_row("is an atomic access of a private stack slot"));
                }
                Some(RegValue::Mixed) => return Err(mixed(base.root)),
                Some(RegValue::Carried) => return Err(carried(base.root)),
                Some(RegValue::Dispatch(_)) => return Err(dispatch_value(base.root)),
            };
            // The address `offset` bytes above `[base + disp]`.
            let address_at = |offset: i64| -> (E, Option<Affine>) {
                let delta = (i64::from(disp) + offset) as u64;
                if delta == 0 {
                    (slot.expr.clone(), slot.affine)
                } else {
                    (
                        slot.expr.clone().bvadd(E::bv_const(delta, 64)),
                        slot.affine
                            .map(|a| a.combine(Affine::constant(delta, u64::MAX), false, u64::MAX)),
                    )
                }
            };
            // The next source event, an access this pseudo row lowers.
            let paired = |next: usize, expected: AtomicPseudo| {
                let Some(SourceEvent::Access(access)) = program.events.get(next) else {
                    return Err(trace(format!(
                        "{:?} where the source's next event is {}",
                        inst.opcode,
                        describe_event(program, next)
                    )));
                };
                let source_access = &program.accesses[*access];
                if source_access.pseudo != Some(expected) {
                    return Err(trace(format!(
                        "{:?} paired with a source access it does not lower",
                        inst.opcode
                    )));
                }
                // An access through an address that may derive from an
                // escaped slot (slice 15) is not one the pseudo rows pair.
                if source_access.slot_reads.is_some() {
                    return Err(pseudo_row(
                        "lowers an access through an address that may derive from an escaped \
                         slot",
                    ));
                }
                Ok(source_access)
            };
            let stop = (stopped.clone(), trapped.clone());
            let writes: Vec<(Root, E)> = if inst.opcode == X86Opcode::AtomicLoadCmpxchg16b {
                // `xor eax, eax; xor edx, edx; xor ebx, ebx; xor ecx, ecx;
                // lock cmpxchg16b [m]` (Intel SDM CMPXCHG8B/CMPXCHG16B): with
                // RDX:RAX = 0, either the 16 bytes are zero (ZF = 1, RCX:RBX =
                // 0 is stored: the same bytes) or they are not (ZF = 0, they
                // are loaded into RDX:RAX and written back unchanged). Either
                // way RAX and RDX hold the low and high 8 bytes and memory is
                // unchanged: the two halves of the source's `I128` atomic
                // load (`l{j}` low, then high, at the address and 8 above).
                let mut halves = Vec::with_capacity(2);
                for half in 0..2u32 {
                    let source_access = paired(next_event, AtomicPseudo::Cmpxchg16b(half))?;
                    let AccessKind::Load(load) = source_access.kind else {
                        unreachable!("an atomic load's half is a load");
                    };
                    next_event += 1;
                    let (address, address_affine) = address_at(i64::from(8 * half));
                    accesses.push(WalkedAccess {
                        row: row.ordinal,
                        address,
                        address_affine,
                        value: None,
                        value_affine: None,
                        slots: Vec::new(),
                        stop: stop.clone(),
                    });
                    halves.push(E::var(memory_load_name(load), 64));
                }
                let high = halves.pop().expect("two halves");
                let low = halves.pop().expect("two halves");
                // RBX (callee-saved) is the pseudo's fixed `xor ebx, ebx`:
                // the frame saves and restores it around the body (trusted,
                // OD-201: `x86_merge_fixed_callee_saved_gpr_defs` adds every
                // fixed callee-saved definition to the prologue's save set),
                // so the walk records the write instead of refusing it as a
                // preserved-register write.
                vec![
                    (Root::Physical(RAX), low),
                    (Root::Physical(RDX), high),
                    (Root::Physical(RCX), E::bv_const(0, 64)),
                    (Root::Physical(RBX), E::bv_const(0, 64)),
                ]
            } else {
                // `mov rax, [m]; L: mov r10, src; lock cmpxchg [m], r10; jne L;
                // mov dst, rax` (`encode_atomic_rmw_cas_loop`, kind 5): with
                // one thread nothing writes `[m]` between the load and the
                // compare, so the first compare succeeds and the loop runs
                // once (OD-83's single-threaded claim): RAX and `dst` hold
                // the old bytes, `[m]` the source register, R10 its copy. A
                // 32-bit form's writes zero-extend.
                let (source_reg, source) = root_of(&inst.operands[1])?;
                let bits = source_reg.bits;
                let load_access = paired(next_event, AtomicPseudo::Exchange { load: true })?;
                let AccessKind::Load(load) = load_access.kind else {
                    unreachable!("an exchange's first access is its load");
                };
                if load_access.carrier.bits() != bits {
                    return Err(trace(format!(
                        "a {bits}-bit exchange paired with a {}-bit source exchange",
                        load_access.carrier.bits()
                    )));
                }
                next_event += 1;
                paired(next_event, AtomicPseudo::Exchange { load: false })?;
                next_event += 1;
                let (address, address_affine) = address_at(0);
                accesses.push(WalkedAccess {
                    row: row.ordinal,
                    address: address.clone(),
                    address_affine,
                    value: None,
                    value_affine: None,
                    slots: Vec::new(),
                    stop: stop.clone(),
                });
                accesses.push(WalkedAccess {
                    row: row.ordinal,
                    address,
                    address_affine,
                    value: Some(low(source.expr.clone(), bits)),
                    value_affine: (bits == 64).then_some(source.affine).flatten(),
                    slots: Vec::new(),
                    stop,
                });
                let old = widen(E::var(memory_load_name(load), bits), bits);
                let destination = gpr(&inst.operands[0]).expect("row shape checked").root;
                if let Root::Physical(root) = destination
                    && SYSV_PRESERVED_ROOTS.contains(&root)
                {
                    return Err(mismatch(X86BodyMismatch::PreservedWrite {
                        row: row.ordinal,
                        register: ROOT_NAMES[root as usize],
                    }));
                }
                vec![
                    (destination, old.clone()),
                    (Root::Physical(RAX), old),
                    (Root::Physical(R10), widen(low(source.expr, bits), bits)),
                ]
            };
            for (root, value) in writes {
                let name = names.define(row.ordinal, value);
                state.insert(
                    root,
                    RegValue::Bits(Slot {
                        expr: E::var(&name, 64),
                        affine: None,
                    }),
                );
            }
            bound_rows.push(row.ordinal);
            continue;
        }
        // Slice 25 (OD-227): a memory-destination `add`/`xor` of a 64-bit
        // register into incoming memory, `DEST <- DEST op SRC` at one
        // effective address (Intel SDM ADD, XOR; unlocked, and under OD-83's
        // single-threaded world trace no access lies between its read and its
        // write): the next two incoming accesses of the world trace, an
        // 8-byte load and an 8-byte store of `old op src` at that address,
        // each paired as a `mov`'s ([`incoming_access`]). The source
        // register's bits are read first (a private address in it escapes),
        // and a private address makes no claim. Its flags are `add`'s
        // (`AddRR`'s rule); `xor`'s stay unmodelled.
        if let Some((op, sib)) = read_modify_write(inst.opcode) {
            let private = || {
                unsupported(X86BodyUnsupported::MachineRow {
                    row: row.ordinal,
                    detail: format!(
                        "{:?} read-modify-writes a private stack slot (slice 25 states one of \
                         incoming memory only)",
                        inst.opcode
                    ),
                })
            };
            let frame_source =
                frame_of(&inst.operands[1]).filter(|_| mutated("s25-rmw-store-via-frame-of"));
            let source = match frame_source {
                Some(_) => None,
                None => Some(root_of(&inst.operands[1])?.1.expr),
            };
            let (address, address_affine) = if sib {
                let operand = sib_operand(&inst.operands[0]).expect("row shape checked");
                match sib_address(&operand)? {
                    SibAddress::Private(_) => return Err(private()),
                    SibAddress::Bits(expr, affine) if mutated("s25-unnamed-ea") => (expr, affine),
                    SibAddress::Bits(expr, affine) => {
                        (E::var(names.define(row.ordinal, expr), 64), affine)
                    }
                }
            } else {
                let Some((MemoryBase::Register(base), disp)) = memory_base(&inst.operands[0])
                else {
                    unreachable!("row shape checked");
                };
                match state.get(&base.root) {
                    None => return Err(undefined(base.root)),
                    Some(RegValue::Frame(_) | RegValue::Indexed(_)) => return Err(private()),
                    Some(RegValue::Mixed) => return Err(mixed(base.root)),
                    Some(RegValue::Carried) => return Err(carried(base.root)),
                    Some(RegValue::Dispatch(_)) => return Err(dispatch_value(base.root)),
                    Some(RegValue::Bits(slot)) => base_disp_bits(slot.clone(), i64::from(disp)),
                }
            };
            let ctx = RowCtx {
                program,
                row: row.ordinal,
                opcode: inst.opcode,
                atomic: inst.proof_origin.is_some(),
            };
            let form = |load: bool| MemoryAccessForm {
                bytes: 8,
                load,
                full: load,
                zero_extends: false,
                sse: false,
            };
            let mut walk = IncomingWalk {
                next_event: &mut next_event,
                accesses: &mut accesses,
                stack,
                escaped,
                frame_bytes,
                stopped,
                trapped,
            };
            let old = if mutated("s25-rmw-store-only") {
                names.undefined(UndefinedSite::Row(row.ordinal), 64)
            } else {
                match incoming_access(
                    &ctx,
                    &mut walk,
                    form(true),
                    address.clone(),
                    address_affine,
                    Stored::Load,
                )? {
                    Incoming::Loaded(old) => old,
                    Incoming::Stored => unreachable!("a load loads"),
                }
            };
            let stored = match (frame_source, source.clone()) {
                (Some(frame), _) => Stored::Frame(frame),
                (None, Some(source)) => {
                    let opcode = match op {
                        RmwOp::Xor if !mutated("s25-xor-stated-as-add") => X86Opcode::XorRR,
                        _ => X86Opcode::AddRR,
                    };
                    let new =
                        names.define(row.ordinal, machine_binary(opcode, 64, old.clone(), source));
                    Stored::Value(E::var(&new, 64), None)
                }
                (None, None) => unreachable!("the source is read unless a mutant stores a frame"),
            };
            incoming_access(
                &ctx,
                &mut walk,
                form(false),
                address,
                address_affine,
                stored,
            )?;
            if op == RmwOp::Add
                && let Some(source) = source
            {
                *flags = Flags::Alu(Box::new(AluFlags::add(old, source, 64)));
            }
            bound_rows.push(row.ordinal);
            continue;
        }
        // Slice 23 (OD-205): the operator key and operands of an arithmetic
        // row whose one written value is `K(c, d)` ([`MachineArith`]).
        let mut arith: Option<(ArithKey, E, E)> = None;
        // Slice 25 (OD-227): a scaled-index load or store is the access its
        // base-only sibling makes at the address `LeaSib` computes. A
        // `MovRMSib` through a register holding a jump table's address, or
        // not so shaped (a physical component), is slice 14's dispatch load
        // below.
        let access = memory_access(inst.opcode)
            .map(|form| (form, false))
            .or_else(|| {
                sib_access(inst.opcode)
                    .filter(|_| {
                        inst.opcode != X86Opcode::MovRMSib
                            || mutated("s25-every-movrmsib-to-memory")
                            || sib_routes_to_memory(inst, state)
                    })
                    .map(|form| (form, true))
            });
        let (expr, affine) = if let Some((form, sib)) = access {
            // Loads and stores (slice 4). Through a private stack address
            // they read and write the slot's bytes exactly; through any other
            // address they are the next incoming-memory access of the world
            // trace, paired with the source's.
            let (address_operand, register) = if form.load {
                (&inst.operands[1], &inst.operands[0])
            } else {
                (&inst.operands[0], &inst.operands[1])
            };
            let target = if sib {
                let operand = sib_operand(address_operand).expect("row shape checked");
                match sib_address(&operand)? {
                    SibAddress::Private(MachinePrivate::Frame(address)) => {
                        AccessTarget::Stack(address)
                    }
                    SibAddress::Private(MachinePrivate::Indexed(address)) => {
                        AccessTarget::Indexed(address)
                    }
                    SibAddress::Bits(expr, affine) if mutated("s25-unnamed-ea") => {
                        AccessTarget::Incoming(expr, affine)
                    }
                    SibAddress::Bits(expr, affine) => {
                        AccessTarget::Incoming(E::var(names.define(row.ordinal, expr), 64), affine)
                    }
                }
            } else {
                let (base, disp) = memory_base(address_operand).expect("row shape checked");
                let disp = i64::from(disp);
                match base {
                    MemoryBase::Slot(slot) => AccessTarget::Stack(FrameAddr { slot, offset: disp }),
                    // Slice 13: before register allocation the selector names
                    // the frame pointer only to read an incoming stack argument,
                    // `[rbp + 16 + 8k]` (the frame the post-allocation prologue
                    // builds, `push rbp; mov rbp, rsp`, puts the caller's
                    // argument area there). Any other access through it makes
                    // no claim.
                    MemoryBase::Register(reg) if reg.root == Root::Physical(RBP) => {
                        let parameter = program.params.iter().position(|param| {
                            param
                                .stack_eightbytes()
                                .into_iter()
                                .any(|stack| i64::from(stack) == disp)
                        });
                        match parameter {
                            Some(index)
                                if form.load && !form.sse && inst.proof_origin.is_none() =>
                            {
                                AccessTarget::StackParameter(index, disp as i32)
                            }
                            _ => {
                                return Err(unsupported(X86BodyUnsupported::MachineRow {
                                    row: row.ordinal,
                                    detail: format!(
                                        "{:?} accesses the frame through RBP other than to read an \
                                         incoming stack parameter",
                                        inst.opcode
                                    ),
                                }));
                            }
                        }
                    }
                    // Slice 13: a store into the open outgoing argument area,
                    // which only the next call reads.
                    MemoryBase::Register(reg) if reg.root == Root::Physical(RSP) => {
                        let inside = outgoing.as_ref().is_some_and(|area| {
                            disp >= 0 && disp + i64::from(form.bytes) <= area.len() as i64
                        });
                        if form.load || form.sse || !inside || inst.proof_origin.is_some() {
                            return Err(unsupported(X86BodyUnsupported::MachineRow {
                                row: row.ordinal,
                                detail: format!(
                                    "{:?} accesses the stack through RSP other than to store an \
                                     outgoing argument",
                                    inst.opcode
                                ),
                            }));
                        }
                        AccessTarget::Outgoing(disp as usize)
                    }
                    MemoryBase::Register(reg) => match state.get(&reg.root) {
                        None => return Err(undefined(reg.root)),
                        Some(RegValue::Mixed) => return Err(mixed(reg.root)),
                        Some(RegValue::Carried) => return Err(carried(reg.root)),
                        Some(RegValue::Dispatch(_)) => return Err(dispatch_value(reg.root)),
                        Some(RegValue::Frame(address)) => {
                            AccessTarget::Stack(address.offset_by(disp).ok_or_else(|| {
                                unsupported(X86BodyUnsupported::MachineRow {
                                    row: row.ordinal,
                                    detail: "overflows a private stack offset".into(),
                                })
                            })?)
                        }
                        Some(RegValue::Indexed(address)) => {
                            AccessTarget::Indexed(address.offset_by(disp).ok_or_else(|| {
                                unsupported(X86BodyUnsupported::MachineRow {
                                    row: row.ordinal,
                                    detail: "overflows a private stack offset".into(),
                                })
                            })?)
                        }
                        Some(RegValue::Bits(slot)) => {
                            let (address, affine) = base_disp_bits(slot.clone(), disp);
                            AccessTarget::Incoming(address, affine)
                        }
                    },
                }
            };
            let width = form.bytes * 8;
            // Slice 13: an 8-byte store of a register that holds a private
            // stack address stores that address as data: its term
            // ([`frame_address_term`]), and its slot escapes with it where the
            // source's does.
            let stored_frame = (!form.load && form.bytes == 8 && !form.sse)
                .then(|| frame_of(register))
                .flatten();
            // The accessed value at its memory width.
            let (value, value_affine) = match target {
                // Slice 13: an outgoing argument's bytes, the stored term's
                // (or a private address's, which the call checks).
                AccessTarget::Outgoing(offset) => {
                    let (term, frame) = match stored_frame {
                        Some(stored) => (frame_address_term(stored), Some(stored)),
                        None => (low(store_source(register)?.1.expr, width), None),
                    };
                    let area = outgoing.as_mut().expect("an open area");
                    for byte in 0..form.bytes {
                        area[offset + byte as usize] = Some(MachineByte {
                            term: term.clone(),
                            width,
                            byte,
                            affine: None,
                            frame,
                            dead: false,
                        });
                    }
                    bound_rows.push(row.ordinal);
                    continue;
                }
                // Slice 13: the low bytes of the parameter's incoming
                // eightbyte, the caller's (an `I64` read whole is the
                // parameter itself).
                AccessTarget::StackParameter(index, disp) => {
                    let eightbyte = E::var(stack_parameter_name(disp), 64);
                    let affine = (width == 64
                        && program.params[index].abi == ParamAbi::Scalar(Carrier::I64))
                    .then(|| parameter_affine(index))
                    .flatten();
                    (low(eightbyte, width), affine)
                }
                AccessTarget::Stack(address) => {
                    let range = stack_range(&address, form.bytes, &program.slot_sizes).ok_or_else(
                        || {
                            mismatch(X86BodyMismatch::StackSlotBounds {
                                row: row.ordinal,
                                slot: address.slot,
                                first: address.offset,
                                end: address.offset.saturating_add(i64::from(form.bytes)),
                                size: program
                                    .slot_sizes
                                    .get(address.slot as usize)
                                    .copied()
                                    .unwrap_or(0),
                            })
                        },
                    )?;
                    let slot = address.slot as usize;
                    // Slice 13: the selector makes no atomic access of a
                    // private slot (the source admits none).
                    if inst.proof_origin.is_some() {
                        return Err(unsupported(X86BodyUnsupported::MachineRow {
                            row: row.ordinal,
                            detail: format!(
                                "{:?} is an atomic access of a private stack slot",
                                inst.opcode
                            ),
                        }));
                    }
                    if let Some(stored) = stored_frame {
                        for (byte, offset) in range.enumerate() {
                            stack[slot][offset] = Some(MachineByte {
                                term: frame_address_term(stored),
                                width,
                                byte: byte as u32,
                                affine: None,
                                frame: Some(stored),
                                dead: false,
                            });
                        }
                        if escaped.contains(&address.slot) {
                            escape_machine(escaped, stack.as_slice(), [stored.slot]);
                        }
                        bound_rows.push(row.ordinal);
                        continue;
                    }
                    // Slice 13: a stored private address read back whole by
                    // an 8-byte load is that address again; any other read of
                    // its bytes is outside the domain.
                    if form.load
                        && stack[slot][range.clone()]
                            .iter()
                            .any(|byte| byte.as_ref().is_some_and(|byte| byte.frame.is_some()))
                    {
                        let read = &stack[slot][range.clone()];
                        let first = read[0].as_ref().and_then(|byte| byte.frame);
                        let whole = form.bytes == 8
                            && !form.sse
                            && first.is_some()
                            && read.iter().enumerate().all(|(i, byte)| {
                                byte.as_ref().is_some_and(|byte| {
                                    byte.frame == first && byte.byte == i as u32
                                })
                            });
                        let destination = gpr64(register).map(|reg| reg.root);
                        let (true, Some(found), Some(destination)) = (whole, first, destination)
                        else {
                            return Err(unsupported(X86BodyUnsupported::MachineRow {
                                row: row.ordinal,
                                detail: format!(
                                    "{:?} reads part of a private stack address stored as data",
                                    inst.opcode
                                ),
                            }));
                        };
                        if let Root::Physical(root) = destination
                            && SYSV_PRESERVED_ROOTS.contains(&root)
                        {
                            return Err(mismatch(X86BodyMismatch::PreservedWrite {
                                row: row.ordinal,
                                register: ROOT_NAMES[root as usize],
                            }));
                        }
                        state.insert(destination, RegValue::Frame(found));
                        bound_rows.push(row.ordinal);
                        continue;
                    }
                    if !form.load {
                        // Write the slot's bytes; nothing is observed.
                        let (reg, value) = store_source(register)?;
                        let term = low(value.expr, width);
                        let affine = if width == 64 && reg.bits == 64 {
                            value.affine
                        } else {
                            None
                        };
                        for (byte, offset) in range.enumerate() {
                            stack[slot][offset] = Some(MachineByte {
                                term: term.clone(),
                                width,
                                byte: byte as u32,
                                affine,
                                frame: None,
                                dead: false,
                            });
                        }
                        bound_rows.push(row.ordinal);
                        continue;
                    }
                    let read: Vec<Option<MachineByte>> = stack[slot][range.clone()].to_vec();
                    // Slice 17: an unreadable byte makes no claim.
                    if read
                        .iter()
                        .any(|byte| byte.as_ref().is_some_and(|byte| byte.dead))
                    {
                        return Err(unsupported(X86BodyUnsupported::MachineRow {
                            row: row.ordinal,
                            detail: format!(
                                "{:?} reads a private stack byte its cut point leaves \
                                 unreadable",
                                inst.opcode
                            ),
                        }));
                    }
                    let whole = read.first().cloned().flatten().filter(|first| {
                        first.width == width
                            && read.iter().enumerate().all(|(i, byte)| {
                                byte.as_ref().is_some_and(|byte| {
                                    byte.term == first.term
                                        && byte.width == width
                                        && byte.byte == i as u32
                                })
                            })
                    });
                    match whole {
                        // One earlier store read back whole: that term.
                        Some(first) => (first.term, first.affine),
                        None => {
                            // Byte by byte, high byte first; a byte the body
                            // never wrote is a free input.
                            let mut bytes = Vec::with_capacity(read.len());
                            for (byte, offset) in read.iter().zip(range) {
                                bytes.push(match byte {
                                    Some(byte) => byte.expr(),
                                    // A byte the body never wrote: the
                                    // slot's initial byte (shared with the
                                    // source, which may read it too).
                                    None => {
                                        let address = FrameAddr {
                                            slot: address.slot,
                                            offset: offset as i64,
                                        };
                                        E::var(
                                            frame_byte_name(register_frame_byte(
                                                frame_bytes,
                                                address,
                                            )),
                                            8,
                                        )
                                    }
                                });
                            }
                            (concat_bytes(bytes), None)
                        }
                    }
                }
                // Slice 17: an access through an indexed address. Its
                // candidates are those of the source access the row's TV-1
                // stamp names (same slot and width), else every offset: the
                // choice only sizes the select, and the walk's own in-bounds
                // claim checks it. A load reads the select over the
                // candidates of what a load at each reads; a store updates
                // each byte a candidate covers.
                AccessTarget::Indexed(address) => {
                    let no_claim = |detail: String| {
                        unsupported(X86BodyUnsupported::MachineRow {
                            row: row.ordinal,
                            detail: format!("{:?} {detail}", inst.opcode),
                        })
                    };
                    if inst.proof_origin.is_some() {
                        return Err(no_claim(
                            "is an atomic access of a private stack slot".into(),
                        ));
                    }
                    if stored_frame.is_some() {
                        return Err(no_claim(
                            "stores a private stack address through an indexed address".into(),
                        ));
                    }
                    let slot = address.slot as usize;
                    let size = program.slot_sizes[slot];
                    let (modulus, residue) = row
                        .inst
                        .lowering_provenance
                        .source_id()
                        .filter(|_| !(sib && mutated("s25-indexed-stamp-wrong-row")))
                        .and_then(|stamp| {
                            program.indexed.iter().find(|site| {
                                site.block == Block(stamp.block)
                                    && site.index == stamp.index as usize
                                    && site.address.slot == address.slot
                                    && site.width == form.bytes
                            })
                        })
                        .map_or((1, 0), |site| {
                            (site.address.modulus, site.address.residue())
                        });
                    let candidates = indexed::candidates(size, form.bytes, modulus, residue);
                    if candidates.is_empty() || candidates.len() > indexed::MAX_CANDIDATES {
                        return Err(no_claim(format!(
                            "accesses private stack slot {slot} through an indexed address with {} \
                             candidate offsets (the lane admits 1 to {})",
                            candidates.len(),
                            indexed::MAX_CANDIDATES
                        )));
                    }
                    let offset = address.term();
                    indexed_claims.push(indexed::in_bounds(
                        offset.clone(),
                        size,
                        form.bytes,
                        modulus,
                        residue,
                    ));
                    let unreadable = |byte: &Option<MachineByte>| {
                        byte.as_ref()
                            .is_some_and(|byte| byte.dead || byte.frame.is_some())
                    };
                    if !form.load {
                        let (_, value) = store_source(register)?;
                        let term = low(value.expr, width);
                        let first = candidates[0];
                        let end = candidates[candidates.len() - 1] + i64::from(form.bytes);
                        let mut updated = Vec::new();
                        for position in first..end {
                            let arms = indexed::covering(&candidates, form.bytes, position);
                            if arms.is_empty() {
                                continue;
                            }
                            let old = &stack[slot][position as usize];
                            if unreadable(old) {
                                return Err(no_claim(format!(
                                    "updates private stack slot {slot} byte {position}, which is \
                                     unreadable or holds a private stack address"
                                )));
                            }
                            let old = match old {
                                Some(byte) => byte.expr(),
                                None => E::var(
                                    frame_byte_name(register_frame_byte(
                                        frame_bytes,
                                        FrameAddr {
                                            slot: address.slot,
                                            offset: position,
                                        },
                                    )),
                                    8,
                                ),
                            };
                            let arms = arms
                                .into_iter()
                                .map(|(k, byte)| {
                                    let byte = if width == 8 {
                                        term.clone()
                                    } else {
                                        term.clone().extract(8 * byte + 7, 8 * byte)
                                    };
                                    (k, byte)
                                })
                                .collect();
                            updated.push((position, indexed::update(&offset, arms, old)));
                        }
                        for (position, byte) in updated {
                            let name = names.define(row.ordinal, byte);
                            stack[slot][position as usize] = Some(MachineByte {
                                term: E::var(&name, 8),
                                width: 8,
                                byte: 0,
                                affine: None,
                                frame: None,
                                dead: false,
                            });
                        }
                        bound_rows.push(row.ordinal);
                        continue;
                    }
                    let mut arms = Vec::with_capacity(candidates.len());
                    for k in &candidates {
                        let range = *k as usize..(*k + i64::from(form.bytes)) as usize;
                        let read: Vec<Option<MachineByte>> = stack[slot][range.clone()].to_vec();
                        if read.iter().any(unreadable) {
                            return Err(no_claim(format!(
                                "reads private stack slot {slot} at candidate offset {k}, which is \
                                 unreadable or holds a private stack address"
                            )));
                        }
                        let whole = read.first().cloned().flatten().filter(|first| {
                            first.width == width
                                && read.iter().enumerate().all(|(i, byte)| {
                                    byte.as_ref().is_some_and(|byte| {
                                        byte.term == first.term
                                            && byte.width == width
                                            && byte.byte == i as u32
                                    })
                                })
                        });
                        let term = match whole {
                            Some(first) => first.term,
                            None => concat_bytes(
                                read.iter()
                                    .zip(range)
                                    .map(|(byte, at)| match byte {
                                        Some(byte) => byte.expr(),
                                        None => E::var(
                                            frame_byte_name(register_frame_byte(
                                                frame_bytes,
                                                FrameAddr {
                                                    slot: address.slot,
                                                    offset: at as i64,
                                                },
                                            )),
                                            8,
                                        ),
                                    })
                                    .collect(),
                            ),
                        };
                        arms.push((*k, term));
                    }
                    (indexed::select(&offset, arms), None)
                }
                AccessTarget::Incoming(address, address_affine) => {
                    let source = || store_source(register);
                    let stored = if form.load {
                        Stored::Load
                    } else if let Some(stored) = stored_frame {
                        Stored::Frame(stored)
                    } else {
                        Stored::Register(&source)
                    };
                    let ctx = RowCtx {
                        program,
                        row: row.ordinal,
                        opcode: inst.opcode,
                        atomic: inst.proof_origin.is_some(),
                    };
                    let mut walk = IncomingWalk {
                        next_event: &mut next_event,
                        accesses: &mut accesses,
                        stack,
                        escaped,
                        frame_bytes,
                        stopped,
                        trapped,
                    };
                    match incoming_access(&ctx, &mut walk, form, address, address_affine, stored)? {
                        Incoming::Loaded(value) => (value, None),
                        Incoming::Stored => {
                            bound_rows.push(row.ordinal);
                            continue;
                        }
                    }
                }
            };
            // The load's destination: `mov r64` and `mov r32` write the whole
            // root (a 32-bit write zero-extends), as does `movzx r32, m8/m16`
            // (the bytes zero-extended); `mov r8`/`mov r16` write only its low
            // bits. The bits above are a free input `u_k`, EVEN
            // when the destination held a defined value: register allocation
            // treats a narrow load's destination as a pure definition
            // (`first_operand_is_def_and_use` in the x86-64 pipeline), so it
            // may place the load in a register that holds anything, and the
            // pre-RA merge is not a promise the emitted code keeps.
            match form.bytes {
                8 => (value, value_affine),
                4 => (value.zero_ext(32), None),
                _ if form.zero_extends => (value.zero_ext(64 - width), None),
                _ => (
                    names
                        .undefined(UndefinedSite::Row(row.ordinal), 64 - width)
                        .concat(value),
                    None,
                ),
            }
        } else {
            match inst.opcode {
                // Slice 15: a copy between a 32- and a 64-bit register. The
                // encoder emits it with REX.W (`encode_alu_rr` clears REX.W
                // only when both registers are 32-bit), so it copies all 64
                // bits of the register allocated to the source, whose bits
                // above 31 a 32-bit source does not keep (four-byte spills,
                // coalesced 32-bit copies); the walk takes only the low 32
                // bits as defined, and the bits above as a free input `u_k`,
                // which holds of either encoding.
                X86Opcode::MovRR
                    if gpr(&inst.operands[0]).map(|reg| reg.bits)
                        != gpr(&inst.operands[1]).map(|reg| reg.bits) =>
                {
                    let value = read_low(&inst.operands[1], 32)?;
                    (
                        names
                            .undefined(UndefinedSite::Row(row.ordinal), 32)
                            .concat(value),
                        None,
                    )
                }
                X86Opcode::MovRR => {
                    let (value, affine, bits) = read(&inst.operands[1])?;
                    (widen(value, bits), affine)
                }
                // Slice 15: `movss`/`movsd xmm, [rip + constant]` writes the
                // constant-pool entry's 4 or 8 bytes (little-endian, checked
                // against the row's width by [`machine_skeleton`]) into the low
                // bits and zeroes the rest of the register (Intel SDM
                // MOVSS/MOVSD with a memory source). Trusted: that the entry is
                // emitted, read-only, at the address the RIP-relative operand
                // resolves to (the encoder's and linker's, as for a symbol).
                X86Opcode::MovssRipRel | X86Opcode::MovsdRipRel => {
                    let O::ConstPoolEntry(index) = inst.operands[1] else {
                        unreachable!("row shape checked");
                    };
                    let data = &consts.const_pool_entries[index].data;
                    let value = data
                        .iter()
                        .rev()
                        .fold(0u64, |value, byte| (value << 8) | u64::from(*byte));
                    (E::bv_const(value, 64), None)
                }
                // Slice 15: `pxor`/`andps`/`andpd d, s, m`: the XOR or AND of
                // the two registers, of which the walk models the low 64 bits
                // (no admitted row reads more; the low bits of a bitwise
                // operation depend only on the operands' low bits).
                X86Opcode::Pxor | X86Opcode::Andps | X86Opcode::Andpd => {
                    let (_, source) = root_of(&inst.operands[1])?;
                    let (_, mask) = root_of(&inst.operands[2])?;
                    let value = if inst.opcode == X86Opcode::Pxor {
                        source.expr.bvxor(mask.expr)
                    } else {
                        source.expr.bvand(mask.expr)
                    };
                    (value, None)
                }
                // A 32-bit copy zero-extends; a constant stays one (slice 11:
                // the selector widens an `I128` shift's 32-bit amount so).
                X86Opcode::MovRR32 => {
                    let constant = root_of(&inst.operands[1])?
                        .1
                        .affine
                        .and_then(Affine::as_constant)
                        .map(|value| Affine::constant(value & 0xffff_ffff, u64::MAX));
                    (widen(read_low(&inst.operands[1], 32)?, 32), constant)
                }
                X86Opcode::MovRI => {
                    let O::Imm(imm) = inst.operands[1] else {
                        unreachable!("row shape checked");
                    };
                    let bits = gpr(&inst.operands[0]).expect("row shape checked").bits;
                    let value = (imm as u64) & crate::smt::mask(u64::MAX, bits);
                    (
                        E::bv_const(value, 64),
                        Some(Affine::constant(value, u64::MAX)),
                    )
                }
                X86Opcode::Movzx
                | X86Opcode::MovzxW
                | X86Opcode::MovsxB
                | X86Opcode::MovsxW
                | X86Opcode::Movsx => {
                    let bits = extension_source_bits(inst.opcode);
                    let signed = matches!(
                        inst.opcode,
                        X86Opcode::MovsxB | X86Opcode::MovsxW | X86Opcode::Movsx
                    );
                    let root =
                        extension_source(&inst.operands[1], bits).expect("row shape checked");
                    let value = low(bits_of(root)?.expr, bits);
                    let extended = if signed {
                        value.sign_ext(64 - bits)
                    } else {
                        value.zero_ext(64 - bits)
                    };
                    (extended, None)
                }
                // Slice 14: `xor r, r, r` of one register, the selector's
                // zeroing of EDX/RDX before an unsigned `div`: zero (Intel SDM
                // XOR; a 32-bit write zero-extends), whatever `r` held, so it
                // reads no value of `r`. Its flags are not modelled.
                X86Opcode::XorRR
                    if inst.operands.len() == 3
                        && inst.operands[1] == inst.operands[0]
                        && inst.operands[2] == inst.operands[0] =>
                {
                    (E::bv_const(0, 64), Some(Affine::constant(0, u64::MAX)))
                }
                // Slice 14: the jump-table dispatch ([`TableValue`]): the
                // table's address, the entry at an index the walk states, the
                // target address formed from it; an indirect `jmp` through it
                // goes to the block of the entry (below).
                X86Opcode::LeaRip | X86Opcode::MovRMSib | X86Opcode::AddRR
                    if match inst.opcode {
                        X86Opcode::LeaRip => {
                            matches!(inst.operands[1], O::JumpTableIndex(_))
                        }
                        X86Opcode::MovRMSib => true,
                        _ => inst.operands[1..].iter().any(|operand| {
                            gpr(operand).is_some_and(|reg| {
                                matches!(state.get(&reg.root), Some(RegValue::Dispatch(_)))
                            })
                        }),
                    } =>
                {
                    let value = match (inst.opcode, inst.operands.as_slice()) {
                        (X86Opcode::LeaRip, [_, O::JumpTableIndex(table)]) => {
                            Some(TableValue::Base(*table))
                        }
                        // Slice 25: entry `index` is `[table + index*8]`
                        // only; any other scale or displacement is not the
                        // selector's dispatch. The entry is read only by the
                        // load of the table's own dispatch block
                        // ([`dispatch_blocks`]), whose `jmp` follows it in
                        // the block: the route literal of that `jmp` holds
                        // only at an index of the table, so the load reads
                        // inside the table. A read of the table in any other
                        // block, where the table-base register may still be
                        // live, has no such literal (its index is any value,
                        // and the machine could fault where the source makes
                        // no access): no claim.
                        (
                            X86Opcode::MovRMSib,
                            [
                                _,
                                O::SibMemAddr {
                                    base,
                                    index,
                                    scale,
                                    disp,
                                },
                            ],
                        ) if (*scale == 8 && *disp == 0)
                            || mutated("s25-dispatch-no-scale-check") =>
                        {
                            match (
                                gpr64(base).and_then(|base| state.get(&base.root)),
                                gpr64(index),
                            ) {
                                (
                                    Some(RegValue::Dispatch(TableValue::Base(table))),
                                    Some(index),
                                ) => {
                                    if dispatch_blocks(consts).get(&row.block) != Some(table)
                                        && !mutated("s25-dispatch-any-block")
                                    {
                                        return Err(unsupported(X86BodyUnsupported::MachineRow {
                                            row: row.ordinal,
                                            detail: format!(
                                                "MovRMSib reads jump table {table} outside its \
                                                 dispatch block"
                                            ),
                                        }));
                                    }
                                    Some(TableValue::Entry {
                                        table: *table,
                                        index: bits_of(index.root)?.expr,
                                    })
                                }
                                _ => None,
                            }
                        }
                        (X86Opcode::AddRR, [_, augend, addend]) => {
                            let held = |operand: &O| {
                                gpr64(operand).and_then(|reg| match state.get(&reg.root) {
                                    Some(RegValue::Dispatch(value)) => Some(value.clone()),
                                    _ => None,
                                })
                            };
                            match (held(augend), held(addend)) {
                                (
                                    Some(TableValue::Entry { table, index }),
                                    Some(TableValue::Base(base)),
                                ) if table == base => Some(TableValue::Target { table, index }),
                                _ => None,
                            }
                        }
                        _ => None,
                    };
                    let (Some(value), Some(destination)) = (value, gpr64(&inst.operands[0])) else {
                        return Err(unsupported(X86BodyUnsupported::MachineRow {
                            row: row.ordinal,
                            detail: format!(
                                "{:?} outside the selector's jump-table dispatch",
                                inst.opcode
                            ),
                        }));
                    };
                    state.insert(destination.root, RegValue::Dispatch(value));
                    bound_rows.push(row.ordinal);
                    continue;
                }
                // Slice 15: an ALU row of mixed 32- and 64-bit registers. Its
                // two-address form copies the first source into the
                // destination with REX.W unless both are 32-bit, and the
                // operation is REX.W unless every operand is 32-bit
                // (`encode_alu_rr`), so the bits above 31 hold whatever the
                // allocated registers held there, which a 32-bit register
                // does not keep. The low 32 bits of an add, subtract,
                // multiply, and, or or xor depend only on the operands' low
                // 32 bits, whichever width the row is encoded at: the walk
                // states those, and the bits above as a free input `u_k`. Its
                // flags are not modelled.
                X86Opcode::AddRR
                | X86Opcode::SubRR
                | X86Opcode::ImulRR
                | X86Opcode::AndRR
                | X86Opcode::OrRR
                | X86Opcode::XorRR
                    if !inst
                        .operands
                        .iter()
                        .map(|operand| gpr(operand).map(|reg| reg.bits))
                        .collect::<Vec<_>>()
                        .windows(2)
                        .all(|pair| pair[0] == pair[1]) =>
                {
                    let lhs = read_low(&inst.operands[1], 32)?;
                    let rhs = read_low(&inst.operands[2], 32)?;
                    let low = machine_binary(inst.opcode, 32, lhs, rhs);
                    *flags = Flags::Unmodelled;
                    (
                        names
                            .undefined(UndefinedSite::Row(row.ordinal), 32)
                            .concat(low),
                        None,
                    )
                }
                X86Opcode::AddRR
                | X86Opcode::SubRR
                | X86Opcode::ImulRR
                | X86Opcode::AndRR
                | X86Opcode::OrRR
                | X86Opcode::XorRR => {
                    let (lhs, lhs_affine, bits) = read(&inst.operands[1])?;
                    let (rhs, rhs_affine, _) = read(&inst.operands[2])?;
                    let op = binary_op(inst.opcode);
                    let affine = match op {
                        BinaryOp::Add | BinaryOp::Sub if bits == 64 => lhs_affine
                            .zip(rhs_affine)
                            .map(|(a, b)| a.combine(b, op == BinaryOp::Sub, u64::MAX)),
                        // A 64-bit operation of two constants is a constant.
                        BinaryOp::Mul | BinaryOp::And | BinaryOp::Or | BinaryOp::Xor
                            if bits == 64 =>
                        {
                            lhs_affine
                                .and_then(Affine::as_constant)
                                .zip(rhs_affine.and_then(Affine::as_constant))
                                .map(|(a, b)| {
                                    let value = match op {
                                        BinaryOp::Mul => a.wrapping_mul(b),
                                        BinaryOp::And => a & b,
                                        BinaryOp::Or => a | b,
                                        _ => a ^ b,
                                    };
                                    Affine::constant(value, u64::MAX)
                                })
                        }
                        _ => None,
                    };
                    // Slice 10: the flags of `add`, `sub` and `imul`, which a
                    // `setcc` of checked arithmetic reads.
                    match inst.opcode {
                        X86Opcode::AddRR => {
                            *flags =
                                Flags::Alu(Box::new(AluFlags::add(lhs.clone(), rhs.clone(), bits)));
                        }
                        X86Opcode::SubRR => {
                            *flags =
                                Flags::Alu(Box::new(AluFlags::sub(lhs.clone(), rhs.clone(), bits)));
                        }
                        X86Opcode::ImulRR => {
                            *flags = Flags::Alu(Box::new(AluFlags::imul(
                                lhs.clone(),
                                rhs.clone(),
                                bits,
                            )));
                            arith = Some((
                                ArithKey::new(ArithOp::MulLo, bits),
                                lhs.clone(),
                                rhs.clone(),
                            ));
                        }
                        _ => {}
                    }
                    (
                        widen(machine_binary(inst.opcode, bits, lhs, rhs), bits),
                        affine,
                    )
                }
                // Slice 11: `adc d, a, b` and `sbb d, a, b` (Intel SDM ADC,
                // SBB: `d = a + b + CF`, `d = a - (b + CF)`) at the width the
                // operands name, CF read from the flags a modelled row of this
                // block defined (an `add`, `sub`, `cmp`, `test`, `imul` or
                // `mul`; undefined flags are a named undefined read, and the
                // flags of any other row make no claim). The flags they write
                // are not modelled (`writes_unmodelled_flags`).
                X86Opcode::AdcRR | X86Opcode::SbbRR => {
                    let (lhs, _, bits) = read(&inst.operands[1])?;
                    let (rhs, _, _) = read(&inst.operands[2])?;
                    let carry = E::ite(
                        flags.condition(trust_cg_ir::X86CondCode::B, row.ordinal, inst.opcode)?,
                        E::bv_const(1, bits),
                        E::bv_const(0, bits),
                    );
                    let result = if inst.opcode == X86Opcode::AdcRR {
                        lhs.bvadd(rhs).bvadd(carry)
                    } else {
                        lhs.bvsub(rhs.bvadd(carry))
                    };
                    *flags = Flags::Unmodelled;
                    (widen(result, bits), None)
                }
                // Slice 11: SSE moves of a float bit pattern. `movss d, s`
                // and `movsd d, s` copy the low 32 or 64 bits of `s`;
                // register allocation treats `d` as a pure definition, so the
                // bits of `d` above the copied ones are a free input (the
                // pre-RA merge is not a promise the emitted code keeps, as
                // for a narrow load). `movd`/`movq` from an XMM register write
                // its low 32 or 64 bits to a general-purpose register (a
                // 32-bit write zero-extends); to an XMM register, the low 32
                // or 64 bits of a general-purpose register zero-extended
                // (Intel SDM MOVD/MOVQ).
                // Slice 21 (ruling OD-198): an SSE rounding row computes the
                // IEEE 754 operation its operator key names ([`machine_float_key`];
                // trusted: the Intel SDM transcription and the default MXCSR,
                // OD-198), of the low 64 (32) bits of its XMM operands (a
                // conversion from an integer: of its 64-bit register). It
                // pairs with the source's next rounding event when the event's
                // key is the row's ([`FloatKey::pairs_with`]) and the row's
                // TV-1 stamp, if it has one, names the event's LIR instruction:
                // the row's operands are then observed against the event's
                // (and an unsigned source conversion's bit 63 against `#b0`),
                // and its result is the event's free input. Any other rounding
                // row's result is an FP leaf of its own, which the theorem
                // holds for every value of. The bits of a 32-bit result's
                // register above 31 are a free input (register allocation
                // treats the destination as a pure definition, as for `movss`).
                // `cvttsd2si` (and `cvtsd2si`) return the integer indefinite
                // `0x8000_0000_0000_0000` where the value does not fit
                // ([`f64_fits_i64`]), else the event's result.
                X86Opcode::Addsd
                | X86Opcode::Subsd
                | X86Opcode::Mulsd
                | X86Opcode::Divsd
                | X86Opcode::Addss
                | X86Opcode::Subss
                | X86Opcode::Mulss
                | X86Opcode::Divss
                | X86Opcode::Cvtsi2sd
                | X86Opcode::Cvtsi2ss
                | X86Opcode::Cvttsd2si
                | X86Opcode::Cvtsd2si => {
                    let key = machine_float_key(inst.opcode).expect("a rounding row");
                    let width = key.operand_bits();
                    let operands = inst.operands[1..]
                        .iter()
                        .map(|operand| read_low(operand, width))
                        .collect::<Result<Vec<E>, _>>()?;
                    let stamp = row
                        .inst
                        .lowering_provenance
                        .source_id()
                        .map(|stamp| (Block(stamp.block), stamp.index as usize));
                    let event = match program.events.get(next_event) {
                        Some(SourceEvent::Float(f)) => Some(&program.floats[*f]).filter(|source| {
                            source.key.pairs_with(key)
                                && stamp.is_none_or(|stamp| stamp == (source.block, source.index))
                        }),
                        _ => None,
                    };
                    let leaf = match event {
                        Some(source) => {
                            next_event += 1;
                            let mut args = operands.clone();
                            if source.unsigned {
                                args.push(E::bv_const(0, 1));
                            }
                            floats.push(WalkedFloat {
                                row: row.ordinal,
                                args,
                                stop: (stopped.clone(), trapped.clone()),
                            });
                            E::var(float_event_name(source.site), key.result_bits())
                        }
                        None => names.float_leaf(row.ordinal, key.result_bits()),
                    };
                    let value = match key.op {
                        FloatEventOp::ToInt64 => E::ite(
                            f64_fits_i64(&operands[0]),
                            leaf,
                            E::bv_const(i64::MIN as u64, 64),
                        ),
                        _ if key.result_bits() == 64 => leaf,
                        _ => names
                            .undefined(UndefinedSite::Row(row.ordinal), 32)
                            .concat(leaf),
                    };
                    (value, None)
                }
                X86Opcode::MovssRR => {
                    let value = read_low(&inst.operands[1], 32)?;
                    (
                        names
                            .undefined(UndefinedSite::Row(row.ordinal), 32)
                            .concat(value),
                        None,
                    )
                }
                X86Opcode::MovsdRR => (read_low(&inst.operands[1], 64)?, None),
                X86Opcode::MovdFromXmm | X86Opcode::MovdToXmm => {
                    (widen(read_low(&inst.operands[1], 32)?, 32), None)
                }
                X86Opcode::MovqFromXmm | X86Opcode::MovqToXmm => {
                    (read_low(&inst.operands[1], 64)?, None)
                }
                // Slice 10: `not dst, src`, `neg dst, src` and `popcnt dst,
                // src` at the width the operands name (a 32-bit write
                // zero-extends).
                X86Opcode::Not | X86Opcode::Neg | X86Opcode::Popcnt => {
                    let (value, _, bits) = read(&inst.operands[1])?;
                    let size = if bits == 64 {
                        crate::x86_64_semantics::X86OperandSize::S64
                    } else {
                        crate::x86_64_semantics::X86OperandSize::S32
                    };
                    let result = match inst.opcode {
                        X86Opcode::Not => crate::x86_64_semantics::encode_not(size, value),
                        X86Opcode::Neg => crate::x86_64_semantics::encode_neg(size, value),
                        _ => count_ones(value),
                    };
                    (widen(result, bits), None)
                }
                // Slice 10: `shl`/`shr`/`sar dst, src` by CL (Intel SDM SAL/
                // SAR/SHL/SHR): the count is CL, the low byte of RCX, masked
                // to 5 bits (32-bit) or 6 bits (64-bit); a 32-bit write
                // zero-extends.
                X86Opcode::ShlRR | X86Opcode::ShrRR | X86Opcode::SarRR => {
                    let (value, _, bits) = read(&inst.operands[1])?;
                    // Slice 23 (OD-205): 32 and 64 bits only, where x86
                    // masks CL to log2 of the width, as the barrel and the
                    // constant case below read it ([`check_row_shape`]
                    // refuses a narrower row by name first).
                    if !matches!(bits, 32 | 64) {
                        return Err(unsupported(X86BodyUnsupported::MachineRow {
                            row: row.ordinal,
                            detail: format!(
                                "a {bits}-bit variable shift: the walk states variable shifts \
                                 at 32 and 64 bits only"
                            ),
                        }));
                    }
                    let rcx = bits_of(Root::Physical(RCX))?;
                    let count = low(rcx.expr, 8);
                    let op = match inst.opcode {
                        X86Opcode::ShlRR => ShiftOp::Shl,
                        X86Opcode::ShrRR => ShiftOp::Lshr,
                        _ => ShiftOp::Ashr,
                    };
                    // Slice 11: a count the walk's exact constant folding
                    // knows (the selector shifts an `I128`'s halves by
                    // constants through CL) is stated as the shift by that
                    // constant, masked as the hardware masks CL: the same
                    // value as the barrel shifter, spelled as a constant
                    // shift (`shl r, imm`'s), which AY certifies.
                    // Slice 23 (OD-205): a shift by a count the walk does not
                    // know is the barrel shifter of its key.
                    arith = Some((ArithKey::shift(op, bits), value.clone(), count.clone()));
                    let shifted = match rcx.affine.and_then(Affine::as_constant) {
                        Some(constant) => {
                            op.by_constant(value, (constant & u64::from(bits - 1)) as u32)
                        }
                        None => shift_modulo_width(op, value, count),
                    };
                    (widen(shifted, bits), None)
                }
                // Slice 10: `mul src` (Intel SDM MUL): EDX:EAX or RDX:RAX :=
                // the unsigned product of EAX/RAX and `src` at the width `src`
                // names (a 32-bit write zero-extends each half). The low half
                // is the wrapped product; CF and OF are set exactly when the
                // high half is not zero, and SF, ZF, AF and PF are undefined.
                X86Opcode::Mul => {
                    let (source, _, bits) = read(&inst.operands[0])?;
                    let accumulator = low(bits_of(Root::Physical(RAX))?.expr, bits);
                    // Slice 14: by a constant power of two (the selector's
                    // magic-number division by one), the shifts it is
                    // ([`power_of_two_product`]).
                    let multiplier = root_of(&inst.operands[0])?
                        .1
                        .affine
                        .and_then(Affine::as_constant)
                        .map(|value| crate::smt::mask(value, bits))
                        .filter(|value| value.is_power_of_two());
                    let operands = (accumulator.clone(), source.clone());
                    let (product, high) = match multiplier {
                        Some(multiplier) => power_of_two_product(accumulator, multiplier),
                        None => (
                            accumulator.clone().bvmul(source.clone()),
                            crate::x86_64_semantics::encode_mul_high(accumulator, source),
                        ),
                    };
                    let high_term = high.clone();
                    let mut defined = Vec::with_capacity(2);
                    for (root, value) in [(RAX, product), (RDX, high)] {
                        let name = names.define(row.ordinal, widen(value, bits));
                        state.insert(
                            Root::Physical(root),
                            RegValue::Bits(Slot {
                                expr: E::var(&name, 64),
                                affine: None,
                            }),
                        );
                        defined.push(name);
                    }
                    // CF = OF = "the upper half is not 0" (Intel SDM MUL), read
                    // off the NAME the row defines for that upper half, so a
                    // name OD-205's pairing re-spells as the source's widening
                    // product carries the flag with it (OD-224: the flag of a
                    // checked multiply whose operands each side computes
                    // differently). An identity: the name is defined as
                    // `widen(high)`. (Tests render history with the term
                    // itself, [`with_mul_flag_of_the_term`].)
                    let upper = if mul_flag_reads_its_name() {
                        low(E::var(&defined[1], 64), bits)
                    } else {
                        high_term
                    };
                    *flags = Flags::Alu(Box::new(AluFlags::carry_and_overflow(
                        upper.eq_expr(E::bv_const(0, bits)).not_expr(),
                    )));
                    // Slice 23 (OD-205): RAX is the low half of the product
                    // and RDX the high half of the widening product.
                    if let Some(stamp) = row.inst.lowering_provenance.source_id() {
                        let stamp = (Block(stamp.block), stamp.index as usize);
                        for (op, name, part) in [
                            (ArithOp::MulLo, &defined[0], ArithPart::Whole),
                            (ArithOp::UMulWide, &defined[1], ArithPart::High),
                        ] {
                            names.record_arith(MachineArith {
                                stamp,
                                key: ArithKey::new(op, bits),
                                operands: operands.clone(),
                                results: vec![(name.clone(), part)],
                            });
                        }
                    }
                    bound_rows.push(row.ordinal);
                    continue;
                }
                // Slice 14: `cqo` (Intel SDM CWD/CDQ/CQO: RDX := the sign of
                // RAX, every bit) and `cdq` (EDX := the sign of EAX, the
                // 32-bit write zero-extending into RDX). Flags unchanged.
                X86Opcode::Cqo | X86Opcode::Cdq => {
                    let bits = if inst.opcode == X86Opcode::Cqo {
                        64
                    } else {
                        32
                    };
                    let value = low(bits_of(Root::Physical(RAX))?.expr, bits);
                    let name = names.define(row.ordinal, widen(sign_of(value), bits));
                    state.insert(
                        Root::Physical(RDX),
                        RegValue::Bits(Slot {
                            expr: E::var(&name, 64),
                            affine: None,
                        }),
                    );
                    bound_rows.push(row.ordinal);
                    continue;
                }
                // Slice 14: `div src`/`idiv src` (Intel SDM DIV/IDIV) at the
                // width `src` names: EDX:EAX or RDX:RAX divided by `src`,
                // unsigned or signed (truncating), quotient to EAX/RAX and
                // remainder (the dividend's sign) to EDX/RDX, each 32-bit
                // half zero-extended; every status flag undefined; #DE when
                // `src` is zero or the quotient does not fit the width
                // ([`machine_division`]). A #DE stops the machine: the walk
                // records it in `stopped`, and every later claim requires it
                // not to have happened wherever the source has not stopped.
                X86Opcode::Div | X86Opcode::Idiv => {
                    let (divisor, _, bits) = read(&inst.operands[0])?;
                    let rax = bits_of(Root::Physical(RAX))?.expr;
                    let rdx = bits_of(Root::Physical(RDX))?.expr;
                    let high_definition = names.definition(&rdx).cloned();
                    let signed = inst.opcode == X86Opcode::Idiv;
                    let dividend = low(rax, bits);
                    let (quotient, remainder, fault, canonical) = machine_division(
                        signed,
                        dividend.clone(),
                        low(rdx, bits),
                        high_definition.as_ref(),
                        divisor.clone(),
                    );
                    *flags = Flags::Undefined;
                    let mut defined = Vec::with_capacity(2);
                    for (root, value) in [(RAX, quotient), (RDX, remainder)] {
                        let name = names.define(row.ordinal, widen(value, bits));
                        state.insert(
                            Root::Physical(root),
                            RegValue::Bits(Slot {
                                expr: E::var(&name, 64),
                                affine: None,
                            }),
                        );
                        defined.push(name);
                    }
                    // Slice 23 (OD-205): the quotient and the remainder of
                    // the dividend's low half by the divisor, as candidates
                    // (only the canonical form is that, [`pair_arithmetic`]).
                    // Never an `idiv`: the selector divides by its fixed-up
                    // divisor (1 where the source divides by -1, so `idiv`
                    // cannot fault at the minimum; `select_div`), which is
                    // never the source's divisor at -1, so the divisor claim
                    // would refute a correct lowering ([`signed_division_pairing`]).
                    if (!signed || signed_division_pairing())
                        && let Some(stamp) = row.inst.lowering_provenance.source_id()
                    {
                        let stamp = (Block(stamp.block), stamp.index as usize);
                        let (quotient_op, remainder_op) = if signed {
                            (ArithOp::Sdiv, ArithOp::Srem)
                        } else {
                            (ArithOp::Udiv, ArithOp::Urem)
                        };
                        for (op, name) in [(quotient_op, &defined[0]), (remainder_op, &defined[1])]
                        {
                            names.record_arith(MachineArith {
                                stamp,
                                key: ArithKey::new(op, bits),
                                operands: (dividend.clone(), divisor.clone()),
                                results: vec![(name.clone(), ArithPart::Whole)],
                            });
                        }
                    }
                    // A division of the canonical dividend, kept for its
                    // pairing with the source's ([`pair_divisions`]).
                    if canonical
                        && let Some(stamp) = row.inst.lowering_provenance.source_id()
                        && !names
                            .divisions
                            .iter()
                            .any(|division| division.quotient == defined[0])
                    {
                        names.divisions.push(MachineDivision {
                            stamp: (Block(stamp.block), stamp.index as usize),
                            signed,
                            bits,
                            dividend,
                            divisor,
                            quotient: defined[0].clone(),
                            remainder: defined[1].clone(),
                        });
                    }
                    let next = bit_or(stopped.clone(), bit_of(fault));
                    *stopped = if next == *stopped {
                        next
                    } else {
                        E::var(names.define(row.ordinal, next), 1)
                    };
                    bound_rows.push(row.ordinal);
                    continue;
                }
                // Slice 14: the `TrapDivZeroExact` carrier of a divisor
                // register traps exactly when the register is zero at the
                // width it names: the x86 pipeline expands it, after this
                // theorem's subject, to `test d, d; je -> ud2` at that width
                // (`expand_x86_div_zero_check_carriers`, whose condition its
                // guard-carrier canary checks), which also writes the flags,
                // so a later reader makes no claim. Its firing stops the
                // machine, by trap: `trapped` records a trap that comes
                // before any other stop.
                X86Opcode::TrapDivZeroExact => {
                    let (value, _, bits) = read(&inst.operands[0])?;
                    let fire = bit_of(value.eq_expr(E::bv_const(0, bits)));
                    let first = if *stopped == bit_zero() {
                        fire.clone()
                    } else {
                        E::ite(guard_holds(stopped.clone()), bit_zero(), fire.clone())
                    };
                    let next_trapped = bit_or(trapped.clone(), first);
                    let next_stopped = bit_or(stopped.clone(), fire);
                    *trapped = E::var(names.define(row.ordinal, next_trapped), 1);
                    *stopped = E::var(names.define(row.ordinal, next_stopped), 1);
                    *flags = Flags::Unmodelled;
                    bound_rows.push(row.ordinal);
                    continue;
                }
                X86Opcode::AddRI
                | X86Opcode::SubRI
                | X86Opcode::AndRI
                | X86Opcode::OrRI
                | X86Opcode::XorRI
                | X86Opcode::ImulRRI => {
                    let (lhs, lhs_affine, bits) = read(&inst.operands[1])?;
                    let O::Imm(imm) = inst.operands[2] else {
                        unreachable!("row shape checked");
                    };
                    // `imm32`, sign-extended to the operand width.
                    let imm = (i64::from(imm as i32) as u64) & crate::smt::mask(u64::MAX, bits);
                    let op = binary_op(inst.opcode);
                    let affine = match op {
                        BinaryOp::Add | BinaryOp::Sub if bits == 64 => lhs_affine.map(|a| {
                            a.combine(
                                Affine::constant(imm, u64::MAX),
                                op == BinaryOp::Sub,
                                u64::MAX,
                            )
                        }),
                        // OD-185: a 64-bit `imul` of a constant by an
                        // immediate is a constant (the selector's `ArrayGep`
                        // stride product at a constant index).
                        BinaryOp::Mul if bits == 64 => lhs_affine
                            .and_then(Affine::as_constant)
                            .map(|a| Affine::constant(a.wrapping_mul(imm), u64::MAX)),
                        _ => None,
                    };
                    (widen(op.apply(lhs, E::bv_const(imm, bits)), bits), affine)
                }
                X86Opcode::ShlRI | X86Opcode::ShrRI | X86Opcode::SarRI => {
                    let (value, value_affine, bits) = read(&inst.operands[1])?;
                    let O::Imm(count) = inst.operands[2] else {
                        unreachable!("row shape checked");
                    };
                    // The CPU masks an imm8 count to 5 (32-bit) or 6 (64-bit) bits.
                    let count = (count as u64) & u64::from(bits - 1);
                    let op = match inst.opcode {
                        X86Opcode::ShlRI => ShiftOp::Shl,
                        X86Opcode::ShrRI => ShiftOp::Lshr,
                        _ => ShiftOp::Ashr,
                    };
                    // A 64-bit left shift of a constant is a constant.
                    let affine = value_affine
                        .and_then(Affine::as_constant)
                        .filter(|_| op == ShiftOp::Shl && bits == 64)
                        .map(|constant| Affine::constant(constant << count, u64::MAX));
                    (widen(op.by_constant(value, count as u32), bits), affine)
                }
                // `rol dst, src, k` is `(src << k) | (src >>u (width - k))`,
                // spelled through the same [`ShiftOp::by_constant`] the shifts
                // use, so it inherits the spelling host qualification chose.
                X86Opcode::RolRI => {
                    let (value, _, bits) = read(&inst.operands[1])?;
                    let O::Imm(count) = inst.operands[2] else {
                        unreachable!("row shape checked");
                    };
                    // The CPU masks an imm8 count to 5 (32-bit) or 6 (64-bit)
                    // bits. The shape check rejects a masked count of zero, so
                    // `count` and `bits - count` are both in `1..bits`.
                    let count = ((count as u64) & u64::from(bits - 1)) as u32;
                    let left = ShiftOp::Shl.by_constant(value.clone(), count);
                    let right = ShiftOp::Lshr.by_constant(value, bits - count);
                    (widen(left.bvor(right), bits), None)
                }
                X86Opcode::Lea => {
                    let O::MemAddr { base, disp } = &inst.operands[1] else {
                        unreachable!("row shape checked");
                    };
                    let (base, base_affine, _) = read(base.as_ref())?;
                    let disp = i64::from(*disp) as u64;
                    // `base + disp`; a zero displacement is the base itself.
                    let (expr, affine) = if disp == 0 {
                        (base, base_affine)
                    } else {
                        (
                            base.bvadd(E::bv_const(disp, 64)),
                            base_affine.map(|a| {
                                a.combine(Affine::constant(disp, u64::MAX), false, u64::MAX)
                            }),
                        )
                    };
                    (expr, affine)
                }
                X86Opcode::LeaSib => {
                    let O::SibMemAddr {
                        base,
                        index,
                        scale,
                        disp,
                    } = &inst.operands[1]
                    else {
                        unreachable!("row shape checked");
                    };
                    let (base, base_affine, _) = read(base.as_ref())?;
                    let (index, index_affine, _) = read(index.as_ref())?;
                    // The effective address ([`sib_bits`]), base read first.
                    sib_bits((base, base_affine), (index, index_affine), *scale, *disp)
                }
                // A symbol's address (slice 5): the free input the source's
                // `GlobalRef` (`lea r, [rip + symbol]`) or `ExternRef` (`mov
                // r, [rip + symbol@GOT]`, whose slot the loader fills with
                // the symbol's address) of the same symbol reads.
                X86Opcode::LeaRip | X86Opcode::MovRipRel => {
                    let O::Symbol(name) = &inst.operands[1] else {
                        unreachable!("row shape checked");
                    };
                    let symbol = SymbolRef {
                        name: name.clone(),
                        got: inst.opcode == X86Opcode::MovRipRel,
                    };
                    let Some(j) = sites.symbols.iter().position(|known| *known == symbol) else {
                        return Err(mismatch(X86BodyMismatch::Symbol {
                            row: row.ordinal,
                            symbol: symbol.describe(),
                        }));
                    };
                    (E::var(symbol_name(j), 64), None)
                }
                // `setcc r8` (slice 5): the byte 1 when the condition holds of
                // the flags a compare defined, else 0 (the shared x86 EFLAGS
                // model). It writes only the low byte, and register allocation
                // treats its destination as a pure definition (a later `movzx`
                // reads just that byte), so bits 8..63 are a free input `u_k`.
                X86Opcode::Setcc => {
                    let O::CondCode(cc) = inst.operands[1] else {
                        unreachable!("row shape checked");
                    };
                    let byte = E::ite(
                        flags.condition(cc, row.ordinal, inst.opcode)?,
                        E::bv_const(1, 8),
                        E::bv_const(0, 8),
                    );
                    (
                        names
                            .undefined(UndefinedSite::Row(row.ordinal), 56)
                            .concat(byte),
                        None,
                    )
                }
                // `cmovcc dst, src` (slice 6): `src` when the condition holds
                // of the flags a compare or test of this block defined, else
                // the destination's own value, which register allocation
                // keeps (its destination is tied: a def and a use). The
                // 32-bit form writes the low 32 bits and zero-extends in both
                // cases.
                X86Opcode::Cmovcc | X86Opcode::Cmovcc32 => {
                    let O::CondCode(cc) = inst.operands[2] else {
                        unreachable!("row shape checked");
                    };
                    let holds = flags.condition(cc, row.ordinal, inst.opcode)?;
                    let (kept, _, bits) = read(&inst.operands[0])?;
                    let (moved, _, _) = read(&inst.operands[1])?;
                    (widen(E::ite(holds, moved, kept), bits), None)
                }
                X86Opcode::Call | X86Opcode::CallR => {
                    // Pair with the source call in the same position.
                    let k = calls.len();
                    let Some(call) = program.calls.get(k) else {
                        return Err(mismatch(X86BodyMismatch::CallCount {
                            lir: program.calls.len(),
                            machine: k + 1,
                        }));
                    };
                    check_call_row(row.ordinal, inst, call)?;
                    // Slice 10: `call r64` jumps to the 64 bits of its register,
                    // read before the call clobbers anything; the theorem
                    // observes them against the source's function pointer.
                    let callee = match &inst.operands[..] {
                        [callee] if inst.opcode == X86Opcode::CallR => Some(read(callee)?.0),
                        _ => None,
                    };
                    // The call is also the next event of the world trace: it
                    // reads and writes incoming memory, so no incoming access may
                    // move across it.
                    if program.events.get(next_event) != Some(&SourceEvent::Call(k)) {
                        return Err(trace(format!(
                            "call {k} where the source's next event is {}",
                            describe_event(program, next_event)
                        )));
                    }
                    next_event += 1;
                    // What the callee reads: each argument register, at the
                    // width its parameter type defines (slice 8: an
                    // aggregate eightbyte at its own bytes). An argument
                    // whose source passes a private stack address (slice 7)
                    // must hold exactly that slot and offset, which makes
                    // the slot escape here.
                    // Slice 11: an `I128` argument's halves at 64 bits each,
                    // a float's bit pattern at its width in its SSE register;
                    // each register is the source call's System V root.
                    // Slice 13: an aggregate eightbyte that is a whole stored
                    // private address is checked like a private-address
                    // argument ([`CallArg::register_frames`]).
                    let registers: Vec<(Option<FrameAddr>, u32)> = call
                        .args
                        .iter()
                        .flat_map(|arg| arg.register_frames().into_iter().zip(arg.register_bits()))
                        .collect();
                    // Slice 17: the indexed private address each register of an
                    // indexed argument holds on the source side.
                    let indexed_args: Vec<Option<IndexedAddr>> = call
                        .args
                        .iter()
                        .flat_map(|arg| match arg {
                            CallArg::Indexed(address) => vec![Some(*address)],
                            other => vec![None; other.registers()],
                        })
                        .collect();
                    let mut args = Vec::with_capacity(registers.len());
                    let mut arg_affine = Vec::with_capacity(registers.len());
                    let mut passed: Vec<u32> = Vec::new();
                    for (argument, ((expected, bits), root)) in registers
                        .iter()
                        .zip(call.arg_roots.iter().copied())
                        .enumerate()
                    {
                        // Slice 17: an indexed argument. The machine must pass
                        // an address of the same slot (else the named
                        // `CallStackAddress`); it is observed as the slot's
                        // address plus the machine's own offset term, against
                        // the source's ([`indexed::argument_term`]), and an
                        // indexed one is claimed into the slot or one past it.
                        if let Some(source) = indexed_args[argument] {
                            let register = Root::Physical(root);
                            let (slot, offset, claimed) = match state.get(&register) {
                                Some(RegValue::Indexed(found)) => (found.slot, found.term(), true),
                                Some(RegValue::Frame(found)) => {
                                    let size = program
                                        .slot_sizes
                                        .get(found.slot as usize)
                                        .copied()
                                        .unwrap_or(0);
                                    if found.offset < 0 || found.offset > i64::from(size) {
                                        return Err(unsupported(X86BodyUnsupported::MachineRow {
                                            row: row.ordinal,
                                            detail: format!(
                                                "Call passes {}, outside its slot, where its LIR \
                                                 source passes an indexed address",
                                                found.describe()
                                            ),
                                        }));
                                    }
                                    (found.slot, E::bv_const(found.offset as u64, 64), false)
                                }
                                Some(RegValue::Bits(_)) => {
                                    return Err(unsupported(X86BodyUnsupported::MachineRow {
                                        row: row.ordinal,
                                        detail: format!(
                                            "Call passes a value the walk does not track as a \
                                             private stack address in {}, where its LIR source \
                                             passes one",
                                            root_name(root)
                                        ),
                                    }));
                                }
                                None => return Err(undefined(register)),
                                Some(RegValue::Mixed) => return Err(mixed(register)),
                                Some(RegValue::Carried) => return Err(carried(register)),
                                Some(RegValue::Dispatch(_)) => {
                                    return Err(dispatch_value(register));
                                }
                            };
                            if slot != source.slot {
                                return Err(mismatch(X86BodyMismatch::CallStackAddress {
                                    row: row.ordinal,
                                    argument,
                                    expected: source.describe(),
                                    found: format!("an address of private stack slot {slot}"),
                                }));
                            }
                            if claimed {
                                indexed_claims.push(indexed::in_bounds(
                                    offset.clone(),
                                    program.slot_sizes[slot as usize],
                                    0,
                                    source.modulus,
                                    source.residue(),
                                ));
                            }
                            args.push(indexed::argument_term(slot, offset));
                            arg_affine.push(None);
                            passed.push(slot);
                            continue;
                        }
                        let (expected, bits) = (expected.as_ref(), *bits);
                        let wrong_address = |found: String| {
                            mismatch(X86BodyMismatch::CallStackAddress {
                                row: row.ordinal,
                                argument,
                                expected: expected.map_or_else(
                                    || "no private stack address".to_owned(),
                                    |address| address.describe(),
                                ),
                                found,
                            })
                        };
                        match (expected, state.get(&Root::Physical(root))) {
                            (Some(expected), Some(RegValue::Frame(found))) => {
                                if found != expected {
                                    return Err(wrong_address(found.describe()));
                                }
                                passed.push(found.slot);
                                arg_affine.push(None);
                            }
                            (Some(_), Some(RegValue::Bits(_))) => {
                                return Err(unsupported(X86BodyUnsupported::MachineRow {
                                    row: row.ordinal,
                                    detail: format!(
                                        "Call passes a value the walk does not track as a private \
                                         stack address in {}, where its LIR source passes one",
                                        root_name(root)
                                    ),
                                }));
                            }
                            (None, Some(RegValue::Frame(found))) => {
                                return Err(wrong_address(found.describe()));
                            }
                            // Slice 17: an indexed address where the source
                            // passes a value is a wrong address; where it
                            // passes one at a constant offset, no claim.
                            (None, Some(RegValue::Indexed(found))) => {
                                return Err(wrong_address(format!(
                                    "an indexed address of private stack slot {}",
                                    found.slot
                                )));
                            }
                            (Some(_), Some(RegValue::Indexed(_))) => {
                                return Err(unsupported(X86BodyUnsupported::MachineRow {
                                    row: row.ordinal,
                                    detail: format!(
                                        "Call passes an indexed private stack address in {}, \
                                         where its LIR source passes one at a constant offset",
                                        root_name(root)
                                    ),
                                }));
                            }
                            (_, None) => return Err(undefined(Root::Physical(root))),
                            (_, Some(RegValue::Mixed)) => {
                                return Err(mixed(Root::Physical(root)));
                            }
                            (_, Some(RegValue::Carried)) => {
                                return Err(carried(Root::Physical(root)));
                            }
                            (_, Some(RegValue::Dispatch(_))) => {
                                return Err(dispatch_value(Root::Physical(root)));
                            }
                            (None, Some(RegValue::Bits(slot))) => {
                                arg_affine.push(if bits == 64 { slot.affine } else { None });
                                args.push(low(slot.expr.clone(), bits));
                            }
                        }
                    }
                    // Slice 13: each stack argument is the bytes the outgoing
                    // argument area holds at its eightbyte: a scalar at its
                    // return bits (every byte a store wrote), a private address
                    // exactly the paired slot and offset. Nothing else may be
                    // open around a call.
                    match (call.stack_args.is_empty(), outgoing.as_ref()) {
                        (true, None) | (false, Some(_)) => {}
                        _ => {
                            return Err(unsupported(X86BodyUnsupported::MachineRow {
                                row: row.ordinal,
                                detail: "the outgoing argument area does not match the call's \
                                         stack arguments"
                                    .into(),
                            }));
                        }
                    }
                    // Slice 15: an `I128` is two eightbytes, each observed
                    // as its own 64-bit item (low half first), as in
                    // registers.
                    let pieces =
                        call.stack_args
                            .iter()
                            .enumerate()
                            .flat_map(|(argument, (arg, offset))| {
                                let first = *offset as usize;
                                match arg {
                                    CallArg::Frame(..) => vec![(argument, arg, first, 8)],
                                    CallArg::Scalar(_, Carrier::I128) => {
                                        vec![
                                            (argument, arg, first, 8),
                                            (argument, arg, first + 8, 8),
                                        ]
                                    }
                                    CallArg::Scalar(_, ty) => {
                                        vec![(argument, arg, first, ty.return_bits() / 8)]
                                    }
                                    CallArg::Aggregate(_) | CallArg::Indexed(_) => {
                                        unreachable!("never a stack argument")
                                    }
                                }
                            });
                    for (argument, arg, first, bytes) in pieces {
                        let offset = first;
                        let area = outgoing.as_ref().expect("checked above");
                        let Some(part) = area.get(first..first + bytes as usize) else {
                            return Err(unsupported(X86BodyUnsupported::MachineRow {
                                row: row.ordinal,
                                detail: format!(
                                    "the outgoing argument area ends before stack argument \
                                     {argument}"
                                ),
                            }));
                        };
                        let written: Option<Vec<&MachineByte>> =
                            part.iter().map(Option::as_ref).collect();
                        let Some(written) = written else {
                            return Err(mismatch(X86BodyMismatch::UndefinedRead {
                                row: row.ordinal,
                                operand: format!("the outgoing stack argument at rsp+{offset}"),
                            }));
                        };
                        let frame = written[0].frame.filter(|_| {
                            written.iter().enumerate().all(|(i, byte)| {
                                byte.frame == written[0].frame && byte.byte == i as u32
                            })
                        });
                        match (arg, frame) {
                            (CallArg::Frame(expected), Some(found)) => {
                                if found != *expected {
                                    return Err(mismatch(X86BodyMismatch::CallStackAddress {
                                        row: row.ordinal,
                                        argument: call.args.len() + argument,
                                        expected: expected.describe(),
                                        found: found.describe(),
                                    }));
                                }
                                passed.push(found.slot);
                            }
                            (CallArg::Scalar(..), None)
                                if written.iter().all(|byte| byte.frame.is_none()) =>
                            {
                                let part: Vec<Option<MachineByte>> =
                                    written.into_iter().cloned().map(Some).collect();
                                args.push(machine_whole_store(&part).unwrap_or_else(|| {
                                    concat_bytes(
                                        part.iter()
                                            .map(|byte| byte.as_ref().expect("written").expr())
                                            .collect(),
                                    )
                                }));
                            }
                            _ => {
                                return Err(unsupported(X86BodyUnsupported::MachineRow {
                                    row: row.ordinal,
                                    detail: format!(
                                        "stack argument {argument} is not the private address or \
                                         value its LIR source passes"
                                    ),
                                }));
                            }
                        }
                    }
                    // Slice 13: with each slot passed here, every slot whose
                    // address an escaped slot's bytes hold escapes
                    // ([`escape_machine`]). The callee then reads exactly the
                    // slots the source's call reads; when the two sides let
                    // different slots escape, no single trace states both, and
                    // the body makes no claim.
                    escape_machine(escaped, stack.as_slice(), passed);
                    if !escaped
                        .iter()
                        .copied()
                        .eq(call.slot_reads.iter().map(|(slot, _)| *slot))
                    {
                        return Err(unsupported(X86BodyUnsupported::MachineRow {
                            row: row.ordinal,
                            detail: format!(
                                "the private stack slots escaped at call {k} ({escaped:?}) are not \
                                 the source's ({:?})",
                                call.slot_reads
                                    .iter()
                                    .map(|(slot, _)| *slot)
                                    .collect::<Vec<_>>()
                            ),
                        }));
                    }
                    // Slice 7: the callee reads every escaped slot's bytes
                    // (observed like its arguments), then leaves each of
                    // them as it chooses: the call-defined input its paired
                    // source call names too.
                    let slots =
                        machine_slot_chunks(escaped, stack, frame_bytes).map_err(|detail| {
                            unsupported(X86BodyUnsupported::MachineRow {
                                row: row.ordinal,
                                detail,
                            })
                        })?;
                    for slot in escaped.iter() {
                        for (offset, byte) in stack[*slot as usize].iter_mut().enumerate() {
                            let address = FrameAddr {
                                slot: *slot,
                                offset: offset as i64,
                            };
                            *byte = Some(MachineByte {
                                term: E::var(call_byte_name(call.site, address), 8),
                                width: 8,
                                byte: 0,
                                affine: None,
                                frame: None,
                                dead: false,
                            });
                        }
                    }
                    // The callee may change every caller-saved register; it
                    // preserves RBX, RBP, R12-R15 and RSP (the walk refuses a
                    // body that writes them) and cannot see virtual registers
                    // or a private stack slot whose address did not escape.
                    for root in SYSV_CALLER_SAVED_ROOTS.into_iter().chain(XMM_ROOTS) {
                        state.remove(&Root::Physical(root));
                    }
                    // Each result lane defines its register (RAX, then RDX;
                    // slice 11: XMM0, then XMM1, for an SSE lane) at the bits
                    // the callee defines; a callee also leaves RFLAGS
                    // undefined.
                    for (lane, result) in call.results.iter().enumerate() {
                        state.insert(
                            Root::Physical(result.root),
                            RegValue::Bits(Slot {
                                expr: call_result_register(call.site, lane, *result),
                                affine: None,
                            }),
                        );
                    }
                    *flags = Flags::Undefined;
                    // Slice 13: the callee owns its incoming argument area and
                    // may leave anything there.
                    if let Some(area) = outgoing.as_mut() {
                        area.fill(None);
                    }
                    calls.push(WalkedCall {
                        row: row.ordinal,
                        callee,
                        args,
                        arg_affine,
                        slots,
                        stop: (stopped.clone(), trapped.clone()),
                    });
                    continue;
                }
                X86Opcode::Ret => {
                    if program.end != SourceEnd::Return {
                        return Err(mismatch(X86BodyMismatch::Control {
                            block: row.block,
                            row: Some(row.ordinal),
                            detail: "returns where the LIR source diverges".into(),
                        }));
                    }
                    // Slice 13: an outgoing argument area still open returns
                    // with RSP not restored (found by the slice-13 robustness
                    // probe: the `add rsp` after a call dropped).
                    if outgoing.is_some() {
                        return Err(mismatch(X86BodyMismatch::PreservedWrite {
                            row: row.ordinal,
                            register: ROOT_NAMES[RSP as usize],
                        }));
                    }
                    // Each result lane's register (slice 11: an SSE lane's is
                    // XMM0 or XMM1).
                    for root in &program.return_roots {
                        let register = match state.get(&Root::Physical(*root)) {
                            None => {
                                return Err(mismatch(X86BodyMismatch::UndefinedReturn {
                                    register: static_root_name(*root),
                                }));
                            }
                            Some(RegValue::Frame(_) | RegValue::Indexed(_)) => {
                                return Err(escapes(Root::Physical(*root)));
                            }
                            Some(RegValue::Mixed) => return Err(mixed(Root::Physical(*root))),
                            Some(RegValue::Carried) => {
                                return Err(carried(Root::Physical(*root)));
                            }
                            Some(RegValue::Dispatch(_)) => {
                                return Err(dispatch_value(Root::Physical(*root)));
                            }
                            Some(RegValue::Bits(register)) => register.clone(),
                        };
                        observed.push(register);
                    }
                    continue;
                }
                X86Opcode::Ud2 => {
                    if program.end != SourceEnd::Trap {
                        return Err(mismatch(X86BodyMismatch::Control {
                            block: row.block,
                            row: Some(row.ordinal),
                            detail: "traps where the LIR source returns".into(),
                        }));
                    }
                    continue;
                }
                // Slice 14: the dispatch's indirect `jmp` goes to the block
                // the table's entry at the walked index names: on this route
                // (to the block [`PathRow::jump`] records) exactly when the
                // index is one of the table's indices of that block, the
                // literal the theorem states (an index past the table, which
                // the selector's bound check excludes, is none of them).
                X86Opcode::JmpR => {
                    let target = gpr64(&inst.operands[0]).expect("row shape checked").root;
                    let (Some(RegValue::Dispatch(TableValue::Target { table, index })), Some(to)) =
                        (state.get(&target), *jump)
                    else {
                        return Err(unsupported(X86BodyUnsupported::MachineRow {
                            row: row.ordinal,
                            detail: "JmpR through a value other than a jump-table target".into(),
                        }));
                    };
                    let hits: Vec<E> = consts.jump_tables[*table as usize]
                        .targets
                        .iter()
                        .enumerate()
                        .filter(|(_, block)| **block == to)
                        .map(|(i, _)| index.clone().eq_expr(E::bv_const(i as u64, 64)))
                        .collect();
                    literals.push(
                        hits.into_iter()
                            .rev()
                            .reduce(|tail, hit| hit.or_expr(tail))
                            .unwrap_or(E::bool_const(false)),
                    );
                    bound_rows.push(row.ordinal);
                    continue;
                }
                // Control and inert rows define nothing.
                X86Opcode::Jmp | X86Opcode::Nop => continue,
                other => unreachable!("row shape admitted {other:?}"),
            }
        };
        // The destination root: a 32- or 64-bit register, or (slice 8) the
        // physical 8- or 16-bit alias a byte or word load writes, whose bits
        // above the loaded ones are a free input (the narrow-load rule above).
        let destination = gpr(&inst.operands[0])
            .or_else(|| xmm(&inst.operands[0]))
            .map(|reg| reg.root)
            .or_else(|| {
                [8, 16]
                    .into_iter()
                    .find_map(|bits| narrow_alias(&inst.operands[0], bits))
            })
            .expect("row shape checked");
        if let Root::Physical(root) = destination
            && SYSV_PRESERVED_ROOTS.contains(&root)
        {
            return Err(mismatch(X86BodyMismatch::PreservedWrite {
                row: row.ordinal,
                register: ROOT_NAMES[root as usize],
            }));
        }
        let name = names.define(row.ordinal, expr);
        if let Some((key, c, d)) = arith
            && let Some(stamp) = row.inst.lowering_provenance.source_id()
        {
            names.record_arith(MachineArith {
                stamp: (Block(stamp.block), stamp.index as usize),
                key,
                operands: (c, d),
                results: vec![(name.clone(), ArithPart::Whole)],
            });
        }
        state.insert(
            destination,
            RegValue::Bits(Slot {
                expr: E::var(&name, 64),
                affine,
            }),
        );
        bound_rows.push(row.ordinal);
    }
    if calls.len() != program.calls.len() {
        return Err(mismatch(X86BodyMismatch::CallCount {
            lir: program.calls.len(),
            machine: calls.len(),
        }));
    }
    if next_event != program.events.len() {
        return Err(unsupported(X86BodyUnsupported::AccessTrace {
            detail: format!(
                "the machine ends its trace after {next_event} event(s) where the source has {}",
                program.events.len()
            ),
        }));
    }
    let return_affine = observed
        .iter()
        .zip(&program.return_tys)
        .map(|(register, ty)| {
            (*ty == ReturnLane::Scalar(Carrier::I64))
                .then_some(register.affine)
                .flatten()
        })
        .collect();
    Ok(Walked {
        // The entry facts are the walk's start's ([`walk_machine`]).
        entry_names: Vec::new(),
        abi_views: Vec::new(),
        returns: observed.into_iter().map(|register| register.expr).collect(),
        return_affine,
        calls,
        accesses,
        floats,
        literals,
        bound_rows,
        end_stop: (stopped.clone(), trapped.clone()),
        indexed: indexed_claims,
    })
}

/// The source's `n`-th world-trace event, for a refusal message.
fn describe_event(program: &SourceProgram, n: usize) -> String {
    match program.events.get(n) {
        None => "none (its trace has ended)".into(),
        Some(SourceEvent::Call(k)) => format!("call {k}"),
        Some(SourceEvent::Access(access)) => {
            let access = &program.accesses[*access];
            format!(
                "a {}-byte {}",
                access.carrier.bytes(),
                match access.kind {
                    AccessKind::Load(_) => "load",
                    AccessKind::Store(_) => "store",
                }
            )
        }
        Some(SourceEvent::Float(f)) => {
            let float = &program.floats[*f];
            format!(
                "the rounding event {:?} of {:?} ({:?})",
                float.key.op, float.key.format, float.key.rounding
            )
        }
    }
}

fn binary_op(opcode: X86Opcode) -> BinaryOp {
    match opcode {
        X86Opcode::AddRR | X86Opcode::AddRI => BinaryOp::Add,
        X86Opcode::SubRR | X86Opcode::SubRI => BinaryOp::Sub,
        X86Opcode::ImulRR | X86Opcode::ImulRRI => BinaryOp::Mul,
        X86Opcode::AndRR | X86Opcode::AndRI => BinaryOp::And,
        X86Opcode::OrRR | X86Opcode::OrRI => BinaryOp::Or,
        X86Opcode::XorRR | X86Opcode::XorRI => BinaryOp::Xor,
        other => unreachable!("not a binary ALU row: {other:?}"),
    }
}

/// The register-register ALU row at its operand width, through the shared
/// `x86_64_semantics` encoders.
fn machine_binary(opcode: X86Opcode, bits: u32, lhs: E, rhs: E) -> E {
    use crate::x86_64_semantics as x86;
    let size = if bits == 64 {
        x86::X86OperandSize::S64
    } else {
        x86::X86OperandSize::S32
    };
    match opcode {
        X86Opcode::AddRR => x86::encode_add_rr(size, lhs, rhs),
        X86Opcode::SubRR => x86::encode_sub_rr(size, lhs, rhs),
        X86Opcode::ImulRR => x86::encode_imul_rr(size, lhs, rhs),
        X86Opcode::AndRR => x86::encode_and_rr(size, lhs, rhs),
        X86Opcode::OrRR => x86::encode_or_rr(size, lhs, rhs),
        X86Opcode::XorRR => x86::encode_xor_rr(size, lhs, rhs),
        other => unreachable!("not a register-register ALU row: {other:?}"),
    }
}

// ---------------------------------------------------------------------------
// The theorem
// ---------------------------------------------------------------------------

/// Little-endian bytes (low byte first) as one value: the canonical
/// right-nested concatenation `(concat b_n (concat ... (concat b_1 b_0)))`,
/// on both sides of every theorem.
fn concat_bytes(bytes: Vec<E>) -> E {
    bytes
        .into_iter()
        .reduce(|low, high| high.concat(low))
        .expect("an access reads at least one byte")
}

/// One source private stack byte at `address` as an 8-bit term: a stored
/// value's byte, the call-defined input of the call that left it (slice 7),
/// or the slot's initial byte (slice 6).
fn source_slot_byte(
    address: FrameAddr,
    byte: &Option<SlotByte>,
    value: &dyn Fn(&Value) -> E,
    walks: &BodyWalks,
) -> E {
    match byte {
        Some(SlotByte::Stored(byte)) => {
            let stored = byte.carrier.memory_value(value(&byte.value));
            if byte.carrier.bytes() == 1 {
                stored
            } else {
                stored.extract(8 * byte.byte + 7, 8 * byte.byte)
            }
        }
        Some(SlotByte::Call(site)) => E::var(call_byte_name(*site, address), 8),
        // Slice 15: a byte a store through a derived address may have written.
        Some(SlotByte::AccessStore(site)) => E::var(access_byte_name(*site, address), 8),
        Some(SlotByte::Entry { root, byte }) => {
            E::var(entry_name(*root), 64).extract(8 * byte + 7, 8 * byte)
        }
        Some(SlotByte::Result {
            site,
            lane,
            byte,
            width,
        }) => {
            let lane = E::var(call_result_name(*site, *lane), *width);
            if *width == 8 {
                lane
            } else {
                lane.extract(8 * byte + 7, 8 * byte)
            }
        }
        // Slice 9: the byte a DAG join merges, defined at the join.
        Some(SlotByte::Merged { id, .. }) => E::var(merged_byte_name(*id), 8),
        // Slice 12: a byte a loop may change, at its header.
        Some(SlotByte::Header { header, .. }) => E::var(header_byte_name(*header, address), 8),
        // Slice 13: a byte of a private address stored as data.
        Some(SlotByte::Address { address, byte }) => {
            frame_address_term(*address).extract(8 * byte + 7, 8 * byte)
        }
        // Slice 17: a byte an indexed store may have written, defined where
        // the store runs.
        Some(SlotByte::Indexed { id, .. }) => E::var(indexed::indexed_byte_name(*id), 8),
        // Slice 17: admission refuses every read of a dead byte; should a term
        // of one ever be built, it names no declared input, and the theorem's
        // construction check refuses it.
        Some(SlotByte::Dead) => E::var("unreadable", 8),
        None => E::var(frame_byte_name(walks.frame_byte(address)), 8),
    }
}

/// Source private stack bytes, low byte first, as one value (slice 8): a
/// run of consecutive bytes of one argument register (an aggregate
/// parameter's) or of one call result lane (an aggregate call result's) is
/// the one extract of that register or lane (the lane itself when it is the
/// whole lane); any other run is the concatenation of its bytes
/// ([`source_slot_byte`]), as in slices 6 and 7.
fn source_bytes(
    bytes: &[(FrameAddr, Option<SlotByte>)],
    value: &dyn Fn(&Value) -> E,
    walks: &BodyWalks,
) -> E {
    let part: Vec<Option<SlotByte>> = bytes.iter().map(|(_, byte)| *byte).collect();
    register_run(&part).unwrap_or_else(|| {
        concat_bytes(
            bytes
                .iter()
                .map(|(address, byte)| source_slot_byte(*address, byte, value, walks))
                .collect(),
        )
    })
}

/// A run of consecutive bytes of one argument register or of one call result
/// lane (slice 8), as the one extract of it (the register or lane itself
/// when the run is all of it); `None` for any other run.
fn register_run(part: &[Option<SlotByte>]) -> Option<E> {
    let n = part.len() as u32;
    let (whole, first, width) = match part.first()? {
        Some(SlotByte::Entry { root, byte }) => (E::var(entry_name(*root), 64), *byte, 64),
        Some(SlotByte::Result {
            site,
            lane,
            byte,
            width,
        }) => (
            E::var(call_result_name(*site, *lane), *width),
            *byte,
            *width,
        ),
        _ => return None,
    };
    let consecutive = part.iter().enumerate().all(|(i, byte)| {
        let at = first + i as u32;
        match (byte, part[0]) {
            (
                Some(SlotByte::Entry { root, byte }),
                Some(SlotByte::Entry {
                    root: first_root, ..
                }),
            ) => *root == first_root && *byte == at,
            (
                Some(SlotByte::Result {
                    site, lane, byte, ..
                }),
                Some(SlotByte::Result {
                    site: first_site,
                    lane: first_lane,
                    ..
                }),
            ) => *site == first_site && *lane == first_lane && *byte == at,
            _ => false,
        }
    });
    if !consecutive {
        return None;
    }
    Some(if first == 0 && 8 * n == width {
        whole
    } else {
        whole.extract(8 * (first + n) - 1, 8 * first)
    })
}

/// One eightbyte of an aggregate passed or returned by value (slice 8), as
/// the bytes at its address, low byte first: the concatenation of its
/// maximal runs, each a run of consecutive bytes of one store (that store's
/// value at its memory width when the run is all of it, else the extract of
/// it), of one argument register or of one call result lane
/// ([`register_run`]), or a single byte ([`source_slot_byte`]).
fn source_eightbyte(
    bytes: &[(FrameAddr, Option<SlotByte>)],
    value: &dyn Fn(&Value) -> E,
    walks: &BodyWalks,
) -> E {
    // Whether `next` continues the run that `last` ends.
    let continues = |last: &Option<SlotByte>, next: &Option<SlotByte>| match (last, next) {
        (Some(SlotByte::Stored(a)), Some(SlotByte::Stored(b))) => {
            a.value == b.value && a.carrier == b.carrier && b.byte == a.byte + 1
        }
        (
            Some(SlotByte::Entry { root: a, byte: i }),
            Some(SlotByte::Entry { root: b, byte: j }),
        ) => a == b && *j == i + 1,
        (
            Some(SlotByte::Result {
                site: a,
                lane: k,
                byte: i,
                ..
            }),
            Some(SlotByte::Result {
                site: b,
                lane: l,
                byte: j,
                ..
            }),
        ) => a == b && k == l && *j == i + 1,
        _ => false,
    };
    let mut runs: Vec<&[(FrameAddr, Option<SlotByte>)]> = Vec::new();
    let mut start = 0;
    for end in 1..=bytes.len() {
        if end == bytes.len() || !continues(&bytes[end - 1].1, &bytes[end].1) {
            runs.push(&bytes[start..end]);
            start = end;
        }
    }
    let terms: Vec<E> = runs
        .into_iter()
        .map(|run| {
            let part: Vec<Option<SlotByte>> = run.iter().map(|(_, byte)| *byte).collect();
            if let Some(whole) = source_whole_store(&part, value) {
                return whole;
            }
            if let Some(register) = register_run(&part) {
                return register;
            }
            match (&part[0], part.len()) {
                (Some(SlotByte::Stored(first)), n) if n > 1 => first
                    .carrier
                    .memory_value(value(&first.value))
                    .extract(8 * (first.byte + n as u32) - 1, 8 * first.byte),
                _ => source_bytes(run, value, walks),
            }
        })
        .collect();
    concat_bytes(terms)
}

/// Bytes of an escaped slot each observed item covers (slice 7).
const SLOT_CHUNK_BYTES: usize = 8;

/// The canonical observation of one escaped slot's contents at a call
/// (slice 7), the same on both sides: the slot's bytes in chunks of
/// [`SLOT_CHUNK_BYTES`] from offset 0 (the last one shorter), each chunk one
/// item. A chunk that is exactly one store's bytes, in order, is that
/// store's value at its memory width (`whole`); any other chunk is the
/// concatenation of its bytes, low byte first ([`concat_bytes`]).
fn slot_chunks<B>(
    bytes: &[B],
    whole: impl Fn(&[B]) -> Option<E>,
    mut byte: impl FnMut(usize, &B) -> E,
) -> Vec<E> {
    let mut chunks = Vec::new();
    for (chunk, part) in bytes.chunks(SLOT_CHUNK_BYTES).enumerate() {
        chunks.push(match whole(part) {
            Some(value) => value,
            None => concat_bytes(
                part.iter()
                    .enumerate()
                    .map(|(i, b)| byte(chunk * SLOT_CHUNK_BYTES + i, b))
                    .collect(),
            ),
        });
    }
    chunks
}

/// The term a chunk of machine slot bytes is, when it is exactly one store's
/// bytes in order: the stored term (slice 7).
fn machine_whole_store(part: &[Option<MachineByte>]) -> Option<E> {
    let first = part.first()?.as_ref()?;
    (first.width as usize == 8 * part.len()
        && part.iter().enumerate().all(|(i, byte)| {
            byte.as_ref().is_some_and(|byte| {
                byte.term == first.term && byte.width == first.width && byte.byte == i as u32
            })
        }))
    .then(|| first.term.clone())
}

/// The machine's contents of every escaped slot, in [`slot_chunks`] items,
/// ascending by slot: what a call reads (slice 7), and (slice 15) an access
/// through an address that may derive from an escaped slot. A byte nothing
/// wrote is the slot's initial byte, shared with the source.
fn machine_slot_chunks(
    escaped: &std::collections::BTreeSet<u32>,
    stack: &[Vec<Option<MachineByte>>],
    frame_bytes: &mut Vec<FrameAddr>,
) -> Result<Vec<E>, String> {
    let mut slots: Vec<E> = Vec::new();
    for slot in escaped.iter() {
        let bytes = &stack[*slot as usize];
        // Slice 17: an unreadable byte observed makes no claim.
        if let Some(offset) = bytes
            .iter()
            .position(|byte| byte.as_ref().is_some_and(|byte| byte.dead))
        {
            return Err(format!(
                "observes private stack slot {slot} byte {offset}, which its cut point leaves \
                 unreadable"
            ));
        }
        slots.extend(slot_chunks(
            bytes,
            machine_whole_store,
            |offset, byte| match byte {
                Some(byte) => byte.expr(),
                None => {
                    let address = FrameAddr {
                        slot: *slot,
                        offset: offset as i64,
                    };
                    E::var(
                        frame_byte_name(register_frame_byte(frame_bytes, address)),
                        8,
                    )
                }
            },
        ));
    }
    Ok(slots)
}

/// The index of the initial frame byte at `address` in the shared numbering
/// of `f{k}`, registering it when no side read it before.
fn register_frame_byte(frame_bytes: &mut Vec<FrameAddr>, address: FrameAddr) -> usize {
    match frame_bytes.iter().position(|known| *known == address) {
        Some(k) => k,
        None => {
            frame_bytes.push(address);
            frame_bytes.len() - 1
        }
    }
}

/// The number of set bits of `value`, at its own width (slice 10): the sum of
/// its bits, each zero-extended to the count's own width (the bits of
/// `width` itself, which no count exceeds), added as a balanced tree, then
/// zero-extended to the width. It is the meaning of LIR `CtPop` (trust-ir
/// `count_ones`) and of the `popcnt` row (Intel SDM POPCNT), stated once; a
/// unit test compares it with `u64::count_ones`. The spelling is chosen by
/// host qualification: on the qualification host AY's strict certification
/// rejects its own proof of a 32- or 64-bit count spelled as a chain of
/// full-width adds, and certifies this one.
fn count_ones(value: E) -> E {
    let bits = value.bv_width();
    let count_bits = 32 - bits.leading_zeros();
    let mut terms: Vec<E> = (0..bits)
        .map(|i| value.clone().extract(i, i).zero_ext(count_bits - 1))
        .collect();
    while terms.len() > 1 {
        terms = terms
            .chunks(2)
            .map(|pair| match pair {
                [a, b] => a.clone().bvadd(b.clone()),
                [a] => a.clone(),
                _ => unreachable!("chunks of two"),
            })
            .collect();
    }
    let count = terms.pop().expect("a bitvector has at least one bit");
    if count_bits == bits {
        count
    } else {
        count.zero_ext(bits - count_bits)
    }
}

/// `value` shifted by `op` by `amount` modulo its width (a power of two),
/// spelled as a barrel shifter (slice 10): for each bit `i` of the width's
/// log, a stage that shifts by `2^i` (an extract and concatenation, or a sign
/// extension for an arithmetic shift) when bit `i` of `amount` is set. It is
/// the meaning both sides give a shift by a variable amount: the source's
/// [`SourceOp::VariableShift`] (trust-ir's shift in range, the stated
/// refinement beyond) and a `shl`/`shr`/`sar r, cl` row (Intel SDM: the
/// count is CL masked to 5 or 6 bits), stated once; a unit test compares it
/// with concrete shifts. The spelling is chosen by host qualification: on
/// the qualification host AY prints its proof of a `bvshl`/`bvlshr`/`bvashr`
/// by a variable amount with an unproved step, and certifies this one.
fn shift_modulo_width(op: ShiftOp, value: E, amount: E) -> E {
    let bits = value.bv_width();
    let stages = bits.trailing_zeros();
    debug_assert!(bits.is_power_of_two() && amount.bv_width() >= stages);
    (0..stages).fold(value, |term, i| {
        let by = 1u32 << i;
        let shifted = match op {
            ShiftOp::Shl => term
                .clone()
                .extract(bits - 1 - by, 0)
                .concat(E::bv_const(0, by)),
            ShiftOp::Lshr => E::bv_const(0, by).concat(term.clone().extract(bits - 1, by)),
            ShiftOp::Ashr => term.clone().extract(bits - 1, by).sign_ext(by),
        };
        E::ite(
            amount.clone().extract(i, i).eq_expr(E::bv_const(1, 1)),
            shifted,
            term,
        )
    })
}

/// The sign of `value` in every bit of its width: `cqo`'s RDX of RAX and
/// `cdq`'s EDX of EAX (slice 14).
fn sign_of(value: E) -> E {
    let bits = value.bv_width();
    value.extract(bits - 1, bits - 1).sign_ext(bits - 1)
}

/// Slice 22 (ruling OD-202): the runtime routine an `I128` LIR `Udiv`,
/// `Sdiv`, `Urem` or `Srem` is a call of: compiler-rt's (and Rust's
/// `compiler_builtins`') `__udivti3`, `__divti3`, `__umodti3` and `__modti3`,
/// which the x86-64 selector calls by symbol (`select_i128_div_libcall`). The
/// theorem checks the call row's symbol against this name, so a selector that
/// called another routine for an opcode is a named mismatch, never a credit.
fn i128_division_routine(opcode: &L) -> &'static str {
    match opcode {
        L::Udiv => "__udivti3",
        L::Sdiv => "__divti3",
        L::Urem => "__umodti3",
        L::Srem => "__modti3",
        other => unreachable!("{other:?} is no division"),
    }
}

/// Slice 13: the C runtime routine an LIR `Memcpy`, `Memmove` or `Memset` is
/// a call of (the selector calls it by symbol,
/// `select_memory_intrinsic_call`), whose effect the theorem trusts to be the
/// intrinsic's (ruling OD-217 refuses one the module or its link unit
/// defines, [`check_trusted_routines`]).
fn memory_routine(opcode: &L) -> &'static str {
    match opcode {
        L::Memcpy => "memcpy",
        L::Memmove => "memmove",
        L::Memset => "memset",
        other => unreachable!("{other:?} is no C memory routine"),
    }
}

/// OD-210, OD-217: the runtime routine whose contract a body theorem trusts
/// when it states `opcode` as a call: an `I128` division's (OD-202, read over
/// the LIR alone, so every division opcode counts) or a C memory routine's
/// (slice 13); `None` for every other opcode.
fn trusted_routine_of(opcode: &L) -> Option<&'static str> {
    match opcode {
        L::Udiv | L::Sdiv | L::Urem | L::Srem => Some(i128_division_routine(opcode)),
        L::Memcpy | L::Memmove | L::Memset => Some(memory_routine(opcode)),
        _ => None,
    }
}

/// OD-210, OD-217: every runtime routine whose contract a body theorem may
/// trust (OD-202's `I128` division routines, [`i128_division_routine`], and
/// slice 13's C memory routines, [`memory_routine`]), ascending by name.
const TRUSTED_ROUTINES: [&str; 7] = [
    "__divti3",
    "__modti3",
    "__udivti3",
    "__umodti3",
    "memcpy",
    "memmove",
    "memset",
];

/// The symbols the module under proof defines, as far as the x86-64 body
/// theorem reads them (rulings OD-210, OD-216 and OD-217): which runtime routines
/// whose contract a theorem trusts (OD-202's `I128` division routines,
/// [`i128_division_routine`]; slice 13's C memory routines,
/// [`memory_routine`]) the module defines itself, and which another compile
/// unit of its link unit defines, as the frontend states (for the rustc
/// bridge, another codegen unit of the crate, or another function module of
/// the same one).
///
/// OD-202 trusts the routine the link binds to `__udivti3`, `__divti3`,
/// `__umodti3` or `__modti3`, and slice 13 that `memcpy`, `memmove` and
/// `memset` are the C runtime's. A definition of one in the module under proof
/// or in another unit of the same link unit (crate) is what the module's own
/// call binds to (the object's definition, ahead of the sysroot's weak one or
/// the C library's), and nothing checks it against the contract: such a
/// routine may return anything, copy nothing, or call itself. So a body whose
/// call of such a routine the module or its link unit defines gets no theorem
/// ([`X86BodyUnsupported::TrustedRoutine`]), and neither does the routine's
/// own definition when it calls itself so. A definition elsewhere in the link
/// (another crate, the sysroot's `compiler_builtins`, the platform's
/// compiler-rt or C library, or, in the JIT, the host's symbol map) still
/// binds and stays trusted.
///
/// It is verifier input: [`Self::input_line`] binds it into the x86-64
/// verifier-input digest of every function it can change the verdict of.
#[derive(Debug, Clone, Default, PartialEq, Eq, Hash)]
pub struct X86ModuleDefinitions {
    routines: std::collections::BTreeSet<&'static str>,
    /// OD-216: the routines another compile unit of the module's link unit
    /// defines (and this module does not), as the frontend states
    /// ([`Self::with_link_unit`]).
    link_unit: std::collections::BTreeSet<&'static str>,
}

impl X86ModuleDefinitions {
    /// The trusted runtime routine named exactly `symbol` (a link-time
    /// name), if any: what a frontend reads to name the routines its link
    /// unit defines ([`Self::with_link_unit`]) without naming every other
    /// definition.
    pub fn trusted_routine(symbol: &str) -> Option<&'static str> {
        TRUSTED_ROUTINES
            .iter()
            .copied()
            .find(|routine| *routine == symbol)
    }

    /// Every trusted runtime routine, ascending by name: what a frontend
    /// names when it cannot tell which its link unit defines (OD-216, a
    /// `global_asm!` block).
    pub fn trusted_routines() -> impl Iterator<Item = &'static str> {
        TRUSTED_ROUTINES.iter().copied()
    }

    /// The definitions of a module that defines exactly `symbols` (link-time
    /// names). Only the trusted routines among them are kept.
    pub fn of_symbols<'s>(symbols: impl IntoIterator<Item = &'s str>) -> Self {
        let routines = symbols
            .into_iter()
            .filter_map(Self::trusted_routine)
            .collect();
        Self {
            routines,
            link_unit: std::collections::BTreeSet::new(),
        }
    }

    /// OD-216: these definitions, in a link unit whose other compile units
    /// define `symbols` too (link-time names, as the frontend states them;
    /// only the trusted routines among them are kept, and one this module
    /// defines itself stays this module's). The rustc bridge names every
    /// trusted routine any codegen unit of the crate defines, so the module
    /// it compiles (a codegen unit, or one function of one) never trusts a
    /// routine its own crate binds.
    pub fn with_link_unit<'s>(mut self, symbols: impl IntoIterator<Item = &'s str>) -> Self {
        for routine in symbols.into_iter().filter_map(Self::trusted_routine) {
            if !self.routines.contains(routine) {
                self.link_unit.insert(routine);
            }
        }
        self
    }

    /// The definitions of a trust-ir module: every function with a body,
    /// whatever its linkage (an `available_externally` body included), and
    /// every global, defined or declared, each by its link-time symbol (its
    /// `name`). Counting a declaration or an inline-only body only refuses
    /// more. (A module with `global_asm!` never reaches a body theorem: the
    /// adapter refuses it.)
    pub fn of_trust_ir_module(module: &trust_ir::Module) -> Self {
        Self::of_symbols(
            module
                .functions
                .iter()
                .filter(|function| function.has_body())
                .map(|function| function.name.as_str())
                .chain(module.globals.iter().map(|global| global.name.as_str())),
        )
    }

    /// Whether the module, or (OD-216) another compile unit of its link unit,
    /// defines `routine`.
    pub fn defines(&self, routine: &str) -> bool {
        self.routines.contains(routine) || self.link_unit.contains(routine)
    }

    /// Why a call of `routine` binds to a definition of the link unit under
    /// proof: the module's own ([`X86RoutineDefinition::TheModule`]), another
    /// compile unit's ([`X86RoutineDefinition::TheLinkUnit`]), or none.
    fn definition_of(&self, routine: &str) -> Option<X86RoutineDefinition> {
        if self.routines.contains(routine) {
            Some(X86RoutineDefinition::TheModule)
        } else if self.link_unit.contains(routine) {
            Some(X86RoutineDefinition::TheLinkUnit)
        } else {
            None
        }
    }

    /// The line the x86-64 verifier-input digests bind for `lir` under
    /// `module` (`None`: a caller that names no module), or `None` when the
    /// module cannot change its verdict. Over the LIR alone, so it reads every
    /// division opcode as one that may be an `I128` division, and every
    /// `Memcpy`, `Memmove` and `Memset` as its C routine's call: the routines
    /// they would call that `module` defines (and, OD-216, that another unit
    /// of its link unit defines) are named, or, for no module, all of them; a
    /// function with no such call, or none such defined, keeps the digest it
    /// had before (the line of a module that defines one itself is OD-210's,
    /// unchanged).
    pub fn input_line(module: Option<&Self>, lir: &Function) -> Option<String> {
        let called: std::collections::BTreeSet<&'static str> = lir
            .blocks
            .values()
            .flat_map(|block| &block.instructions)
            .filter_map(|inst| trusted_routine_of(&inst.opcode))
            .collect();
        match module {
            None if !called.is_empty() => Some(format!(
                "x86_module_definitions=unnamed routines={:?}",
                called
            )),
            None => None,
            Some(module) => {
                let defined: Vec<&str> = called
                    .iter()
                    .copied()
                    .filter(|routine| module.routines.contains(routine))
                    .collect();
                let linked: Vec<&str> = called
                    .iter()
                    .copied()
                    .filter(|routine| module.link_unit.contains(routine))
                    .collect();
                match (defined.is_empty(), linked.is_empty()) {
                    (true, true) => None,
                    (false, true) => Some(format!(
                        "x86_module_definitions=defines routines={defined:?}"
                    )),
                    _ => Some(format!(
                        "x86_module_definitions=defines routines={defined:?} \
                         link_unit routines={linked:?}"
                    )),
                }
            }
        }
    }
}

/// OD-210, OD-216, OD-217: refuse a theorem that trusts a runtime routine's contract
/// (OD-202's `I128` division routines, slice 13's C memory routines) where
/// nothing outside the link unit under proof binds the routine: the function
/// under proof IS the routine (it would call itself), the module defines it,
/// another compile unit of its link unit defines it (as the frontend states),
/// or the caller named no module (its definitions are unknown). Never a
/// mismatch: the lowering may be right; no claim is made.
fn check_trusted_routines(
    owner: &SourceBoundX86Body<'_>,
    module: Option<&X86ModuleDefinitions>,
) -> Result<(), X86BodyRefusal> {
    for routine in owner.trusted_routines() {
        let definition = if owner.source().name == routine {
            X86RoutineDefinition::TheFunction
        } else {
            match module {
                None => X86RoutineDefinition::Unnamed,
                Some(module) => match module.definition_of(routine) {
                    Some(definition) => definition,
                    None => continue,
                },
            }
        };
        return Err(unsupported(X86BodyUnsupported::TrustedRoutine {
            routine: routine.to_owned(),
            definition,
        }));
    }
    Ok(())
}

/// LIR `Udiv`, `Urem`, `Sdiv` or `Srem` of two operands of one width (slice
/// 14), trust-ir's `eval_int_binop` wherever it is defined (the divisor not
/// zero and, signed, not the minimum by -1): `lhs / rhs` and `lhs % rhs` of
/// the unsigned values, or of the signed values truncating toward zero (Rust
/// `i128` `/` and `%`, the remainder with the dividend's sign), at the width.
/// SMT-LIB's `bvudiv`, `bvurem`, `bvsdiv` and `bvsrem` are exactly these on
/// that domain; outside it they are total and the value is never observed
/// (the run stops, [`StopKind::Undefined`]). A signed one is spelled with its
/// divisor's two unit cases first, exact for every dividend (SMT-LIB's
/// `bvsdiv` by 1 is the dividend and by -1 its `bvneg`, `bvsrem` by either
/// is 0; `the_division_meanings_are_trust_irs` checks the spelling against
/// the pinned interpreter): the selector's `idiv` divides by 1 where the
/// source divides by -1 (its overflow fixup), and a solver then compares
/// `bvneg` terms instead of two division circuits. The machine's quotient
/// and remainder of a canonical dividend are spelled the same way
/// ([`machine_division`]), and [`pair_divisions`] restates them as the
/// source's where their operands are equal.
fn division(signed: bool, remainder: bool, lhs: E, rhs: E) -> E {
    match (signed, remainder) {
        (false, false) => lhs.bvudiv(rhs),
        (false, true) => lhs.bvurem(rhs),
        (true, _) => {
            let bits = lhs.bv_width();
            let one = rhs.clone().eq_expr(E::bv_const(1, bits));
            // -1 at the width (the double-width dividend's division is 128
            // bits wide, past a 64-bit constant).
            let all_ones = if bits <= 64 {
                E::bv_const(crate::smt::mask(u64::MAX, bits), bits)
            } else {
                E::bv_const(0, bits).bvsub(E::bv_const(1, bits))
            };
            let minus_one = rhs.clone().eq_expr(all_ones);
            if remainder {
                E::ite(
                    one.or_expr(minus_one),
                    E::bv_const(0, bits),
                    signed_remainder(lhs, rhs),
                )
            } else {
                E::ite(
                    one,
                    lhs.clone(),
                    E::ite(minus_one, lhs.clone().bvneg(), lhs.bvsdiv(rhs)),
                )
            }
        }
    }
}

/// An unsigned quotient or remainder by the constant power of two `k`
/// (slice 14): `lhs >> log2(k)` and `lhs & (k - 1)`, exactly `bvudiv` and
/// `bvurem` by `k` for every `lhs` (`the_division_meanings_are_trust_irs`
/// checks it against [`division`]). The selector divides by a constant
/// with the magic-number `mul`, which by a power of two the walk spells as
/// the shifts it is ([`power_of_two_product`]); a solver then compares
/// shifts, never a division circuit with a 128-bit product.
fn power_of_two_division(remainder: bool, lhs: E, k: u64) -> E {
    let bits = lhs.bv_width();
    if remainder {
        lhs.bvand(E::bv_const(k - 1, bits))
    } else if k == 1 {
        lhs
    } else {
        lhs.bvlshr(E::bv_const(u64::from(k.trailing_zeros()), bits))
    }
}

/// The low and high halves of the unsigned product of `value` and the
/// constant power of two `multiplier` at `value`'s width (slice 14): `value
/// << j` and `value >> (width - j)` for `multiplier = 2^j` (0 and `value`
/// for `j = 0`), exactly Intel's `mul` of those operands
/// (`encode_mul_high` and the wrapped product; a unit test sweeps both).
fn power_of_two_product(value: E, multiplier: u64) -> (E, E) {
    let bits = value.bv_width();
    let j = u64::from(multiplier.trailing_zeros());
    if j == 0 {
        (value, E::bv_const(0, bits))
    } else {
        (
            value.clone().bvshl(E::bv_const(j, bits)),
            value.bvlshr(E::bv_const(u64::from(bits) - j, bits)),
        )
    }
}

/// SMT-LIB's `bvsrem` (slice 14), which `SmtExpr` has no node for, spelled
/// as the standard defines it, through `bvurem` of the magnitudes: the
/// unsigned remainder of `|lhs|` by `|rhs|` (each the two's complement
/// negation when its sign bit is set, so the minimum is 2^(w-1)), negated
/// when `lhs` is negative. Total: by zero it is `lhs`, as `bvsrem` is.
fn signed_remainder(lhs: E, rhs: E) -> E {
    let bits = lhs.bv_width();
    let negative = |value: &E| {
        value
            .clone()
            .extract(bits - 1, bits - 1)
            .eq_expr(E::bv_const(1, 1))
    };
    let magnitude = |value: E| E::ite(negative(&value), value.clone().bvneg(), value);
    let unsigned = magnitude(lhs.clone()).bvurem(magnitude(rhs));
    E::ite(negative(&lhs), unsigned.clone().bvneg(), unsigned)
}

/// Where trust-ir makes LIR `Udiv`/`Urem` (`signed` false) or `Sdiv`/`Srem`
/// of `lhs` by `rhs` undefined (slice 14; `interpret::eval_int_binop`): a zero
/// divisor, and signed, the minimum divided by -1 (`signed_div_overflows`).
fn division_undefined(signed: bool, lhs: E, rhs: E) -> E {
    let bits = lhs.bv_width();
    let zero = rhs.clone().eq_expr(E::bv_const(0, bits));
    if !signed {
        return zero;
    }
    let minimum = E::bv_const(1u64 << (bits - 1), bits);
    let minus_one = E::bv_const(crate::smt::mask(u64::MAX, bits), bits);
    zero.or_expr(lhs.eq_expr(minimum).and_expr(rhs.eq_expr(minus_one)))
}

/// x86 `div src` (`signed` false) or `idiv src` at the width of `divisor`
/// (32 or 64 bits; slice 14), Intel SDM DIV/IDIV: the dividend is
/// `high:low` (EDX:EAX or RDX:RAX), of twice the width; the quotient
/// (truncating toward zero) and the remainder (the dividend's sign) of the
/// unsigned or signed values; #DE (the returned `fault`) when the divisor is
/// zero or the quotient does not fit the width (signed: `[-2^(w-1),
/// 2^(w-1))`). Exact for every `high`. When `high_definition`, what the name
/// in `high` was defined as, is the zero `xor` (unsigned) or the sign of
/// `low` from `cqo`/`cdq` (signed), the dividend is `low` extended, and the
/// same values are stated at the width, as [`division`] states the source's
/// (for a nonzero divisor the double-width quotient of an extended dividend
/// then fits, but for the signed minimum by -1, so it is the narrow one
/// extended); any other `high` is stated at double width. The last value
/// says which: `true` for the narrow, canonical form.
fn machine_division(
    signed: bool,
    low: E,
    high: E,
    high_definition: Option<&E>,
    divisor: E,
) -> (E, E, E, bool) {
    let bits = low.bv_width();
    let zero_divisor = divisor.clone().eq_expr(E::bv_const(0, bits));
    let canonical = high_definition.is_some_and(|definition| {
        if signed {
            *definition == widen(sign_of(low.clone()), bits)
        } else {
            *definition == E::bv_const(0, 64)
        }
    });
    if canonical {
        let fault = if signed {
            division_undefined(true, low.clone(), divisor.clone())
        } else {
            zero_divisor
        };
        return (
            division(signed, false, low.clone(), divisor.clone()),
            division(signed, true, low, divisor),
            fault,
            true,
        );
    }
    let dividend = high.clone().concat(low);
    let wide_divisor = if signed {
        divisor.clone().sign_ext(bits)
    } else {
        divisor.clone().zero_ext(bits)
    };
    let quotient = division(signed, false, dividend.clone(), wide_divisor.clone());
    // The remainder as `dividend - quotient * divisor` at double width, which
    // is `bvurem`/`bvsrem` for every divisor (by zero too: SMT-LIB's quotient
    // times zero is zero, and the remainder by zero is the dividend), and
    // which the library gate's native evaluator computes at 128 bits (its
    // `bvurem` stops at 64).
    let remainder = dividend.bvsub(quotient.clone().bvmul(wide_divisor));
    let narrow_quotient = quotient.clone().extract(bits - 1, 0);
    let overflow = if signed {
        narrow_quotient
            .clone()
            .sign_ext(bits)
            .eq_expr(quotient)
            .not_expr()
    } else {
        // `high:low / divisor` fits `bits` exactly when `high < divisor`.
        high.bvuge(divisor)
    };
    (
        narrow_quotient,
        remainder.extract(bits - 1, 0),
        zero_divisor.or_expr(overflow),
        false,
    )
}

/// Name a source value: `define(expr)` states one fresh name for a value of
/// at most 64 bits; a 128-bit value (slice 11: an `I128`) is stated as its
/// two 64-bit halves, low half first, and is their concatenation. Every name
/// the theorem defines is therefore at most 64 bits wide; only intermediate
/// terms are wider. (The one canonical spelling for every function; the
/// sampler that checks the library gate evaluates names as 64-bit words.)
fn name_source_value(expr: E, mut define: impl FnMut(E) -> E) -> E {
    match expr.bv_width() {
        128 => {
            let low = define(expr.clone().extract(63, 0));
            let high = define(expr.extract(127, 64));
            high.concat(low)
        }
        _ => define(expr),
    }
}

/// Whether `expr` is only another name: a declared name, or (slice 11) the
/// 128-bit concatenation of two, an `I128` named by its halves. (A narrower
/// concatenation of names, such as a load of two stores' bytes, is a value
/// of its own, named as before.)
fn is_name(expr: &E) -> bool {
    match expr {
        E::Var { .. } => true,
        E::Concat { hi, lo, width: 128 } => {
            matches!(hi.as_ref(), E::Var { .. }) && matches!(lo.as_ref(), E::Var { .. })
        }
        _ => false,
    }
}

/// `expr` (of `from` bits) at `to` bits: its low bits, or zero-extended.
/// Whether every bit of `expr` at or above bit `bits` is 0 for every value of
/// its free inputs, judged from its shape alone (slice 12): bit by bit
/// ([`zero_bits`]), or because its unsigned value is below `2^bits`
/// ([`upper_bound`]; the selector computes a `bool` read from a byte as
/// `(byte + 255) >> 8`), through the machine names `defs` defines (each name
/// stands for its defining term, a definition the theorem states).
fn zero_above(expr: &E, bits: u32, defs: &HashMap<&str, &E>) -> bool {
    match expr.try_bv_width() {
        Ok(width) if width <= bits => true,
        Ok(width) => {
            zero_bits(expr, bits, width - 1, defs, 0)
                || (bits < 128 && upper_bound(expr, defs, 0) < 1u128 << bits)
        }
        Err(_) => false,
    }
}

/// An upper bound on the unsigned value of bit-vector term `expr` for every
/// value of its free inputs, from its shape alone (slice 12): a constant's
/// value; a zero extension's operand's; an extraction's operand's, shifted
/// down to its low bit; a concatenation's parts; an addition or
/// multiplication that cannot wrap at its width; a logical shift right by a
/// constant; an `and`'s smaller operand; an `or`'s or `xor`'s operands' bit
/// length; an `ite`'s larger arm; a defined name's term (at most 64 names
/// deep). Anything else is bounded only by its width.
fn upper_bound(expr: &E, defs: &HashMap<&str, &E>, depth: u32) -> u128 {
    let Ok(width) = expr.try_bv_width() else {
        return u128::MAX;
    };
    let full = if width >= 128 {
        u128::MAX
    } else {
        (1u128 << width) - 1
    };
    let bound = |expr: &E| upper_bound(expr, defs, depth);
    let found = match expr {
        E::BvConst { value, .. } => u128::from(*value),
        E::Var { name, .. } => match defs.get(name.as_str()) {
            Some(term) if depth < 64 => upper_bound(term, defs, depth + 1),
            _ => full,
        },
        E::ZeroExtend { operand, .. } => bound(operand),
        E::Extract { low, operand, .. } => {
            if *low >= 128 {
                0
            } else {
                bound(operand) >> low
            }
        }
        E::Concat { hi, lo, .. } => {
            let low_width = lo.bv_width();
            let high = bound(hi);
            if high == 0 {
                bound(lo)
            } else if low_width >= 128 || high > u128::MAX >> low_width {
                full
            } else {
                (high << low_width) | ((1u128 << low_width) - 1)
            }
        }
        E::BvAdd { lhs, rhs, .. } => bound(lhs).saturating_add(bound(rhs)),
        E::BvMul { lhs, rhs, .. } => bound(lhs).saturating_mul(bound(rhs)),
        E::BvLshr { lhs, rhs, .. } => match rhs.as_ref() {
            E::BvConst { value, .. } if *value < 128 => bound(lhs) >> value,
            _ => bound(lhs),
        },
        E::BvAnd { lhs, rhs, .. } => bound(lhs).min(bound(rhs)),
        E::BvOr { lhs, rhs, .. } | E::BvXor { lhs, rhs, .. } => {
            let larger = bound(lhs).max(bound(rhs));
            if larger == 0 {
                0
            } else {
                u128::MAX >> larger.leading_zeros()
            }
        }
        E::Ite {
            then_expr,
            else_expr,
            ..
        } => bound(then_expr).max(bound(else_expr)),
        _ => full,
    };
    // An addition or multiplication past the width wraps: only the width
    // bounds it then.
    if found > full { full } else { found }
}

/// Whether bits `lo..=hi` of `expr` are 0 for every value of its free
/// inputs, judged from its shape alone: a constant's bits, a zero
/// extension's new bits, the parts of a concatenation or extraction, both
/// arms of an `ite`, either operand of an `and`, both of an `or` or `xor`,
/// and a defined name's term (at most 64 names deep). Anything else is not
/// known (which only keeps a loop header's free input for the bits above a
/// parameter).
fn zero_bits(expr: &E, lo: u32, hi: u32, defs: &HashMap<&str, &E>, depth: u32) -> bool {
    if lo > hi {
        return true;
    }
    let zero = |expr: &E, lo: u32, hi: u32| zero_bits(expr, lo, hi, defs, depth);
    match expr {
        E::BvConst { value, .. } => {
            let span = hi - lo + 1;
            let shifted = if lo >= 64 { 0 } else { *value >> lo };
            span >= 64 || shifted & ((1u64 << span) - 1) == 0
        }
        E::Var { name, .. } => {
            depth < 64
                && defs
                    .get(name.as_str())
                    .is_some_and(|term| zero_bits(term, lo, hi, defs, depth + 1))
        }
        E::ZeroExtend { operand, .. } => {
            let width = operand.bv_width();
            lo >= width || zero(operand, lo, hi.min(width - 1))
        }
        E::Concat {
            hi: high, lo: low, ..
        } => {
            let width = low.bv_width();
            (lo >= width || zero(low, lo, hi.min(width - 1)))
                && (hi < width || zero(high, lo.max(width) - width, hi - width))
        }
        E::Extract { low, operand, .. } => zero(operand, low + lo, low + hi),
        E::Ite {
            then_expr,
            else_expr,
            ..
        } => zero(then_expr, lo, hi) && zero(else_expr, lo, hi),
        E::BvAnd { lhs, rhs, .. } => zero(lhs, lo, hi) || zero(rhs, lo, hi),
        E::BvOr { lhs, rhs, .. } | E::BvXor { lhs, rhs, .. } => {
            zero(lhs, lo, hi) && zero(rhs, lo, hi)
        }
        _ => false,
    }
}

fn fit(expr: E, from: u32, to: u32) -> E {
    match from.cmp(&to) {
        std::cmp::Ordering::Greater => expr.extract(to - 1, 0),
        std::cmp::Ordering::Less => expr.zero_ext(to - from),
        std::cmp::Ordering::Equal => expr,
    }
}

/// The cut-point relation of loop header `header` on one edge into it
/// (slice 12), as `(source, machine)` pairs, under each caller convention
/// walked (`exits`: the machine state at the end of the edge's walk, psABI
/// then clean-bool): each parameter's value on the edge (`edge.values`, in
/// the source's terms at the end of the edge's block, `values`) against the
/// low bits of its register ([`ParamRoot::relation`]), then each header byte's
/// source byte against the machine's byte at the same frame address. The
/// theorem states every pair on the edge, under the edge's guard; at the
/// start of the header's region it assumes exactly these equalities, with
/// one free input for each pair ([`LoopHeader`], [`machine_header_start`]).
fn cut_edge_relation(
    header: &LoopHeader,
    roots: &[ParamRoot],
    edge: &CutEdge,
    exits: &(MachineState, Option<MachineState>),
    values: &HashMap<Value, E>,
    walks: &BodyWalks,
) -> Vec<(E, E)> {
    let mut pairs = Vec::new();
    let walked = std::iter::once((&exits.0, BoolArguments::PsAbi))
        .chain(exits.1.as_ref().map(|exit| (exit, BoolArguments::Clean32)));
    for (exit, convention) in walked {
        for (root, value) in roots.iter().zip(&edge.values) {
            let Some(RegValue::Bits(register)) = exit.regs.get(&root.root) else {
                unreachable!("the walk checks every parameter's register holds bits on its edges");
            };
            // Slice 20 (OD-193): an `I128`'s high register too.
            let high = root.high.map(|high| match exit.regs.get(&high) {
                Some(RegValue::Bits(register)) => register.expr.clone(),
                _ => unreachable!("the walk checks every parameter's registers hold bits"),
            });
            pairs.extend(root.relations(
                values[value].clone(),
                register.expr.clone(),
                high,
                convention,
            ));
        }
        for &(slot, offset) in header.bytes.keys() {
            let address = FrameAddr { slot, offset };
            let source = source_slot_byte(
                address,
                &edge.state.slot_bytes[slot as usize][offset as usize],
                &|v: &Value| values[v].clone(),
                walks,
            );
            let machine = match &exit.stack[slot as usize][offset as usize] {
                Some(byte) => byte.expr(),
                None => E::var(frame_byte_name(walks.frame_byte(address)), 8),
            };
            pairs.push((source, machine));
        }
    }
    pairs
}

// ---------------------------------------------------------------------------
// Slice 23 (ruling OD-205): arithmetic congruence pairing
// ---------------------------------------------------------------------------

/// Slice 23 (ruling OD-205): the operation of an operator key ([`ArithKey`]).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub(crate) enum ArithOp {
    /// `(bvmul a b)` at the width: a product's low half, the same for
    /// signed and unsigned operands (LIR `Imul`; `imul r, r`; `mul`'s RAX).
    MulLo,
    /// `(bvmul (zext_n a) (zext_n b))` at twice the operands' width `n`: the
    /// unsigned widening product (the overflow result of `CheckedUmul`;
    /// `mul`'s RDX:RAX).
    UMulWide,
    /// `(bvmul (sext_n a) (sext_n b))`: the signed widening product (the
    /// overflow result of `CheckedSmul`; no row of the walk computes it as a
    /// value).
    SMulWide,
    /// [`division`] of the unsigned values: the quotient.
    Udiv,
    /// The unsigned remainder.
    Urem,
    /// [`division`] of the signed values: the quotient.
    Sdiv,
    /// The signed remainder.
    Srem,
    /// [`shift_modulo_width`] left.
    Shl,
    /// [`shift_modulo_width`] right, logical.
    Lshr,
    /// [`shift_modulo_width`] right, arithmetic.
    Ashr,
}

/// Slice 23 (ruling OD-205): an operator key: the operation (its signedness
/// included) and the width `bits` of its operands. Two terms of one key over
/// equal operands are one SMT-LIB function of them ([`Self::apply`]); a key
/// never equates two operations that differ on some input, because the width
/// and the signedness are part of it (only [`ArithOp::MulLo`] has no
/// signedness: a product's low half is the same for both extensions). The
/// slice-23 design swept both facts exhaustively at 1 to 8 bits;
/// `the_operator_keys_are_distinct_functions` does at small widths.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub(crate) struct ArithKey {
    op: ArithOp,
    bits: u32,
}

impl ArithKey {
    pub(crate) const fn new(op: ArithOp, bits: u32) -> Self {
        Self { op, bits }
    }

    fn shift(op: ShiftOp, bits: u32) -> Self {
        let op = match op {
            ShiftOp::Shl => ArithOp::Shl,
            ShiftOp::Lshr => ArithOp::Lshr,
            ShiftOp::Ashr => ArithOp::Ashr,
        };
        Self::new(op, bits)
    }

    /// The key's term of `a` and `b`, spelled exactly as BOTH sides spell the
    /// operation: the source's LIR meaning (`BinaryOp::Mul`, the exact
    /// product [`CheckedOp::overflows`] tests, [`division`],
    /// [`shift_modulo_width`]) and the walk's Intel transcription of the row
    /// (`encode_imul_rr`, `encode_mul_full`, [`machine_division`]'s canonical
    /// form, the `shl`/`shr`/`sar r, cl` barrel). A shift's `b` is its
    /// amount, of any width of at least log2(`bits`) bits.
    pub(crate) fn apply(self, a: E, b: E) -> E {
        let bits = self.bits;
        match self.op {
            ArithOp::MulLo => a.bvmul(b),
            ArithOp::UMulWide => a.zero_ext(bits).bvmul(b.zero_ext(bits)),
            ArithOp::SMulWide => a.sign_ext(bits).bvmul(b.sign_ext(bits)),
            ArithOp::Udiv => division(false, false, a, b),
            ArithOp::Urem => division(false, true, a, b),
            ArithOp::Sdiv => division(true, false, a, b),
            ArithOp::Srem => division(true, true, a, b),
            ArithOp::Shl => shift_modulo_width(ShiftOp::Shl, a, b),
            ArithOp::Lshr => shift_modulo_width(ShiftOp::Lshr, a, b),
            ArithOp::Ashr => shift_modulo_width(ShiftOp::Ashr, a, b),
        }
    }

    fn commutative(self) -> bool {
        matches!(
            self.op,
            ArithOp::MulLo | ArithOp::UMulWide | ArithOp::SMulWide
        )
    }

    fn is_shift(self) -> bool {
        matches!(self.op, ArithOp::Shl | ArithOp::Lshr | ArithOp::Ashr)
    }

    /// The bits of operand `k` the operation reads: a shift's amount (`k =
    /// 1`) at its low log2(`bits`) bits (5 at 32 bits, 6 at 64: the only
    /// shift widths a key admits), the bits the barrel's stages test and the
    /// bits x86 reads of CL at those widths (OD-57's refinement beyond the
    /// width is the shared barrel); every other operand whole.
    fn read_operand(self, k: usize, operand: E) -> E {
        if k == 1 && self.is_shift() {
            operand.extract(self.bits.trailing_zeros() - 1, 0)
        } else {
            operand
        }
    }

    /// Whether `a` and `b` have the widths the key's term reads: both `bits`
    /// wide, but a shift's amount, which has at least log2(`bits`) bits. A
    /// shift key is a 32- or 64-bit one only: there x86 masks CL to log2 of
    /// the width, which is what the barrel reads; an 8- or 16-bit variable
    /// shift masks its count to 5 bits (modulo 32), so no key states it.
    pub(crate) fn admits(self, a: &E, b: &E) -> bool {
        let (Ok(a), Ok(b)) = (a.try_bv_width(), b.try_bv_width()) else {
            return false;
        };
        if self.is_shift() {
            matches!(self.bits, 32 | 64) && a == self.bits && b >= self.bits.trailing_zeros()
        } else {
            a == self.bits && b == self.bits
        }
    }
}

/// Slice 23 (OD-205): whether a machine row's key is a source operation's:
/// the same operation (its signedness included) at the same width.
fn same_key(machine: ArithKey, source: ArithKey) -> bool {
    machine == source
}

/// Slice 23 (OD-205): the operator key and operands of a source definition
/// that is an arithmetic operation: LIR `Imul` (a product's low half), the
/// widening product the overflow result of `CheckedUmul`/`CheckedSmul` tests,
/// a division by a value that is no constant of the chain, and a shift by a
/// variable amount. `None` for any other definition.
fn source_arith(
    definition: &SourceDefinition,
    value: &dyn Fn(&Value) -> Option<E>,
) -> Option<(ArithKey, E, E)> {
    let bits = definition.ty.bits();
    let (key, a, b) = match &definition.op {
        SourceOp::Binary(BinaryOp::Mul, a, b) => {
            (ArithKey::new(ArithOp::MulLo, bits), value(a)?, value(b)?)
        }
        SourceOp::Overflow {
            op: op @ (CheckedOp::Umul | CheckedOp::Smul),
            lhs,
            rhs,
        } => {
            let (a, b) = (value(lhs)?, value(rhs)?);
            let op = if *op == CheckedOp::Umul {
                ArithOp::UMulWide
            } else {
                ArithOp::SMulWide
            };
            (ArithKey::new(op, a.try_bv_width().ok()?), a, b)
        }
        SourceOp::Divide {
            signed,
            remainder,
            lhs,
            rhs,
            constant: None,
        } => {
            let op = match (signed, remainder) {
                (false, false) => ArithOp::Udiv,
                (false, true) => ArithOp::Urem,
                (true, false) => ArithOp::Sdiv,
                (true, true) => ArithOp::Srem,
            };
            (ArithKey::new(op, bits), value(lhs)?, value(rhs)?)
        }
        SourceOp::VariableShift(op, v, amount) => {
            (ArithKey::shift(*op, bits), value(v)?, value(amount)?)
        }
        _ => return None,
    };
    key.admits(&a, &b).then_some((key, a, b))
}

/// Whether `expr` reads no free input: each name it reads is defined (in
/// `defined`) by such a term. A constant, and a name the theorem defines as
/// one, is a constant BY VALUE, which slice 23 never pairs.
fn closed_term(expr: &E, defined: &HashMap<String, E>, memo: &mut HashMap<String, bool>) -> bool {
    expr.free_vars().iter().all(|name| {
        if let Some(&closed) = memo.get(name) {
            return closed;
        }
        // The definitions are acyclic (each reads earlier names only); the
        // provisional `false` only guards against a malformed table.
        memo.insert(name.clone(), false);
        let closed = defined
            .get(name)
            .is_some_and(|definition| closed_term(definition, defined, memo));
        memo.insert(name.clone(), closed);
        closed
    })
}

/// Slice 23 (OD-205): what [`pair_arithmetic`] states for one walk: each
/// paired machine name's definition, each operand claim `(= a c)` with the
/// unit of the source operation it pairs with, in walk order, and each
/// paired row as the pairing record states it ([`X86PairedRow`], its names'
/// walk definitions still to be read from the walk's own table).
#[derive(Default)]
struct ArithPairing {
    definitions: HashMap<String, E>,
    claims: Vec<(usize, E)>,
    rows: Vec<PairedArith>,
}

/// Slice 23 (OD-205): one row [`pair_arithmetic`] paired: its key, the
/// source's operands `(a, b)`, the row's own operands `(c, d)` in the walk's
/// order (`crossed`: claimed as `(d, c)`, a commutative key's crossing), and
/// each name it defines with the part of the key's term it holds.
struct PairedArith {
    key: ArithKey,
    source: (E, E),
    machine: (E, E),
    crossed: bool,
    results: Vec<(String, ArithPart)>,
}

#[cfg(test)]
thread_local! {
    /// Tests only ([`with_arithmetic_pairing`]): whether [`build_theorem`]
    /// pairs arithmetic rows (slice 23, OD-205).
    static ARITHMETIC_PAIRING: std::cell::Cell<bool> = const { std::cell::Cell::new(true) };
}

/// `f` with every theorem built with (`on`) or without slice 23's
/// arithmetic pairing ([`pair_arithmetic`]): without it, the spelling of
/// slices 1 to 22, the custody of the goldens slice 23 moves. Tests only;
/// never an owner's spelling.
#[cfg(test)]
pub(crate) fn with_arithmetic_pairing<T>(on: bool, f: impl FnOnce() -> T) -> T {
    let before = ARITHMETIC_PAIRING.with(|cell| cell.replace(on));
    let result = f();
    ARITHMETIC_PAIRING.with(|cell| cell.set(before));
    result
}

